INSERT INTO `quest_request_items` VALUES
(2,1,0,'哦，强大的$C，我知道你会来的。你是要告诉我你在狩猎行动中的进展吗？',12340),
(5,1,0,'哦？有我兄弟的东西？爽！幸运之光今天可算照到我身上了！',12340),
(6,6,6,'你找到加瑞克·帕德弗特了吗？我们终于可以摆脱这个恶棍了吗？',12340),
(7,1,6,'你的猎杀行动进展如何，$N？你清剿那些狗头人歹徒了吗？',12340),
(8,6,0,'来啦来啦！是谁呀？$B$B这些可怜人的胃口还真是不小。请随便些……就像在家里一样。我叫芮妮，如果你有什么需要，我愿意效劳。',12340),
(9,1,6,'啊，你回来了！你已经把那几片田上的看守傀儡清理干净了吗？二十台吗？',12340),
(10,6,6,'嗯，有什么消息吗？你看起来像是经过一场大战……谢申克是不是还活着呢？',12340),
(11,0,0,'你好，$N。你去杀豺狼人了吗……？',12340),
(12,1,1,'或许是我没说清楚吧，抱歉。为了证明你的能力足以效忠人民军和圣光，你必须杀死15名迪菲亚猎人和15名迪菲亚走私者，完成之后再回来找我吧。',12340),
(13,1,1,'我们可没时间聊天了，$N。迪菲亚掠取者在正威胁着西部荒野人民的生命与财产的安全。你必须至少干掉15名迪菲亚掠取者和15名迪菲亚强夺者，这样我们也可以给他们传达一个明确的信息:这里不容任何邪恶势力入侵。',12340),
(14,1,1,'$N，现在可不是发呆闲聊的时候。如果你还想向人民军证明你的实力的话，就得去杀死我之前说的那些迪菲亚盗贼。完成任务之后在就回来向我汇报。',12340),
(15,1,6,'你去过矿洞了吗？情况如何？',12340),
(16,0,0,'在田地里工作很容易让人口渴，我一直想要喝点清凉的泉水。$B$B如果你有的话，我愿意和你做个交换。',12340),
(17,6,6,'你拿到我需要的紫色蘑菇了吗？找不到我要的东西，我可不会付给你报酬的！',12340),
(18,6,6,'你已经收集到足够的面罩了吗？',12340),
(19,0,0,'黑石氏族的兽人仍然在压制着我们。你干掉萨瑞尔祖恩了吗？',12340),
(20,0,0,'你杀掉多少兽人了，$N？有的话让我看看啊！',12340),
(21,1,1,'我知道这是场血战，$N，但清除狗头人对北郡的安全非常重要，你做得如何了？',12340),
(22,5,4,'猪肝馅饼怎么可以没猪肝！快去找猪肝，记得要八片！',12340),
(23,6,0,'啊，$N——我正想着你呢！你的狩猎行动怎么样了？',12340),
(24,6,0,'再次欢迎你，$N！你是来向我展示你完成狩猎的证明的吗？',12340),
(25,1,0,'你回来了？那儿的情况怎么样——已经搞定了吗？',12340),
(26,1,0,'',12340),
(27,1,0,'',12340),
(30,1,0,'你带来合并好的坠饰了吗，$N？如果你在寻找它们时遇到了麻烦，就跟这里的居民交谈以获取信息。这不仅能帮助你找到坠饰，还能帮助你探索这片神圣的土地。',12340),
(31,1,0,'你回到雷霆崖的消息早已传遍了这里，但是在我向传授你水栖形态的知识之前，我必须检验你在月光林地所学的成果。$B$B你把海狮坠饰拿来了吗？',12340),
(32,6,0,'很抱歉，我不认识你……但是看来你似乎对我已经有所了解了。我能帮你什么忙吗？或者你有什么东西要交给我？',12340),
(33,6,6,'嘿，$N。我有些饿了……你拿到硬狼肉了吗？',12340),
(34,6,6,'贝利格拉布还活着吗？还是你已经永远的替湖畔镇把这个祸害除掉了？',12340),
(35,1,0,NULL,12340),
(36,6,6,'我还真是很想念弗娜·法布隆呀。我想，你在过来的路上应该是碰到她了吧？',12340),
(37,1,0,NULL,12340),
(38,1,1,'带着以下材料回来：$b $b 3 块带筋的兀鹰肉 $b 3 个野猪鼻子 $b 3 只鱼人眼 $b 3 根秋葵',12340),
(39,1,0,NULL,12340),
(40,1,0,NULL,12340),
(45,1,0,NULL,12340),
(46,0,0,'你的狩猎行动如何了，$N？',12340),
(47,0,0,'喂！你找到金砂了吗？',12340),
(48,94,94,'嗝！呵呵！你还想再来一段？$B$B在南边那片藤蔓盘绕的土地$B$B有一口隐秘的水井，水色深又清$B$B纯净如圣光的神圣之女$B$B现在给我带些神圣泉水来。',12340),
(49,94,94,'再说一遍？当然没问题！$B$B琥珀的颜色是我毕生之爱$B就像天边夕阳下的云彩$B为了它的诞生呀，勇敢的少年我召唤你$B我要一袋黑麦、大麦和玉米！',12340),
(50,94,94,'你要我再给你唱一遍？当然行了，朋友！$B$B我捣！我搅！我捣！我搅！$B因为这是我们的私人珍宝$B我需要一种够硬的金属来做酒罐儿$B给我弄些真银来，好让我可以唱完这首歌！',12340),
(51,94,94,'还想听一遍？你想怎么着都行！$B$B还没过滤但是刚刚蒸馏$B就像是新皮甲还没上油$B然后得烧它七八斤炭呀$B我说你赶紧动身去办呀！',12340),
(52,1,0,'你杀掉那些狼和熊了吗？',12340),
(53,94,94,'当然，我可以为你再唱一遍，朋友！$B$B甘美的液体清澈如婴儿的眼泪$B经年累月转成可人的深琥珀色$B但在我俩喝到酩酊大醉之前$B得先造出一只烧焦的橡木桶。',12340),
(54,1,0,'你有治安官玛克布莱德的信？和艾尔文森林相比，北郡就像是个花园，但我现在更关心治安官玛克布莱德有什么消息给我。$b$b来，让我看看他的信……',12340),
(55,5,5,'你必须消灭摩本特·费尔！',12340),
(56,1,6,'你杀掉那些战士和法师了吗？',12340),
(57,1,25,'杀死15个骷髅魔和15个恐怖骷髅以后再回来见我，$N。',12340),
(58,1,25,'我需要你的帮助，$N。到西北方的墓园去杀掉20个瘟疫食尸鬼。$B$B完成任务之后就回来告诉我。',12340),
(59,2,0,'暴风城军队委托我给他们的士兵制作布甲和皮甲。$b$b如果你有标记给我的话，我很乐意给你也做一件。',12340),
(60,0,0,'你收集到足够的蜡烛了吗？',12340),
(61,0,0,'哦，我兄弟让你送来的货？太棒了！我今天运气真好！',12340),
(62,1,0,'你有什么要报告的吗，$N？你去过法戈第矿洞了吗？',12340),
(63,1,0,'火盆折射着周围的光芒，当你靠近时，火焰微微地扑动。$B$B山间的堕落气息似乎对此相当敬畏，看起来火盆已经可以进行召唤净化的水灵的仪式了。',12340),
(64,6,6,'你找到我的怀表了没？',12340),
(65,1,0,'我们需要知道到底谁是他们的头儿，还有他们都藏在哪儿。在湖畔镇的旅馆里有个叫威利的小贼，他以前欠了我一个人情，你可以找他帮忙。$B$B到艾尔文森林东边的赤脊山去吧，湖畔镇就那座山的脚下，到那里去碰碰运气。',12340),
(66,1,0,NULL,12340),
(67,1,0,'啊，我记得你。你是在打听那个斯塔文的下落的人。你找到你想要的东西了吗？',12340),
(68,6,6,'啊，我记得你。你是在打听那个斯塔文的下落的人。你找到你想要的东西了吗？',12340),
(69,1,0,NULL,12340),
(70,6,6,'你找到什么了？让我来瞧瞧……',12340),
(71,0,0,'你好，$N。你找到罗尔夫和马拉凯的下落了吗？',12340),
(72,1,0,NULL,12340),
(74,6,6,'你找到什么了？我的视力很差，根本看不清楚。把它放到我手上来，让我仔细瞧瞧。',12340),
(75,6,6,'你找到我所说的那页日记了吗，$N？',12340),
(76,1,0,'你好，$N。你有什么要报告的吗？去玉石矿洞显示过了吗？',12340),
(77,6,6,'我相信你回来一定是拿到任务需要的十瓶蜜酒了，是吧？',12340),
(78,6,6,'治安官哈迦德派你来的？怎么不早说？$B$B哈，狡猾的哈迦德。可怜的小伙子再过不久眼睛就会彻底瞎了。不说那些了，让我看看你带来的是什么。',12340),
(79,1,0,'你最好是真的有急事找我，$C。让我看看你带来的东西，再说说你的故事。以圣光之名，请你快一点。我的首要职责是保卫夜色镇，而不是把时间都浪费在毫无意义的事情上。',12340),
(80,6,6,'$N，你又回来了？这次你找到什么了？',12340),
(81,5,0,'如果你不是来买东西或是有东西要交给我的话，那你就是在浪费我的时间！你最好已经把蜜酒弄来了！',12340),
(82,5,5,'你是初级勘探员$N？快点行动吧，现在情况很紧急！你拿到菲兹杜瑟要你去取的那些昆虫肢体了吗？',12340),
(83,6,6,'我的亚麻布不够了，$N。你能帮我找点来吗？',12340),
(84,1,0,'呃……我快饿死了！你拿来我要的馅饼了吗，$N？',12340),
(85,1,0,NULL,12340),
(86,6,6,'我怎么能给那个偷了我项链的小孩子做吃的？不过如果只有这样才能把我的项链找回来，那也只好这么做了！$b$b你有野猪肉吗？',12340),
(87,3,3,'你好，$N。你找到我的项链了吗？',12340),
(88,6,6,'你看到它了吗？干掉它了吗？',12340),
(89,6,6,'这桥可不会自己把自己造出来！铁矛和铁铆钉在哪儿呢？',12340),
(90,6,6,'你找到10块狼肋排了吗？那暴风城菲利希亚的调味料呢？',12340),
(91,1,1,'交回10个影皮坠饰给我，你就可以得到我们的奖励。',12340),
(92,0,0,'我还需要5块硬兀鹰肉，5个巨型血牙野猪头和5份香脆蜘蛛肉。',12340),
(93,3,3,'你好啊，$N。找到粘糊的蜘蛛腿了吗？',12340),
(94,1,0,'这个狮子雕像已有几十年的历史了，它一直孤孤单单地看守着声名狼籍的伊尔加拉之塔。$B$B雕像的底部有一处凹陷，那里正好可以放置一块宝石或者雕文……',12340),
(95,1,0,NULL,12340),
(96,1,0,'你回来了，太好了！$B$B你的银松森林之旅怎么样？花了不少时间吧？$B$B我很难判断你是否在那里获得了成功，因为已经有如此多的地方彻底堕落了。你所做的一切在邪恶的力量面前还是显得微不足道，但是即便是微小的胜利，有时都会和重大的胜利一样重要。净化那里的水对于你和所有的萨满都很重要。',12340),
(97,1,5,'嗯，$N？',12340),
(98,6,6,'嗯，$N？',12340),
(99,0,0,'你拿到焚木镣铐了吗，$N？',12340),
(100,1,0,NULL,12340),
(101,1,1,'找10颗食尸鬼的牙齿、10根骷髅的手指和5瓶蜘蛛毒液来给我，我会为你制作一个惩罚图腾，让那些企图伤害你的敌人自食其果。',12340),
(102,6,6,'你从那些阴险的豺狼人身上拿到8只爪子了吗？',12340),
(103,0,0,'灯油用完之后火炬马上就会熄掉了，$N。',12340),
(104,0,0,'你已经消除了老瞎眼的威胁了吗？有人看见它今天早上在西部荒野的海岸线上闲逛。$B$B把这只邪恶的野兽干掉以后再回来找我。',12340),
(105,6,6,'你已经接到我指派的任务了，$N。你拿到巫妖的护符匣碎片以作为完成任务的证明了吗？',12340),
(106,5,0,'你带来了她的信？梅贝尔是我枯燥无味生活中的一盏明灯。快点，快让我看看她的信！',12340),
(107,0,0,'斯通菲尔德的字条？我有好几年没有见到她了！不知道她到底有什么事……',12340),
(109,1,0,'你真应该去格里安·斯托曼那儿报到。他是人民军的领袖，这是个专门负责保卫西部荒野的人民军组织，我敢说你是能帮他一些忙的。一般来说，你可以在哨兵岭的石塔周围找到他，那地方就在西部荒野中部的路边上。',12340),
(110,1,0,NULL,12340),
(111,1,0,'我都等不及去看朋友们的反应了！$B$B他们肯定猜不到！',12340),
(112,0,0,'你找到水晶海藻叶了吗？我敢说梅贝尔一定很想快点见到她的爱人……',12340),
(113,6,0,'你好，初级勘探员$n，匹斯特苏格的报告完成了吗？',12340),
(114,0,0,'你把我的信带给汤米·乔了吗？他有说什么吗？',12340),
(115,6,6,'你和暗影法师的交手战况如何？有找到午夜宝珠了吗？',12340),
(116,25,25,'我希望你能从住在西部荒野的葛瑞姆·雷酒那里搞一桶雷霆啤酒，从暴风城搞一桶葡萄酒，从夜色镇搞一瓶月光酒，还有还有，再从闪金镇搞一袋蜂蜜酒来。把这些好酒都给我弄来，我会重重谢你的。',12340),
(117,94,94,'快点，朋友，动作要快$b为了让我们的浓酿尝起来$b更像啤酒而不是炖菜$b酿造时就需要蛇麻草。',12340),
(118,0,0,'嗯，你说是弗纳派你来的？好，把他的信给我，说说看他到底要什么吧！',12340),
(119,0,0,'好极了，你回来了！你拿到马蹄铁了吗？',12340),
(120,6,6,'有什么事吗？',12340),
(121,6,6,'将军有什么消息给我吗？援军已经上路了吗？',12340),
(122,0,0,'若我没能及时把鳞片给他送过去的话，贪婪的阿古斯一定会自己派人去找的。你拿到足够的鳞片了吗？',12340),
(123,0,0,'什幺？！我们的人已经有好几个月都没在艾尔文森林的矿洞里工作了！$B$B让我看看你拿来的那张记录……',12340),
(124,1,0,'我的马似乎还是一直受到惊吓，在夜里我也还是会听见那该死的狼嚎。拜托你，$N，把那些豺狼人都干掉！',0),
(125,6,6,'你找到我的工具了吗？',12340),
(126,0,0,'犹勒可是个危险的家伙，$N。你要是没准备好的话，就别急着去，我能理解。',12340),
(127,0,0,'你有鱼要给我吗？',12340),
(128,1,25,'杀掉15个黑石勇士再回来吧。',12340),
(129,0,0,'这是达希为我做的午饭？她真是个善良的姑娘。那么……我们开饭吧！',12340),
(130,1,0,NULL,12340),
(131,0,0,'你好啊，$N。派克吃到我做的午餐了吗？',12340),
(132,6,0,'看见你回来真好，$N。威利都说了些什么？',12340),
(133,0,0,'我听到有一群食尸鬼在屋后面跑动——我得赶紧把假人立起来！你找到食尸鬼的肋骨了吗？',12340),
(134,0,0,'你找到我的木箱了吗？如果找到的话，请赶快把它给我！',12340),
(135,6,0,'你找我有事吗？我可是很忙的……',12340),
(136,1,0,'如果你读到这封信的话，那就意味着我，桑德斯船长，已经长眠在深深的水底了。所以，只要按照我的线索去做，我的宝藏就是你的了。$B$B首先你必须要找到我的置物箱，它应该就在西部荒野西边海岸的某处船只残骸旁，如今应该八成都埋在沙里了。海岸边有许多处船只的残骸，但只有一只沉船旁有个锈掉的锚。找到锚你就找到箱子了！在箱子里面，你可以找到下一条线索。',12340),
(138,1,0,NULL,12340),
(139,1,0,NULL,12340),
(140,1,0,NULL,12340),
(141,6,0,'肖尔有提到任何线索吗？',12340),
(142,6,6,'$N，你收集到什么情报没有？找到那个信差了吗？',12340),
(143,6,6,'你好，$C。请问你找人民军有什么事吗？',12340),
(144,6,6,'人民军能派来援军来吗？斯托曼大人是怎么说的？',12340),
(145,6,6,'看来你是千里迢迢赶到这里来的，$C。你到夜色镇来有什么事吗？',12340),
(146,6,6,'啊，很高兴看到你回来，信差。我是不是该通知我的治安官说，守夜人部队已经上路向这边来了？',12340),
(147,0,0,'你找到收货人了吗？查出他为谁工作了吗？',12340),
(148,1,0,NULL,12340),
(149,1,0,'<哭泣>哦，不要，不要看着我！我自己把眼睛挖掉了，但是我还是能感觉到你在看我！$B$B我长得很丑陋！$B$B很丑陋！求求你，把脸转过去吧！',12340),
(150,0,0,'把鳍带来了没？动作快点，我们一定得把这群鱼人赶出湖去！',12340),
(151,6,6,'老布兰契已经快累死了。你找到给它吃的燕麦了吗？',12340),
(152,1,0,'去杀死7名滩行鱼人、7名鱼人战士、7名潮行鱼人，还有7名鱼人智者，完成任务之后到我这里来领取你的报酬。',12340),
(153,1,1,'帮我拿15条红色皮面罩来，我就付给你可观的酬劳。',12340),
(154,6,6,'我想你已经见过盲眼玛丽了，你拿到梳子了吗？',12340),
(155,1,0,'有事吗？',12340),
(156,6,6,'你好，$N。你帮我找到腐败之花了吗？',12340),
(157,0,0,'我要把幽灵的发丝挂在门窗上，来阻绝那些该死的亡魂。你替我拿来发丝了吗？',12340),
(158,1,0,NULL,12340),
(159,0,0,'我需要喝些僵尸汁在寒冷的夜里保持暖和。你替我拿僵尸汁来了吗？',12340),
(160,6,0,'亚伯克隆比……？我不认识这个人。你是说这个人有封信给我？$B$B哦，那我就收下好了……',12340),
(161,6,0,'你说什么，孩子？除了耳鸣我什么都听不见。喂，你那儿拿的是什么？',12340),
(162,2,0,'愿平和与宁静伴随你，陌生人。你今天为何来找我？',12340),
(163,1,0,'啊，$N！回来的这么快？你肯定又被野兽追了吧？别在意你经历的那些周折，终究它们会让你更强大！$B$B……至少，你也没变得更差',12340),
(164,6,0,'你看起来挺健壮的，$C。你是来帮我们战斗的吗？',12340),
(165,1,0,'伊莲·克尔文？呵呵，是的……当然，克尔文家族的。不不不，我没什么事，只是现在要去镇上很困难。路上太危险了，而我已经不再年轻。你能帮帮我这个老头子吗？',12340),
(166,6,6,'追踪艾德温·范克里夫的事情进展如何了？',12340),
(167,6,6,'你找到有关我弟弟的线索了吗？经过这么久的时间还有任何希望吗？',12340),
(168,6,6,'你找回我那些老同事们的矿业工会会员卡了吗？',12340),
(169,6,6,'你那儿有什么，$R？',12340),
(170,1,1,'这些穴居人真是烦人啊！',12340),
(171,6,0,'很高兴再见到你，$N。你有没有在儿童周中完成自己的义务？',12340),
(172,1,0,NULL,12340),
(173,1,0,'$N，你干得如何了？',12340),
(174,6,6,'你找到可以制造青铜管的工程师了吗？',12340),
(175,1,0,NULL,12340),
(176,0,0,'没错，霍格一直让我们倍感头疼。你有关于他的消息？',12340),
(177,6,6,'考格看过我们的观星机器的雏形之后非常满意。你找到合适的反光镜了吗？',12340),
(178,0,0,'你说我通过一个坠子和你说话？快给我，我好研究研究它。',12340),
(179,11,11,'那些狼好对付吗？它们的狂牙利爪没有伤到你吧？',12340),
(180,6,6,'你有什么事吗？',12340),
(181,6,6,'你有没有说服札克乌尔把他的单片眼镜借给我们做实验？',12340),
(182,6,1,'据我所知，这些巨魔来自于霜鬃氏族。$N，恐怕我没有什么其他的资讯可以告诉你了。',12340),
(183,2,6,'捕猎进行得如何啦？',12340),
(184,5,0,'你有我的农场的地契？真是太好了！几天前有几个恶棍把它给偷走了……我还以为再也找不回来了！$b$b请把它还给我吧。我们正要离开西部荒野，短期内不会回来了，不过万一日后我们又要再回来的话，我们就会需要这些文件。',12340),
(185,1,1,'在你证明自己能先猎杀最年幼的老虎之前，我没有信心再教你更多，$n。',12340),
(186,1,0,'如果你想要接受更大的挑战，就必须要先完成我交付给你的任务来证明你的实力。杀死10只荆棘谷猛虎后再回来找我。',12340),
(187,1,0,'在面对最后的挑战之前，你必须先杀死10只老年荆棘谷猛虎，否则你是没资格成为一位真正的猎虎大师的。',12340),
(188,6,6,'猎杀辛达尔的事情进行得如何啦？',12340),
(189,0,0,'你成功了吗？这里遍地都是巨魔，这群丑陋的魔鬼。$b$b哦，对了，这倒提醒了我，记得把这件事告诉你的同伴，好吗？我们还需要更多的帮手！',12340),
(190,1,25,'一名真正的猎豹高手应该在荒野中搜寻猎物。尽力去完成你的目标，$c，然后再回来。',12340),
(191,1,0,'去猎杀十只黑豹！给我们看看你的战利品！',0),
(192,1,0,'你在这儿干什么，$n！你该在灌木丛里爬着去杀十只暗影齿黑豹。我还以为你自认是个大型猎物$c呢？',0),
(193,6,6,'巴尔瑟拉是这片丛林里最狡猾的野兽，你捕猎到它了吗？',12340),
(194,1,0,'我从没见过猎人站在营火旁边也能打到猎物的——呃，除了我父亲。你是打算杀死荆棘谷迅猛龙还是等那些猎物老死？',12340),
(195,1,0,'一位真正的猎人脑中总是想着他的猎物。而你呢，我的朋友，你似乎更喜欢在营火旁边谈天说地。好了，快离开这里，你最好赶在我把这些鞭尾迅猛龙全部杀光前猎杀10只回来。',12340),
(196,1,0,'呸！你站在那儿干什么，$N！真正的狩猎大师绝不会在猎物进入视野后放弃。那些丛林潜伏者可不会自己跑到这堆营火边跳进去。傻小子。',12340),
(197,6,6,'猎杀泰希斯的事进行得怎么样了？你找到它的老窝了吗？',12340),
(198,1,0,'是的？有什么事吗？哦，地精送来的补给品。他们居然会让一个$R送过来，还真是奇怪，一般都是他们自己送来的。不管了……你没碰过里面的东西吧？很好，很好……我可不希望我们的地雷突然爆炸，绝对不想。',12340),
(199,6,0,'你找到什么线索了吗，$N？',12340),
(200,1,0,NULL,12340),
(201,1,6,'如何？你找到那个营地了吗？',12340),
(202,1,0,'你能将库尔森和他的保镖们都杀死么，$N？',12340),
(203,1,0,'我希望你能在这次行动中获得成功，$N。要是没有你的帮助，我们真的没可能跟他抗衡这么久。',12340),
(204,1,0,'我等着你取回那些药物与毒液，$N。',12340),
(205,1,0,'你拿到那些神像了吗，$N？它们可能藏着库尔森堕落的秘密……我必须知道！',12340),
(206,0,0,'我赐予你我的祝福。麦佐斯的力量只有他的邪恶能与之匹敌。',12340),
(207,1,0,'$N！你找到这些巨魔的传说了吗？我必须得了解他们的秘密！',12340),
(208,1,1,'我等着你回来，小$g伙子:姑娘。虎王邦加拉什有好几次都让我狼狈地爬回营地，它的确是块难啃的骨头。',12340),
(209,6,6,'他们确实是帮挺难对付的家伙。那么，你的运气怎么样？请原谅我的急躁，不过我的确是太牵挂这件事了！到底怎样？',12340),
(210,1,0,'你好！你找我有事？',12340),
(211,6,6,'你已经接到我指派的任务了，$N。你拿到那个巫妖的护符匣碎片作为完成任务的证明了吗？',12340),
(212,5,5,'$N！拿到冷眼蜥蜴的肉了吗？我必须开始作准备了，否则晚上的宴会可就完了！',12340),
(213,5,5,'我急需那些石头，$n。无论如何都要给我搞到！快去干吧，细节问题与我无关！$b$b我只要结果，$n，别的什么都不要。',12340),
(214,6,6,'怎么样，你把迪菲亚强占的土地都夺回来了没有？如果你完成了这个任务，就拿出10条红色丝质面罩来作为证据。',12340),
(215,1,0,NULL,12340),
(216,1,6,'你参加对蓟皮熊怪的战斗了吗？只要我们两座基地之间的道路畅通无阻，我们占领整个灰谷的机会就可以大大增加。',12340),
(217,1,1,'格劳姆格和他的两个护卫纳什尔及布劳勒尔还活着。他们这三个家伙不死，你的任务就不能算是完成了。矮人王国需要你的帮助，$N。',12340),
(218,6,6,'$N！日记拿回来了吗？',12340),
(219,1,0,'嗯？',12340),
(220,1,0,'又见面了，$N。你看起来不错。$B$B怎么这么快就回来了？',12340),
(221,1,0,'这么快就回来了，$N？你不是跑来告诉我你已经放弃了吧？',12340),
(222,1,0,'他们很危险吧？不过不要害怕，$N，为光明而战的人决不会失败！',12340),
(223,0,0,'嗯，有什么事吗？请快一点，我还有紧急的事情要处理。',12340),
(224,1,5,'洛克莫丹正在四面受敌，$N！我们需要联盟里每一个有能力的成员帮助我们。你干掉10个碎石穴居人和10个碎石怪斥候了吗？',12340),
