(226,1,6,'你还在捕猎那些狼吧？',12340),
(227,1,0,NULL,12340),
(228,1,1,'就算你对付不了摩拉迪姆，我也不会责怪你的，$N。我们有很多最棒的守夜人都死在他手下。',12340),
(229,1,0,NULL,12340),
(230,5,0,'你找到什么了吗？请让我看看……',12340),
(231,1,0,'让我安息吧……',12340),
(232,6,0,'你好，我能为你做些什么？你是为了皇家药剂师协会的事情而来，还是仅仅来这里随便逛逛？',12340),
(233,6,0,'嗯？你有东西交给我？',12340),
(234,1,0,'有什么我可以帮忙的吗？',12340),
(235,1,0,NULL,12340),
(236,0,0,'嗯哼？你是不是被部落打败，余烬被抢走了，只能蹲在路边哭？',12340),
(237,1,25,'我们需要更多时间，$r。你的命令是杀死十名石锥碎颅者和十名石锥先知。在援军到来前持续压制敌人。现在不是懈怠的时候。',12340),
(238,1,0,'嗯，我想卢卡和你都忙得不可开交了。不管怎么样——请快把采样工具包交给我吧。我要对它进行一些调整，以便搜寻合适的基础性材料。$b$b你身上是带着采样工具包的，对吧？',12340),
(239,1,0,NULL,12340),
(240,5,5,'$N，你回来了！拿到我想要的食物了吗？',12340),
(243,1,0,'嗯，我能帮你做些什么吗？你显然有事要找我帮忙，但也许我并不会帮你。你是否考虑到了出现这种情况的可能性？',12340),
(244,1,0,NULL,12340),
(245,1,0,'对付蜘蛛的时候你得小心点，我们已经有不少人被它们杀掉了。要知道，看见蜘蛛用毒液把人放倒以后再把他们倒挂在蜘蛛网上并不是什么有趣的事情。$B$B我可不想让某只蜘蛛把你当午饭给吃了。',12340),
(246,1,0,'请原谅，$N，我们有太多的事情要处理。如果你没什么事情要报告的话，我就去忙其它的事了。',12340),
(247,1,0,NULL,12340),
(248,1,0,'这只罐子以前是用来装劣质烈酒的，但现在却被丢在一堆木桶旁边。',12340),
(249,5,5,'快一点，$N，在莫甘斯伸出他的魔爪之前解决掉他！',12340),
(250,1,0,NULL,12340),
(251,0,0,'亚伯克隆比写给镇长的信？我不认识这个人，但是如果他确实住在墓地那边，我看他的脑子一定是坏掉了！',12340),
(252,1,0,'啊，信翻译好了？请让我看看……',12340),
(253,6,6,'你找到伊莉莎的坟墓了吗？找到藏尸者的心脏了吗？',12340),
(254,1,0,'',12340),
(255,1,6,'你做得怎么样了？',12340),
(256,6,6,'嗯？你有什么事吗？',12340),
(257,1,1,'运气不佳？别太难过了，$n……$B$B并不是每个人都像我这么厉害的。',0),
(258,1,1,'被一个你不认识的人嘲笑确实会让你羞得无地自容，不过你也别太难过了，$n。$B$B嗯？我没记错你的名字吧？',0),
(261,1,25,'天灾军团每天都在不断壮大。如果你真的想阻止他们，就证明给我看。',12340),
(262,1,0,'如果你找到了什么和那个模糊的人影有关的东西，别忘了让我看看。也许我能从中找出些和它的主人有关的蛛丝马迹来。',12340),
(263,1,6,'这么快就回来了？也许我还没说清楚，我要你去杀掉10个碎石怪萨满和10个碎石怪断骨者，$N。现在出发吧，穴居人杀手！',12340),
(264,1,0,'这块石头摸上去冰凉刺骨，但是显然没有人照看。这里遍地都是垃圾，棺材顶上的雕刻布满了又深又长的缺口，周围的植物长得比坟墓还高。$b$b没人关心是谁被埋在这儿。',12340),
(265,1,0,'有时我会把空白的书卖给学者、法师，或是任何想要写日记的人。$B$B对于过去几个月来买书的每一个人，我都记得很清楚……',12340),
(266,1,0,'血鸦旅店的生意已经大不如以前了，不过还是时常有旅人从这儿经过。$B$B如果你能描述一下你要找的那个人的特征，我可能会想起些什么来。',12340),
(267,6,6,'你给我拿来8颗穴居人的石牙了吗？没有的话，就快去完成你的任务吧，$N。',12340),
(268,6,6,'你发现那个模糊的人影是谁了吗？',12340),
(269,1,0,'休息一会儿吧，$g兄弟:姐妹。我看得出你走了很远的路，身上还承担着重任。你能告诉我是什么样的阴影笼罩着你吗？',12340),
(270,1,0,NULL,12340),
(271,1,1,'啊，$N！这么快就回来了？你一定又去打猎了？遇到挫折也别担心，从长远来看，挫折可以让你变得更加成熟！$B$B（反正你已经够糟的了……）',12340),
(272,1,0,'你带来合并好的坠饰了吗，$N？如果你在寻找它们时遇到了麻烦，可以试着跟这里的居民交谈以获取资讯。这不仅能帮助你找到坠饰，还能帮助你探索这片神圣的土地。',12340),
(273,1,0,NULL,12340),
(274,6,0,'阿什兰说什么了吗？',12340),
(275,1,0,'湿地仍在哭泣，沼泽爬行者仍在肆虐。任务完成后再来找我。',12340),
(276,1,0,'你还有重任在身，年轻的$C。',12340),
(277,1,0,'你把那些豺狼人的生火工具都夺过来了吗？',12340),
(278,5,5,'你找到我们需要的东西了吗？我们必须争分夺秒！',12340),
(279,0,0,'高布勒尔和它的鱼人爪牙们不死，我们的商人就得不到安宁。',12340),
(280,1,0,'你慢慢地拧开了木桶的盖子。',12340),
(281,1,0,NULL,12340),
(282,66,66,'欢迎你，$N，要多加小心，通往丹莫罗的隧道里满是穴居人，你八成得杀出条血路才能过去。$b$b如果你在丹莫罗没有什么紧急的事情要办的话，我就得请你待在安威玛尔，直到隧道比较安全为止。',12340),
(283,1,0,NULL,12340),
(284,1,0,NULL,12340),
(285,1,0,NULL,12340),
(286,0,0,'你拿到雕像了没有？',12340),
(287,1,0,'你找不到要塞？我的方位说明可是非常清晰的！我们没多少时间了，你必须快点！找不到那个洞穴就别回来。',12340),
(288,1,1,'哦，我非常口渴！你不愿意为我这样一个穷困潦倒的可怜虫买点喝的吗？',12340),
(289,1,0,'在梦里，我时常听见弟兄们悲惨的呻吟！求求你，好心的$g先生:女士，帮助他们从囚禁和痛苦中解脱出来，平息他们的哭嚎吧。',0),
(290,1,0,'这个箱子被牢牢地锁着。',12340),
(291,0,0,'嗯……看来我的卫兵都是些饭桶，什么人都放了进来。好吧，有什么事？快点说吧。',12340),
(292,6,0,'那个酒鬼菲兹莫斯派你来找我？好吧，你告诉他我可没有多余的麦芽酒。他最好去向别的人乞讨吧！',12340),
(293,6,0,'你手上拿的那个球是什么？它看起来……似乎被污染了。',12340),
(294,1,0,'杀死10只杂斑迅猛龙和10只杂斑尖啸龙，$N。我那些弟兄们的血债一定要用血来偿还。',12340),
(295,1,21,'我一定要让这些杂斑刺喉龙和杂斑锯齿龙为它们以前所做过的一切付出代价。每种你都杀死了10只了吗？',12340),
(296,6,6,'萨尔图斯已经死了吗？你是否为逝者报仇雪恨了？',12340),
(297,6,6,'你拿到那些石像了吗？我们得研究它们，并把结果报告给铁炉堡！',12340),
(298,1,0,'哦，挖掘场送来的进度报告？很好！',12340),
(299,6,6,'你找到那些石板碎片了吗，$N？它们是阿度斯碎片、莫德尔碎片、高尔姆碎片和奈尔鲁碎片……',12340),
(301,25,0,'我们雷矛卫队的人不喜欢被小事情烦扰，$C。我希望你带来的是值得我关注的消息。',12340),
(302,1,0,NULL,12340),
(303,1,1,'罗戈没能联络到更多的援军，但我们必须要保持对黑铁矮人营地的压力，$c。快去，为麦格尼陛下而战！',12340),
(304,6,6,'你找到邪恶的巴尔加拉斯了吗，$C？他躲躲藏藏已经有一段日子了。',12340),
(305,1,0,NULL,12340),
(306,6,6,'你找到麦琳了吗？她有没有让你捎口信过来？',12340),
(307,6,6,'你拿到矿工装备了吗，$N？',12340),
(308,0,0,'啊！这么多好酒！不过我必须严格遵守命令，谁也不许碰它们一下。要是我能喝一口雷霆麦酒该有多好啊……那样会让我变得更加聪明，不骗你！',12340),
(309,1,0,NULL,12340),
(310,1,0,'从这桶酒的酿造日期来看，它马上就可以被开封了。',12340),
(311,0,0,'你把酒调换了吗？',12340),
(312,6,6,'你找到我的储藏柜了吗，$N？',12340),
(313,0,0,'嘿，$N。你去过灰色洞穴了吗？那些雪怪可是非常凶猛的。',12340),
(314,0,0,'瓦加什仍然让这里的羊群感到恐惧！帮我们杀了这个卑鄙的野兽吧！',12340),
(315,6,6,'你弄到微光草了吗？我有大量的酒需要酿制，要赶快把这种植物也加进去。',12340),
(317,1,1,'准备工作进展顺利，你的捕猎行动进展如何呢？',12340),
(318,1,0,NULL,12340),
(319,1,0,'你干掉那些野兽了吗？',12340),
(320,6,0,'你拿到酒了吗？',12340),
(321,1,0,NULL,12340),
(322,6,6,'我能帮你什么忙吗，$C？',12340),
(323,1,1,'勇敢一些，$N。不要绝望，因为你的绝望就是敌人最强的武器。',12340),
(324,6,6,'你找到足够的光铸铁锭了吗？',12340),
(325,1,0,'你好，$N。你并没有离开多久，但我却从你的眼中看到了以前没有看到过的火焰。',12340),
(328,1,0,'保险箱是用青铜制造的，非常坚固，而且非常重。',12340),
(329,1,0,'你发现还有谁知道索尔森的秘密了吗？谁是我们当中的内鬼？',12340),
(330,1,0,NULL,12340),
(331,1,0,NULL,12340),
(332,2,0,'你好，欢迎，$N。你尝过我们的美酒了吗？',12340),
(333,6,0,'你带来了巴格雷先生的信？',12340),
(334,1,0,'要买衣服吗？',12340),
(335,6,6,'维沙克马上就能说服足够多的议员支持他了，那样我们将会非常被动。你找到蒂罗亚之泪和麝鼠根了吗？',12340),
(336,5,5,'你没看见我正忙着吗？你听不懂我说的话吗？我对王国的未来十分重要！$B$B噢……你说你要找我干什么来着？为什么这玩意看起来像是一种很提神的饮料……',12340),
(337,6,0,'哦！你拿的那本是什么书啊？能让我看看吗？',12340),
(338,6,6,'你已经把这几章书都给收集齐了吗，$N？',12340),
(339,6,0,'你能找到第1页，第4页，第6页和第8页吗？没这四页，我们就没办法凑齐第一章。',12340),
(340,1,0,'我们仍然需要第10页，第11页，第14页和第16页才能完成第二章，$N。',12340),
(341,6,0,'你找到第18页，第20页，第21页和第24页了吗？只有找到了这些我们才能凑出完整的第三章。',12340),
(342,6,0,'我们只需要三页就能完成完整的第四章，$N。你找到第25页，第26页和第27页了吗？',12340),
(343,1,0,NULL,12340),
(344,1,0,NULL,12340),
(345,1,0,NULL,12340),
(346,6,0,'你找到符文之书了吗？',12340),
(347,6,6,'你找到瑞斯班矿石了吗？',12340),
(348,0,0,'……妈妈？$b$b好冷……$b$b……像是要掉进扭曲虚空了……抱……抱紧我，妈妈……',12340),
(349,1,0,'巫医安巴格瓦当然知道野人莫克是什么。是的，是的！$b$b我与他的灵魂对话并把他召唤过来，我可以。$b$b但其它的猩猩也很喜欢精神交谈。这样吧，你保护好巫医安巴格瓦，我把它召唤到你面前。$b$b巫医安巴格瓦想先要点东西。你带一颗猩猩牙来，我就会马上开始召唤它！',12340),
(350,1,0,NULL,12340),
(351,1,0,'发现目标！你赫然看到石头上躺着一只……机器小鸡？！从机器小鸡中传出了声音：$B$B“太好了，你干得不错！这确实是我的母体，根据我的检测判断，它需要进行一定的启动动作才能够重新飞回藏宝海湾进行修理。请把定向器放到母体机器人里，剩下的它自己会去搞定！”',12340),
(353,6,0,'你这家伙是从暴风城过来的？我听说人类那边是越来越乱了，盗匪和兽人满地跑，嗯，那真是个让你这样的$C大显身手的好地方！',12340),
(354,0,0,'你把阿加曼德一家人的尸体带来了吗？这群该死的野兽被彻底消灭了吗？',12340),
(355,1,0,NULL,12340),
(356,1,0,'你的巡逻报告呢？',12340),
(357,0,0,'$N，你拿到那本书了吗？',12340),
(358,0,0,'你的任务完成了吗？把那些狗一样的废物都给干掉了吗？拿到他们身上的防腐剂没？',12340),
(359,1,0,NULL,12340),
(360,1,0,NULL,12340),
(361,1,0,'嗯？',12340),
(362,0,0,'你找到代弗林了吗？',12340),
(363,1,0,NULL,12340),
(364,1,0,'如果你连最弱小的僵尸都干不掉的话，你的新生之路只可能早早结束，$n。没有完成任务，就别回来见我。',12340),
(365,6,6,'亡灵卫兵希米尔带了信过来，说你会提供给我一些我急需的炼金材料。你收集到10颗南瓜了吗，$N？',12340),
(366,1,0,'你的主人把你派来实在是愚蠢之极，我再也不会做天灾军团的奴隶了！',12340),
(367,5,0,'你收集到5瓶黑暗犬的血液了吗，$N？时间紧迫！',12340),
(368,6,0,'$N，你有能力从那些鱼人身上取得5片邪鳍鱼人的鳞片吗？',12340),
(369,6,0,'你找到那种夜行蜘蛛的毒液了吗，$N？这是我的实验所必需的最后一种成分了。',12340),
(370,1,0,'年轻的$C，你不应该在你的同胞们需要你为他们的生存而战时躲在布瑞尔这里浪费时间。现在就动身吧，带上你的武器，到西南方的废塔那里去干掉派瑞恩队长、3名血色十字军狂热者和3名血色十字军传教士。我们得把血色十字军像牲口一样赶在一起，然后一网打尽。',12340),
(371,1,0,'你的任务还没有完成，你怎么就回来了？或许你一点也没把这群正在搅乱黑暗女王陛下计划的愚蠢人类放在眼里？如果不是的话，你就应该听从使命的召唤，去杀死瓦松队长和他手下的血色十字军苦行修士！',12340),
(372,1,5,'你还没有去履行你的职责，$c。只要血色十字军继续牵制着我们的士兵，我们就根本没办法指望黑暗女王陛下的计划能够得到良好的执行。杀了他们，向希尔瓦娜斯大人证明你的价值！',12340),
(373,0,0,'嗯？我能帮你做些什么吗？',12340),
(374,6,0,'你收集到10枚血色十字军徽记之戒了吗，$c？',12340),
(375,0,0,'你找到五张夜行蝙蝠的毛皮和粗线了吗，$N？',12340),
(376,0,0,'在我给你装备之前，千万别不小心挂掉了。',12340),
(377,5,5,'让迪克斯特·瓦德这样骚扰死者的恶棍活下来，就等于背叛正义。你去执行埃伯洛克大人的判决，杀掉瓦德之后再回到我这儿。我们可以还给被盗墓的死者的家属一个公正的结果，而且还可以把这个消息传达给暴风城的贵族议会，让他们好好颜面扫地一次。',12340),
(378,1,1,'我可不想让那群愚蠢的人类官僚介入到我们矮人的内部事务里来，$N。卡姆·深怒是萨多尔大桥惨案的同谋者，证据确凿。麦格尼国王的许多善良臣民都因他而死，人类也许早就把这件事给忘了，让那个刽子手在监狱里安度晚年，但我一想到这个混蛋还活着，就寝食难安！',12340),
(379,6,6,'怎么样，那些游牧民有没有“自愿”把废土水袋交给你呢？',12340),
(380,1,0,'小心蜘蛛的毒液，$N。如果你感到有强烈的灼烧感，就要看看自己身上是不是已经被蚀出个洞来了。',12340),
(381,1,0,'那些笨蛋……他们只会自掘坟墓，却从来都乐此不疲。',12340),
(382,6,0,'你的任务完成了吗，$N？',12340),
(383,0,0,'你有什么事？',12340),
(384,1,1,'我需要六根峭壁野猪肋排和一杯狂想麦芽酒，$N。',12340),
(385,6,6,'我有没有跟你说过有一次我差点被鳄鱼咬死的事情？那个恶心的东西，牙齿象刀一样锋利。不过我很幸运……我把刀子插进了它的嘴里。现在我还总是随身带着那把刀……',12340),
(386,6,6,'你到暴风城监狱里去了吗？我怕万一塔格尔耍了什么手段而侥幸逃生，早晚他会被放出来。他被判处了死刑，$N，现在他只是因为某个贵族的小算盘而暂时保全性命。',12340),
(387,1,5,'监狱里的叛乱依然没有平息！我们得让这群迪菲亚老鼠知道，我们是绝不会容忍他们的行为的。现在，快去让他们见识见识我们的实力！',12340),
(388,6,6,'你回来了，$c。你从监狱里的那些迪菲亚人渣身上取得10条红色毛纺面罩了吗？',12340),
(389,1,0,NULL,12340),
(391,6,6,'要么你把斯雷德的首级带来，要么我取你的，明白吗，$N？',12340),
(392,6,6,'你找我吗，$N？你有什么发现？',12340),
(393,6,6,'你好，我能为你做些什么吗，$C？',12340),
(394,1,0,NULL,12340),
(395,1,0,NULL,12340),
(396,6,6,'$N，对吗？巴隆斯·阿历克斯顿已经告诉我你会前来。我得说，我对你要说的话非常有兴趣。',12340),
(397,1,0,'嗯？',12340),
(398,6,0,'嗯？',12340),
(399,6,6,'$N！你的运气如何？',12340),
(400,0,0,'嗯？要成为一个攻城机具的驾驶员，恐怕你还太年轻了。不过没关系……你需要修理什么东西吗？$B$B到后面慢慢排队去吧。我正忙着修理两部攻城机具，这几天恐怕都没工夫。$B$B哦，你不会是有别的事情吧……？',12340),
(401,1,0,'',12340),
(403,1,0,'',12340),
(404,0,0,'你完成了我委托给你的任务了吗？拿到那些腐烂的爪子了吗？',12340),
(405,0,0,'你好。你要么不知道我是谁，要么就是你找我确实有急事，对吧？$b$b如果这两者都不是的话，你就太蠢了，竟然敢打扰我……',12340),
(407,5,0,'离我远点，你们这群愚蠢而邪恶的东西！愿圣光保佑我！我们伟大的血色十字军一定会把你们……这群垃圾清出艾泽拉斯……$b$b……噢，等等。那是要给我吃的东西吗？我真的好饿好饿……',12340),
(408,0,0,'时间紧迫，$N。天灾军团在提瑞斯法林地的势力分分秒秒都在不断壮大。',12340),
(409,1,0,'我期待着你向我证明你的忠诚，$c。',12340),
(410,1,0,'这是一张古老、结实、满是血迹的桌子。',12340),
(411,0,0,'把书还给冈瑟尔了吗？他说了些什么？',12340),
(412,0,0,'只要有充足的多档齿轮和自适应齿轮，自动净化器就能很快运转起来。',12340),
(413,3,0,'你好，$C！是哪阵风把你吹来啦？$B$B我希望你给我带来的是一些令人振奋的东西。我已经很久没有好好战斗了，而且这桶麦芽酒也都快要干了……',12340),
(414,2,0,'你好，$C，欢迎来到塞尔萨玛！',12340),
(415,1,0,NULL,12340),
(416,6,6,'你好啊，$N。进行得怎么样了？',12340),
(417,6,6,'你好，$N。你有我朋友莫里·铁砧的消息吗？',12340),
(418,6,6,'我已经准备好要做血肠了，你把原料拿来了吗？',12340),
(419,1,0,NULL,12340),
(420,1,0,'你好啊，要喝一杯吗？这大冷的天，除了喝酒还能干什么呢？',12340),
(421,1,1,'如果你想向我证明自己的能力，就必须先杀死5只月怒白头狼人。完成这件任务之后，我将视你的能力来为你指派下一步的任务。',12340),
(422,1,1,'在我知道我们在跟什么样的敌人作战之前，$C，我得先得研究一下《阿鲁高的拯救》。把它给我带回来，不然我就只好找个更能干的手下了。',12340),
(423,0,0,'在我了解当前的形势并策划出一个用以对付阿鲁高的最终解决方案之前，我先得需要一些暴食者镣铐和黑暗之魂镣铐以作研究之用。赶快去执行你的任务，杀掉月怒暴食者和月怒黑暗之魂狼人，直到你收集齐了我要的东西为止。',12340),
(424,6,6,'你干掉苍白的格瑞姆森了吗？如果我们没有完成瓦里玛萨斯大人下达的命令，他一定会不高兴的。',12340),
(425,0,0,'你杀掉邪恶的伊瓦了吗？如果你不愿意为我和我哥哥做这件事，就为被遗忘者做这件事吧。',12340),
(426,0,0,'与天灾军团的全面战争已经开始了，$N。尽你所能将那群巫妖王的傀儡全部赶回瘟疫之地去！',12340),
(427,1,0,'如果你想在黑暗女王面前证明自己，就去杀掉10名血色十字军战士，$C。',12340),
(428,1,0,NULL,12340),
(429,0,0,'我的时间紧迫，$c，黑暗女王交给了我一件极其重要的任务。',12340),
(430,6,0,'我妹妹说你是来帮助我们的。这是真的吗？',12340),
(431,1,0,'木箱中整齐地摆放着一排诱灵蜡烛，你得从中取出一支来召唤莉莉丝·奈法拉。$B$B你要拿起一根蜡烛吗？',12340),
(432,1,15,'太难过了！呜呜呜！',12340),
(433,1,0,'如果我们能把古博拉采掘场里的穴居人赶走，这将会是，我们完全解决这个威胁所需探取的诸多步骤中的第一步。',12340),
(434,1,0,'怎么样了，$N？泰里恩那边一切顺利吧？他赞扬了我对形势的正确把握，另外我已经帮他把马尔松骗到了皇宫里。$B$B暴风城里的很多人都讨厌马尔松，而且这些人中的大部分都是我的好友。没有人敢惹我的朋友……除非他不想活了。$B$B可惜的是，肖尔和军情七处会因此得到不少好处，不过并不是每个计划都能做到十全十美的。',12340),
(435,1,0,'请说得尽量简短点。这太危险了，我们可没法站在这里悠闲地聊天。',12340),
(436,1,0,NULL,12340),
(437,0,0,'你击败了奈塔拉什了吗，$N？我们若要成功地击败腐皮豺狼人，就必须先干掉这个女妖。',12340),
(438,1,0,NULL,12340),
(439,0,0,'$N，你回来了。你的调查有结果了吗？',12340),
(440,0,0,'你好，$N。来布瑞尔有什么事吗？',12340),
(441,6,0,'我认识你吗？',12340),
(442,0,0,'我们不能容忍天灾军团的势力占据银松森林的任何一寸土地，$N。杀死图勒后再回来找我。',12340),
(443,0,0,'你搞到腐皮豺狼人的脓液了吗，$N？',12340),
(444,0,0,'我得完全集中精力才能进行研究。所以你最好别为些琐碎的事情打扰我。',12340),
(445,6,0,'找我有什么事吗，$C？',12340),
(446,0,0,'你好，$N。比索说了些什么？',12340),
(447,66,66,'你好，$C。你来拜访皇家药剂师协会有什么事吗？',12340),
(448,1,0,NULL,12340),
(449,0,0,'你找到那两个亡灵哨兵了吗？',12340),
(450,1,1,'你回来了，$N。',12340),
(451,6,6,'来幽暗城有什么事，$N？',12340),
(452,1,0,NULL,12340),
(453,5,0,'你是谁？别过来！',12340),
(454,1,0,NULL,12340),
(455,1,0,'你是从洛克莫丹来的？奥加兹隘口那边的兽人有什么动向？',12340),
(456,1,1,'还有活儿没干完呢，$N。等你削减了夜刃猎豹和草刺野猪的数量后再回来找我。',12340),
(457,25,25,'你的活儿没干完呢，$N。等你杀掉了7头癞皮夜刃豹和草刺野猪后再来找我。',0),
(459,0,0,'为了证明我的怀疑，$N，请交给我8块魔苔。',12340),
(460,1,0,'这坟看起来像是随便挖的。',12340),
(461,1,0,'就是这儿！没错！让我靠近点！',12340),
(463,1,0,NULL,12340),
(464,0,0,'你与龙喉兽人交战过了吗？',12340),
(465,1,0,'那些投石车正等你呢，把它们烧成灰烬！',12340),
(466,0,0,'矿石在哪儿，$N？！',12340),
(467,1,0,NULL,12340),
(468,1,0,NULL,12340),
(469,1,0,'欢迎光临，$C。你想要点什么？一双合脚的靴子，还是一些上好的皮革？',12340),
(470,0,0,'你找到我的包了吗？',12340),
(471,18,18,'那可怜的小家伙对我来说就跟亲儿子一样。他只剩一条腿了，这让他以后可怎么活呀。$b$b啊，$N，事情怎么样啦？搞到那些皮了没？',12340),
(472,1,0,NULL,12340),
(473,1,0,NULL,12340),
(474,0,0,'你杀掉纳克罗什了吗？',12340),
(476,0,5,NULL,12340),
(477,1,0,NULL,12340),
(478,0,0,'你有什么发现吗，$N？',12340),
(479,0,0,'我们必须迅速行动，彻底破坏掉他们的计划，否则，我们将失去整个银松森林的控制权。',12340),
(480,0,0,'动作快一点，$N！我们没多少时间了！',12340),
(481,0,0,'怎么，$C？这是什么？',12340),
(482,1,0,NULL,12340),
(483,1,0,'如果我们不能从西边的班奈希尔兽穴寻回唤醒圣物，$N，那么猛禽德鲁伊们就将永远困在翡翠梦境中。$b$b我们每耽搁一分钟，他们就更多一分危险。',12340),
(484,6,6,'$N，怎么样啦？带回鳄鱼皮了没？',12340),
(485,1,0,'发现目标！你赫然看到石头上躺着一只……机器小鸡？！从机器小鸡中传出了声音：$b$b“太好了，你干得不错！这确实是我的母体，根据我的检测判断，它需要进行一定的启动动作才能够重新飞回藏宝海湾进行修理。请把定向器放到母体机器人里，剩下的它自己会去搞定！”',12340),
(486,1,0,'在痛击者厄萨被杀之前，我们的同胞无法被唤醒，$N。',12340),
(487,1,5,'道路仍然很不安全，$c。去杀掉6个瘤背伏击者，然后再回来向我报告。',12340),
(488,0,0,'你有没有像小蜜蜂一样忙碌，$N？我一直在等你拿来我需要的东西。',12340),
(489,4,0,'你给我带什么来啦，$N？我猜是份可口的点心？',12340),
(491,0,0,'$N，你战胜图勒·鸦爪了吗？',12340),
(492,14,0,'要是我手里拿着我那杆步枪，你们就都得去死，$C。我们的蒸汽坦克旅马上就要来救我啦！',12340),
(493,6,0,'你有东西要给我吗？',12340),
(494,1,0,NULL,12340),
(495,1,0,NULL,12340),
(496,1,1,'你回来了，希望你已经找到了我要的药剂。要是再不弄死些什么人，我就会闷到发狂的。',12340),
(498,1,0,'你得快点行动，$C。一想起人类会对德卢尔和托格萨做些什么，我就浑身发抖。',12340),
(499,1,0,'呱呱！',12340),
(500,0,0,'$N，你还在猎杀食人魔吗？找到我要的指节骨了吗？',12340),
(501,1,1,'我记得你，$N。你本要帮我调制最新的药剂。在我能把我独有的苦难带给希尔斯布莱德的居民之前，我需要那份血。',12340),
(502,1,0,'汪汪？',12340),
(503,0,0,'把钥匙给我，$C，让我自己来开锁。',12340),
(504,1,0,'你还得杀更多的好战者，$N。你得爬到山上完成任务，而不是收着武器站在山下。',12340),
(505,1,0,'你已经杀掉那些辛迪加刺客了吧？',12340),
(506,1,0,NULL,12340),
(507,1,0,'你……想要什么？',12340),
(508,6,0,'$N，你回来了？任务完成了吗？',12340),
(509,6,6,'在奈杉德岗哨的进展还顺利吗？',12340),
(510,0,0,'$N，你看起来很焦急。有什么要告诉我的吗？',12340),
(511,6,0,'你好，$G先生:女士。你找我有什么事吗？',0),
(512,0,0,'你一直在追捕辛迪加吗？拿到戒指了吗？',12340),
(513,5,0,'你看不见我正忙着吗，$C？黑暗女王坚持要在诺森德来的天灾军团压倒我们之前再制造一场瘟疫。南方的人类越来越有威胁，时间对我们来说是最宝贵的东西。你最好不是要拿什么鸡毛蒜皮的事情来烦我！',12340),
(514,6,0,'是南海镇的迪布斯让你来的？那个老书呆子现在怎么样了？',12340),
(515,1,1,'很高兴看见你回来，$N。我在这儿快闷死了。连一丁点有意思的事情都没有，每天都是制造毒药，把毒药喂给乌比，然后复活它……不断地重复再重复……$b$b你的幽暗城之旅怎么样？一路上有没有杀几个人类解闷啊？',12340),
(516,1,0,'你找到他们的巢穴了吗，$n？时间紧迫！',12340),
(517,1,1,'在塔伦米尔这儿待久了，我常常会感到厌烦，总是忍不住想要打开装满酒精的瓶子，让这股芳香在空气里飘荡，虽然这气味让乌比有点紧张。$b$b你能从矮人那儿弄一瓶酒回来吗？如果无法让什么人喝下这瓶完美无缺的致命毒药的话，我肯定会疯掉的。',12340),
(518,1,0,'你的任务还没有完成，$N。我要不要把你不称职的表现报告给沙琳德拉呢？',12340),
(519,1,0,'提他们的头来见我，$N，否则就提你自己的。',12340),
(520,1,0,'我已经拿到三颗脑袋了，还需要第四颗。要么是玛格索尔的脑袋，要么就是你的，$N。我说到做到。',12340),
(521,1,0,'什么？你有什么要报告的？',12340),
(522,0,0,'你怎么气喘吁吁的，有什么要报告的吗？',12340),
(523,0,0,'瓦杜斯男爵派刺客来对付我们南海镇，但是他别指望能逃过正义的惩罚。把他的脑袋提来见我！',12340),
(524,1,0,'地毯上传来一股发霉的味道。',12340),
(525,0,0,'$N。你又去长途旅行过了吗？带回什么消息了？',12340),
(526,1,0,'你找到足够的光铸铁锭了吗？',12340),
(527,1,0,'我是塔伦米尔的指挥官，受瓦里玛萨斯和黑暗女王的直接领导。你必须听从我的命令。$B$B你有没有任何帮助联盟的举动？如果有的话，我会把你就地正法。如果没有，那就往西边去到希尔斯布莱德镇，按照我的命令向人类作战。$B$B你可以退下了。',12340),
(528,1,0,'你有要务在身，$c，不要像无头苍蝇一样在塔伦米尔闲逛，其他地方还有很多事情等着你去做呢。',12340),
(529,6,6,'你完成了我的命令没有，$C？你除掉铁匠维林坦和他的助手了吗？还有，我要的铁在哪儿呢？',12340),
(530,6,6,'你砍下他的手了吗，$N？',12340),
(531,11,0,'干得好，$N！这家伙被吓坏了！把这颗头给我吧，我来处理。',12340),
(532,6,6,'你干得怎么样了？',12340),
(533,6,6,'你找到什么了吗？我担心高迪尔的处境会一天比一天糟……',12340),
(535,1,0,'你是来给我送些喝的呢，还是回来结果我的？',12340),
(536,1,0,'再给我来瓶麦芽酒，刚才那瓶跟没喝似的！$B$B圣光啊，我还得困在这儿多久？$B$B哦，是你呀，$N。你杀掉那些鱼人了吗？',12340),
(537,0,0,'你找到阿古斯复苏的特使了吗？',12340),
(538,1,0,'你好！你一看就不是本地人，是个修行中的学徒吗？',12340),
(539,1,0,'你已经接到了攻击碧玉矿洞的命令。现在你最好为你在塔伦米尔整日闲逛找出合适的理由，否则我就以叛国罪将你斩首。',12340),
(540,6,6,'我也想自己到奥特兰克废墟去，不过我这把老骨头恐怕已经不能爬山了。你寻找书籍的进展如何，$N？',12340),
(541,1,0,'丹加洛克对你而言应该是个很棘手的要塞吧，$C？我认为你在希尔斯布莱德的英勇表现已经很值得认可了。$B$B如果你不能胜任我交给你的任务，我就会去找个能完成任务的人。至于你嘛，我想黑暗女王在提瑞斯法林地那边还需要更多的掘墓工。',12340),
(542,6,6,'$N，你回来了！在奥特兰克的进展如何？找到什么东西了吗？',12340),
(543,1,1,'你好，$N。小心别踩在我的外套的下摆上，这身套装可是刚做的。',12340),
(544,0,0,'你找到那些小偷了吗？你拿回他们偷走的东西了吗？',12340),
(545,1,0,'你去消灭达尔然遗迹周围的巡逻队了吗？',12340),
(546,6,6,'幸运的$N凯旋了？你今天干掉了多少个人类？我猜有几百个吧！$b$b有没有给我收集颅骨？',12340),
(547,6,6,'你拿回我的剑了吗，$N？如果指挥官达萨利亚知道我这么蠢，一定会把我吊死的。',12340),
(549,1,0,'除了在这儿站着，你就没什么别的可以做的了，$c？作为一个指挥官，我还有很多重要的事要做，没闲工夫对着你这张坑坑洼洼的脸打发时间！',12340),
(550,1,0,'是什么事让一个$C大老远地从战场上跑到幽暗城里来？',12340),
(551,6,0,'哦，你应该有些要给我看的东西，对吧？是不是从山上找来的文献？',12340),
(552,6,6,'你找到赫尔库拉的魔棒了吗？这一带有很多雪人，很难找出是他们中的哪一个拿了魔棒。不过不管怎么样，我们必须把赫尔库拉的魔棒拿回来才能继续。',12340),
(553,1,0,'赫尔库拉的墓地中充满着神秘的能量。',12340),
(554,6,0,'又来打扰？$B$B啊，这卷羊皮纸上覆着一道极其复杂、编织精细的法术。我当然能解开它，但那需要时间。而时间对我来说非常宝贵……$B$B或许我干脆直接从你手上买下来？',12340),
(555,6,6,'找到原料了吗？告诉你吧，这里已经不像原来那么平安了。哎，如果这些动荡从来没有出现过该多好……',12340),
(556,0,0,'找到石雕了吗，$N？魔导师很想揭开其中的奥秘。',12340),
(557,0,0,'你好啊，$N。元素生物是很难对付，不过我知道你肯定可以胜任这个任务。你拿到地缚护腕了吗？',12340),
(558,0,0,'有一天我要成为吉安娜·普罗德摩尔一样的英雄……好吧，一个男生英雄好了。',12340),
(559,0,0,'你为我拿到那些鱼人的头了吗，$N？',12340),
(560,0,0,'你好，市民。你是来为维护南海镇的安全出一份力的吗？',12340),
(561,1,0,NULL,12340),
(562,0,0,'我有一封信要交给暴风城的萨缪尔森少校，但首先我得有战功才行。',12340),
(563,1,0,'你好，市民。暴风城卫队有什么可以效劳的吗？',12340),
(564,1,5,'山地狮隔三岔五地捕食我们的马，而你只管站在这儿聊天吹牛。$B$B要想证明自己是个真正的英雄，你就少说些废话多做些实事吧。',12340),
(565,94,94,'你回来见伟大的巴图罗了。是不是已经找齐了做雪人毛皮披风所需的材料？要不然就是你专门来称赞我巴图罗的伟大？',12340),
(566,6,6,'啊，$N。你是不是杀掉了瓦杜斯男爵来拿赏金的？',12340),
(567,1,0,'嗯？',12340),
(568,1,0,'我们的补给线仍然经常受到这些凶猛的迅猛龙的攻击，$c。',12340),
(569,1,6,'你有没有到米札废墟去收拾那些巨魔啊，$C？',12340),
(570,6,6,'有什么好消息吗？',12340),
(571,6,6,'运气怎么样啊，$N？找到合适的肌腱了吗？',12340),
(572,6,6,'你收集到足够的材料了吗？',12340),
(573,6,6,'我差不多已经准备好了，你达成我的要求了吗？',12340),
(574,1,0,'尤瓦中士告诉我你非常勇敢，而且很有作战经验，$C。你有什么要向我报告的吗？',12340),
(575,0,0,'其它的东西我早就准备好了，$n，就差那些皮啦。我们可不能让雷德沃克斯等太久，对吧？$b$b要是让这位技工协会的首席发明家等得不耐烦了，我可要吃不了兜着走啊。',12340),
(576,3,3,'嗨，我的好伙计！也许我看不见，但隔着半个港口我就能闻到你。$b$b真希望能要回我的眼睛。船长要是知道我的眼珠落在那帮肮脏的血帆海盗手里，非把我拖到船底去不可。$b$b一个看不见东西的瞭望员有什么用？了望台曾经是我的家……没有这双眼睛，我大概只配去刷船底。',12340),
(577,1,0,'崔斯里克的刨花皮靴，最好的做工，百分之百海鳄皮。没什么比这更好的啦！$b$b简直找不出合适的形容词来形容它，不是吗？$b$b还是说，你把那些皮带来给我了吗？',12340),
(578,1,0,'巨魔确实拥有一些十分神奇的魔法物品，$N。现在，没准我也有机会将这其中的一两件纳入到我那令人称羡的收藏品之中。你找到这条传闻的源头了吗？',12340),
(579,1,1,'瓦里安国王十分重视教育，他投入了很大一笔资金用于各种书籍卷册的抄录，并允许平民们自行抄录。很简单，你只需向我出示图书馆的阅览证，我就可以给你一本允许借阅的书的手抄本。',12340),
(580,5,5,'淹死我吧！我快要在这里醉死啦！船长要起锚，老斯利姆就得被丢在塔纳利斯沙漠里变成人干了呀。他要是发现他的酒没了……啊呀！',12340),
(581,0,0,'$C。给我血顶部族的獠牙，以此来证明你确实猎杀了他们。$b$b快把你的战利品给我看看。',12340),
(582,1,0,'$N。我一直在担心着我们酋长的儿子。你收集了多少个皱缩头颅供我检查？',12340),
(583,1,0,'嗯？',12340),
(584,1,0,'冒泡的大锅中装着满满一锅绿色的肉汤。',12340),
(585,0,0,'我等着你拿来那些头颅……',12340),
(586,1,0,'虽然我的眼睛鼻子耳朵全都给煮没了，但我还是能感觉到你在害怕。$B$B哈哈！你就是死也不可能完成这个任务……',12340),
(587,6,6,'运气如何？找到那些东西了吗，伙计？',12340),
(588,1,0,NULL,12340),
(589,1,0,'你弄到水晶了没有，$N？我们得到心灵之眼后要举行一个仪式，这些水晶是仪式必需的材料。',12340),
(590,1,0,'不错啊，朋友……干得真不错。',12340),
(591,1,0,'你好，$N。自我将你决定去对付麦佐斯的事情告诉了丛林之灵后，他们一直在歌颂着你的英勇与无畏。$b$b你拿到心灵之眼了吗？',12340),
(592,1,0,'$N。肯维雷告诉我你已经出发去对付耶尼库了。$b$b这是真的吗？你抓到他了吗？',12340),
(593,1,0,'耶尼库呆若木鸡地站在你的面前，他的意志仿佛在另一个世界里漂游……',12340),
(594,1,0,'我不慎被囚禁，这实在是愧对我的祖先与部族。除非有谁能帮我拿下这些镣铐，否则我没有任何逃离这里的希望。',12340),
(595,1,0,NULL,12340),
(596,0,0,'血顶部族总有一天会被我们暗矛部族彻底粉碎！你把他们的项链拿回来了吗？',12340),
(597,1,0,NULL,12340),
(598,0,0,'劈颅部族将我们拖入了战争中，他们定会遭到诅咒！你完成任务了吗？',12340),
(599,1,0,NULL,12340),
(600,0,0,'你弄到多少水晶啦？我需要它们！$b$b呃，其实我的意思是……我必须要确切地知道那邪恶的风险投资公司已经失去了在荆棘谷立足的根基。因为，你知道，我们这些老实人也得养家糊口啊！',12340),
(601,1,0,'进度如何了，$N？',12340),
(602,1,0,'我现在很忙，你有什么事吗？',12340),
(603,1,0,'你最好不是来挑战我的，你没听说过吗？我已经决定不再参加任何决斗了。',12340),
(604,6,6,'啊哈，$n。你从南边的血帆营地那里带回什么消息啦？',12340),
(605,0,0,'你拿到那些水晶碎片了吗？我会给你一笔丰厚的报酬的！',12340),
(606,25,25,'嘿，你看我干什么啊，$g小子:小姑娘！',12340),
(607,0,0,'你好啊，$N。拿到那病鬼的钱没？',12340),
(608,1,0,'有什么问题吗，$N？我们得在血帆海盗发起进攻前先下手！',12340),
(609,0,0,'$N，你找到那三条狗没？把他们身上值钱的玩意都抢过来没？',12340),
(610,1,0,'我以前从没有被打败过，你知道吗，$N？我的确被砍到了，斗刀的时候受点小伤是难免的，但他突然打了我一拳，正好敲在了我脑袋上，一下就把我给打晕了。等我醒来的时候我的匕首已经没了。$B$B正如我的绰号一样，我仍然需要一把匕首才能参加以后的战斗，而且，对我来说，那把匕首无疑是最好的。',12340),
(611,1,0,'你为我拿到海潮之石了吗，$N？我已经在我的收藏室里腾出了一块不错的地方准备用来摆放它了。',12340),
(613,6,6,'啊哈，$N！你找到玛雷的钥匙了吗？',12340),
(614,3,3,'你好啊，$N！你找到高拉什了吗？那箱子是我最喜欢的，里面有个小夹层，我最值钱的宝贝都藏在里面！',12340),
(615,1,0,NULL,12340),
(616,1,0,NULL,12340),
(617,0,0,'要是你不想和我进行交易，那就请便吧，$N。',12340),
(618,1,0,'把我的弯剑抢回来没有，$N？',12340),
(619,1,0,'这是一条已经被遗弃了很久的救生艇。小艇的两舷上布满了划痕，油漆的字迹已经显得很斑驳了：$B$B“斯莫特的复仇”',12340),
(620,1,0,'你好。你有什么事吗？',12340),
(621,0,0,'你拿到了赞吉尔的药剂了吗？',12340),
(622,1,0,'你好，$N。你去过藏宝海湾了吗？克拉兹克把我的锅修好了吗？',12340),
(623,1,0,'啥？',12340),
(624,1,0,'',12340),
(625,1,0,'',12340),
(626,1,0,'',12340),
(627,1,0,'你好啊，$N。你找到那些血石了吗？',12340),
(628,1,0,'我听说老海鳄正濒临灭绝……这对我来说真不是什么好消息，不是吗？$b$b尽管如此，我还是希望你能带张老海鳄的皮给我！',12340),
(629,0,0,'我正等着你带石板裂片回来呢，$N。',12340),
(630,0,0,'感谢祖先的英灵，终于有人来帮助我了。你拿到钥匙了吗？',12340),
(631,1,0,NULL,12340),
(632,6,0,'有老伊本瑟的信儿了吗，$N？',12340),
(633,1,5,'必须摧毁所有的爆裂物！',12340),
(634,1,0,NULL,12340),
(635,1,0,NULL,12340),
(636,1,0,NULL,12340),
(637,1,0,'$C，你看起来好像走了一段很长的旅程，而且并不平坦。这段时间里我们的灵魂都备受煎熬。你带来了什么消息？',12340),
(638,1,0,NULL,12340),
(639,6,6,'你找到第一块符印没有？它最有可能在激流堡城内的某个辛迪加成员身上。',12340),
(640,66,66,'（兽人语）你好，$c。森古告诉我你需要我的帮助。',12340),
(641,6,0,'$N！你拿到第二块符印了吗？',12340),
(642,0,0,'这簇水晶碎片很像密斯赖尔水晶碎片，但是却没有那种安全感。',12340),
(643,0,0,'$N，瓦罗卡尔不是那么容易就能找到的。他骑在马上，来去如风。不论如何，我们一定要得到他的符印。',12340),
(644,6,6,'$N，你回来了。托尔贝恩的防线崩溃了吗？',12340),
(645,1,0,'托尔贝恩墓室正面的墓碑上的雕刻与伊格纳乌斯符印表面闪闪发亮的线条完全吻合……',12340),
(646,6,6,'$N！你拿到剑了吗？',12340),
(647,6,6,'有什么好消息，$R？',12340),
(648,1,0,'没错，我就是奥格索普·奥布诺提斯，世上最强的发明家，随时为您效劳！现在，我能帮您什么忙吗？',12340),
(649,1,0,NULL,12340),
(650,1,0,NULL,12340),
(651,1,0,'这里是内禁锢之石，它是所有禁锢之石中最坚固的一块，必须先于其它三块解开。',12340),
(652,1,0,'钥匙之石充满了巨大的能量。',12340),
(653,1,0,NULL,12340),
(654,5,5,'怎么样，你得到你要的东西了吗？如果你在能量耗尽之前没有完成的话，里面存储的所有东西都会消失，你就不得不重新来过。$B$B嘿，不要老是可怜巴巴地看着我。我的职责就是为加基森水业公司创造利润，我的目标就是不断把能量源卖给你，直到我们能够负担得起把丹莫罗的冰水引到塔纳利斯沙漠的工程为止！就这样吧！',12340),
(655,1,0,NULL,12340),
(656,1,0,'现在，密斯赖尔水晶碎片出奇地安静。',12340),
(657,1,0,NULL,12340),
(658,1,1,'感谢你帮我们找到了那个信差，$N。$B$B你走了以后，基恩洛看见有一个药剂师走出那间房子朝南边去了。我确信他们不会是在做什么好事——但是我可不想草率行动，所以首先，我们得有一些确切的证据。$B$B怎么样，你要不要帮忙？',12340),
(659,1,0,'希尔斯布莱德到处都是一片混乱，这让我十分担心。$B$B在我转至侦察的同伴回来以前，我是不会离开这儿的。',12340),
(660,1,0,'现在不是聊天的时候。为了希尔斯布莱德的所有人民，请你一定要保护好基恩洛。',0),
(661,1,0,NULL,12340),
(662,0,0,'你的打捞工作进行得如何了，$n？我们必须从处女号和银松之灵号里取回那些航海图和日志。$b$b如果那些宝贵的资讯落入敌人手里，舰队指挥官绝对会让我们吃不了兜着走的。$b$b更确切的说，这关系到我们能否从现在的糟糕处境中摆脱出来。',12340),
(663,1,0,NULL,12340),
(664,1,0,'呀，也许我应该亲自去手刃那些该死的纳迦！显然，你是不会去做这个的。$B$B也许我该给你找些针线活，让你不至于太清闲。',12340),
(665,1,0,'没时间细说了！潜水镜需要注入魔石的力量才能工作！',12340),
(666,6,6,'潜水镜用得如何？运转还算正常吧？如果需要的话，我可以对它们做一些调整。$b$b哦，如果你用完了，就把潜水镜还给我。我想奥布里船长很快就要用到它了。',12340),
(667,1,0,'准备作战！',12340),
(668,0,0,'嘿，$C。是哪阵风把你吹到这里来的？',12340),
(669,6,0,'是哪阵风把你吹到藏宝海湾来了，$C？',12340),
(670,1,0,'海角给你留下的印象不错吧？我跟你打赌，他一笑起来，那张嘴能从藏宝海湾一直咧到棘齿城去！',12340),
(671,0,0,'我们曾经为恶魔的诅咒付出了极大的代价，$N。如果有人……或者有什么东西又在召唤恶魔的话，我们就一定要阻止它。',12340),
(672,0,0,'我要打造一枚护符，它能给戈莫尔带来一些迅猛龙的力量。也许那样能够唤醒他体内的火焰……',12340),
(673,0,0,'我血液中的灼烧感与日俱增……我们必须阻止这个术士。',12340),
(674,0,0,'如果连一个懦夫也能杀死英雄中的英雄，希望在哪里？我问你，希望在哪里？',12340),
(675,1,0,NULL,12340),
(676,1,5,'我连磨斧头的时间都没有，更别说离开前哨去杀那些想杀我族人的野兽。$B$B你看起来连步兵的经验都没有，更别说正式战士了，你想要什么，$N？',12340),
(677,1,25,'如果你还没有完成我交给你的任务，那你也许是个懦夫加菜鸟。',12340),
(678,1,6,'你在犹豫，为什么？$N，你已展示了强大的力量，不要让我失望。',12340),
(679,1,0,'我看你的勇气最终还是消退了。我的直觉似乎是对的：你一直都是在虚张声势而不具备真正的实力。$b$b要嘛带着野兽的头颅回来见我，要嘛就永远都别回来。',12340),
(680,0,0,'奥卡拉尔就在阿拉索之塔附近出没。杀掉他就能阻止巨魔对落锤村的袭击，也能保住我丈夫的生命。$B$B你的眼睛告诉我，在你的心中已经认定我是个软弱甚至不光彩的懦弱者，因为我过于沉默。但是总有一天，你会理解我所做的一切的。也许到那时，你就会理解一种不同于以往的力量与荣耀。$B$B请按我说的去做，杀了奥卡拉尔。',12340),
(681,1,0,'$N，我们对于激流堡的控制力正在迅速下降。你必须加快行动速度，否则我们的城市必定会陷落。',12340),
(682,0,0,'$N，你取回了激流堡徽章了吗？要让辛迪加明白，他们绝对没法从我们阵亡的士兵那里得到任何好处。',12340),
(683,6,0,'你是$C$N？你对联盟作出的贡献已经众所皆知了，你知道吗？$B$B你今天来找我有什么事吗？',12340),
(684,6,6,'你好，$C。有什么要报告的吗？',12340),
(685,6,6,'你好。有什么事要报告吗？',12340),
(686,1,0,NULL,12340),
(687,1,0,NULL,12340),
(688,1,0,NULL,12340),
(689,5,5,'$N，$N，$N！你有没有拿到足够的奥特兰克花岗岩让我为苏利·巴鲁建纪念碑？',12340),
(690,5,5,NULL,12340),
(691,6,6,'$N，你弄到我要的东西了吗？$B$B<克里汀一边念念有词，一边在他的日记本上作了些笔记。>$B$B如果我的研究工作是正确的话，那么你可以在枯木巨魔身上找到獠牙，在枯木巫医身上找到医药包，而最强大的枯木暗影猎手应该随身带着小刀。不过，只有当你和他们战斗之后，才能知道哪个暗影猎手拥有一把小刀。',12340),
(692,5,5,'你找到那些卷轴的碎片没有？！如果你想重新禁锢她的话，就早点去找吧，否则就太迟了！',12340),
(693,1,1,'我们的目标是魔杖，$N。你要想尽一切办法把它拿回来。',12340),
(694,6,6,'$N，你好呀，又见面了。你找到碧蓝玛瑙石了吗？',12340),
(695,1,0,NULL,12340),
(696,1,1,'干得好！马林一定会为你感到高兴的。',12340),
(697,6,6,'嗯？你看起来有些面熟。抱歉，我们是不是见过？我太忙了，所以有些健忘。',12340),
(698,66,66,'你好啊，$C。在沼泽地里旅行可不是什么轻松的事情呀，你能到这里来就足以说明你非常勇敢了。',12340),
(699,0,0,'上好的蜂蜜酒，温暖的营火，一队兽人战士和一库武器……这就是我们在这片海滩上最需要的东西了。尽管我一点都不后悔为了保卫斯通纳德而来到这里，但要是有个地堡或是哨塔该有多好呀。',12340),
(700,1,0,NULL,12340),
(701,0,0,'我的准备工作已经完成，现在只缺迅猛龙的心脏就可以开工了。',12340),
(702,0,0,'你又回来啦？的确，除了托尔甘的怜悯之外，我也不能再期望得到其他的什么了。$B$B你这次为我带来了什么？也许是一条颜色鲜艳的细绳？或者一条可以结束我悲惨命运的绳索……',12340),
(703,0,0,'嘿，$N。你带回秃鹫的翅膀了吗？',12340),
(704,6,6,'你找到那些罐子了吗，$N？我们必须找出它们与这些穴居人之间的联系！',12340),
(705,6,6,'你找到我需要的珍珠了吗？闪光弹快要用完了！',12340),
(706,6,6,'你的狩猎行动进展如何了，$C？',12340),
(707,1,0,NULL,12340),
(708,1,0,'什么？你说你找到了什么？',12340),
(709,5,5,'你找到石板了吗？它一定包含了什么秘密！可以拯救我们的秘密！',12340),
(710,6,6,'这个地区对于——你能拿着这些东西在这里站一会吗？对，就像那样，面向那边。嗯，我说到哪儿啦……哦，对，这个地区对于测试我的新项目来说实在是太完美啦。充足的原材料，开阔的空地……对于一个充满智慧和灵感的发明家来说已经是很棒了。',12340),
(711,0,0,'我真是太高兴了，$N。我的咒语对小石头碎块的作用效果和我期待的一致。如果这个实验如预期一样成功的话，我将能控制的元素生物会使任何在此之前召唤出来的任何元素生物都相形见绌。',12340),
(712,1,1,'你找来的石片简直太完美了，$N。在我们完成现在的任务之后，卢希恩会将剩余的石片带到卡拉诺斯去。它们应该还能在那里发挥一些作用。$B$B比方说，在我配制高爆爆裂物的时候，那些石片可是制作掩体的最佳材料……$B$B<鲁特维尔的声音越来越小，他又投入到了实验中。>',12340),
(713,6,6,'你找到我需要的冰霜之油了吗？那东西对我的研究很有帮助。',12340),
(714,0,0,'好，好，好，请等一下。$B$B<鲁特维尔又继续和他的小装置打交道去了。>',0),
(715,6,6,'他差不多接近完成了。你这边进展得如何？',12340),
(716,6,6,'$N，我不会为那个护腕而等待太长时间。$b$b天知道接下来会发生什么……',12340),
(717,1,1,'虽然很久以来黑龙的监狱一直被强大的魔法力量所保护着，但我们还是不能让布莱克拉什和赫玛图斯有任何逃脱的机会。',12340),
(718,1,1,'在沙漠里挨饿真是糟糕透顶，我的朋友，我跟你说……你知道那有多糟么？$B$B嘿……那是什么东西……',12340),
(719,1,1,'我不清楚暗炉矮人在找什么，但他们肯定有什么特殊的目的。',12340),
(720,1,0,NULL,12340),
(721,1,0,NULL,12340),
(722,1,1,'暗炉氏族……咳咳，非常危险，多加小心。咳咳，你必须尽快找到护符。',0),
(723,1,0,'我不得不说这是糟糕透顶的一天，不过在这糟糕透顶的地方，你还能指望有什么不糟糕的事情么？',12340),
(724,1,0,'啊，你好。又是一个来向我谘询的旅人。$B$B不过$G先生:小姐，真是对不起，我现在没时间来回答一些无聊的问题。',12340),
(725,6,6,'嗯？有什么事吗，$C？',12340),
(726,1,0,NULL,12340),
(727,3,3,'你好。欢迎到我的商店来，不过当心不要到处乱翻。$B$B有时候，知识也会是致命的。',12340),
(728,6,6,'啊，有一个$C急急忙忙地跑过来了，你到这里来是为了向我学点什么吗？很好！$B$B不过请注意:知识能给强者力量，也会让弱者变得癫狂。',12340),
(729,1,0,'',12340),
(730,1,0,'',12340),
(731,1,0,'勘察员雷姆塔维尔还活着吗？',12340),
(732,1,1,'这伙流浪的巨魔穿梭于荒芜之地的几个营地之间，这里到处肆虐的热浪和旋风让追踪他们的行动变得非常困难。',12340),
(733,6,6,'嗯，我已经尽力做了我可以做到的，不过……这还不够。你找到更多的物资了吗？',12340),
(734,1,0,NULL,12340),
(735,6,6,'你拿到我要的东西了吗？',12340),
(736,6,6,'你的任务进展如何，$c。',12340),
(737,6,6,'有些日子没见你了，拿到笔记了吗？',12340),
(738,1,0,NULL,12340),
(739,1,0,'你有关于阿戈莫德的消息吗？你找到他了吗？',12340),
(741,1,0,'我能为你做什么，$R？',12340),
(742,1,0,NULL,12340),
(743,1,0,'风怒鹰身人是我们的死敌，这些家伙顽强的作战能力和它们对新鲜血肉的强烈嗜好一样名声在外。',12340),
(744,0,0,'这个头饰无疑是给我兄弟的最好的礼物。',12340),
(745,1,0,'如果白鬃豺狼人尊重这片土地和这里的居民的话，这场冲突就不会发生了。',12340),
(746,0,0,'你好，$N。你带来损坏的工具了吗？矮人的挖掘行动会激怒莫高雷的科多兽，我们必须阻止他们这种玷污大地的行为！',12340),
(747,1,1,'为部族带回肉和羽毛是你在酋长面前证明自己的第一步。',0),
(748,6,6,'你拿到那些爪子了吗，$N？',12340),
(749,1,0,NULL,12340),
(750,1,1,'如果你能给部族带回这些皮毛的话，我会把你的功绩告诉我的父亲，鹰风酋长。',12340),
(751,1,0,'你好，$N。你知道风险投资公司准备在我们的土地上做些什么吗？$b$b如果他们像对待别的土地那样来开采这片土地上的资源，我们就一定要阻止他们。',12340),
(752,1,0,NULL,12340),
(753,6,6,'看来你是刚从平原那边回来的吧。你带我母亲的口信来了吗？',12340),
(754,1,0,'不要耽误时间，$n。冬蹄之井的污染一定要尽快清除！',0),
(755,1,0,NULL,12340),
(756,0,0,'$N，你找到我要的爪子了吗？雷角之井的污染已经越来越严重了！',12340),
(757,6,6,'你完成力量祭祀仪式了吗，$N？我要求你通过杀死部族之敌——刺背野猪人来证明你的英勇。',12340),
(758,1,0,'雷角之井的水仍未得到净化，$n。你必须马上完成净化仪式！',0),
(759,0,0,'你找到我要的牙齿了吗，$N？',12340),
(760,1,0,NULL,12340),
(761,0,0,'你找到猛鹫了吗，$N？拿到它们的羽毛了？',12340),
(762,1,1,'时间紧迫，$N。拉格纳罗斯不会给我们时间来准备的。',12340),
(763,6,6,'欢迎来到我的村庄，$C。',12340),
(764,1,0,'我们已经剥夺了风险投资公司在莫高雷的采矿权，不过看来他们根本不在意我们做了些什么。牛头人向来不喜欢拐弯抹角，我们有自己的方法来让他们了解我们的意图。',12340),
(765,0,0,'风险投资公司居然为了利益就准备对我们采取这些行动，这让我非常恼火。',12340),
(766,1,1,'我发烧发得越来越严重了，而且脑子也开始神志不清，不断做梦魇……我早该知道，我祖父对付不了的野兽我也肯定对付不了……$b$b你找到解毒药了吗？如果再不清洗染毒的伤口，我就死定了。',12340),
(767,1,0,NULL,12340),
(768,1,0,'你好。你的狩猎行动怎么样了？你拿到我需要的兽皮了吗？',12340),
(769,1,0,'你弄到我需要的材料了吗，$N？',12340),
(770,1,0,NULL,12340),
(771,1,1,'等你收集到水井周围的水井石和大树下的琥珀颗粒之后，我就可以为你准备先知之水了。',12340),
(772,1,0,NULL,12340),
(773,1,0,NULL,12340),
(775,1,0,NULL,12340),
(776,6,6,'你找到阿兰其亚了吗？',12340),
(777,0,0,'<鲁特维尔并没有从他对镣铐的研究中抬起头来，他只是伸出一只手，不耐烦地晃动着指头。>$B$B把齿轮给我，$N，齿轮！',12340),
(778,6,6,'这跟我预期的结果有些偏差……你能取回我的镣铐吗？',12340),
(779,1,0,'大地封印就在这儿，三个凹陷的壁龛分别对应着紫水晶符石、蛋白符石和星钻符石。',12340),
(780,0,0,'斗猪的数量正在不断增加。你有没有教训过它们？有没有带回猪头和肋排来？',12340),
(781,6,6,'你看起来脸色不太好，$N。你带来了什么消息？',12340),
(782,0,0,'索葛兰的背叛……你对于巨魔已经脱离部落的事实还有什么疑问么？如果他死了，我想我会很高兴的，那样的话我们就能重新夺回大地印章了。',12340),
(783,1,0,NULL,12340),
(784,1,25,'你已经接到命令了，$N。杜隆塔尔正处于危机之中。完成你的任务，否则就在羞耻中悬梁自尽吧。$B$B证明你的荣誉和勇气，击败提拉加德城堡的人类。',12340),
(786,1,5,'半人马一直都是部落的心头大患，我们决不能让他们的进攻计划得逞！',12340),
(787,1,0,NULL,12340),
(788,0,0,'我希望你在完成任务之前先不要回来找我，$N，好吗？不不，当然我并不怀疑你的能力。我对你还是抱有很大希望的。',12340),
(789,1,0,'对于一名有着坚定决心的战士来说，蝎子坚硬的表壳其实就像纸一样脆弱。不要犹豫，给那些蝎子以最沉重的打击吧，你会发现它们真的非常脆弱。',0),
(790,16,0,'啊……父亲经常说，我不会太出众，看来，他是对的，现在的我就只能这样躺在树下慢慢等死……$b$b但至少，我希望在我死之前能得知我的最后一个敌人也已经被干掉了……',12340),
(791,1,1,'在我们刚刚开始探索这片大陆的时候，我曾和大酋长肩并肩地奋勇作战，战争在我身上留下了累累疤痕。$b$b在击败阿克蒙德的战斗中，我以斧头和勇气维护了部落的荣誉，那时由于形势所迫，我们不得不和人类、暗夜精灵结成了联盟。$b$b不过现在我可以尽我所能地为部落效劳，这让我又找到了新的价值。',12340),
(792,1,1,'要想证明你的确选择了与火刃氏族为敌，那么你首先必须杀死那些邪灵劣魔。完成了这个任务之后再回来向我复命。',12340),
(793,0,0,'很少有敌人像龙那样可怕，也很少有龙像布莱克拉什和赫玛图斯那样残忍。',12340),
(794,0,0,'你完成任务了吗，$N？你把燃刃勋章带回来没有？',12340),
(795,1,0,'大地封印就在这儿，三个凹陷的壁龛分别对应着紫水晶符石、蛋白符石和星钻符石。',12340),
(804,1,0,NULL,12340),
(805,1,0,NULL,12340),
(806,0,0,'$N，你找到费索了吗？我们必须把费索和其它火刃氏族的余孽从我们的领土上清除掉！',12340),
(808,0,0,'你找到我兄弟的颅骨了吗，$N？他的灵魂自由了吗？',12340),
(809,1,0,NULL,12340),
(812,1,1,'我现在这个模样……不能回森金村去也许对我是好事……别人铁定会拿我这又蠢又弱的样子寻开心。',12340),
(813,1,1,'记住，无论你要狩猎的是什么生物，研究他们的习性都是必需，有时候，了解这些就有可能救自己一命。',12340),
(815,5,5,'早饭、中饭、晚饭！谁管到底是哪顿饭？反正最后都得有人来做吧？那还不就是我吗？！',12340),
(816,1,1,'我日夜不停地企盼着克伦回到我的身边，不过我几乎已经知道他遭遇了怎样的不幸……',12340),
(817,1,1,'我还记得我第一次去捕猎老虎时的情形，$N。我来到了回音群岛中最大的一个岛，在树丛中的阴暗处静静地等了一天，等待着……观察着……$b$b我的肌肉绷得紧紧的，随时都准备出击。当那只老虎终于咬上诱饵的时候，那是我最棒的胜利之一。',12340),
(818,1,1,'时间是对个人力量和意志的最佳检验。如果丧失耐心或向软弱屈服，你就无疑是个失败者。',12340),
(819,0,0,'嗯？',12340),
(821,0,0,'找到我要的东西了吗？',12340),
(822,6,6,'你找到那些原料了吗，$N？',12340),
(823,1,0,NULL,12340),
(824,1,0,'啊，你好。我花了大量时间来研究水，以及所有的元素——有时候我甚至对周围的事物浑然不觉。$b$b我能帮你什么忙吗？',12340),
(825,1,1,'只要我们能搞懂人类是如何使用那些奇特的机器的，我们将来就更有希望在战场上击败他们。$b$b这些新的知识会让部落变得更加强大。',12340),
(826,0,0,'你打败札拉赞恩了吗，$N？',12340),
(827,1,0,'你进入骷髅石洞了吗，$N？你拿到灼热项圈了吗？',12340),
(828,1,0,NULL,12340),
(829,2,2,'向您致以我最谦卑的致意，$C。我能帮您什么忙吗，我的$R$G兄弟:姐妹？',0),
(830,6,6,'你好像在担心什么事请，$C。你发现什么异常状况了吗？',12340),
(831,1,0,'你没看到我正忙着吗？没什么要紧的事情就别来打扰我……',12340),
(832,0,0,'你有很重要的事情要向我报告，我可以从你的眼中看得出来。',12340),
(833,1,5,'你必须把那些刺背干涉者驱逐出我们的神圣墓地，$n。',12340),
(834,0,0,'我当然能出色地完成我的工作，但是问题不在于我，这整件事情太可笑了！你想让我怎么办？坐在这里玩办家家吗？',12340),
(835,1,0,'你不会想到我的头儿加兹鲁维这样的人也会说这样的话，不过他总是高瞻远瞩。他说:“不要害怕采取行动。”$B$B如果我们不有所动作的话，鹰身人还会继续给我们制造麻烦，而商队还会不断受到袭击，对吧？',12340),
(836,1,0,'没错，我就是奥格索普·奥布诺提斯，世上最强的发明家，随时为您效劳！现在，我能帮您什么忙吗？',12340),
(837,1,0,'他们的确是有点头脑、有点组织，不过让我惊讶的是他们竟然能在卡利姆多占领这么多的领土。也许他们比我想象中的更狡猾……',12340),
(838,1,0,NULL,12340),
(840,15,0,'你想干什么，小子？如果不是来应征入伍的话，我可没时间和你应酬。',12340),
(841,1,0,'怎么样，你弄到十个水袋了吗？',12340),
(842,0,0,'哎呀，看看谁来了？卡加尔又帮我召募了个新兵吗？',12340),
(843,5,5,'巴尔莫丹矮人的到来让很多无辜的牛头人失去了生命，或者被迫离开了他们世代生活的家园。我们必须夺回自己的领地！',12340),
(844,6,6,'你收集到陆行鸟的喙了吗？你让它们血染贫瘠之地了吗？',12340),
(845,0,0,'你杀掉多少角斑马了？',12340),
(846,1,1,'你回来了，$N。$B$B卡兹戈姆的死也许会暂缓他们对这片土地的挖掘进程，但依然无法完全制止他们。$B$B为了保护挖掘场的安全，矮人军队也在不断进驻巴尔莫丹城堡，这已经对我们构成了严重的威胁。$B$B如果你找到了我需要的原料，我就能制造出威力强大的炸药来，让那些草率的矮人重新考虑一下他们在贫瘠之地的行动。',12340),
(847,1,0,NULL,12340),
(848,0,0,'$N，你找到这些孢子了吗？我必须制造一种药剂送给雷霆崖的同事，而这种药剂正需要这种孢子来配制……',12340),
(849,1,0,'矮人的飞行器被摧毁之后，我感到了一种极其甜美的复仇的快感。',12340),
(850,0,0,'你好，$N。你带巴拉克的头颅回来了吗？',12340),
(851,0,0,'$N，你找到维罗戈了吗？',12340),
(852,0,0,'$N，你打败赫兹卢尔了吗？',12340),
(853,0,0,'你从药剂师赫布瑞姆那里给我带来了一些东西？快让我看看。',12340),
(854,1,0,NULL,12340),
(855,0,0,'$N，你的任务完成了吗？',12340),
(857,5,5,'众月之泪在哪儿？我需要它！很需要！',12340),
(858,1,0,'快点，我们得在他们起疑之前逃出这里！',12340),
(860,1,0,NULL,12340),
(861,3,3,'你好，找我有事吗？',12340),
(862,6,0,'$n，找到足够多的掘地鼠了吗？',12340),
(863,1,0,'我能帮你吗？',12340),
(864,1,0,'欢迎回来。至少，如果你带回了我要的实验资料的话，我欢迎你回来。否则，我可不会浪费宝贵的时间来和你废话，你要做的就是尽快去完成我交给你的任务。',12340),
(865,0,0,'$N，你弄到赤鳞镰爪龙的角了吗？那些角会让我大赚一笔！',12340),
(866,1,0,'你好，$N。找到那些草药的根须样本了吗？',12340),
(867,0,0,'杀了足够多的鹰身人了吗？如果没有的话就继续和她们战斗，我要你给我带回来8只巫翼鹰身人的爪子。',12340),
(868,1,1,'小心不要弄碎了你找到的卵，$N。如果它们破了的话就没用了。',12340),
(869,0,0,'$N，你拿到那些迅猛龙的头了吗？',12340),
(870,1,0,'$n，你去过遗忘之池吗？有没有发现什么？',0),
(871,1,0,'野猪人的袭击行动越得不到遏制，我们就越难获得足够的补给。',12340),
(872,1,1,'只要杀了那些野猪人的头儿，他们就会立刻陷入混乱之中，$N。好好学着吧，这些手段对你的将来会大有帮助的。$B$B这些野猪人会像无头苍蝇一样到处乱撞，而那时我们就能趁机夺回贫瘠之地。',12340),
(873,0,0,'不要对大海有所畏惧，$R。',12340),
(874,1,0,NULL,12340),
(875,0,0,'你收集到6枚鹰身人首副官之戒了吗？她们频频袭击部落的恶行必须受到审判！',12340),
(876,0,0,'除非我看到塞瑞娜的脑袋，不然你什么也得不到。',12340),
(877,1,6,'你去过死水绿洲了吗？在死水绿洲的湖水下有地缝吗？',12340),
(878,1,0,'先去<猪哼声>杀了刺背部族中的那些精神领袖，然后我才会告诉你更多内幕，$R。<猪哼声>',12340),
(879,1,0,'$R，你的猎杀进行得如何了？<猪哼声>$B$B索克自以为他知道是谁领导了那些袭击行动，<猪哼声>但是你的成功会让他明白他是大错特错了。$B$B我的死亡是无可挽回的，但是你对我的敌人造成了巨大的创伤，所以我也就没什么可后悔的了。<猪哼声>',12340),
(880,6,6,'你拿到龟壳了吗？',12340),
(881,0,0,'那只狮王在召唤你，$N。',12340),
(882,0,0,'$N，你战胜伊沙姆哈尔了吗？',12340),
(883,0,0,'$N，从你的步伐中我看到了一种新的力量。告诉我，你的灵魂有没有与伟大的拉克塔曼尼进行碰撞？',12340),
(884,0,0,'$N，从你的目光中我看到了一种新的力量！你一定见过伟大的奥瓦坦卡了吧？',12340),
(885,0,0,'你有一种新的决心，$N。一种来源于痛苦的决心……$B$B你承受着瓦希塔帕恩之死的痛苦吗？',12340),
(886,1,0,NULL,12340),
(887,1,0,'我甚至不愿去核算我到底在历次的海盗袭击中损失了多少，现在他们居然敢在我的家门口扎营？形势有点失控，安德曼必须得采取一些行动了。',12340),
(888,1,1,'你找到我的东西了吗，$N？',12340),
(889,1,0,'给碎牙带10块血岩裂片回来，你就可以获得无人能敌的迅捷。你将像角斑马一样疾驰，就连风都会嫉妒你的速度。$B$B虽然这种效果的持续时间不会很长，但它也足以让你穿越广袤的贫瘠之地。',12340),
(890,0,0,'$N，你有什么要托运的吗？',12340),
(891,5,5,'呀，也许我应该亲自去手刃那些该死的纳迦！显然，你是不会去做这个的。$B$B也许我该给你找些针线活，让你不至于太清闲。',12340),
(892,0,0,'那么，迪兹维格怎么说？',12340),
(893,1,1,'我不相信落后的野猪人能发展出什么高超的锻造技术。不过，我会按大酋长的要求去做，向钢鬃部族学习任何可以学到的东西。$B$B我有很多需要劳力工作的工作经验，只要是对兽人有帮助的，我都非常乐意也很愿意。',12340),
(894,1,0,NULL,12340),
(895,0,0,'有什么事吗？我能帮你什么吗？有需要托运的货物吗？',12340),
(896,0,0,'只要我们知道是哪个矿工找到了翡翠，那么得到它就是轻而易举的事情了……',12340),
(897,6,6,'你看起来好像有什么麻烦，$N。你在贫瘠之地的修行进行得如何了？有什么事情在困扰着你吗？',12340),
(898,1,0,'嗯？',12340),
(899,1,1,'野猪人会为此付出代价，$N。我发誓。',12340),
(900,1,0,'控制台上闪烁的指示灯显示，主控制阀还没有关闭。',12340),
(901,1,0,'控制灯熄灭了，各种仪表都指向了零刻度，整台设备顿时停了下来。',12340),
(902,1,0,'哦，你回来了，$N！你找到主动式负载平衡器了吗？',12340),
(903,0,0,'你的狩猎行动进行得怎么样了，$N？找到徘徊者了吗？',12340),
(905,1,0,'找到它们的巢穴了吗，$N？',12340),
(906,6,0,'怎么啦？',12340),
(907,0,0,'那些雷霆蜥蜴被击败了吗，$N？',12340),
(908,1,0,'你找到深渊之核了吗？没有它的话，我们就无法得知暮光之锤究竟在那里做什么。',12340),
(909,1,0,'啊，又见面了，$N。我正在像往常一样观察海洋的波涛。什么风把你吹到这里来了？',12340),
(910,1,0,'我们到了吗？',12340),
(911,1,0,'我们到了吗？',12340),
(913,6,6,'任务完成了吗？你杀掉雷鹰了吗？',12340),
(914,6,6,'尖牙德鲁伊的狰狞面容仍然在我的梦魇中萦绕，$N。你拿到他们的宝石了吗？',12340),
(915,1,0,'我希望他们除了草莓冰淇淋之外还能做出更多口味的冰淇淋，但是还好我最喜欢的就是草莓口味！',12340),
(916,6,6,'你收集到毒囊了吗，$N？',12340),
(917,6,6,'你去过影丝洞了吗，$N？你找到蜘蛛卵了吗？',12340),
(918,6,6,'你弄到种子了吗？我急切地想要种下它们。',12340),
(919,3,3,'你好，$N。湖水周围有新芽吗？',12340),
(920,0,1,'怎么啦？',12340),
(921,1,1,'月亮井里的水源自永恒之井，这个蕴涵着强大的魔法能量的古代源泉曾给我们的世界带来的巨大的恐慌。$B$B德鲁伊们充分利用月亮井的特性来修行，而哨兵们则将它视为月神艾露恩的祭坛，但是无论是谁，都不许再使用魔法。',12340),
(922,2,0,'你好……$b$b请问你有事吗？',12340),
(923,3,3,'$N，你去过涌泉湖了吗？你干掉那些树精了吗？',12340),
(924,1,0,'恶魔之种仍然存在，我能感受到它的魔力……',12340),
(925,1,0,'当兽人孤独地与命运抗争时，牛头人与他们同甘共苦而不图回报。这就是荣耀，$N。',12340),
(926,1,0,'',12340),
(927,1,0,'$N！你有东西给我吗？',12340),
(928,1,1,'你好，$C。是什么事让我们能在此愉快地会面呢？',12340),
(929,3,3,'你好，$N。完成你的任务了吗？',12340),
(930,0,0,'$N，你看起来像是有事要告诉我。是关于树精的新消息吗？',12340),
(931,0,0,'你有东西要给我吗？',12340),
(932,6,2,'你杀掉迈雷纳斯领主了吗？去干净利落地把他干掉，$N。否则他就会一直是我们的心腹大患。',12340),
(933,1,0,'起初关于疯狂熊怪的袭击的报告都被忽略了。谁又能想到那么热爱和平的熊怪们会变得如此狂暴？这又成了困扰我们新家园的一大问题。',12340),
(934,1,0,'神谕之树、大德鲁伊和德鲁伊们一起密切关注着泰达希尔的成长。但是虽然我们有了一个新家，但我们还没有重新得到不朽的生命。',0),
(935,0,0,'我并没有召唤你来，所以我想知道为什么你会来到这里。$B$B无论是什么原因，请快点说明你的来意。',12340),
(936,1,0,NULL,12340),
(937,1,1,'以你的一己之力来对抗它们的利嘴钢爪会很困难，$N，但是我坚信你能完成这个任务。',12340),
(938,1,0,'密斯特……是我的错！那些家伙趁我不备……我没有保护好你……',12340),
(939,6,6,'这是什么，$C？你看来对它很感兴趣。',12340),
(940,1,0,'嗯……森林之灵充满你的全身，$C。你找我这个卡多雷的大德鲁伊有什么事呢？',12340),
(941,1,0,'培养槽里装满了由德纳兰精心准备的土壤。',12340),
(942,1,0,'你要给我什么呀，朋友？',12340),
(943,1,0,'$N，有了雷鲁之石，无论是我找到的化石还是雷姆塔维尔在黑海岸那里找到的化石，对我来说就都没有什么秘密可言啦。',12340),
(944,1,0,'主宰之剑，$N。$B$B到那里去，然后和我交谈。',12340),
(945,1,0,'我妹妹喜欢到处闲逛，不过这次她离开的时间也太长了……',12340),
(947,6,6,'$N，你拿到了我要的蘑菇了吗？你去过那处洞穴了吗？',12340),
(948,1,0,NULL,12340),
(949,1,0,NULL,12340),
(950,1,0,'$N。你回来了。',12340),
(951,1,0,'$N，你在玛塞斯特拉废墟找到什么了吗？',12340),
(952,1,0,'啊，$C。我能为你做什么吗？',12340),
(953,1,0,'如果你研究过石碑刻文，并了解了亚米萨兰的沦落史，我想把你知道的资讯报告给奥伯丁的上古议会。',12340),
(954,1,0,NULL,12340),
(955,1,0,'一旦得到那些耳环，我就可以施展魔法来找出囚禁我的封印。几个世纪以来，我一直期望着能摧毁这个封印，给我带来真正的自由……在这几个世纪里我也曾想过可能再也无法重获自由……',12340),
(956,0,0,'这个神殿的柱子对我来说就是牢不可破的枷锁，$N。我没有力气打破它们，也没有魔法摧毁它们……$B$B一千多年来，我注视着它们，思考着这样的问题:究竟要等到什么时候，我才能获得自由？而到那时，是否又会有另一层无形的枷锁束缚着我……',12340),
(957,1,0,'实话说，$N，我有些担心……担心你的到来——以及这所有的一切——仅仅是一种幻觉。你知道那有多痛苦吗？我……求求你，你必须尽快行动。',12340),
(958,0,0,'如果高等精灵们的那些魔法物品在那场摧毁了一切的大灾难中也同样被毁灭就好了……不过现在的当务之急是，我们必须尽全力确保过去的悲剧不再重演。',12340),
(959,0,0,'自从疯狂的马格利什偷了那瓶99年波尔多陈酿逃走之后，码头主管就天天找我的麻烦。我想那瓶酒一定是大财主里维加兹私底下送给加兹鲁维的礼物。$B$B如果你有足够的胆量和耐心找到疯狂的马格利什，并且帮我取回那瓶波尔多酒的话，我一定会重重酬谢你的。',12340),
(960,1,0,NULL,12340),
(961,1,0,'',12340),
(962,1,1,'我很想知道你是否能从哀嚎洞穴收集到足够的毒蛇花。我已经派去了很多人，但没一个回来的。',12340),
(963,1,1,'怀着满心的悲痛，我随着怒风尊师进入了休眠状态，把哀伤深深地埋藏在梦中，这一睡就是数千年。',12340),
(964,1,1,'尽可能多地杀戮吧，$C——我们需要大量合适的骸骨碎片来制造钥匙的外壳。你要知道，骷髅钥匙这个名字可不是白来的。',12340),
(965,1,0,NULL,12340),
(966,6,6,'你找到卷轴碎片了吗？如果你找到足够的碎片，我应该可以从中找出什么线索来。',12340),
(967,6,0,'$C，你找我有什么事吗？',12340),
(968,3,0,'你好，$G先生:女士。$B$B你对我的书感兴趣吗？',12340),
(969,11,11,'带回我要的碎片，然后我就会告诉你更多东西！',12340),
(970,6,6,'你得到那枚灵魂宝石了吗？',12340),
(971,1,1,'去灰谷的路途很遥远，你的任务也不简单。不过如果你能拿到手稿，$N……你将得到可观的报酬。',12340),
(973,6,6,'你看起来有点不舒服，$n。你还好吗？',12340),
(974,1,1,'我想过要自己去找，但是……我害怕那里的火元素！',12340),
(975,1,0,'',12340),
(976,1,0,'我们急需把物资送去增援在黑海岸的哨兵部队。',12340),
(977,0,0,'$N，我已经快要完成毛皮的粘贴工作了，请你快点帮我找到角。',12340),
(978,6,6,'这些能量到底是从什么地方来的？我想我们正在沿着正确的道路找寻答案，$N。',12340),
(979,1,0,NULL,12340),
(980,1,0,NULL,12340),
(981,1,0,NULL,12340),
(982,1,1,'这两艘船的船长都是好人，他们不应该遭受这样的厄运。也许把他们的东西从鱼人手中夺回来是安慰他们灵魂的最好方法。',12340),
(983,1,0,'传声盒827号静静地站在那里，只有一束闪光显示需要把6只蟹腿放进它的储物盒里。',12340),
(984,1,0,'你的搜索行动进展如何了，$N？',12340),
(985,1,1,'别缩手缩脚的，孩子。我知道杀害森林中的生物有些让你难于接受，但在现在的情况下，这是迫不得已的。当前我们还没有发现任何能让森林不再堕落的方法，因此只有尽我们的所能去延缓这个堕落的进程，直到我们找到了有效的方法为止。',12340),
(986,1,0,'在为你做好那件披风之前，我是不会让你冒险去找沃科尔的。',12340),
(990,1,0,NULL,12340),
(991,1,0,NULL,12340),
(992,6,6,'欢迎回来，初级勘探员$n！你完成我交给你的任务了吗？',12340),
(993,0,0,'',12340),
(994,1,0,'',12340),
(995,1,0,'嗯，$n？',12340),
(996,0,0,'你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(997,6,1,'你有东西要给我吗？',12340),
(998,1,0,'你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(1000,1,0,NULL,12340),
(1001,1,0,'机器的舱口开着，似乎在满怀希望地等待有人把3颗蛇颈龙的眼球放进去。',12340),
(1002,1,0,'当你把6颗月夜猛虎的牙齿放进机器里之后，你听见里面传出了语无伦次的话语。难道已经有别的什么人把机器修好了？',12340),
(1003,1,0,'你听见从传声盒525号中传出了歌声。$b$b“尽管，螃蟹酒甜美，蛇颈龙麦芽酒清醇，月夜猛虎酒的品质优良，但没有什么，能比得上灰斑蓟熊啤酒来得珍贵。我马上就能品……品尝！”$b$b机器的舱口是开着的，伴随着一遍又一遍的歌声，等待4块灰色头皮的到来。',12340),
(1004,1,0,NULL,12340),
(1007,0,0,'你找到雕像了吗，$N？',12340),
(1008,0,0,'决不能让纳迦侵犯我们的海岸，$N。你必须到佐拉姆海岸去完成你的任务。',12340),
(1009,0,0,'据说佐拉姆之戒能打开那座城市中的任何一把锁。$N，你找到它了吗？',12340),
(1010,6,6,'你收集到巴斯兰的头发了吗，$N？这孩子的情况越来越糟糕了……',12340),
(1011,6,6,'你找到营地了吗，$N？有没有拿到病菌？',12340),
(1012,1,0,'朵丹尼尔的德鲁伊在我的梦里哀嚎，$N。你必须杀了他们的领袖！',12340),
(1013,1,0,'你找到那本书了吗，$N？',12340),
(1014,1,1,'只要阿鲁高一死，我们就能进一步巩固黑暗女王在洛丹伦大陆上的势力。',12340),
(1015,1,0,NULL,12340),
(1016,1,1,'你必须摧毁护腕才能干掉那些水元素，所以你可能不太容易找齐那些具有特定资讯的护腕。如果你还没有收集到所有护腕的话，可以用自己找到的护腕与别人交换来集齐你所需的护腕。',12340),
(1017,6,6,'完成了吗？萨瑞鲁斯·法伯尼死了吗？',12340),
(1018,1,0,NULL,12340),
(1019,1,0,NULL,12340),
(1020,1,0,'很抱歉，我实在没有时间再和你聊天了。我的孩子蕾拉就快要病死了！',12340),
(1021,1,0,NULL,12340),
(1022,1,0,'麦尔莎迪丝之书是件神秘的物品，它已经不是传统意义上的书了。这本书的每一页都受到了麦尔莎迪丝本人的佑护，书中记载着重大的事件。$B$B我很难具体解释，等你到了神殿之后自然就会了解了。',12340),
(1023,2,2,'啊，欢迎回来，$N。',12340),
(1024,1,0,'嗨，你好吗？',12340),
(1025,1,0,'熊怪并非一直是我们的敌人，$N。可是时代不同了，在这片黑暗的森林里，和平早已不复存在。',12340),
(1026,1,0,'树人的堕落让我感到十分不安，真希望我能为他们做些什么。',12340),
(1027,1,0,'$N，你找到魔棒的最后一段了吗？',12340),
(1028,1,0,'你能感受到一种微妙而又强大的力量在神殿和周围的森林中荡漾。$B$B当你把魔棒放入神殿之后，轻柔的低鸣声萦绕于耳，神殿开始泛出亮光……',12340),
(1029,1,0,NULL,12340),
(1030,1,0,NULL,12340),
(1031,1,0,'你找到她们了吗？安妮莉亚有没有说什么？她现在在哪儿？',12340),
(1032,1,0,'请帮我为安妮莉亚复仇！',12340),
(1033,6,6,'$N，你找到伊瑞斯湖了吗？你拿到月神之泪了吗？',12340),
(1034,6,6,'你得到星尘了吗，$N？',12340),
(1035,6,6,'你干掉沼泽兽神谕者了吗，$N？如果是的话，请把陨落的月亮石给我。蕾拉已经奄奄一息了！',12340),
(1036,1,0,NULL,12340),
(1037,1,0,NULL,12340),
(1038,0,0,'你找到了什么？',12340),
(1039,1,0,NULL,12340),
(1040,1,0,NULL,12340),
(1041,1,0,NULL,12340),
(1042,1,0,NULL,12340),
(1043,1,1,'不做好准备就贸然闯进森林是很危险的。紧紧握住你的武器，时刻保持高度警惕，否则你一旦进入这片充满邪恶的森林，就可能永远出不来了。',12340),
(1044,1,0,NULL,12340),
(1045,0,0,'你杀掉兰恩了吗，我的朋友？$B$B他甚至没有资格去憎恨暗夜精灵。他的仇恨比我更加强烈，但他的思想已不再受他自己的控制。对于森林中的所有生物而言，他都是一个巨大的威胁。',12340),
(1046,6,0,'哨兵部队在灰谷竭尽全力地战斗着，但是多亏了像你一样的$r，我们才保住了这片原本就属于我们的土地。',12340),
(1047,1,0,NULL,12340),
(1048,1,0,'或许我没有把命令说清楚，$c。我要你去干掉高阶审判官怀特迈恩，把她那张厚脸皮也给我剥下来。$B$B再去杀掉血色十字军指挥官莫格莱尼，那个该死的狂热者。还要杀掉血色十字军勇士赫洛德。最后，别忘记也要送驯犬者洛克希上路，顺便把他的那些蠢狗都给我剁成肉酱。$B$B现在就去吧！',12340),
(1049,1,1,'凯恩是一个勇敢而高贵的领袖，我会终生遵循他的领导，但是我对这里的整个高层并不是很信任。$b$b一旦我有机会收集所有可以利用的知识，就能为酋长创建一个成熟的议会。$b$b你去过提瑞斯法林地了吗？进过血色修道院了吗？《堕落者纲要》只是这错综复杂的谜团中的一小部分罢了……',12340),
(1050,1,1,'修道院过去曾是训练圣骑士的学院。它曾经是光明的要塞，但现在却落到了血色十字军的狂热分子手上。$b$b十字军自以为有一个崇高的目标，他们要清除不死生物的瘟疫，净化洛丹伦的土地，但是现在他们脑子里只有疯狂的臆想，成了所有人的敌人。$b$b把《泰坦神话》给我带回来，这样我就可以研究它并把它收藏在铁炉堡里了。$b$b修道院的图书馆已经被废弃，不再适合摆放这样的珍宝了。',12340),
(1051,1,0,'你有什么事吗，陌生人？',12340),
(1052,6,0,'你是谁？你有什么事吗？',12340),
(1053,1,5,'除非那些高层官员被铲除，否则修道院中的堕落就不会停止。$b$b以圣光的名义，去杀掉高阶审判官怀特迈恩，血色十字军指挥官莫格莱尼，十字军的勇士赫洛德和驯犬者洛克希。一旦除掉了他们，也许十字军将会重新回归他们神圣的创立宗旨。那时十字军才会成为一支无坚不摧的正义力量。$b$b从南海镇出发吧，去完成你的使命！',12340),
(1054,1,1,'熊怪的堕落让灰谷已经很难重现往日的荣耀了。',12340),
(1055,1,0,NULL,12340),
(1056,1,0,'嗯？',12340),
(1057,1,0,'想要让焦炭谷恢复成过去那样的茂盛的森林，我们就得付出非常大的努力。$B$B把谷中的那些肮脏的鹰身人都清除掉，$N！只有这样，我们才能让焦炭谷重归自然的怀抱。',12340),
(1058,11,11,'看看我们这群可怜的精灵朋友，他们都被关在这里，没法在森林里玩耍啦！$b$b我要的那些苔液呢？夜行虎的胡须呢？灵龙的鳞片呢？$b$b当然，我还需要很多眼球！没足够的眼球是无法施展强大的森林魔法的！',12340),
(1059,1,0,NULL,12340),
(1060,0,0,'你看起来是个不太面善。找我有什么事？',12340),
(1061,1,0,NULL,12340),
(1062,1,1,'巨木谷就在西北边，$N。去吧。把恐惧深深地烙入这群破坏大地的地精心里吧！',12340),
(1063,1,0,NULL,12340),
(1064,1,0,NULL,12340),
(1065,1,0,'你好啊，有什么事吗？',12340),
(1066,6,6,'你找到辛迪加暗影法师了吗？从他们那儿收集到血液了吗？',12340),
(1067,6,0,'你回来了，$N。你从药剂师林度恩那儿给我带了东西来？',12340),
(1068,1,1,'树灵们正因为它们的同胞被无情屠戮而恸哭，$N。你必须马上把伐木机XT:4和XT:9毁掉，否则，恐怕石爪山将永远不得安宁。',12340),
(1069,1,1,'$N，你找到蜘蛛卵了吗？我已经跟码头管理员迪兹维格签了送货合同了。',12340),
(1070,1,0,NULL,12340),
(1071,1,6,'你已经完成任务了，$N？',12340),
(1072,1,0,'对矮人哲学家来说，时间并不是什么难题，问题是你在这里干什么。有什么事啊？快说快说！',12340),
(1073,6,6,'我没这些药水便配不出一丁点硝酸甘油炸药来……这些原料在制作中是十分关键的。',12340),
(1074,0,0,'啊，很好，你回来啦。',12340),
(1075,1,0,NULL,12340),
(1076,6,6,'你好，$N。你找到我所需要的材料了吗？',12340),
(1077,5,0,'哈哈！你回来了！拿到了吗？拿到那法术了吗？',12340),
(1078,2,2,'很高兴再次见到你，$N。$B$B你从石爪山的谷地里带回我需要的鳞片了吗？',12340),
(1079,6,6,'搞到计划书了吗，$N？',12340),
(1080,6,6,'行动进行得怎么样了，$N？',12340),
(1081,1,0,NULL,12340),
(1082,1,0,NULL,12340),
(1083,0,0,'第一次看见焦炭谷里的景象时，我几乎要哭了，$N。',12340),
(1084,1,1,'我觉得加克希姆应该能从弹片中找出些关于风险投资公司如何使用这种武器的线索。',12340),
(1085,1,0,NULL,12340),
(1086,1,0,'如果风险投资公司在那里确实有一座空港的话，你就必须找到它，$N。',12340),
(1087,0,0,'看，在这里想要引导魔法就像是用竹篮打水一样。',12340),
(1088,0,0,'当我的主人吩咐我来石爪峰的时候，我一直希望能消灭那些暗夜精灵……那些占据了我们古老而神圣的艾萨拉圣殿遗迹并玷污了它的蠢货……可是奥达努斯居然从我手里溜走了。',12340),
(1089,1,0,'在石头上有三个钥匙孔。',12340),
(1090,1,0,'小心，巡逻兵和工人经常会在这一带走动，要是我们被抓住可就惨了。',12340),
(1091,6,0,'你好，$N。有什么事吗？',12340),
(1092,0,0,'找我有什么事吗？',12340),
(1093,0,0,'你找到设计书了吗？我要用这东西给我的新老板露上一手。当然，我希望他知道我对他是有多么的死心塌地以后——嘿，别打岔，我对他当然是死心塌地的……你了解地精的忠诚么？——那么以后我就可以在这儿如鱼得水地大干一场了！',12340),
(1094,3,0,'你好！有什么可以帮忙的吗？',12340),
(1095,1,0,NULL,12340),
(1096,0,0,'斯布特瓦夫显然需要能证明格雷苏已死的证据，我想他的机械臂就很合适。',12340),
(1097,1,0,NULL,12340),
(1098,1,0,NULL,12340),
(1100,6,0,'从你凝重的脸色中，我看出……有什么东西出了问题……',12340),
(1101,1,1,'只要卡尔加·刺肋在剃刀沼泽召集军队，这片土地将陷入巨大的危险之中。',12340),
(1102,6,6,'只有当我得知剃刀沼泽的邪恶野兽被赶出他们那个肮脏的窝时，我才能松一口气，因为那样才能说明我的报复行动已经完成了。$b$b你将野猪人从剃刀沼泽里赶走了吗？你干掉卡尔加了吗？',12340),
(1103,1,0,'你有灵契吗，我的$G兄弟:姐妹？$B$B我知道另一个人在打败那个堕落的水灵之后有了麻烦——似乎他等得太久，最后因为不耐烦而离开了。我不希望看见这样的事情再次发生，为此我决定继续等在这里，直到确信没有人再需要我的帮助为止。',12340),
(1104,6,6,'喂！你找到毒液了吗？',12340),
(1105,1,1,'我兄弟在新燃料设计上有了进展，这让我很担心。我得尽快开始做龟壳燃料箱！',12340),
(1106,35,0,'啊，你找到我了。很好。$b$b你来是为了我替加塞尔佐格所铸造的那把斧头的事情吗？还是为了夺回杜切斯·帕麦尔的荣耀？$b$b实际上，我根本不在乎是哪个原因。如果你是来打架的，那就放马过来吧……',12340),
(1107,6,6,'你弄到尾鳍了吗？如果我们的赛车有在急速行驶中解体的危险，那我就不能指望它跑完全程啦！',12340),
(1108,6,6,'$N，你找到精铁碎片了吗？我已经一切就绪，就准备进行测试了。',12340),
(1109,1,0,'啊，你回来了。你得到沼泽蝙蝠的粪便了吗？',12340),
(1110,6,6,'$N，你在闪光平原上到处搜过了吗？弄到足够的零件了吗？',12340),
(1111,0,0,'大声点儿！你是来取货的还是托运的？',12340),
(1112,0,0,'你去过棘齿城了吗？取回零件了吗？',12340),
(1113,1,0,'你从血色修道院回来了？为了这个令人愉悦的实验，我需要许多心脏来作为原料！$b$b毫无疑问，瓦里玛萨斯和黑暗女王也会因为血色十字军那些渣滓被干掉而感到高兴的。',12340),
(1114,0,0,'你有东西要给我？太好了！让我看看！',12340),
(1115,1,0,NULL,12340),
(1116,6,6,'这么快就回来了？你拿到我要的幻梦之尘了吗？',12340),
(1117,6,0,'你找到有关纳兹的资讯了吗？有没有什么事情是他不想让人家知道的？',12340),
(1118,3,0,'您好！是什么让您这么一个高贵的$R来到了藏宝海湾？',12340),
(1119,3,0,'你好，$N。菲兹巴布可以帮我们吗？',12340),
(1120,6,0,'嗨！你有东西要给我？',12340),
(1121,6,0,'你在看什么？',12340),
(1122,1,0,'你好，$N。那种酒的效果如何？味道很烈吧？哈哈哈！',12340),
(1123,1,0,NULL,12340),
(1124,1,0,'这儿危机四伏，$C。是什么让你来到希利苏斯这片荒原的？',12340),
(1125,1,1,'部落或者联盟，这都没有关系——这个世界上没有谁的灵魂活该被折磨。释放这些灵魂，让他们获得解脱，$N。',12340),
(1126,6,6,'好吧，你干得怎么样了？看来你没有缺胳膊少腿，这是个好消息。你找到什么了吗？',12340),
(1127,1,0,'你搞到赞吉尔的药剂了吗，$N？',12340),
(1130,1,0,NULL,12340),
(1131,0,0,'你打败邪恶的钢齿土狼了吗，$N？',12340),
(1132,1,0,NULL,12340),
(1133,1,2,NULL,12340),
(1134,0,0,'$N，你拿到巨翼双足飞龙的毒囊了吗？我们不能让兽人用这些野兽的毒液来对付我们！',12340),
(1135,1,0,'$N，你找到风巢了吗？那些双足飞龙还好对付吗？',12340),
(1136,0,0,'$N，你去过奥特兰克山了吗？你遇见那形影不定的霜喉雪人吗？',12340),
(1137,1,0,NULL,12340),
(1138,0,0,'……柠檬汁炖螃蟹、清蒸螃蟹和铁炉堡特级螃蟹，这就是螃蟹存在的意义。$B$B哦，你好，$N。你拿到我要的优质蟹肉了吗？',12340),
(1139,1,1,'$N，我们必须完成铁趾的遗愿，我欠他太多了。$B$B你要尽快返回奥达曼，这不仅有助于实现我们的计划，也有助于保护所有矮人的安全。如果石板落入黑铁矮人的手中，天知道他们能造出多少强大的作战魔像来。',12340),
(1140,1,1,'我曾听人私下里说过，萨特的历史与暗夜精灵有着某种联系，但我尊敬的暗夜精灵主人们对这件事却是讳莫如深。',12340),
(1141,1,1,'用黑海岸石斑鱼可以做出很多美味佳肴来。它们味道非常鲜美，但是我更加喜欢钓鱼的过程。$B$B你钓到黑海岸石斑鱼了吗？',12340),
(1142,1,0,'什么风把你吹到我家来了，$R？',12340),
(1143,1,1,'埃瑟里克斯·纳拉辛是一个古代的强大术士，也许我们应该等德尔葛兰来帮我们。不过既然他派你只身前来，那么想必他对你非常有信心。',12340),
(1144,1,0,'带我出去！',12340),
(1145,25,0,'$C，我嫉妒你，因为看起来你已经在奥格瑞玛城外的世界中游历很久了。$B$B如果萨尔不需要我的才能，我就会像你一样四处旅行。但是萨尔是个优秀的领导者，我相信他的判断力——只要他需要我，我就会继续留在这儿。',12340),
(1146,1,0,'$C，战争把我的队伍带到了闪光平原上，那么是什么把你带到这儿来的呢？',12340),
(1147,1,0,'有很多旅人会去观看那些赛车比赛，我相信我们可以说服足够多的探险者去帮助我们击退这些昆虫。我的队伍在接到命令之前是绝对不会离开这里的。',12340),
(1148,1,1,'啊，$N，很久不见了，我能为你做些什么吗？看来你最近经过了不少战斗的洗礼。你经历的战斗越多，你的经验就越丰富，你也会变得越发强大。',12340),
(1149,1,0,'信仰，它比某些人想象得更为重要。$B$B有时你信仰的是什么并不重要，重要的是你要有自己的信仰。',12340),
(1150,1,1,'你必须在精神上、身体上和意志上都做好充足的准备，才能去迎接未来的挑战。$b$b我们经常未经准备就草率行事，并为此付出惨痛的代价。当年轻的冒险者准备离开他们圣洁的家园外出闯荡时，我会帮他们为可能面临的危险做好准备，我视这种职责为己任，不论他们属于哪个部族。',12340),
(1151,1,1,'罗卡里姆被千针石林的半人马部族称作重锤，原因是他的拳头会击碎一切胆敢挡住他去路的生物。',12340),
(1152,1,0,NULL,12340),
(1153,1,1,'我又见到那些旅人了——他们连一块矿石也不卖给我。我唾弃他们，因为他们不愿为大酋长效力。$B$B这些旅人会像懦夫一样在战场上死去，而不会像所有部落的勇士一般在战场上奋勇作战。',12340),
(1154,1,1,'你研究完这本书之后就把它给我拿来，在你归还书之后，我才会向你发问。',12340),
(1159,1,0,NULL,12340),
(1160,1,1,'我希望你在偷走血色十字军的书之前让他们好好吃些苦头。$b$b我对他们那类人的评价并不是没有根据的。十字军也许曾是圣光的追随者，但是现在他们却想要消灭任何与他们的信仰不相符合的生物。他们相信所有的不死生物——无论是被遗忘者还是天灾军团——都必须被清除，甚至连曾经踏上不死生物的土地都是可以招致杀身之祸的理由。他们简直就是白痴。',12340),
(1164,5,5,'杀光他们，把他们的头拿来！',12340),
(1166,0,0,'我想喝酒，想要我的鼻烟，还有保险箱！你去为莫格穆洛克主宰把东西拿回来。$b$b去南边，我们以前的家。我太忙了，没法带着食人魔去拿。',12340),
(1167,1,0,NULL,12340),
(1168,1,0,'莫格穆洛克让所有食人魔留在这里，保卫这里的安全。我觉得食人魔应该去消灭黑龙，把原来的家夺回来。$b$b你来帮食人魔夺回原来的家。帮食人魔复仇。',12340),
(1169,0,0,'只要有了黑龙的舌头和心脏，我就可以找出是什么样的卑鄙野兽把它们带到了我们的家园里。我们对这些侵略者的了解越深，就越有可能找到除掉它们的办法，收复已毁灭的石槌村。$b$b当然，要说服莫格穆洛克挪动他那肥胖臃肿的身体离开这个鬼地方根本是不可能的任务……',12340),
(1170,1,0,'你这个小家伙干嘛来烦我？',12340),
(1171,1,0,'我们尊敬的莫格穆洛克主宰有什么指示？',12340),
(1172,1,0,'你必须尽快赶到黑龙谷去，$n。如果再不对巨龙泥沼里那些奥妮克希亚的卵采取行动的话，我们就要面对铺天盖地的敌人了。$b$b毁了她的卵！不要让黑龙肆虐我们的家园。',12340),
(1173,1,0,'我以为你准备把莫格穆洛克赶出村子，你却跑来要和我聊天？',12340),
(1175,1,0,'整日清理赛车事故中遗留下来的残骸让我头痛不已。',12340),
(1176,6,6,'你找到秃鹫骨头吗？我正准备着手改造驾驶模组，但是在拿到我需要的部件之前，我还不想把机身拆开。',12340),
(1177,0,0,'给我吃的，不然我就吃你。',12340),
(1178,1,0,NULL,12340),
(1179,5,0,'注意你前进的方向！要高度集中！你看，这是个非常精密的装置，如果我们想要获胜，一切都得运转得完美自如才行！',12340),
(1180,1,0,'',12340),
(1181,1,0,NULL,12340),
(1182,0,0,'尽管我颇不愿意承认这一点，但这群地精的发明确实很不错。我们的伙计需要他们搞出来的这些新发明。',12340),
(1183,1,0,'$N！你拿到新的燃料调节器了吗？',12340),
(1184,1,0,NULL,12340),
(1185,1,0,NULL,12340),
(1186,1,0,NULL,12340),
(1187,0,0,'我是怎么做到在赛道上风光无限而又毫不出错的呢？我跟你说吧，这就是我与生俱来的天赋。',12340),
(1188,0,0,'你肯定知道，基兹莫瑞配件店能够满足所有技工的要求！有什么我可以帮你的吗？',12340),
(1189,1,0,'你能相信普兹克居然在赛车里加了一桶沙吗？我车座下面放着一桶沙还怎么挂到最高档？',12340),
(1190,1,0,'我们必须搞清楚铜栓兄弟发现的这个东西到底是什么玩意儿，然后将其弄过来为我们自己所用。',12340),
(1191,1,0,NULL,12340),
(1192,1,1,'我想将这些精铁应用于我们赛车的每个部件中，但我需要大量的原始精铁矿石来制造这些部件。$B$B渡过无尽之海，到卡兹莫丹南面的荒芜之地去，在那一带的奥达曼挖掘场里应该能找到不少精铁矿石。$B$B地精已经有了他们自己的供货管道，所以我们一定要找到我们的供货管道来赶上地精的开发进度。',12340),
(1193,1,0,'你面前摆着一个巨大的陷阱，它已经坏掉了。看起来那些食人魔似乎尝试过修理它，但是没成功。一张匆匆写成的便笺摆在陷阱旁边，令你惊讶的是，便笺上面居然写明了修理陷阱所需要的材料:一个瑟银零件，外加一些冰霜之油。如果你能修复陷阱，那么当某个巨魔踏过它的时候就会被困住。$b$b幸运的是，似乎没有几个巨魔能读懂这张便笺上面的字。$b$b你真是幸运到家了。',12340),
(1194,1,0,NULL,12340),
(1195,1,1,'我们得到那瓶水之后就要尽快把它送给我在千针石林的朋友，劳恩。他需要这瓶水，也比我们更了解它的用处。',12340),
(1196,6,0,'你是赞金派来的吗？',12340),
(1197,6,6,'我在等你拿来裂开的蹄子——你拿到它了吗？',12340),
(1198,1,0,NULL,12340),
(1199,1,1,'黑暗深渊曾经是古代暗夜精灵的神殿，里面有一眼充满强大魔力的月亮井。谁也不知道暮光之锤到底在那里酝酿着怎样的阴谋。$B$B你的行动进展如何了？',12340),
(1200,1,1,'时间是很宝贵的东西啊，$C。$B$B我在达纳苏斯的责任是确保银色黎明的兴盛和消灭那些盘踞在卡利姆多的邪恶势力。$B$B有事快说，不然就走吧！',12340),
(1201,1,0,'你找到间谍了吗，$N？',12340),
(1202,0,0,'你拿到文件了吗，$N？这些文件对联盟的稳定十分重要，因此也对部落的安全十分重要。',12340),
(1203,6,6,'你找到我要的剑了？',12340),
(1204,6,6,'你找到分叉的舌头了吗？',12340),
(1205,0,0,'你拿到死沼巨鳄的牙齿了吗，$N？你结束它的痛苦了吗？',12340),
(1206,0,0,'我要的眼睛在哪儿？',12340),
(1218,6,6,'啊，调味料！给我们的生活来那么一丁点调味料是大有好处的……你说是吧？',12340),
(1219,0,0,'你有什么要报告的吗？',12340),
(1220,0,0,'你有东西要给我吗？',12340),
(1221,0,0,'$N，你拿到蓝叶薯了吗？',12340),
(1222,1,0,'你看见伊格纳兹先生了吗？我前些日子要他到沼泽地去找些东西，不过他到现在还没回来！',12340),
(1238,6,0,'你有东西要给我吗？',12340),
(1239,0,0,'你还有别的事要报告，$N？',12340),
(1240,6,0,'你身上跟着一个愤怒的灵魂，我的$g兄弟:姐妹。你来找肯维雷有什么事吗？',12340),
(1241,1,0,'嗯，你最好有个能打扰我钓鱼的好理由。否则，我就让你吃不完兜着走。',12340),
(1242,6,0,'你好，$N。我能为你做些什么吗？想不想尝尝我们特制的提亚斯切达干酪？或者来块达纳苏斯乳酪？',12340),
(1243,6,0,'在这片森林里旅行可不太安全，$N。小心为上，如果你看到任何可疑或者危险的东西，请立刻向守夜人报告。不要试图自己去解决问题，否则出了什么事情我们可无法负责。$B$B不过你我都知道你根本不会在意我的话，而且会不择手段与黑暗中的怪物搏斗，不是吗？哈哈，是呀，你们这些冒险者都是一样的。',12340),
(1244,1,1,'小心点，$N。我知道提亚斯派来的人个个身手不凡，但这并不意味着这片森林里潜伏着的东西就不会给你造成任何麻烦……特别是在你调查迪菲亚兄弟会的时候。',12340),
(1245,6,6,'啊，你回来了，而且看起来没有缺胳膊少腿。你我都知道我们不是来这里做乳酪买卖的，所以就别废话了吧。巴库斯帮上什么忙了吗？还是说，你根本就没去过暮色森林呢？',12340),
(1246,14,0,NULL,12340),
(1247,1,0,NULL,12340),
(1248,1,0,NULL,12340),
(1249,1,0,'你没让他跑了吧？那小子注视我们时的样子有点诡异。',12340),
(1250,1,0,NULL,12340),
(1251,6,0,'你手里拿着什么，$n？是从树荫旅店的废墟里找到的东西吗？',12340),
(1252,6,6,'你在树荫旅店找到什么有用的东西了吗？',12340),
(1253,6,6,'你在树荫旅店的废墟里找到什么证据了吗？',12340),
(1258,6,6,'我对泥石龟舌的研究进展很不错，我相信你找螃蟹腿也还顺利吧？',12340),
(1259,1,0,NULL,12340),
(1260,1,0,NULL,12340),
(1261,0,0,'$N，你发现玛格的下落了吗？',12340),
(1262,0,0,'你是从尘泥沼泽的蕨墙村过来的？纳泽尔过得如何？他在那里的生意又如何？',12340),
(1264,1,0,NULL,12340),
(1265,1,0,'嗯，$N？',12340),
(1266,1,0,NULL,12340),
(1267,1,0,NULL,12340),
(1268,1,0,NULL,12340),
(1269,6,0,'你找到关于树荫旅店的线索了吗？',12340),
(1270,1,0,'嘿！你有没有在沼泽地里看到一个名叫伊格纳兹的臭哄哄的家伙？我派他去尘泥沼泽采点草药给我，现在他也该回来了吧！',12340),
(1271,1,0,NULL,12340),
(1273,1,0,'你找到雷瑟了吗？',12340),
(1274,1,0,NULL,12340),
(1275,1,0,'只要我有了足够的样本，就可以开始真正的研究了。有了这些从黑暗深渊里找到的萨特和纳迦的脑干，我就能找出这两种被魔法扭曲了心智的生物之间的联系。$B$B或许……如果我们对这些东西能有足够的了解，我们就能阻止血精灵步他们的后尘，走向堕落的深渊。',12340),
(1276,3,0,'你好啊，$c。我能帮你什么忙吗？',12340),
(1282,1,0,'',12340),
(1284,1,0,NULL,12340),
(1285,1,0,NULL,12340),
(1286,1,0,NULL,12340),
(1287,1,0,NULL,12340),
(1288,1,0,NULL,12340),
(1289,1,0,'',12340),
(1301,1,0,NULL,12340),
(1302,1,0,NULL,12340),
(1318,1,0,'哈哈，你还没有找到它，是不是，老大？也许那只是一个故事……很难相信那个可恶的精灵居然可以从我们戈多克的大王身边偷走东西！',12340),
(1319,6,6,'有什么事吗？',12340),
(1320,1,0,NULL,12340),
(1321,0,0,'你找我，$c？',12340),
(1322,0,0,'你找到蜘蛛的毒囊了吗？',12340),
(1323,1,0,NULL,12340),
(1324,1,0,'又见面了，$N。我希望你不会介意我提供的这点小帮助，但我们绝不能让亨德尔给跑了，或者更糟的让他被灭口。',12340),
(1338,6,0,'从洛克莫丹那边带来的信？不知道会是谁找我……$B$B请让我看看是怎样的订单吧。',12340),
(1339,1,0,NULL,12340),
(1358,0,0,'你有个包裹要给我？',12340),
(1359,6,0,'你有东西要给我吗？',12340),
(1360,6,6,'好吧，你有没有去和那帮穴居人杀个天昏地暗，有没有找到我的箱子，有没有拿到我的宝贝？',12340),
(1361,1,0,'我发现你的活儿没干完啊，$N。难道要我告诉Sharlindra你很蠢吗？',12340),
(1362,1,0,NULL,12340),
(1363,1,0,NULL,12340),
(1364,6,6,'来守望堡有什么事吗，$R？',12340),
(1365,0,0,'$N，你杀死戴兹帕可汗了吗？',12340),
(1366,0,0,'你收集了多少半人马的耳朵啦，$N？',12340),
(1367,1,0,'滚！玛格拉姆不和弱者交谈！我们只会杀了他们！$B$B如果你想和我谈话，就先让我看看你有多强大！去杀更多的吉尔吉斯人，然后再回来！',12340),
(1368,1,0,'离吉尔吉斯人的土地远一点，这里不欢迎你！$B$B证明你对吉尔吉斯人的善意吧，去杀掉那些该死的玛格拉姆人。当你让玛格拉姆族血流成河的时候再回来吧！',12340),
(1369,1,0,'如果你是我的朋友，就按照我的要求去做！',12340),
(1370,1,0,'向吉尔吉斯半人马证明了你的价值以后再回来！',12340),
(1371,1,0,'如果你是我的朋友，就按照我的要求去做！',12340),
(1372,1,0,NULL,12340),
(1373,0,0,'$N，你得向我证明你是吉尔吉斯族的朋友。',12340),
(1374,1,0,'$N，你要向我证明你是吉尔吉斯部族的朋友。',12340),
(1375,1,0,'为玛格拉姆完成任务，那么我就会帮助你。',12340),
(1380,1,0,'赫兰萨可汗死了吗？你找到钥匙的碎片了吗？',12340),
(1381,1,0,'照我说的去做。让我确信你是玛格拉姆人的朋友！',12340),
(1382,1,0,'走开！吉尔吉斯不想在这里看见你！$B$B干掉更多玛格拉姆部族的家伙以后再回来，那时候我才会和你好好谈谈。',12340),
(1383,11,11,'被关在斯通纳德的间谍肯定会开口的……只要他喝了我特制的药水，哈哈！$B$B不过要得到配制药水所必需的各种成分并不简单。暗影黑豹在沼泽地很常见，但是收集足够多的心脏还是颇困难的。另外，泥沼之王也是个难应付的家伙。',12340),
(1384,1,0,'你拿到符咒了吗？你让科卡尔部族知道他们的魔法有多么脆弱了吗？',12340),
(1385,1,0,'赶快滚，不然玛格拉姆部族就把你揍扁！要想成为我们的朋友，你就必须去杀更多的吉尔吉斯半人马。',12340),
(1386,1,0,'你难道害怕科卡尔部族了吗？为什么不去杀了他们？也许你已经忘了该如何杀人了。赶快去给我杀了他们！',12340),
(1387,0,0,'有什么要报告的吗，$N？',12340),
(1388,0,0,'药剂师法奥斯丁，我希望你的药水对我们亲爱的朋友有所帮助。',12340),
(1389,6,6,'你夺回德莱尼水晶了吗？',12340),
(1390,1,0,'',12340),
(1391,20,0,'可怜可怜我吧！我有一些超出联盟范畴的机密消息。虽然我不是部落的支持者，但是有些正在进行中的政治阴谋一定要被揭露出来！',12340),
(1392,0,0,'你好，欢迎来到避难营。',12340),
(1393,1,0,'保险箱的钥匙孔里填满了黑色树脂，看来是不可能打开的。',12340),
(1394,1,0,NULL,12340),
(1395,3,3,'嗨！别在意这些骚动，这在守望堡简直就是家常便饭。$B$B你有什么东西要给我的吗？',12340),
(1396,1,0,'沼泽里的怪物正在逼近，$N。拜托，你一定要守住营地！',12340),
(1398,6,6,'找到流木了吗，$N？',12340),
(1418,1,0,NULL,12340),
(1419,0,0,'你拿到足够的腭骨了吗？',12340),
(1420,6,6,'你回来了，你带来了一份报告？',12340),
(1421,0,0,'你找到那些原料了吗，$N？',12340),
(1422,1,0,NULL,12340),
(1423,6,0,'你有东西要给我吗？',12340),
(1424,1,1,'没人知道阿塔哈卡神庙内现在潜伏着何种黑暗邪恶的力量，但我们都能感觉到那里聚集了强大的魔法能量。$b$b我们必须尽可能多地了解这种魔法，或许阿塔莱的法术对我们部落是有用处的。$b$b一旦你在泪水之池收集到了足够的阿塔莱神器，我就能了解到那群巨魔究竟施放了怎样的法术，以及那里到底发生了多么恐怖的事情。',12340),
(1425,0,0,'找我有什么事吗？',12340),
(1426,1,0,'我很有耐心，我的耐心就如同德拉诺的坎克石一般不可动摇。绝对不能让任何一个鱼人跨越过我们的边境——只要我还在，就不能。假如有一支完全听从我的命令的军队，我就要彻底把这种该死的动物从这个世界上清除掉。就算只是提到它们，我也感觉到我的仇恨随时都要爆发。',12340),
(1427,1,0,NULL,12340),
(1428,1,0,'只有大海与她所有的孩子都回归寂静之后，我才会高兴……尤其是那些恶心的鱼人。',12340),
(1429,1,0,'你竟然能来到这里，真是太勇敢了。嗯，到底是勇敢还是愚蠢呢……',12340),
(1430,1,1,'我为你准备了一桶酒，准备给你开个庆功会，$N。在我把这些肉送到顾客那边之前，我们一定要先尝个鲜。',12340),
(1431,1,0,NULL,12340),
(1432,1,0,NULL,12340),
(1433,1,0,NULL,12340),
(1434,1,0,'有一个牛头人同伴警告我说，萨特的内心世界可能与它们的外表截然不同。他相信它们并不是表面上看起来的那么简单，也许是邪恶扭曲了它们的本性，但我是看不见这些事情的。$B$B我只是看见了它们无情地屠戮弱小，不惜一切地追寻黑暗的力量。$B$B我将继续履行歼灭它们的职责，直到大酋长给我新的指示。在那之前，我不会对它们有丝毫的同情。',12340),
(1435,0,0,'我自己也尝试过尽可能将魔法弄得简单些。从受伤的躯体中抽取灵魂实在是易如反掌，但你不能完全依赖宝石的力量去杀敌。你必须在他们濒死的时候才能启动宝石，否则宝石就不能发挥它的功效。',12340),
(1436,1,0,NULL,12340),
(1437,1,0,NULL,12340),
(1438,1,0,NULL,12340),
(1439,1,1,'我担心泰拉尼斯是为了获取火刃氏族的秘密而不惜加入他们的阵营——他对魔法已经着迷了。$B$B我不知道自己是否忍心把泰拉尼斯沉迷魔法的事情告诉家乡的同胞，让我做这样的事情简直就是犯罪！但是为了保护我们自己不再遭受巨大的灾难，这样做也是可以理解的。',12340),
(1440,1,0,NULL,12340),
(1442,1,0,'对于一个向我要科尔宝石的人，我会怀疑他是不是真的追寻神圣的道路。不过我相信你胜于相信我的某些同类，更不会因为你们之中某人的堕落而怀疑你们所有的人。',12340),
(1444,1,0,NULL,12340),
(1445,1,0,'如果阿塔莱的神像中蕴藏着能召唤出哈卡并实现迦玛兰预言的力量，那么我们就必须拿到它们。部落必须了解并掌握这种力量。',12340),
(1446,1,1,'只要除掉迦玛兰，我就有机会回到我的同胞身边。$b$b如果迦玛兰继续蒙蔽他们的理智，那么阿塔莱必将遭受灭族之祸。',12340),
(1447,11,0,'这一切其实都是个误会，我从来没有说你是一个愚蠢的$C。我们是朋友，对吧？别那么严肃吧？',12340),
(1448,1,0,'我曾到过艾泽拉斯的森林深处，也到过卡兹莫丹的雪峰峰顶。$B$B以前我从来没有在冒险的时候要求过别人的帮助，可现在我已经是一把老骨头啦。$B$B没什么事能比完成探险者协会赋予我的最后一个任务更能让我心满意足的了。$B$B如果你能帮我找到阿塔哈卡神庙的话，$C，我将对你感激不尽。$B$B希望你能仔细搜索悲伤沼泽，然后向我回报你的成果。',12340),
(1449,1,0,NULL,12340),
(1450,1,0,NULL,12340),
(1451,1,0,NULL,12340),
(1452,6,6,'你喝过我酿的酒吗？要我说啊，这可是史上最好喝的酒！嗝儿！$B$B如果要我从那次差点要了我命的……嗝儿……沼泽飞行事故中缓过神来，你就得给我弄点东西来。嗝儿！$B$B你不想知道我把那些砂囊和肝加到卡利姆多鸡尾酒里是个什么味儿么？$B$B嗝儿！',12340),
(1453,1,0,NULL,12340),
(1454,1,0,NULL,12340),
(1455,1,0,NULL,12340),
(1456,1,1,'无论尼耶尔是谁，我都无意冒犯他，不过这个营地并不是我过夜的最佳场所，$N，希望你明白我的意思。',12340),
(1457,1,0,'$N，我的生意非常繁忙，所以没有很多时间来回答问题。如果你和寻物公司有生意往来的话，我洗耳恭听。否则，我只好请你去找我的手下谈谈，他们应该就可以处理你的问题了。',12340),
(1458,1,1,'萨特是一种卑劣的畜牲，传说他们曾和暗夜精灵有一种说不清道不明的关系，不过我不是很相信那些说法。$B$B我想这样的说法大概源于很多年前，曾有个暗夜精灵让萨特卷入了战争中吧。这个世界真是越来越危险了……',12340),
(1459,1,1,'抱歉，我无法告诉你要到哪里去寻找科多兽或者荒土蝎。我不熟悉这片地区，而且也没有时间来进行调查。',12340),
(1462,1,0,'你没有了灵契，也没有得到大地图腾，真是不幸。',12340),
(1463,1,0,'我出于信任给你一个。你已经证明过自己一次，但我想你以后应该更小心些。',12340),
(1464,1,0,'如果你在战斗中输给了火焰之魂，告诉我，我会再给你一个火焰灵契，让你能够看到山顶那座圣殿中的火焰之魂。',12340),
(1465,0,0,NULL,12340),
(1466,1,1,'我还没有意识到这些恶魔居然会出现在凄凉之地。我记得曾经从什么地方读到过……很多年前，暗夜精灵离开了这里，而半人马则接踵而至。$B$B我想知道恶魔们为什么会在这里出现，他们又是怎么来的。',12340),
(1467,1,0,'很高兴见到你，$N。铁炉堡到处是一片生意兴隆的景象，铁锤敲击砧板的声音响彻全城，鼓风机扇起的火苗直冲半空，而且老婆还给我制作了一块派作为餐后点心——还有什么样的生活能比这更惬意呢？',12340),
(1468,1,0,NULL,12340),
(1469,6,6,'你总算回来了，$N。好久没见了，我还以为你已经把我的事视l悀F呢。$B$B你找到那个狮鹫骑士了吗？他有没有告诉你些什么？',12340),
(1470,1,0,'你现在的力量实在是太弱小了，但是我觉得你能够感受到即将发生的事情。$b$b拥有这种力量之后，即使是死去的人也能感受到生命的气息。',12340),
(1471,1,0,'我期望着听到你的好消息，$N。至少别让我失望，不过，你应该不会失败的。',12340),
(1472,1,0,NULL,12340),
(1473,1,0,'埃加林是我的老师，他曾教我召唤虚无行者的方法。他很伟大，他只需要用一个眼神就可以操控他召唤出来的虚无行者。$B$B而当轮到我来进行召唤的时候，我过分的自信给我带来了不幸。不要轻视你还不能完全控制的这种力量，$N，即使你保持着警惕，它们还是随时有可能将你吞噬。',12340),
(1474,1,0,'魅魔拥有能穿越虚无的强大力量，是最危险的生物之一，她经常将弱者们玩弄于股掌之间。$B$B从现在开始，你得永远记住这一点。',12340),
(1475,1,1,'我已经不能再胜任一个冒险者的工作了，所以我希望你能帮忙，$N，帮我为探险者协会完成这最后的任务吧。如果我这身老骨头还有力气闯入悲伤沼泽、潜进神庙里的话，我肯定会和你并肩作战的。$B$B尽管我的自尊让我很难开口来要求你的帮助，但我的年纪让我不得不这么做。$B$B拜托你了，$N。我想在完成了探险者协会交给我的最后一个任务之后就光荣退休。',12340),
(1476,1,0,'我对你当前的进展速度非常满意，$N。若能马上把心脏拿来，我对你将更满意。',12340),
(1477,1,0,NULL,12340),
(1478,1,0,NULL,12340),
(1479,1,0,'我们到了吗？',12340),
(1480,0,0,'火刃氏族开始意识到他们有多么的渺小了。他们的魔法是肤浅的，他们的力量是薄弱的。$B$B他们唯一可以依靠的力量来自他们所侍奉的主人，而不是来自于对于力量与知识的真正理解和掌握。',12340),
(1481,0,0,'别带错的头皮给我，$c。如果用错材料的话，可是会要我们的命的。这个恶魔领主的身上可能有很多法术可以用来杀死那些想侦测他的人。$B$B命运已经让我品尝过那样的苦楚了。',12340),
(1482,0,0,'我已经都准备好，就等神谕水晶了，$c。找到并除掉阿兹雷索克领主将为大酋长带来一个巨大的好处。我们得好好合作，尽快完成这件事，这样无论对我们还是酋长都有好处。',12340),
(1483,1,0,NULL,12340),
(1484,1,0,NULL,12340),
(1485,1,0,'能控制你用法术召唤出的生物很重要。愿意学习$C之道的人本就很少，我不愿在你还没准备好时就冒险教些东西，把送你的命送掉。',12340),
(1486,0,0,'我对这些生活在洞穴中的变异生物身上的皮非常感兴趣。你弄到足够的皮了吗，$C？',12340),
(1487,1,0,'$N，我们纳拉雷克斯的门徒需要你的帮助。主人被困在扭曲的梦魇中，我们的数量正在锐减。我们已无力应对如今盘踞这些洞穴的腐化生物。$b$b我求求你，进入洞穴，向那些畸变生物开战！',12340),
(1488,1,15,'荣耀归于部落，而死亡归于吾敌，$N！$B$B凄凉之地的恶魔领主比以前更具威胁性了，我希望以后去觐见大酋长的时候，每次都能向他报告好消息，而不是像现在这样……$B$B有些时候，我真希望只有半人马需要对付。',12340),
(1489,1,0,'你师傅们把你派到这里实在太蠢，因为我再也不是天灾的奴隶了！',12340),
(1490,1,0,NULL,12340),
(1491,0,0,'我要的哀嚎香精在哪里？',12340),
(1492,0,0,'你是想搭下一班船呢，还是你有什么东西要送？',12340),
(1498,1,0,'你拿到鳞片了吗，$N？除非你可以承受那些雷霆蜥蜴的猛烈攻击，否则我不会给你任何好处的。',12340),
(1499,1,0,NULL,12340),
(1501,1,0,'你找到维尔加石板了吗，$N？没有它的话，我是不会和你说任何事的。',12340),
(1502,1,0,NULL,12340),
(1503,1,0,'你找到我的那些钢锭了吗？',12340),
(1504,1,0,'虚无行者是一种强大的生物。我现在还清晰地记得当年我与它战斗时的情景，$N。经过了这么多年，我的虚无行者已经很少与我发生冲突了，我想这也许是它想让我放松警惕的缘故吧。$B$B牢牢记住这一点，$N。',12340),
(1505,1,0,NULL,12340),
(1506,1,0,NULL,12340),
(1507,1,0,NULL,12340),
(1508,1,0,NULL,12340),
(1509,1,0,NULL,12340),
(1510,1,0,NULL,12340),
(1511,1,0,'怎么啦？',12340),
(1512,1,0,'你回来了。准备好挑战魅魔了吗？',12340),
(1513,1,0,'一看到魅魔，我的心脏就开始咆哮……但与此同时，我能感觉到我的灵魂正在迅速消逝，如海潮退却一般地衰减。$B$B你要多加小心，我的朋友。',12340),
(1514,1,0,'你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(1515,1,0,'啊啊啊……有人来救我了吗……',12340),
(1516,1,0,'坚韧是大地最伟大的美德。大地见证着万物归环的道理：巍峨的高山或许会变为平坦的沙漠，宽阔的河流或许会变为狭窄的溪谷。大地的元素是所有元素之中最亘古不变且最为睿智的，它不会容忍任何急躁的行为。$B$B时间就要到了，大地将会召唤你。当你在成功后再度回到我这里来的时候，你就会对它有更深的了解。$B$B无知者会因你的睿智而嫉妒你，因他们的渺小而憎恨你。',12340),
(1518,1,0,'希望我是第一个欢迎你踏上萨满之道的人。$B$B如果你已经拥有了大地赐予你的石头，那么我就会按约定把图腾交给你。$B$B但如果你还没得到，那么就继续去追寻吧。',12340),
(1519,1,0,'大地是宽容的，她将等到你完全准备好接受挑战为止，因为她知道，随着时间的流逝，事物会腐朽入土，也会获得新生。这是万物的轮回。巍峨的高山会变为平坦的沙漠，宽阔的河流会变为狭窄的溪谷，而大地是所有自然的元素之中最恒久睿智的。$B$B你也必须要拥有这样凌驾于一切之上的宽容与韧性。大地之所以对你发出了感召，是因为她认为你已经准备好了。将这次的仪式作为你重生的祭典吧，从此你将告别野蛮和无知。',12340),
(1520,1,0,NULL,12340),
(1521,1,0,'你好，$N。如果你没有完成你的任务，你就不用再回来找我了。愿我能成为第一个欢迎你踏上你萨满道路的人。$B$B如果你已经拥有了土元素交给你的石头，我将会按照约定把图腾柱给你。如果你没得到，那么很可惜。只有当你将自身完全奉献给元素时，拥有它才会值得你自豪，也只有那样，拥有它才会有意义。',12340),
(1522,1,0,NULL,12340),
(1523,1,0,NULL,12340),
(1524,1,0,'恭喜你，$N。你已经来到来眠炎圣殿，只有那些通晓萨满之道的人才能发现这里的秘密，以及蕴藏在这里的巨大能量。但是很抱歉，你长途跋涉来到这里，现在有必须原路返回。这一路的确危机四伏，但是作为圣殿的守护人，我不能让任何人在这里游荡。',12340),
(1525,1,0,'只要你能找来试剂袋和火焰焦油，我就可以给你制作火焰灵契。燃刃祭司的试剂袋里通常都装着制作火焰灵契所需的所有材料，而且数量也很充足。$B$B只有用与某种元素属性相同的材料才能制成那种元素的灵契，这也让我们的工作轻松了不少，只要去找那些成天和火焰打交道的术士就行了。',12340),
(1526,1,0,'火盆只有你的三分之一高，看起来没什么特别，只是在光滑的金属围栏上刻有文字。整座火盆都没有任何风化侵蚀的痕迹，摆在顶端的小碗摸上去十分冰凉。',12340),
(1527,1,0,'嗯，这不是$N吗？',12340),
(1528,1,0,NULL,12340),
(1529,1,0,NULL,12340),
(1530,1,0,NULL,12340),
(1531,1,0,'',12340),
(1532,1,0,NULL,12340),
(1534,1,0,'你找到泉水了吗，$N？传说有强大的生物保卫着那片废墟，它们不惧怕任何不速之客。不过，那可能只是暗夜精灵用来吓唬敌人的伎俩而已。$B$B不管怎么样，你要多加小心。',12340),
(1535,1,0,'我正在准备交给你下一项任务。你装满水囊了吗？$B$B我知道这些野猪人会拼命保护他们的水源，即便是一滴水对他们来说也是一笔巨大的财富。偶然降临贫瘠之地的毛毛细雨对他们而言也不啻为一场盛筵。他们将水视为神圣之物，因为它是如此稀少。你明白了吗？',12340),
(1536,1,0,'$N，镇中那口井依然保持纯洁，这让我想起年轻时曾听到过的故事。即使是在最痛苦和最悲伤的时候，你也能找到一丝微弱的希望和重新振作的可能。兽人眼中的萨尔就是这样一种象征，他从绝境中站立起来，用他的力量和精神指引着他的人民。$B$B我想不会有哪个兽人和他一样经历过如此多的磨难，当然，也不会有谁像他那样强大。',12340),
(1558,1,0,'我们到了吗？',12340),
(1559,1,0,NULL,12340),
(1560,1,0,'图加在哪里？',12340),
(1578,6,6,'我没时间闲聊。你有事找我吗？',12340),
(1579,6,6,'$N，你找到我的小齿轮了吗？没有小齿轮，我这个伟大的发明家就什么都干不了！',12340),
(1580,6,6,'你找到导电器了吗？我得有这些东西才能继续研制诱鸭器。',12340),
(1581,1,0,'你好，$N。你弄到我要的药剂了吗？',12340),
(1582,0,0,'你好，$N。',12340),
(1598,11,0,'要我自己去把书从图书馆里偷来实在是太丢人现眼了，他们那帮蠢货可真是帮我大忙了。',12340),
(1599,1,0,'那些新兵们带着的羽毛符咒使他们拥有了一些魔法力量，研究它们是件有趣的事情，但是这些蠢货也只有这么点魔法能力了。',12340),
(1618,1,1,'我希望你从铁炉堡带来的是好消息，我这儿已经快要应付不过来了！',12340),
(1638,1,0,NULL,12340),
(1639,1,0,NULL,12340),
(1640,1,0,'你想要我的酒杯？先打倒我再说吧！',12340),
(1641,1,0,'',12340),
(1642,1,0,NULL,12340),
(1643,1,0,NULL,12340),
(1644,1,1,'但愿我丈夫约翰在铁炉堡能有更好的运气。他并不想把我和孩子们留下，自己一个人跑去那儿，不过他知道必须这么做，他真是太善良了。$B$B前些年的生活还不错，不过现在的日子越来越难过了。我们都能感觉到好像会有重大的变化发生，不过又有谁知道呢？',12340),
(1645,1,0,NULL,12340),
(1646,1,0,NULL,12340),
(1647,1,0,NULL,12340),
(1648,1,1,'就算是这里和整个艾泽拉斯的商人都愿意帮忙，我们也无法得到足够的材料为孤儿院的所有孩子们制作衣裳。请帮我收集一些亚麻布，好让我的妻子力所能及地帮助孩子们。谢谢您，$N。$B$B如果走运的话，不久之后我就能回家见到我的妻子了。',12340),
(1649,1,0,NULL,12340),
(1650,1,0,NULL,12340),
(1651,1,0,'我们要守住这里！',12340),
(1652,1,0,NULL,12340),
(1653,1,0,NULL,12340),
(1654,1,1,'这些材料很难找到，不过我可以向你保证，我为你制造的武器绝对值得你这么做。$B$B这将是我当前为止最出色的作品，是送给你当作回报的。',12340),
(1655,11,11,'运气怎么样？哈哈，那些巨魔打不过你，对不对？',12340),
(1656,6,6,'你好，年轻人，我能为你做点什么吗？$B$B从台地走到这里对某些人来说可实在是极大的负担，不过对另一些人则是开阔眼界的好机会。我想知道你是这两种人里的哪一种？',12340),
(1657,1,11,'你把我们的“礼物”送给南海镇的居民了吗？$B$B<黑暗召唤者雅恩卡邪恶地笑了起来。>',12340),
(1658,1,0,'你去过提瑞斯法林地查看过了吗？他们通常会在幽暗城附近庆祝那个节日……',12340),
