(1666,1,0,NULL,12340),
(1667,6,6,'你找到我的勋章了吗？我可不希望蛀牙杰克用它去作恶。',12340),
(1678,1,0,'你去过维吉雷克的棚屋了吗，$N？',12340),
(1679,1,0,'可有什么收获吗？',12340),
(1680,1,0,NULL,12340),
(1681,1,0,'你去过铁环的小院了吗？你找到阴影矿石了吗？',12340),
(1682,1,0,NULL,12340),
(1683,1,0,'你拿到角了吗，$N？玷污月亮井的恶魔沃鲁斯死了吗？',12340),
(1684,1,0,NULL,12340),
(1685,1,0,NULL,12340),
(1686,1,0,'你打败艾鲁拉的阴影了吗，$N？你找到丢失的月神矿石了吗？',12340),
(1687,1,0,'我们到了吗？',12340),
(1688,1,1,'即使是睿智的长者有时也会被年轻貌美的女人迷惑，$N。你得牢牢记住这个忠告。',12340),
(1689,1,1,'在你制服虚无行者之前，我没办法教你怎么控制它。',12340),
(1690,1,0,'那么快就回来了？我希望你已经按照我的要求，以地精的方式为我们伸张了正义！',12340),
(1691,1,6,'怎么样，你杀死那些游牧民了吗？加基森水业公司需要你的成功来开展进一步的行动！不要让我们失望，现在就去……',12340),
(1692,1,0,'你好，年轻的$C。我的手艺能为你做什么？',12340),
(1693,1,0,NULL,12340),
(1698,1,0,NULL,12340),
(1699,1,0,NULL,12340),
(1700,2,0,'你好，很高兴见到你。我能帮你什么忙吗？',12340),
(1701,6,6,'你的任务完成得怎么样了，$N？拿到材料了吗？',12340),
(1702,3,0,'你好！今天真是个无聊的日子，你不觉得吗？',12340),
(1703,2,0,'向你致意，$C。',12340),
(1704,2,0,'你好啊，我也不知道该说“早安”还是“晚安”。因为在这里我分不清是白天还是夜晚。你找我有什么事？',12340),
(1705,6,6,'$N，你拿到燃烧之血和燃烧之石了吗？我需要用它们来完成这件铠甲。',12340),
(1706,1,0,NULL,12340),
(1707,6,6,'拿到我要的五个废土水袋了吗？如果你能帮我们找到五个废土水袋的话，加基森水业公司的103——XB型护理袋就是你的了！',12340),
(1708,3,3,'你好你好，$N！你搞到灼热珊瑚了吗？我恨不得马上就开始工作！',12340),
(1709,1,0,NULL,12340),
(1710,6,6,'你找到蛋壳了吗，$N？我可以把它们碾碎并制成强力的护甲漆，然后就可以用它来加固我新制作的锁甲了。',12340),
(1711,1,0,NULL,12340),
(1712,6,6,'你找到那些东西了吗，$N？找到这些东西，这样你才能证明自己有力量面对塞克隆尼亚。',12340),
(1713,5,5,'$N，我必须得到旋风之心！',12340),
