(1719,1,0,'你完成挑战了吗？',12340),
(1738,6,6,'你找到同心树了吗，$N？',12340),
(1739,11,11,'有的时候我会想，苏伦娜是不是一个伪装之后跑来扭曲和破坏我的意志的魅魔……哈！我想我的确给她带来了太多的麻烦。',12340),
(1740,1,0,'我用了很多年的时间来收集札盖恩宝珠的碎片，对我而言，它很好使，我想对你也一样。',12340),
(1758,1,0,NULL,12340),
(1778,1,0,NULL,12340),
(1779,1,0,NULL,12340),
(1780,1,0,NULL,12340),
