(1782,1,0,NULL,12340),
(1783,1,0,NULL,12340),
(1784,1,1,'你回来了！我很高兴你能回来，$N。我的伤已经好了，只要我能够说服我的妻子不要再多担心我，就可以准备回到盔枕湖去了。',12340),
(1785,1,0,NULL,12340),
(1786,1,0,NULL,12340),
(1787,6,6,'亨兹还好吗，$N？你成功了吗？$B$B以你的战斗技巧，再加上光明的力量，我想英雄岗哨不会再受到迪菲亚盗贼的威胁了，不过那是国王和他的顾问应该关心的事情。',12340),
