(1794,1,0,NULL,12340),
(1795,1,0,'每个$C都应有一只地狱犬听命。虽然它难以驯服，但它带给主人的力量远超代价。',12340),
(1796,6,6,'你搜寻长袍的进展如何，$N？你是准备亲自制作长袍吗？如果你自己动手的话，就会有很大的成就感。不过如果你准备走捷径找人为你制作的话，我也可以理解你想要迅速强大起来的——怎么说呢……雄心壮志。',12340),
(1798,1,0,NULL,12340),
(1799,6,6,'一看就知道你不是个法师，我不知道自己能不能相信你。我可以嗅到你身上的魔法的味道，但是却没有什么堕落的气息混杂在其中。$B$B没错，一个$C……一个来寻求我帮助的$C。$B$B好吧，我可以为你做点什么呢，$N？',12340),
(1800,1,0,'我们到了吗？',12340),
(1801,1,0,NULL,12340),
(1802,1,0,'事情进行得怎么样了，$N？',12340),
(1803,1,0,'也许你所追寻的东西只是一团空气，$N，但真相往往就隐藏在最夸张的谣言之中。',12340),
(1804,1,0,'好一阵子没在这附近见到你了。你找到那本书和那些法杖了吗？',12340),
(1805,1,0,'$N，还有什么事吗？我还能为你做些什么？',12340),
