(1842,1,0,'你得到它们的蹄子了吗，$N？那些蹄子里面蕴含着强大的力量。',12340),
(1843,1,0,NULL,12340),
(1844,1,0,'你得到角了吗？她最终得到解脱了吗？',12340),
