(2845,1,0,'我正在担心你呢！谢谢你带沙恩回来，$N。',12340),
(2846,6,6,'你取得了那个皇冠吗，$N？维蕾萨有没有付出代价？',12340),
(2847,1,1,'就像我说过的那样，你要想学会制作蛮皮护甲，就得先替我工作。野葡萄是强大而又混乱的，它可以在原本已经非常强大的护甲上加上随机的魔法属性，但是我发现这一点可是花了很长时间的。$B$B这一过程的最初阶段的花费是十块厚皮。$B$B当你得到十块厚皮之后，我们再继续进行下一步工作，给你护甲的图样。',12340),
(2848,6,6,'你弄到我要的六块厚重护甲片和一株野葡萄了吗？$B$B不要以为制作护甲片是一种简单的体力活儿，当你制作护甲片的时候，你也在不断提高自己在装饰方面的技能，这种训练对于提高制作精细装备的技巧也有很大的帮助。$B$B看到了吧——其实这才是我让你给我带六块护甲片来的真正原因……',12340),
(2849,6,6,'你弄到两件龟鳞外衣和两副龟鳞手套了吗？还有别忘了野葡萄！$B$B即使是最基本的图样，其基础造型也可以被转化运用到更多更复杂的装备制作工艺中。通过制作龟鳞外衣，你应该已经掌握了制作蛮皮外衣的基本要领。$B$B还有手套……好了，你要为我带来这些东西。记住，你是在为我工作！',12340),
(2850,1,1,'我需要那些外套和头罩，另外还需要一株野葡萄，然后我就会把蛮皮盔帽的制作方法告诉你。$B$B防护头部的装备是冒险者们垂涎已久的，无论是简单的头带还是一顶密闭的盔帽，无论其外观如何，制造有价值的头部装备的道理是恒久不变的。',12340),
(2851,6,6,'在你学习这个图样以前，你必须完成裤子、靴子和野葡萄的订单，$N。你找到这些东西了吗？$B$B从我们学会制作第一双靴子起，我们便开始懂得如何掌握靴子的舒适性与功能性之间的尺度。只有兼顾两样，我们才能够制造出令穿着者忘记疲劳的靴子，我们的靴子绝对会让那些劣质的同类产品无地自容。',12340),
(2852,6,6,'你弄到龟鳞头盔和护腕了吗？另外不要忘记我还要两株野葡萄。$B$B现在，你已经开始意识到蛮皮护胫潜在的能量了。一件拥有无穷应用潜力的护甲对于一个皮革匠来说是无价的，唯一的瓶颈是制作这些护甲所需要的原料——而不是成品的品质！',12340),
(2853,2,2,'你好，$R……从你的神情我看得出你也和我一样是个制皮师。你是来学我的手艺，还是另有别事？',12340),
(2854,1,0,'就像我说过的那样，你要想学会制作蛮皮护甲，就得做我的学徒。野葡萄是强大而又混乱的，它可以在原本已经非常强大的护甲上加上随机的魔法属性，但是我发现这一点可是花了很长时间的。$b$b这一过程的最初阶段的花费是十块厚皮。$b$b当你得到十块厚皮之后，我们再继续进行下一步工作，给你护甲的图样。',12340),
(2855,1,0,'你带来六副厚重护甲工具包和我需要的野葡萄藤了吗？$b$b把制作护甲工具包当作一堂关于稳定可靠工艺的课；你通过这些工具包练就的一贯手法，会帮你掌握制作野性皮甲所需的精细工夫。$b$b每一课都有其意义，$N。重要的是相应地对待每一课。',12340),
(2856,1,0,'你弄到两件龟鳞外衣和两副龟鳞手套了吗？还有别忘了野葡萄！$b$b即使是最基本的图样，其基础造型也可以被转化运用到更多更复杂的装备制作工艺中。通过制作龟鳞外衣，你应该已经掌握了制作蛮皮外衣的基本要领。$b$b当你逐渐熟练了之后，你的手艺就会如艺术一般完美。',12340),
(2857,1,0,'我需要那些外套和头罩，另外还需要一株野葡萄，然后我就会把蛮皮盔帽的制作方法告诉你。$b$b防护头部的装备是冒险者们垂涎已久的，无论是简单的头带还是一顶密闭的盔帽，无论其外观如何，制造有价值的头部装备的道理是恒久不变的。',12340),
(2858,1,0,'在你学习这个图样以前，你必须把裤子、靴子和野葡萄给我拿来，$N。你找到这些东西了吗？$b$b从我们学会制作第一双靴子起，我们便开始懂得如何掌握靴子的舒适性与功能性之间的尺度。只有兼顾两样，我们才能够制造出令穿着者忘记疲劳的靴子，我们的靴子绝对会让那些劣质的同类产品无地自容。',12340),
(2859,1,0,'你弄到龟鳞头盔和护腕了吗？另外不要忘记我还要两株野葡萄。$b$b现在，你已经开始意识到蛮皮护胫潜在的能量了。一件拥有无穷应用潜力的护甲对于一个皮革匠来说是无价的，唯一的瓶颈是制作这些护甲所需要的原料——而不是成品的品质！',12340),
(2860,1,0,'你好，$r……从你的神情我看得出你也和我一样是个制皮师。你是来学我的手艺，还是另有别事？',12340),
(2861,1,0,'',12340),
(2862,5,5,'我们把那些豺狼人都击退了，但是它们仍然在坚持进攻！一定是有什么人或什么东西让它们变得如此疯狂……哦，你回来了，任务完成了吗，$N？你拿到我要的鬃毛了吗？',12340),
(2863,1,0,'时间宝贵，$N！如果你来这里不是要向我报捷的话，那么你就是在浪费时间！',12340),
(2864,1,0,'',12340),
(2865,0,0,'你弄到壳了吗？我那藏宝海湾的堂兄在等着我给他寄去一大批壳呐，他已经等得不耐烦了！',12340),
(2866,1,0,'当你进入废墟的中心地带后，你注意到这个了望台显得格外突出……',12340),
(2867,1,0,'',12340),
(2869,1,1,'$N，如果你来这里是来核实我交给你的任务，那么，很好——我要的是十块憎世纳迦的鳞片。如果你来这里是为了闲聊，那么现在我没空和你多罗嗦。$B$B要知道，我们暗夜精灵不是好战分子，我们致力于维护和平与安宁，但这并不代表我们会放弃维护自己的利益。这是我对羽月将军和这座要塞应尽的职责。',12340),
(2870,6,6,'除掉沙尔札鲁领主必定能让他们的计划拖延至少数个星期。除此之外，那块圣物也让我们非常感兴趣。$B$B$N，你完成任务了吗？',12340),
(2871,2,0,'嗯，我能帮你什么忙吗？$B$B等等，你是协助羽月将军和拉托对付纳迦的$C，对吗？我是维斯提亚，拉托——嗯，或许叫拉托尼库斯更合适些，我是他的妻子。很高兴见到你！$B$B对不起，你是有什么东西要交给我的吗？',12340),
(2872,1,0,'',12340),
(2873,6,6,'你有没有找到我的那批朗姆酒，$N？',12340),
(2874,6,0,'斯杜雷有没有交出我要的那瓶酒？',12340),
(2875,0,0,'你看起来有些神情恍惚，是不是刚刚看过我们的法律文件？',12340),
(2876,0,0,'你看起来上气不接下气的，有什么事吗？',12340),
(2877,1,5,'别想就当前任务讨价还价，$r！如果众神想要那些软泥死，他们早该用奇迹办成了，不是吗？！',12340),
(2878,1,0,'你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(2879,1,0,'艾奎尼克斯石碑静静地立在废墟中。它到底蕴藏着什么秘密呢？',12340),
(2880,5,5,'我想要那些巨魔身上的部族项链。如果你想得到它的话，那就把你所看到的巨魔都干掉吧！$B$B向蛮锤部族证明你的价值！',12340),
(2881,1,0,'我要五条巨魔随身携带的部落项链。如果你还需要我说明白些，那么杀掉其中一个就有很大机会得到一条！$B$B向蛮锤部族证明你的价值！',12340),
(2882,1,0,'这个箱子被锁上了！',12340),
(2902,1,0,'在豺狼人营地里的一堆堆垃圾中有一张画得很潦草的地图……',12340),
(2903,6,0,'欢迎回来，$N——你有没有找到豺狼人的作战计划之类的东西？',12340),
(2904,1,0,'嗯？克努比还活着？',12340),
(2922,6,6,'你有没有发现尖端机器人？你有没有找回它的记忆体核心？',12340),
(2923,1,0,'',12340),
(2924,6,6,'你拿到基础模组了吗？',12340),
(2925,1,0,'',12340),
(2926,5,5,'你没看见我们正在这里想办法治疗地精族群所面临的瘟疫吗？！我们需要更多的辐射尘！',12340),
(2927,1,0,'嘿，拉兹，看看这个穴居怪带来了什么！',12340),
(2928,0,0,'如果这个任务是场比赛的话，你现在已经失败了。',12340),
(2929,1,0,'任务完成了吗？他有没有请求你的宽恕？',12340),
(2930,6,6,'你拿到棱彩穿孔卡片了吗？',12340),
(2931,1,0,'',12340),
(2932,1,0,'你还没有完成我交给你的任务，$N。',12340),
(2933,0,0,'你好啊，$C。整整一天了，没有一次实验是成功的……我希望你带给我的是好消息。',12340),
(2934,0,0,'你拿到完好无损的毒囊了吗，$N？我渴望用新鲜的毒液做实验，而且已经定购了一大批蹦蹦跳跳的小动物作准备！',12340),
(2935,1,0,'',12340),
(2936,1,0,'你知道蜘蛛之神的名字了吗？',12340),
(2937,6,6,'你拿到毒液了没有？',12340),
(2938,0,0,'有消息说你要来，$N。你有包裹给我？',12340),
(2939,1,0,'',12340),
(2940,1,0,'你找到了什么吗？',12340),
(2941,6,0,'给我的信？',12340),
(2942,1,1,'我很高兴你回来了，$N。你有什么新的发现吗？',12340),
(2943,6,0,'你好，$N。你去过达纳苏斯了吗？',12340),
(2944,1,1,'嗯，你终于回来了，$N。你还带来了克格尔为我制造的装置——真是太好了。',12340),
(2945,1,0,'你面前的地精装置上面钉着一张金属铭牌，上面写着“超级清洁器5200型”。阅读了铭牌上的说明之后，你发现这台机器是用来清洗污垢的，它是一个投币装置，将想要清洁的物体放入其中，然后投三枚银币，机器就会启动。$B$B你前不久发现的那枚脏兮兮的戒指正好可以用来试试看！',12340),
(2946,1,0,'这个看起来很眼熟的底座从滚烫的沙子里突了出来。这其中一定有什么原因……',12340),
(2947,1,0,'嘿，朋友，放轻松点——我是个有头有脸的商人！肯定是邮差忘了把帐单给我送来……等等……你不是我的房东。$B$B好吧，你当然不是来耍我的！你是来寻找铁炉堡最好的珠宝商的吧，我可绝对不会制作被诅咒的珠宝哦！绝对不会！$B$B嗯……你需要什么？',12340),
(2948,1,0,'你拿到我需要的材料了吗？要不是我运气实在不好，我也不会问你要……',12340),
(2949,1,0,'我们一定要找到一种方法来击败那些丑陋的小地精，我甚至敢跟你打赌，他们从我们这里偷走钻探设备只是一个开始！呸，那些肮脏的小滑头……嗯，什么？你需要什么东西吗？',12340),
(2950,1,0,'你拿到我需要的材料吗？没有那些东西，我可没办法对戒指进行改造。',12340),
(2951,1,0,'似乎这个装置需要某种脏兮兮的东西和三枚银币才能运行。既然两样都有了，超级清洁器5200型应该开始运转了……',12340),
(2952,1,0,'',12340),
(2953,1,0,'超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动！',12340),
(2954,1,0,'在进一步发展之前，你必须知道石之看守者要让你干什么……',12340),
(2962,1,1,'嗯，你没有发光，这是个好兆头。',12340),
(2963,1,0,'',12340),
(2964,1,0,'',12340),
(2965,1,0,'',12340),
(2966,1,0,'这个看起来很眼熟的底座从滚烫的沙子里突了出来。这其中一定有什么原因……',12340),
(2967,6,6,'欢迎回来，$N。那张圆盘对你有用吗？或者它根本就是个没用的东西？',12340),
(2968,1,0,'随着风吹过，变化的迹象开始散播。你是不是想要知道我对奥丹姆的看法呢？',12340),
(2969,1,0,'我们不能让恐怖图腾氏族毁灭这些美丽的精灵龙！',12340),
(2970,1,1,'金达尔需要时间准备，可我们杀掉的已经有好几十个了。恐怖图腾氏族非常清楚我们在这片区域，他们像毒蛇一样搜寻我们。$B$B他们会全力砍下我们的头。你该保持警惕……既然你插了手，他们现在也会来找你。',12340),
(2972,1,0,'你好，孩子。我们为越来越多强大的冒险者来到神殿感到由衷地高兴。如果你有时间的话，能和其它年轻的冒险者们分享一下你的故事吗？我相信这样对他们会有很大的帮助。$B$B对不起，请原谅我的鲁莽。你应该是到神殿里来寻求帮助的，我失礼了。请你原谅。我能为你做些什么？',12340),
(2973,1,1,'被激怒的小精龙是非常危险的，和它们打交道要多加小心，$C。这个地区的暗夜精灵比它们还危险，那些烦人的蠢货也会在森林里出没。$b$b当你拿到足够多的翅膀之后就告诉我，我一定会好好奖励你的！',12340),
(2974,1,1,'认真听我说，$C，恐怖图腾氏族都是恶魔。如果你在附近看到他们，那你就应该尽快决定是否要迎头痛击他们……否则他们就会闯入我们的领地，夷平我们的村庄，玷污我们的土地。',12340),
(2975,1,0,'行动迅速点，$N。难道是这个任务对你来说太难了？',12340),
(2976,1,0,'快一点，$C，我今天有很多事要做。',12340),
(2977,6,0,'欢迎回来，$N。那张圆盘对你有用吗？或者它根本就是个没用的东西？',12340),
(2978,0,0,'这是什么？',12340),
(2979,0,0,'我们必须找到更多资讯，才能知道戈杜尼巨魔出现在这里的原因，$N。',12340),
(2980,1,0,'你找到那片废墟了吗，$N？',12340),
(2981,1,0,'',12340),
(2982,1,1,'$N，你要小心那些戈杜尼巨魔。他们的魔法似乎已经在他们所占领的土地上造成了一场大灾难。',12340),
(2983,1,0,'',12340),
(2984,1,0,'',12340),
(2985,1,0,'',12340),
(2987,5,5,'赶快去挖！$b$b我还要去很多地方，见很多人——时间就是金钱！',12340),
(2988,1,0,'你有没有搜查过笼子，$N？我们必须得找到沙普比克！',12340),
(2989,1,0,'赶快，$N！邪枝巨魔抓到了沙普比克，谁知道他们会对他干些什么！',12340),
(2990,0,0,'$N，你给我带来了什么礼物？',12340),
(2991,6,6,'你拿到耐克鲁姆的勋章了吗，$N？我急切地等待着发现勋章中隐藏的力量。',12340),
(2992,1,0,'',12340),
(2993,1,0,'',12340),
(2994,1,0,'救出沙普比克！',12340),
(2995,1,6,'将高原精灵孤立起来是一切的关键……你找到小屋了没有？',12340),
(2996,1,0,'',12340),
(2997,1,0,'',12340),
(2998,1,0,'',12340),
(2999,1,0,'',12340),
(3000,1,0,'',12340),
(3001,1,0,'',12340),
(3002,6,0,'你给我带什么来了，$R？',12340),
(3022,0,0,'我猜又是从克格尔那儿来的货吧？',12340),
(3042,0,0,'你拿来我要的调和剂了吗，$N？',12340),
(3062,0,0,'不能让艾丹娜继续在这片土地上继续为非做歹了。',12340),
(3063,1,0,'北泉鹰身人的翅膀象夜一样黑不要让它们从你的视线中消失，否则黑夜会掩盖它们的行踪。',12340),
(3065,2,0,'又一个加入我们队伍的$R，很好！$b$b或许要你举起像斧头这样的好武器会有些困难，但长矛或其它什么武器也一样好用。$b$b欢迎来到试炼谷。',12340),
(3082,2,0,'珍莎在强大的$C面前看到了，众灵也认可。$b$b$C之道是我们最古老的生活方式之一。当年部落还在艾泽拉斯艰难求生时就求助于我们，要我们教导他们，向他们揭示许多事物的秘密。他们本已很强：萨满之道强，战士之道强。但$C之道并非他们那时的道路。',12340),
(3083,2,5,'欢迎来到试炼谷，$n。如果你没有收到我的石板的话，就不会找到这儿来了，因此让我们单刀直入吧。$B$B我叫鲁瓦格，在试炼谷负责训练盗贼、小偷和刺客。如果你还没有为将来的使命做好准备，我就得对上面负责。但是别担心，上面不会操纵你所做的每件事，可是如果他们需要你这种人才的话，和他们合作才是明智之举。',0),
(3084,2,0,'啊，欢迎，$N。我很高兴你能来这里。我有很多学生要教，日子变得越来越忙碌，不过像你这样的学生的到来将会给我带来很强的成就感——我还记得你们的萨满教导我的那段日子。',12340),
(3085,2,0,'你终于来了……很好，很好！我的灵魂告诉我，你很快就会来见肯杰。我将是试炼谷中第一个来欢迎你的人。这里只是你暂时的家，既然如此，你就该好好珍惜这段时光。',12340),
(3086,2,0,'你看起来已经让迈安很满意了，$N。这样很好，你尊重迈安，迈安也会尊重你。好了，你是来学习魔法，不是来听迈安说话的。$B$B关于魔法，只有一件事是迈安不能教你的，$N，那就是如何防止自己因追求力量而堕落。',12340),
(3087,2,0,'啊，你终于来了，太好了。基沙在这里等你。$B$B许多人认为这条道路很平坦，但基沙告诉你:并不是这样的。控制杜隆塔尔或其它地区的野兽与掌握魔法或是同我们的祖先交流一样需要很多技巧。$B$B对你来说，射箭开枪可能没有施放魔法那样危险，但它对你的敌人来说却是一样危险的。',12340),
(3088,2,5,'嘘，小声点。我对站在那边的纳托克可不信任。对那些在洞中比我“隐藏”得更深的家伙，我们要小心对待。$b$b我相信你在这里不会迷路吧？',12340),
(3089,2,0,'你来了，我正在想你什么时候会来呢，前一段时间我把羊皮纸送出去之后就没了下文。$B$B说了够多闲话了……我让你来这儿是因为你已经被选中来指引我们同胞的精神生活。',12340),
(3090,1,0,'你终于来了……而且还很谨慎。很好。$b$b我们的世界满是蠢人，阿萨托克塔。就连强大的萨尔也有大多数人看不见的缺陷。他背弃了让这片土地彻底归我们所有所需的力量！我们已不再是那个被来自虚空的生物操纵利用的种族。我们是自己的种族。我们自豪……而且强大。',12340),
(3091,2,2,'啊，你终于来了，$C。我在便条里没有说谎，$N。我们也是一个特殊的种族，与我们部族的德鲁伊或萨满并无不同。你同样重要。我们就是那些被召唤来保卫边境、猎杀半人马、奔赴战场的人。',12340),
(3092,2,2,'欢迎来到纳拉其营地，$n。我已经听说过很多关于你的事情了。你拥有优良的血统，所以许多长者都认为你已经具备了相当的素质，但是你还需要磨练。$b$b莫高雷平原在接下来的一段时间里将成为你的家——你最好在这里认真地学习。终有一天，你会离开这里，踏上陌生的土地去进行更高层次的修炼，你要做好准备。',12340),
(3093,2,2,'转瞬之间，你就来到了我的面前。我很高兴你的动作如此迅速，这意味着你已经意识到了来这里见我是多么的重要。我并不是一个领袖，但是我懂得作为领袖所必须具备的素质，我还能和我们同胞的灵魂进行沟通。我会把这些都教给你的。',12340),
(3094,2,2,'你终于来了。太好了。我们祖先的灵魂在莫高雷一带开始变得越来越不平静，但我不知道为什么。学会聆听自然的灵魂，成为它们的化身——这将是你永远的任务。你应该永远记住这一点。',12340),
(3095,1,0,'啊，你来了，很好。我听说有一些人也逃脱了“死亡”，并纷纷涌入镇子里。或许我们有一天会重归安宁。$B$B你应该感谢希尔瓦娜斯，她给了你自由……心灵和肉体的自由。虽然你仍遭受着瘟疫的折磨，但你现在至少可以随自己的心愿来去了。',12340),
(3096,1,0,'你终于来了？很好，随着时间的流逝，我们会需要更多的盗贼。当巡影者认为时机合适的时候就会马上会找你，所以不要疏忽，不要做你可能会后悔的事情。他们需要有才能的密探……而不是小贼和蠢货。',12340),
(3097,1,0,'啊，在火灾、瘟疫、暴动和其它更糟糕的灾难中，那些值得“信赖”的东西就成了我的希望。好吧，欢迎你，$C。请允许我花些时间解释一两件事，然后你再决定要在什么时候去寻找你生活的意义:圣光不再眷顾你，你祖先的精神祇是一些缥缈的传说，扭曲虚空中的恶魔不再需要你。$b$b你能明白我的意思吗？',12340),
(3098,1,0,'$N，我知道你会来的。之所以这么说是并不是因为你无法按照自己的意志前进，而是因为我们具有相似的灵魂，我们都感受到了痛苦。现在我们都拥有了力量，能够把属于我们的土地、生命和命运掌握在自己手里的力量。但是你还要学很多的东西。',12340),
(3099,2,0,'欢迎你的到来，我的$g兄弟:姐妹。我知道你会来的，只是个时间早晚的问题。$b$b你对我所说的事情感兴趣，对吗？我的话引起了你的共鸣……你的心知道我说的是真的。很好。$b$b不过你要知道，我并不是背叛了希尔瓦娜斯。就算她知道我说了些什么，她也会欣赏我的，因为正是她的信仰让被遗忘者走到了今天。',12340),
(3100,2,0,'啊，你收到我的信了，$N……太好了。$B$B最近有许多战士涌入艾尔文森林——对于暴风城来说，这真是个好消息，但这一地区的豺狼人和迪菲亚盗贼可不会喜欢这个消息。',12340),
(3101,4,0,'你终于来了！我们终于见面了，欢迎你来到北郡。在你学习技艺的这段时间里，这里将是你的家。暴风城离这里并不远，不久之后，命运就将指引你到那里去。但是你一定要有耐心，一切都要慢慢来……白银之手骑士团的骑士。',12340),
(3102,2,0,'你顺利地来到了这里，好像并没有多少人注意到你。这对我来说很好，因为我不想有很多人注意到我这里……越低调越好，我相信你会理解这一点。$b$b你有什么麻烦吗？我希望没有，不过很快一切都会改变的。',12340),
(3103,2,0,'啊，你终于来了。我知道你会来的。圣光照耀着你，你选择了属于你的道路。这是个艰险的时代——艾泽拉斯大陆上仍有燃烧军团的存在，卡利姆多大陆上的人们在寻找生机，你能提供多少帮助就提供多少吧。',12340),
(3104,6,0,'你好，$N。我是凯尔东。有什么我能帮你的吗？',12340),
(3105,1,0,'啊，你来了，来得正好，$N。刚才有些守卫经过这里，用好奇的眼神看着我……这些可怜的凡人。',12340),
(3106,6,0,'该死的大冷天，看起来这大雪永远也化不掉了，$N。$b$b你也许已经注意到了，我们的城市中居住着许多地精。这是因为他们自己的家园被占据了。不要到处说这些话，我也不会因为他们和我们住在一起而责备他们——如果黑铁矮人或者别的什么该死的家伙占据了铁炉堡的话，我也会暴跳如雷的。',12340),
(3107,1,0,'你终于来了！一点都没有拖延。寒脊山谷中还有很多事要做，我需要你的帮助，你也需要我的帮助！$B$B你现在是白银之手骑士团的骑士了，准备承担你的责任吧。',12340),
(3108,4,0,'你终于来了！很高兴见到你！你最好不是跟在我身后找到这里来的，哈哈！$B$B我们这个职业拥有优良的传统，$N。你需要学习一些关于这片土地的东西，比如学习如何在山岭中追踪一只熊。即使简单的生存技能也需要投入很多的勇气和智慧才能熟练掌握。你认为你能够胜任吗？',12340),
(3109,2,0,'你终于来了！太好了！$B$B我们最近会有一系列的行动，所以我很高兴邀请铁炉堡的另一个氏族加入我们。我们中有太多的人因为自己的品味而向往魔法之类的东西，我对于他们和他们的信仰并没有什么要说的，但是只有你手中冰冷的剑和让你避开亮光的阴影才是最好的，你明白我什么意思吗？',12340),
(3110,6,0,'啊！你终于来了，$N！太好了！$B$B我本想说，我几乎都要失去信心的时候，你就来了……明白吗，失去信心？只是开玩笑啦，$伙计:小姑娘……啊，别介意。总之你不是来听我说蹩脚笑话的。',12340),
(3112,2,0,'啊，好吧，又是一个$R的任务备忘录……真是不错。$B$B不，不，小家伙，我不是在嘲笑你。必须敬佩你的执着，这点毫无疑问。如果铁炉堡被黑铁矮人占领了，我也会同样恼火，所以别以为我不体谅你的处境……',12340),
(3113,1,0,'很高兴看到你带着我的便笺回来。抱歉，我把它伪装成一份高级公函……我并没有恶意，我相信包括我们两个在内的所有盗贼都应该紧密地团结在一起。$B$B许多人都不认为我们这类人聚集在同一个城市里是件好事，但我认为我们合作得很愉快，你说呢？',12340),
(3114,11,0,'耶，看看这是谁，一个$R？如果你不介意的话，请大点声说话。我喝麦芽酒之后耳朵有点不好使。',12340),
(3115,1,0,'太棒了！你显然收到了我的备忘录。$b$b$N，忽视你周围那些愚蠢的家伙吧。圣光？！剑和盾？！这不是像我们这样意志宽广的强者所应走的路。看看那些“普通”的魔法把我们的家园糟踏成了什么样子。还有那些该死的技工，我们这一族几乎都要灭绝了。现在我们不得不依靠矮人过活，而他们却把时间花在跟那些人类打交道上，而不是帮助我们重建家园。我们看起来就像是二等公民，说真的，你有没有注意过他们打量我们时的那模样？',12340),
(3116,2,0,'你成功了。我真高兴。$b$b过去这几年发生了很多事，$N：泰达希尔的诞生、此处与远方许多森林生物的腐化、发现我们以为早已失去的土地如菲拉斯……如此之多，如此之短。但这些只是我们来此的部分原因，最重要的原因是要保护我们的族群免受更多邪恶侵害。',12340),
(3117,2,0,'你来了，而且来得正好，$N。欢迎来到幽影谷。$B$B我相信我的印记找到你时你身心安好？$B$B正如我之前所说，我来此把你训练成$C；驯服野兽助你作战；以百发百中的准头使用弓箭；尊重我们称之为家的土地，以及家之外的土地。',12340),
(3118,2,1,'你好，$n。很高兴你找到了我。我还在想你大概迷路了。$B$B自从我给你符记之后，幽影谷没有发生什么新的事情，但我会让你去收集一些资讯。如果愿意的话，你可以去和奥达希尔的其它居民谈谈。',0),
(3119,2,0,'我很高兴你这么快就来了，$N。欢迎你。$b$b或许你已经听说过，整个泰达希尔都充斥着来来往往的旅人，甚至还有一些联盟的成员也被允许攀上泰达希尔的主冠来和那些准备外出冒险的卡多雷会面。',12340),
(3120,2,0,'啊，年轻的$C。我看得出你非常渴望继续你的历练，这很好。$b$b我想要知道，你是否已经在翡翠梦境中待了很长时间呢？也许你还没有为此作好准备……至少现在没有，我敢肯定。$b$b不管怎么样，在那一天到来之前，我们还有很多其它的事情要讨论。',12340),
(3121,0,0,'有事吗？',12340),
(3122,0,0,'你见过瑟拉希了吗？',12340),
(3123,0,0,'你捕获那些野兽了吗？$b$b如果你成功了，我们就准备好缩小并捕获菲拉斯生物的灵魂精华。',12340),
(3124,6,6,'你捕获那些角鹰兽的灵魂了吗？',12340),
(3125,6,6,'你捕获那些精灵龙的灵魂了吗？',12340),
(3126,6,6,'你捕获那些森林漫游者的灵魂了吗？',12340),
(3127,6,6,'你捕获那些山岭巨人的灵魂了吗？',12340),
(3128,0,0,'你收集到我需要的材料了吗？',12340),
(3129,1,0,'看看吧，这就是你的努力所创造出来的东西。',12340),
(3130,1,0,'羽月将军派你来帮我对付纳迦军队，对吗？好吧，如果你愿意接受挑战，我这里有对付纳迦的很有效的方法……',12340),
(3141,1,0,'不要打断我，$r。',12340),
(3161,0,0,'你的搜寻工作进行得怎么样了？$B$B塔纳利斯到处都是加兹瑞迪安饰物，$N，所以请继续搜索吧！',12340),
(3181,274,0,'不，我不会把门打开的。',12340),
(3182,0,0,'你好啊，年轻的女士。想参观一下博物馆吗？',12340),
(3201,274,0,'我不相信。',12340),
(3221,1,0,'',12340),
(3261,1,0,'',12340),
(3281,6,6,'你拿到银币了吗？',12340),
(3301,0,0,'我可以闻到你身上贫瘠之地的尘土味道，$C。你看来是远道而来的。',12340),
(3321,1,0,'今天，我们要庆祝你正式加入秘银会。',12340),
(3341,1,0,'这件事非常重要，$N。我们必须阻止天灾军团获得其它方面支持的行动。',12340),
(3361,0,0,'天啊，$N，这个城镇并不适合我这种人。这里讨厌的怪物简直和事故之前诺莫瑞根里的一样多！$b$b你拿到我的东西了吗？如果没有，天知道那些该死的巨魔把我的东西怎么了……',12340),
(3362,1,0,'我想要仔细观察一下那个山谷里的仙人掌……所以打架的时候别把它们都给砸了，好吗？',12340),
(3363,1,0,'你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(3364,6,4,'是的，我是德南·弗卡特。你有东西要给我吗？',12340),
(3365,1,7,'我相信你已经及时地把热腾腾的热酒交给德南了！杯子带回来了吗？',12340),
(3366,1,0,NULL,12340),
(3367,1,0,'我想我到不了铁炉堡了……',12340),
(3368,18,18,'<索里奥斯抽泣着。>',12340),
(3369,6,0,'我能帮你什么忙吗？',12340),
(3370,6,0,'我能帮你什么忙吗？',12340),
(3371,1,0,'',12340),
(3372,1,0,'祭坛是空的。',12340),
(3373,1,0,'当你接近伊兰尼库斯告诉你的精华之泉的时候，他的声音再次出现在你的脑海中。$B$B“是的，凡人，这个精华之泉将会救赎我留在这颗宝石内的心智中未污染的部分。将宝石放在泉水中，然后让绿龙族的魔法净化我身上的堕落和污染元素。只有这样我才能得到真正的解脱，只有这样绿龙军团才能够获得管理阿塔莱的权利。',12340),
(3374,6,6,'我们已经到了，$N，到了另一个十字路口。是该作出个选择的时候了。凡人，你的选择是什么？',12340),
(3375,1,1,'要制作另外一个瓶子，我需要一瓶法力药水、一块煤和一些蜂蜜饮料。$B$B另外，还需要很多很多的耐心。',12340),
(3376,1,1,'只要尖牙刺鬃酋长死了，我们就再也不用忍受他的骚扰了。把他的头颅给我拿来作为你已经干掉他的证据，$N。$B$B我们牛头人生存的意义就在于打猎，而最大的乐趣莫过于猎杀那些有可能反咬我们一口的猎物了。如果你成功地完成这项任务，你就会理解我所说的话。',12340),
(3377,1,0,'请允许我讲完我的故事。',12340),
(3378,0,0,'你来月神殿有什么事吗，$N？',12340),
(3379,1,6,'你带回什么消息了吗？',12340),
(3380,1,0,'啊，你好，旅人。什么风把你吹来了？',12340),
(3381,1,0,'我仍然在这里执行主人吩咐的任务。我其实可以随便要求你提供什么东西来做为见到主人的代价，但是现在，我只要求每个旅人提供两根羽毛来完成我精美的箭。$b$b如果你不够小心的话，我可是会提价的。六枚金币听起来怎么样？$b$b就这样了，我现在就要求那么多。小心行事，我会暂时把价格保持在现在的水准。',12340),
(3382,1,0,'这将是一场艰苦的战斗……',12340),
(3385,6,6,'那家伙还活着吗？',12340),
(3402,1,0,'想要看看我的商品吗？',12340),
(3421,1,0,'',12340),
(3441,1,0,'让我把话说完……$r。',12340),
(3442,6,6,'你收集到我要的材料了吗？',12340),
(3443,0,0,'八把，$N。我需要八把匕首！',12340),
(3444,0,0,'棘齿城离这儿不远，$N。花不了你多长时间的。',12340),
(3445,1,0,'啊，你好，旅人。什么风把你吹来了？',12340),
(3446,1,0,'在检查雕像时，你注意到边边有一处凹陷，与玛尔冯给你的石环尺寸相同……',12340),
(3447,1,0,'哈卡雕像耸立在你的头上……',12340),
(3448,1,0,'',12340),
(3449,4,4,'很好，很好，很好，很高兴见到你回来这里，$N。你帮泰摩尔拿到拓印了吗？$B$B尽管跟这里一样都是危机四伏，但是海岸附近却没什么动静。或许是因为水下有纳迦的关系，但是这与我无关……我是在天空巡逻的。',12340),
(3450,1,0,'',12340),
(3451,1,0,'',12340),
(3452,0,0,'如果没有合适的魔法能量来源，惩戒火炬就无法完成。',12340),
(3453,1,0,'不要打断我。',12340),
(3454,1,0,'火炬在空中悬浮着。',12340),
(3461,6,0,'你回来了！太棒了，你把我的绘图工具包拿回来了吗？',12340),
(3462,1,0,'你得原谅我的主人，他最近……有些异常。',12340),
(3463,1,0,'你迷路了吗，$N？',12340),
(3481,1,0,'打开箱子。',12340),
(3482,1,0,'',12340),
(3483,1,0,NULL,12340),
(3501,1,0,'你在探险中找到什么好东西了吗？',12340),
(3502,1,0,'哦？德莱尼水晶？记得吗？$B$B<库米沙握紧拳头敲打你的脑袋。>$B$B有人在家吗？',12340),
(3503,1,0,'',12340),
(3504,1,0,'啊，贝尔戈洛姆果然已经老了，他最终还是派了个外人来帮助我们，对吗？$b$b这个营地里曾驻扎了12个强壮的战士，$N，但是他们都已经死了。那个名叫雷姆托里的法师杀死了他们，她像戏弄猴子一样欺骗了贝尔戈洛姆。不过话说回来，她的确是个相当有诱惑力的女人。这也许是我仍然愿意帮助贝尔戈洛姆的原因——换了是我也会犯同样的错误。',12340),
(3505,1,0,'黑色的皮革封面上是用金叶镶嵌的书名——卡多雷召唤宝典。当你翻开书时，你发现这本书的年代十分久远，但是保存的十分完好。$b$b你猜测其中的文字是某种古代语言……或许是卡多雷语？$b$b你的直觉告诉自己，你应该在完成对血精灵的报复之后回到这里。',12340),
(3506,1,0,'报复那些血精灵叛徒的事进行的如何了，$N？$b$b有任何的进展吗？我希望你够强壮，可以把那条狗狠扁一顿！她应该为她的所作所为死一百次！',12340),
(3507,1,0,'我记得你，$C。我曾请求你去艾萨拉杀死那个叛徒！这好像是很久以前的事了。别告诉我阿格图和其他人也死了！',12340),
(3508,1,0,'不要打扰我。',12340),
(3509,1,0,'我可不愿意被你这种小虫打扰，走开。',12340),
(3510,1,0,'<亚考罗克领主弯下腰来看你。>$b$b头颅在哪儿？',12340),
(3511,6,6,'你回来了！我真惊讶，$R。你知道那个恶魔真正的名字了吗？',12340),
(3512,1,0,'',12340),
(3513,0,0,'你有什么事？',12340),
(3514,1,5,'不能让联盟踏入我们的领地，$N。让他们明白这一点。',12340),
(3517,1,0,'我要你收集的石板能让我们发一笔小财，当你找到它们之后，我会告诉你把它们送往何处的。但是，我可不是蠢货……我只有在确定它们都已送达的情况下才会把你应得的那一份给你。$b$b出发吧——我们的时间不多。我也许得多找些人来帮我。',12340),
(3518,1,0,'你好，$N。我能为你做什么吗？我还要处理很多事情，请快一点。',12340),
(3520,0,0,'你收集到尖啸者灵魂的灵魂了吗，$N？',12340),
(3521,0,2,'请去收集我所说的那些原料，$N。埃沃隆需要我们的帮助。',12340),
(3522,0,0,'哦……$N，很高兴你回来了。',12340),
(3523,1,0,'我并不是搞政治的，我不在意你是为部落还是为联盟效力。我对解决所有种族直接造成影响的重大威胁更感兴趣……现在我们就有一个很大的威胁。$B$B要是你愿意成为真正的人民英雄，就将我作为承诺的黑曜石还给我吧。对我的族人来说这代表着重要的同意契约。',12340),
(3524,1,0,'这些生物是在最近才开始以如此令人震惊的数量在黑海岸登陆，我觉得这是某种不祥的征兆。到南边去弄些这种生物的骨头样本，这将有助于达纳苏斯对事态做出正确的评估！',12340),
(3525,1,0,'',12340),
(3526,1,0,'我可以在一里外闻到新技师的气味，就像我可以在一里外闻到炸药的气味一样。你是来揭开炸药的神秘面纱的吗？',12340),
(3527,6,6,'你拿到摩沙鲁的预言石板了吗，$N？$b$b等我获得石板后就可以进行研究，然后学习如何控制哈卡的精华！',12340),
(3528,6,6,'你打败了哈卡的化身了吗，$N？他的精华被封入我给你的卵中了吗？',12340),
(3541,1,0,'你有什么事？我今天有许多事情得处理，我没看到我的行程表里有你的名字。你要是想没事跑来烦我，我会特别为你“安排”的。',12340),
(3542,1,0,'嗯……<嗝>……这真是个惊喜啊？一个冒险者……<嗝>！$b$b我能帮你做些什么……<嗝>？',12340),
(3561,1,0,'我能帮上什么忙吗，$N？',12340),
(3562,1,0,'哦，玛加萨说什么了？那个老太婆……我敢打赌她根本不知道什么是礼貌。',12340),
(3563,1,0,'你跟杰斯雷蒙谈过了吗？$B$B他跟其它巨魔比起来简直像头猪，但是他的资讯通常都很正确，而且他给的报酬也很丰厚。$B$B如果你能忍受他的态度，那么也许你能从他那赚一大笔钱。',12340),
(3564,1,0,'你见到安德隆了吗？他很少离开幽暗城，我想你应该不难找到他。',12340),
(3565,1,0,'嗯，克希雷姆说了些什么？他有没有对你做什么？他对你施法术了吗？或者强迫你为他做事了吗？',12340),
(3566,274,274,'我不相信你！把证据拿出来！',12340),
(3567,1,0,'',12340),
(3568,6,0,'你知道她会怎么样吗，$N？她死定了……一看就知道。现在对她来说，最好的结果就是帮助我们找到治疗这种瘟疫的方法。她饮用的水也许能帮助我们。她早晚要死的——不如在死之前为我们做点贡献。你认为呢？',12340),
(3569,1,0,'我听说幽暗城的炼金师长久以来一直在努力研究如何治愈自己的疾病，所以我来到了这里。据说他们也许能够帮助我。$B$B尽管我在这似乎不受欢迎，但是我别无选择——我受到疾病的煎熬，我急切需要他们的帮助。',12340),
(3570,1,0,'你知道这会走向哪里，对吧，$N？她不可能活下来了……看看她。现在对她最好的事，就是帮我们找到瘟疫的解药。她喝下的这水也许有线索，能帮我们弄清方法。她反正要死了——不如在死前为我们的人民做件高尚的事。你不同意吗？',12340),
(3601,14,0,'那些讨厌的血精灵。我告诉你，如果我和你一样强壮的话，我会去那里然后亲自好好教训一下他们！但我最好还是付钱给你请你帮我解决他们。',12340),
(3602,25,25,'邪恶的力量不会停下脚步来等你，蠢货。当你被干掉之后有的是事件来休息。现在，把水晶交给我。',12340),
(3621,6,0,'洛拉姆斯？我上次听到这个名字已经是许多年前的事了。',12340),
(3625,1,0,'如果打断锻造的过程，那么我打造出来的武器就是不完美的。请耐心一些，$n。',12340),
(3626,1,0,'你终于回来了！',12340),
(3627,0,0,'三位一体，前方的通路已经敞开。',12340),
(3628,0,0,'没有什么可害怕的了。',12340),
(3629,1,0,'我可以在一里外闻到新技师的气味，就像我可以在一里外闻到炸药的气味一样。你是来揭开炸药的神秘面纱的吗？',12340),
(3630,6,0,'嗯嗯，你有什么事要我帮忙吗？很显然，我有的是时间，因为我的家乡现在正笼罩在一片辐射云里，而我却站在这里无所事事。',12340),
(3631,1,0,'',12340),
(3632,6,0,'嗯嗯，你有什么事要我帮忙吗？很显然，我有的是时间，因为我的家乡现在正笼罩在一片辐射云里，而我却站在这里无所事事。',12340),
(3633,1,0,'我可以在一里外闻到新技师的气味，就像我可以在一里外闻到炸药的气味一样。你是来揭开炸药的神秘面纱的吗？',12340),
(3634,6,0,'嗯嗯，你有什么事要我帮忙吗？很显然，我有的是时间，因为我的家乡现在正笼罩在一片辐射云里，而我却站在这里无所事事。',12340),
(3635,3,0,'你好啊！如果你是来跟我说导航机器人坠毁在你家房顶上之类的事情，那么请去找我的律师。如果不是，请问找我有什么事？',12340),
(3636,1,0,'你必须杀死亚门纳尔。快点去吧。',12340),
(3637,3,0,'你好啊！如果你是来跟我说导航机器人坠毁在你家房顶上之类的事情，那么请去找我的律师。如果不是，请问找我有什么事？',12340),
(3638,0,0,'如果你签署了这份文件并把它交给我的话，那事情就这么定了。你要知道这是影响你一生的抉择。如果你决心已定，那么欢迎你加入我们！',12340),
(3639,1,1,'一旦我收到你制作的物品并检查完毕之后，我就会教最后一些知识，好让你要加入我们地精工程师这个严格小团体！',12340),
(3640,0,0,'如果你签署了这份文件并把它交给我的话，那事情就这么定了。$B$B我接下来要告诉你的是，签署这样一份保密协定是非常严肃的事情。我签了一份，我们的其它成员也都签了。你将要加入这个幸运的团体了，工程师$N！',12340),
(3641,1,1,'一旦我收到你制作的物品并检查完毕之后，你就可以成为受认可的侏儒工程师，你可以不受限制地拜访世界上任何地方的任何侏儒工程学训练师。',12340),
(3642,0,0,'如果你签署了这份文件并把它交给我的话，那事情就这么定了。$B$B虽然我有时候会因为诺莫瑞根的问题对组织产生异议——特别是对那个愚蠢的技工大师欧沃斯巴克——但是，保密协议高于一切！你必须签署它，然后一生都要遵循它。',12340),
(3643,1,1,'在我收到你制作的物品并检查完毕之后，我就会给你发放一张真正的侏儒工程师协会会员卡！在这张卡片的有效期内，你可以不受限制地拜访世界上任何地方的任何侏儒工程学训练师。',12340),
(3644,1,0,'要想延长你的会员期的话，你就得花些钱来为你的会员卡续费。',12340),
(3645,1,0,'要想延长你的会员期的话，你就得花些钱来为你的会员卡续费。',12340),
(3646,1,0,'要想延长你的会员期的话，你就得花些钱来为你的会员卡续费。',12340),
(3647,1,0,'要想延长你的会员期的话，你就得花些钱来为你的会员卡续费。',12340),
(3661,0,0,'如果可能的话，尽可能避开那些枭兽，$N。它们也许会以为你要伤害它们……',12340),
(3681,1,0,'',12340),
(3701,1,6,'你带来什么新的消息没有？',12340),
(3702,1,0,'请听我讲完索瑞森的历史。',12340),
(3721,1,0,'',12340),
(3741,24,24,'你好。我很想我的项链！是我爸爸送我的。爸爸说湖水中有怪兽，你打败它们了吗？',12340),
(3761,25,25,'放轻松点，如果你拿来了安戈洛的泥土，就赶紧拿出来，不然就该干什么干什么去！',12340),
(3762,1,0,'',12340),
(3763,1,0,'',12340),
(3764,4,4,'哦，当然，泥土。大德鲁伊想要20份，所以你就得拿来20份。没有就别废话了！',12340),
(3765,1,0,'',12340),
(3781,2,0,'朋友，和平与宁静与你同在。是大德鲁伊派你来的，对吗？',12340),
(3782,2,0,'朋友，和平与宁静与你同在。是大德鲁伊派你来的，对吗？',12340),
(3783,0,0,'我有很多准备工作要做，请你尽快把毛皮交给我！',12340),
(3784,1,0,'',12340),
(3785,6,6,'嗯，$N，你种植出用于大德鲁伊的研究工作的晨光麦了吗？他为塞纳里奥议会进行的研究事关重大，你的帮助必定给你带来丰厚的回报！',12340),
(3786,6,6,'嗯，$N，你种植出用于大德鲁伊的研究工作的晨光麦了吗？我们对安戈洛环形山神秘构造的了解已经越来越多了，谢谢你为我们提供的帮助。',12340),
(3787,1,0,'',12340),
(3788,1,0,'',12340),
(3789,1,0,'',12340),
(3790,1,0,'',12340),
(3791,1,1,'我要十株晨光麦——要启动我的研究，至少需要这么多。毫无疑问，整个研究过程肯定要消耗不少晨光麦，但这也正是研究的本质。',12340),
(3792,1,1,'你好，我们又见面了，$N。我的研究进展得相当顺利，不果如果你还有5株晨光麦的话，我会很乐意地从你这儿购买的。呃……“乐意”在这里只是一个修饰语罢了，和这些东西相处的时间越长，我就越发感到不太舒服。尽管如此，我的研究任务仍要求我必须认真对待工作，并尽力克服我这奇怪的心理作用。',12340),
(3801,1,0,'',12340),
(3802,0,0,'雕像隐隐约约地矗立在你的面前。',12340),
(3803,1,1,'大德鲁伊始终在寻找更多的晨光麦以供塞纳里奥议会研究之用。我们以10株为单位进行收购，而且会奖励给你一包很有用的东西。如果你弄到了10株晨光麦，就来找我，我将奖赏你的。',12340),
(3804,1,1,'大德鲁伊始终在寻找更多的晨光麦以供塞纳里奥议会研究安戈洛环形山之用。我们以10株为单位进行收购，而且会奖励给你一包很有用的东西。如果你弄到了10株晨光麦，就来找我，我将奖赏你的。',12340),
(3821,1,0,'',12340),
(3822,6,6,'你找到沙妮了吗？她还好吗？',12340),
(3823,1,25,'你的军服还没有沾上足够的血，士兵！',12340),
(3824,6,6,'哦，光荣的一天！你带回那个家伙的头了吗？',12340),
(3825,1,6,'完成任务了？你有没有把当时的场景画下来？',12340),
(3841,3,0,'你好啊，$C。$B$B可别被我所待的地方给糊弄了，我到这儿来可不是为了赛车……不是为了娱乐而来。$B$B我到千针石林是为了调查这片土地到底有多么贫瘠。现在我要让这里的盐硷地变成新鲜肥沃的土壤，使它获得新生！也许我很快就要在这附近发现水源了。$B$B你有没有觉得菲拉斯和千针石林之间的差异之大简直令人感到匪夷所思？一定有什么奇怪的魔法从中作祟……',12340),
(3842,1,1,'我在这儿待的时间越长，就越想参与到赛车中去，$N。我可真有些犹豫……$B$B你找到药剂了吗？在我辨别出这颗蛋是否健康之后，我就会把它还给你，你要好好地保护它，直到小精龙孵化为止。$B$B准备好了就告诉我。',12340),
(3843,6,0,'你好，$N。我能帮你什么忙吗？',12340),
(3844,1,0,'',12340),
(3845,0,0,'你好，我以前见过你……是不是啊？',12340),
(3861,1,0,'小鸡用它那双黑暗而凌厉的眼神盯着你，等着你给它喂食。$B$B“咕咕嘎！$B$B咕咕……咕咕……咕咕。”',12340),
(3881,1,1,'要是我们还想有活着离开这鬼地方的机会，首先就需要大箱大箱的食物来充饥。此外，尽可能取回研究设备对身陷困境的我们而言也是个福音。',12340),
(3882,0,0,'你可以对我有看法，但是，他们拿去研究的骨头究竟是来自古代的剑龙和双帆龙还是那些在我们扎营时差点把我们生吞了的恐龙，对他们而言没有什么区别。只要我们能活着离开这儿，我就高兴了……',12340),
(3883,6,6,'你弄到格里什虫巢的样本了吗，$N？',12340),
(3884,3,0,'你好！我和我的同伴很高兴在这里见到除野蛮巨兽之外的活物！是什么把你带到了安戈洛环形山？',12340),
(3901,1,0,'那些在执行任务时浪费时间的新兵也许会像我们那些不幸的兄弟姐妹一样，漫无目的地在镇子里徘徊。我不希望你再度成为一个毫无思想的僵尸，你说呢？',12340),
(3902,0,0,'你有没有为我们搜寻到一些有用的装备？重新利用那些被弃置不用的装备并不是件可耻的事情。没人会给我们施舍的——我们被遗忘者必须要自给自足！',12340),
(3903,1,0,'',12340),
(3904,0,0,'你拿回我的葡萄了吗，$N？',12340),
(3905,0,0,'你看起来精神很好嘛！来！坐下来喝杯酒吧！',12340),
(3906,1,0,'元素仍然处于混乱之中，$N。',12340),
(3907,5,5,'整个大陆很快就会被烈焰吞噬，快一点行动，$N！',12340),
(3908,0,0,'我的天啊，林克终于找人把剑送到我这里了。',12340),
(3909,6,6,'这么快就回来了？',12340),
(3911,1,0,'<薇薇安·拉格雷搓揉着她的双手>$B$B成功了吗？',12340),
(3912,1,0,'你为什么而来？',12340),
(3913,1,0,'这一定是加里杨提到的那块墓碑。',12340),
(3914,25,0,'哦！我记得你！你是……不，别说！让我想想！',12340),
(3921,0,0,'我正忙着干活哪，$C。除非你有事找我，不然你最好该干什么干什么去……',12340),
(3922,0,0,'你拿到高强度齿轮了吗，$N？我一直在盯着这个主动式负载平衡器，而且在急切地盼望着能开始动手修补它。',12340),
(3923,0,0,'小心你的头！最好不要影响我的工作！',12340),
(3924,0,0,'你拿到说明书了吗？',12340),
(3941,1,0,'',12340),
(3942,1,0,'',12340),
(3961,3,0,'你好，我们又见面了，$N！',12340),
(3962,1,1,'火焰使者用金色火焰创造了一个保护光环，使它无法被击败。只要使用亚奎门塔斯的银图腾，你就可以消除这个光环。',12340),
(3981,1,0,'<他惊奇地睁大了双眼>$B$B你……你是谁？',12340),
(3982,1,5,'先保住你自己的命，傻瓜！',12340),
(4001,1,0,'你到这里来干什么？',12340),
(4002,1,0,'你接受任务吗？',12340),
(4003,1,0,'<茉艾拉公主惊恐地蜷缩成一团。>',12340),
(4004,1,0,'<萨尔向你敬礼。>',12340),
(4005,6,6,'你回来了？嗯……让我看看那个东西，$N。',12340),
(4021,0,0,'你拿到旌旗了吗？',12340),
(4022,1,0,'<塞勒斯的双眼变成了两颗燃烧的火球。>',12340),
(4023,1,0,'<塞勒斯的双眼变成了两颗燃烧的火球。>',12340),
(4024,6,0,'你干掉那个怪物了吗？',12340),
(4041,1,1,'替我弄一支灵根草来，我就可以帮你制作视灵药剂。$B$B我知道所有关于草药和炼金术的事情……为什么？让我告诉你，那次我把准备拿来当午餐的乳酪变成了金子的故事……喂……你要去哪儿？',12340),
(4061,5,5,'不要轻视这个任务，$N！',12340),
(4062,6,0,'你那儿拿到了什么，$R？',12340),
(4063,6,6,'是他吗？他还活着吗？',12340),
(4081,1,6,'你有什么事吗，$r？你难道看不出我有一大堆事要忙吗？',12340),
(4082,1,6,'你回来了？你很有毅力，所以我当然要把任务交给你来完成，$N。',12340),
(4083,1,0,'鬼灵之杯在空中飘浮着，缓慢地上升和下降……就好像一颗将死的心脏在跳动。',12340),
(4084,1,1,'我可以告诉你更多关于击败火焰使者的资讯，但是首先，你必须收集到我要的那些东西。',12340),
(4101,5,5,'我知道费伍德森林正在被痛苦折磨，$N，因为我自己也在体尝这样的痛苦！但我必须保持自己坚定的意志……如果我所掌握的知识落入了错误的人的手里，那费伍德森林就将遭受一场空前的灾难。$B$B帮我从扭木元素身上抽取血琥珀，然后我就能相信你会帮助我和堕落进行斗争了。',12340),
(4102,5,5,'我知道费伍德森林正在被痛苦折磨，$N，因为我自己也在体尝这样的痛苦！但我必须保持自己坚定的意志……如果我所掌握的知识落入了错误的人的手里，那费伍德森林就将遭受一场空前的灾难。$B$B帮我从扭木元素身上抽取血琥珀，然后我就能相信你会帮助我和堕落进行斗争了。',12340),
(4103,1,1,'只要你拿着塞纳里奥信标，你就能从那些堕落的野兽身上找到受污染的灵魂裂片，为了费伍德森林的未来，你一定要拿到那些裂片。我会对裂片进行研磨加工，将其制成塞纳里奥植物药膏。我们可以用这种药膏拯救那些奄奄一息的堕落植物。$b$b如果你能给我弄些裂片来，我就可以给你几份植物药膏。',12340),
(4104,1,0,'如果你随身带着塞纳里奥信标，那么你在采矿的时候就会看到那些污染了矿脉的硫酸盐。我可以对那些硫酸盐进行净化，然后把它们制成塞纳里奥植物药膏。你可以用这种药膏来拯救堕落的大自然。$b$b给我弄些受污染的硫酸盐来，我就可以给你几份药膏。',12340),
(4105,1,0,'训练有素的草药师可以用塞纳里奥信标探测到那些被污染的魔藤——这是费伍德森林被污染后所诞生的产物。我在这里进行了一些研究工作，现在我可以把魔藤转化为一种净化原料……然后就可以用它来制作我们所说的塞纳里奥植物药膏了。$b$b当你在费伍德森林里收集草药的时候，别忘了带着这个信标来寻找魔藤。给我弄些魔藤来，我就给你几份药膏作为交换。',12340),
(4106,1,0,'训练有素的剥皮匠可以用塞纳里奥信标从费伍德森林里的生物身上找到受污染的毛皮，我可以把这些皮制作成塞纳里奥植物药膏。$b$b当你在这里采集兽皮的时候，记得带上信标。给我弄些受污染的毛皮来，我就可以给你几份药膏。',12340),
(4107,1,0,'分解物品所得到的魔法精华中蕴藏着相当大的能量。我已经研究出一种方法，可以把炼金术所使用的原始精华材料转化为制作塞纳里奥植物药膏所需的材料。你不需要拿着塞纳里奥信标，只要是能够分解出次级虚空精华的物品都适用。$b$b我只需要一个次级虚空精华，作为交换，我可以给你一些塞纳里奥植物药膏。那些精华的能量很强大，所以即使很少的精华就能制作出不少的药膏了。',12340),
(4108,1,1,'只要你拿着塞纳里奥信标，你就能从那些堕落的野兽身上找到受污染的灵魂裂片，为了费伍德森林的未来，你一定要拿到那些裂片。我会对裂片进行研磨加工，将其制成塞纳里奥植物药膏。我们可以用这种药膏拯救那些奄奄一息的堕落植物。$b$b如果你能给我弄些裂片来，我就可以给你几份植物药膏。',12340),
(4109,1,0,'如果你随身带着塞纳里奥信标，那么你在采矿的时候就会看到那些污染了矿脉的硫酸盐。我可以对那些硫酸盐进行净化，然后把它们制成塞纳里奥植物药膏。你可以用这种药膏来拯救堕落的大自然。$b$b给我弄些受污染的硫酸盐来，我就可以给你几份药膏。',12340),
(4110,1,0,'训练有素的草药师可以用塞纳里奥信标探测到那些被污染的魔藤——这是费伍德森林被污染后所诞生的产物。我在这里进行了一些研究工作，现在我可以把魔藤转化为一种净化原料……然后就可以用它来制作我们所说的塞纳里奥植物药膏了。$b$b当你在费伍德森林里收集草药的时候，别忘了带着这个信标来寻找魔藤。给我弄些魔藤来，我就给你几份药膏作为交换。',12340),
(4111,1,0,'训练有素的剥皮匠可以用塞纳里奥信标从费伍德森林里的生物身上找到受污染的毛皮，我可以把这些皮制作成塞纳里奥植物药膏。$b$b当你在这里采集兽皮的时候，记得带上信标。给我弄些受污染的毛皮来，我就可以给你几份药膏。',12340),
(4112,1,0,'分解物品所得到的魔法精华中蕴藏着相当大的能量。我已经研究出一种方法，可以把炼金术所使用的原始精华材料转化为制作塞纳里奥植物药膏所需的材料。你不需要拿着塞纳里奥信标，只要是能够分解出次级虚空精华的物品都适用。$b$b我只需要一个次级虚空精华，作为交换，我可以给你一些塞纳里奥植物药膏。那些精华的能量很强大，所以即使很少的精华就能制作出不少的药膏了。',12340),
(4113,0,0,'你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4114,1,0,'你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4115,1,0,'你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4116,1,0,'你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4117,1,0,'你找到了一株病怏怏的、被腐化了的鞭根草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4118,1,0,'你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4119,0,0,'你找到了一株病怏怏的、被腐化了的夜龙草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4120,1,0,'每个感染恶魔能量的动物都会泛出绿光……我感到了极端邪恶而强大的力量。',12340),
(4121,0,0,'我会照顾这个叛徒的，$N。',12340),
(4122,1,0,'',12340),
(4123,0,0,'你拿到山脉之心了吗？对我来说，它是无价之宝。',12340),
(4124,1,0,'',12340),
(4125,1,0,'',12340),
(4126,5,5,'你找到配方了吗，$N？我绝不能忍受那些黑铁矮人居然能够饮用我系列的酒！',12340),
(4127,2,2,'啊，欢迎回来，$N。我希望你能发现一些关于拉斯卡尔的线索，尽管这可能是个悲剧。',12340),
(4128,1,0,'',12340),
(4129,6,0,'基恩诺派你来的？$B$B我的心灵占卜能力让我心力交瘁……我在牌桌上的损失也一样。要塞里的其它人都叫我“厄运之王”。没有牌运……但在掌握自然的秘密方面运气还不错，大概就是如此吧。$B$B好吧，我当然可以帮你。这可能是我们找到拉斯卡尔的关键所在。如果你愿意给我那把刀子，我们就可以开始了。',12340),
(4130,1,0,'',12340),
(4131,1,0,'',12340),
(4132,1,0,'那个屠夫有没有被正法？',12340),
(4133,1,0,'',12340),
(4134,6,6,'你找到雷酒配方了吗，$N？',12340),
(4135,1,0,'',12340),
(4136,0,0,'你抓到雷布里了吗？或者……至少把他身上的一部分交给我。',12340),
(4141,11,11,'拉瑞安在谋划一些东西，肯定是这样的！',12340),
(4142,0,0,'我在这片森林中与世无争地生活……$B$B好吧，至少我原认为是这样的。我在这里碰到的来访者比我在铁炉堡的时候还要多！',12340),
(4143,1,1,'拉瑞安还是不和我说话！看来他要对我沉默到底了。',12340),
(4144,1,1,'计划是这样的，$n：去收集一些血瓣花苗——你要知道，现在这种植物还没有开始广泛传播其种子，所以尽快把它们给我弄来，然后我就能看看阿塔莱之雾可以干些什么……$B$B你也许会认为我复仇心很重……事实上，所有人都应该有这样的权利！$B$B事实是这样的，我知道离开这里的路，但是除非拉瑞安承认我是对的，否则的话我就得永远待在这里！$B$B快点出发吧，找到那些血瓣花苗，然后就准备看好戏吧！',12340),
(4145,1,5,'除非莫尔金向我道歉，否则我绝对不会再和他说话。',12340),
(4146,5,5,'累死人了，$N。那些东西搞得我永不得安宁！',12340),
(4147,1,0,'',12340),
(4148,1,1,'要让除草器开工的话，我们就得有一份目标生物的样品。去环形山里找一个血瓣花苗来，然后我就设法用它启动莫尔金的小朋友……$b$b如果他不是那么固执的话，我们应该已经在回家的路上了……但是在我们能动身回家之前，我要向他证明他的那个小恶作剧并不能妨碍我！',12340),
(4161,0,0,'记住这种平衡，$N。我希望你能拥有一颗对这片森林充满理解和宽容的心。',12340),
(4181,1,0,'我可以在一里外闻到新技师的气味，就像我可以在一里外闻到炸药的气味一样。你是来揭开炸药的神秘面纱的吗？',12340),
(4182,1,0,'猎龙行动进行得怎么样了？',12340),
(4183,1,0,'幸会，$N。我们之前见过吗？你看起来好眼熟啊。',12340),
(4184,1,0,'是什么风把你吹到暴风要塞里来了？',12340),
(4185,1,0,'<伯瓦尔专注地看着你。>',12340),
(4186,1,0,'有没有乌瑞恩国王传来的消息？',12340),
(4201,1,0,'你拿到材料了吗？我心中的空虚正在吞噬我！',12340),
(4221,1,0,'你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4222,1,0,'你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4223,1,0,'啊，你就是我们要求的“增援”？',12340),
(4224,1,0,'你和约翰谈过了吗？',12340),
(4241,1,0,'<温德索尔元帅朝你发出低吼。>',12340),
(4242,1,0,'你回来啦！',12340),
(4243,1,0,'',12340),
(4244,0,0,'用来放置秘银外壳的面板仍处于关闭状态。艾米 01的其它部分没有任何动静。',12340),
(4245,1,0,'你能帮助艾米吗？看来很可能是她的秘银外壳被损坏了，我相信如果你给她换一个秘银外壳，她就能恢复如初，而且可以自己回家。',12340),
(4261,1,0,'',12340),
(4262,1,0,'<加琳达目不转睛地盯着你。>',12340),
(4263,1,6,'那个恶魔死了吗？',12340),
(4264,1,0,'<温德索尔元帅盯着你手中的信。>$B$B你手里拿着什么，$N？',12340),
(4265,1,0,'你有事要报告吗，$n？',12340),
(4266,1,0,'',12340),
(4267,2,2,'欢迎来到月神殿，朋友。我已经事先知晓你会从羽月要塞来这里了。你有没有带来珊蒂斯·羽月所说的那份报告？',12340),
(4281,2,0,'欢迎来到萨兰纳尔，$C。你需要什么帮助吗？',12340),
(4282,1,0,'不久之后，这个大阴谋就要彻底破灭了。',12340),
(4283,0,0,'<奥拉留斯对着一只又大又脏的巨魔耳朵喃喃自语。>$B$B我们要掌控燃烧平原，掌控它……',12340),
(4284,5,5,'$N，我在等着你拿水晶回来呢！',12340),
(4285,1,0,'你去过水晶塔了吗，$N？',12340),
(4286,1,1,'我现在很忙，$N。我和温奇正在开会。',12340),
(4287,1,0,'你去过水晶塔了吗，$N？',12340),
(4288,1,0,'你去过水晶塔了吗，$N？',12340),
(4289,2,2,'你已经跟那些生物交过手了吗，$N？$B$B不要轻易认输。即使对一个熟练的猎手来说，追踪并击败安戈洛的猩猩也不是件简单的任务。',12340),
(4290,1,1,'不要对我说的话心不在焉，$N。如果你真想面对这头野兽，那你就必须非常小心……而且非常聪明。要想引出拉克维并打败它，你必须拥有超群的力量和观察力。',12340),
(4291,1,1,'小心，$N。靠近任何恐龙蛋的行动都必定会引来它们的母亲……即使你做好了准备也要万分小心。那些雌性暴掠龙和拉克维一样致命，它们会拼死保护自己的蛋。但是，如果你成功了，我们就一定有办法把拉克维从它的藏身之处引出来。',12340),
(4292,2,2,'不要让恐惧战胜你，$N。恐惧是最大的叛徒……你必须保持意志！$B$B带上这块肉，把它放在小山谷中，然后给肉上涂满资讯素。那时你就要面对死亡的挑战了。',12340),
(4293,1,0,'我需要至少5份腐化的样本来进行试验，$N。继续去收集样品，希尔瓦娜斯女王已经下令要得到它了……',12340),
(4294,6,0,'怎么样，$N？你的研究进展如何了？',12340),
(4295,5,5,'哦，麦芽酒！为了黑铁啤酒，我甚至愿意去杀人！快点，我的酒劲正在消退！我的视线越来越模糊了……你看起来越来越像上个星期我干掉的那个$r了！',12340),
(4296,0,0,'你找到七贤石板了吗，$N？你找到石板中隐藏的秘密了吗？',12340),
(4297,6,6,'找到肉了吗，$N？这颗蛋就快孵化了。要是第一餐不喂饱，没准它连一周都活不了，我可不愿意发生这样的事。$B$B我没骗你，$N。我很是羡慕你能得到这颗蛋呢。别让我后悔这样帮助你。',12340),
(4298,1,0,'',12340),
(4300,6,6,'我的顾客可没那么多的耐心，$N。你拿到爪子了吗？',12340),
(4301,1,1,'尤尔查……这头野兽非常健壮。巨大的身躯，赤红的外皮，像匕首一样巨大的牙齿。它的胳膊像树干一样粗，动作比我见过的任何猎豹都要快。你能找到这样一个测试你勇气的机会，应该觉得很幸运——我的同胞可能一辈子都看不到这样的生物。',12340),
(4321,1,0,'',12340),
(4322,1,0,'$n，你看起来一副精疲力尽的样子。也许你应该在火堆旁找个位子好好休息一下。',12340),
(4324,1,0,'',12340),
(4341,1,0,'又来了一个？$B$B<卡兰抱怨着。>',12340),
(4342,1,0,'请允许我说完我的故事。',12340),
(4343,1,0,'你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4361,1,0,'你找到他了？',12340),
(4362,1,0,'我……我在哪儿？你是谁？$B$B<铜须公主看着达格兰·索瑞森大帝的尸体。>$B$B你对我亲爱的达格兰做了什么？！',12340),
(4363,1,0,'',12340),
(4381,1,0,'你可以把绿色能量水晶和黄色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以治疗你和你的同伴。',12340),
(4382,1,0,'你可以把绿色能量水晶和蓝色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以提高你的精神属性。',12340),
(4383,1,0,'你可以把绿色能量水晶和红色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以提高你抵抗物理攻击的能力。',12340),
(4384,1,0,'你可以把红色能量水晶和蓝色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以削弱敌人的防御能力。',12340),
(4385,1,0,'你可以把红色能量水晶和黄色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以猛烈地爆炸，对你的敌人造成伤害。',12340),
(4386,1,0,'你可以把蓝色能量水晶和黄色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以产生一道能对敌人造成伤害的屏障。',12340),
(4401,1,0,'你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
