(4447,0,0,'你找到了一株病怏怏的、被腐化了的夜龙草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4448,1,0,'你找到了一株病怏怏的、被腐化了的夜龙草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4449,1,0,'我可没有闲工夫在这里待着！给我弄些丝绸来！我是说那些黑铁地质学家，抓住那些地质学家！他们应该尝尝我的，嗯……你的愤怒。',12340),
(4450,6,6,'是，是？我能为你做什么，$R？我忙得很，还有许多客人要我的服务。也许你能说快点。不是我想无礼，只是我要赶完所有活儿，实在没时间。',12340),
(4451,1,0,'*咳咳*$b$b你是谁？没看见我很忙吗？',12340),
(4461,1,0,'你找到了一株病怏怏的、被腐化了的鞭根草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4462,1,0,'你找到了一株病怏怏的、被腐化了的夜龙草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4463,25,25,'把材料呈上来，凡人。$B$B这次制作我还要三十枚金币作为报酬。',12340),
(4464,1,0,'你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4465,0,0,'你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4466,1,0,'你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4467,1,0,'你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。',12340),
(4481,1,1,'这世上所有的东西都有价格，你所寻找的东西的价格是三十枚金币。$B$B当然，我会留下你收集的大部分材料。但是不用担心，你会得到你想要的东西。',12340),
(4482,1,1,'三十枚金币，$R，三十枚金币外加必需的材料。',12340),
(4483,6,6,'如果你想要的是韧性圣契，那得给我三十枚金币。',12340),
(4484,274,274,'不要浪费我的时间，渺小的$R。我要的是三十枚金币，外加必需的材料。',12340),
(4485,1,0,'',12340),
(4486,1,0,'',12340),
(4487,1,0,'',12340),
(4488,1,0,'',12340),
(4489,1,0,'',12340),
(4490,1,0,'',12340),
(4491,1,0,'我好担心林格……',12340),
(4492,1,0,'什……什么？',12340),
(4493,1,0,'',12340),
(4494,1,0,'',12340),
(4496,0,1,'找到一个合适的臭腺可能会有一点难度——腺体不能损坏，但是取得腺体的过程似乎不容易得出这种结果。至于土壤，我认为很容易就能找到。$b$b不管怎样，你拿到我制造诱饵所需要的东西了吗？',12340),
(4501,1,0,'实话跟你说吧，我以前不是很担心那些奇怪生物的数量……直到有一天我看到写在一块大石头上的话：$B$B小心翼手龙$B$B这是谁写的呢？我不知道，但是忽视这句话显然是愚蠢的。',12340),
(4502,6,6,'安戈洛环形山里的火山真的是活火山吗？我相信我可以从火山灰中了解到很多东西，$N。',12340),
(4503,0,0,'每个伟大的交通工具都需要有个名字……我想我会叫它……双翼飞行器！',12340),
(4504,4,4,'特兰雷克又要大获成功了——超级粘合剂即将风靡市场！',12340),
(4505,5,5,'这是至关重要的，赶快出发吧。',12340),
(4506,1,5,'不要告诉我你搞不定这种小事！快去！',12340),
(4507,1,1,'我们当务之急是要得到皇后的脑袋作为研究。根据我们所了解的情况，我们相信这些异种蝎可能被一种邪恶的智慧力量所控制。每当我想起能够控制像异种蝎这么邪恶的东西的力量，我都感到浑身发抖，$N。',12340),
(4508,5,5,'他们都是笨蛋，$N！他们甚至没有想到在自己的周围潜藏着多么可怕的威胁，他们对部落的仇恨最终会导致我们的毁灭！我不知道除了把他们直接丢到其中一个蝎巢以外，还有什么关于异种蝎威胁的证据可以给他们？$B$B对不起，你有什么消息要给我吗？',12340),
(4509,5,5,'他们都是笨蛋，$N！他们甚至没有想到在自己的周围潜藏着多么可怕的威胁，他们对联盟的仇恨最终会导致我们的毁灭！我不知道除了把他们直接丢到其中一个蝎巢以外，还有什么关于异种蝎威胁的证据可以给他们？$B$B对不起，你有什么消息要给我吗？',12340),
(4510,2,2,'艾露恩保佑你，$C。我能为你做些什么？',12340),
(4511,2,2,'啧啧！我能为你做些什么吗，$C？',12340),
(4512,1,1,'我已经完成的一些实验效果很不错。我相信只要再多加把劲，就能找出这些生物的特性，以及它们在艾泽拉斯的生物演化史中扮演了什么样的角色……如果它真的和艾泽拉斯的物种起源有关的话。$B$B我最重要的理论之一似乎并不是很受欢迎——我认为软泥怪和泥浆怪及这个星球上的生物是密切相关的……彷佛它们本身就是这个星球的分泌物。$B$B但是如果没有更多样品的话，我是无法证实或者推翻这一理论的。',12340),
(4513,1,1,'我要考虑许多问题。它意味着什么？它是如何影响艾泽拉斯的种种生物的？',12340),
(4521,1,25,'完成我给你的任务之后再回来向我报告。',12340),
(4542,6,0,'你有什么事，$C？紧急通知？这是给我的？',12340),
(4561,1,0,'你拿出一份从安戈洛环形山取来的淤泥样本，把它分开放进了桌上的试管和烧杯里。溶液开始沸腾并猛烈地喷溅，淤泥的颜色渐渐发生了改变。当反应渐缓，溶液不再喷溅时，你看见培养皿中有净化过的安戈洛淤泥样本和其它的一些残留物。',12340),
(4581,6,0,'你有什么要给我的吗？',12340),
(4601,1,0,'似乎这个装置需要某种脏兮兮的东西和三枚银币才能运行。既然两样都有了，超级清洁器5200型应该开始运转了……',12340),
(4602,1,0,'似乎这个装置需要某种脏兮兮的东西和三枚银币才能运行。既然两样都有了，超级清洁器5200型应该开始运转了……',12340),
(4603,1,0,'超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动！',12340),
(4604,1,0,'超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动！',12340),
(4605,1,0,'',12340),
(4606,1,0,'',12340),
(4621,1,0,'你这么快就回来了，你这该死的家伙！我吩咐的事办完了吗？要是让我们失望，你就得走跳板。$B$B呀啊啊……',12340),
(4641,6,0,'对于一个强大的战士来说，再厚的蝎壳都不值一提。下手强劲利落，你就会发现那些壳很脆的。',12340),
(4642,1,0,'试验怎么样了，$N？我会继续研究你给我带回来的样本——我开始明白为什么希尔瓦娜斯会对这些生物如此感兴趣了。如果它们真是上古诸神的一部分，那么也许我们可以好好利用这些东西。',12340),
(4661,1,0,'你拿出一份从费伍德森林取来的淤泥样本，把它分开放进了桌上的试管和烧杯里。溶液开始沸腾并猛烈地喷溅，淤泥的颜色渐渐发生了改变。当反应渐缓，溶液不再喷溅时，你看见培养皿中有净化过的安戈洛淤泥样本和其它的一些残留物。',12340),
(4681,1,1,'在你调查了西边那片水域中的生物残骸之后，我就应该能向达纳苏斯的月神殿提交一份较为准确的报告了。然后我们再来研究一下，为什么这些不幸的生物会选择在黑海岸结束它们的生命。',12340),
(4701,1,6,'你解决座狼的问题了吗？',12340),
(4721,1,25,'你知道自己该做什么，$N。',12340),
(4722,3,0,'你好，$N，你有没有发现什么被冲到海岸上的尸体？',12340),
(4723,3,0,'很高兴再次见到你，$N！是什么风把你吹回奥伯丁的？你来这里是不是有什么新的发现要报告给我们？',12340),
(4724,1,1,'只要那头母狼被干掉，我们就可以削弱黑石塔中的座狼，然后设法进入那座要塞。',12340),
(4725,1,0,'很高兴再见到你，$N。我们正在努力找寻巨型海洋动物纷纷在黑海岸搁浅的原因，但是似乎只要我们有一点进展，就会陷入更大的谜团中。$b$b你有什么可以对我们的研究有所帮助的新消息吗？',12340),
(4726,6,6,'你拿到小龙精华了吗，$N？我想要尽快开始研究它。$B$B除此之外……别让我的赞助人失望。',12340),
(4727,3,0,'你好，$N，你有没有发现什么被冲到海岸上的尸体？',12340),
(4728,3,0,'很高兴再次见到你，$N！是什么风把你吹回奥伯丁的？你来这里是不是有什么新的发现要报告给我们？',12340),
(4729,0,0,'基布雷尔正在和奥普斯激烈地争执着。>',12340),
(4730,3,0,'很高兴再次见到你，$N！是什么风把你吹回奥伯丁的？你来这里是不是有什么新的发现要报告给我们？',12340),
(4731,3,0,'很高兴再见到你，$N。我们正在努力找寻巨型海洋动物纷纷在黑海岸搁浅的原因，但是似乎只要我们有一点进展，就会陷入更大的谜团中。$B$B你有什么可以对我们的研究有所帮助的新消息吗？',12340),
(4732,1,0,'你好，$N，你有没有发现什么被冲到海岸上的尸体？',12340),
(4733,1,0,'很高兴再次见到你，$N！是什么风把你吹回奥伯丁的？你来这里是不是有什么新的发现要报告给我们？',12340),
(4734,6,6,'$N，你测试过龙蛋冷冻器了吗？',12340),
(4735,6,6,'你拿到蛋了吗，$N？我的赞助人听说你在帮我收集龙蛋，他很想亲手摸到那些蛋！',12340),
(4736,1,0,'',12340),
(4737,1,0,'',12340),
(4738,1,0,'',12340),
(4739,1,0,'',12340),
(4740,1,0,'你好，$c——今天哨兵部队能为你提供什么帮助吗？你是来询问 有关莫克迪普的赏金事宜的吗？',12340),
(4741,1,0,'别说你害怕了！继续前进！',12340),
(4742,1,0,'勇气与耐心高于一切，$N！',12340),
(4743,1,0,'别浪费时间，$N。奈法利安正狂热地要把他的邪恶释放到我们的世界上。',12340),
(4761,1,0,'',12340),
(4762,1,1,'壁泉河的污染为黑海岸拉响了警报。你提供的样本有助于我们制定计划……我猜想我们需要的是一项攻击计划。',12340),
(4763,0,0,'堕落护符是一件邪恶的物品，它唯一的作用就是破坏自然的平衡。当你从萨特手中夺取这件让熊怪堕落的物品时，就把它交给我来处置，这样我们今天就可以说是有所斩获了！',12340),
(4764,0,0,'你找到扣环了吗，$N？我的主顾愿意出大价钱买它。',12340),
(4765,0,0,'有人告诉我，一个来自黑石塔的信差给我带来了一件礼物。$B$B你就是那个信差吗？',12340),
(4766,1,0,'',12340),
(4767,6,6,'$N，你弄到那些双足飞龙的蛋了吗？我简直等不及要进行飞龙骑士的训练了！',12340),
(4768,6,6,'你找到石板了吗，$N？我想尽快对它进行研究。',12340),
(4769,1,0,'',12340),
(4770,1,0,'',12340),
(4771,1,25,'记住，$N——我们必须在信念上宽容而坚定！',12340),
(4781,2,2,'金锭，对，没错。给我拿一块金锭来，我就可以帮你纺织出金线。不过呢，我建议你的目标应该是努力使自己变得更强大。最艰难的考验还在前面呢。相信我……无论你认为自己的能力有多强，你都该追求更强。',12340),
(4782,1,0,'',12340),
(4783,1,1,'凄凉之地可不是个友善的地方。纳迦、巨人、萨特、燃烧军团、好战的半人马部落……所有这些都使得这片区域危机四伏，所以你得加倍小心。$B$B就像我先前所说的一样，这次任务不仅会考验你的力量和智慧，还会考验你的耐性。随时保持警惕，$N。',12340),
(4784,1,1,'很快就好了，$N。我向你保证。我制作的披风绝对符合你的要求，它能使你在战斗中占尽上风。',12340),
(4785,1,0,'',12340),
(4786,1,0,'再等一等，$n……',12340),
(4787,0,0,'你拿到远古之卵了吗？我感到一股强大的力量在蠢蠢欲动，我担心时间已经不多了。',12340),
(4788,6,6,'你去过黑石塔了吗，$N？你找到第五块和第六块石板了吗？',12340),
(4801,1,1,'在冬泉谷，你会与强大的霜刃豹战斗，这些猛兽拥有令人难以置信的速度和狡诈。如果你希望拥有霜刃豹的速度，就把你从它们身上找到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。',12340),
(4802,1,1,'在冬泉谷，你将与被称为冬泉熊怪的堕落生物搏斗，这些怪物拥有令人难以置信的力量。如果你想要获得冬泉熊怪的力量，就把你从它们身上找到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。',12340),
(4803,1,1,'在冬泉谷，你会找到强壮无比的巨熊，这些裂齿熊有着很强的忍耐力。如果你想要获得抵抗火焰的能力，就把你从裂齿熊身上找到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。',12340),
(4804,1,1,'在冬泉谷，你会与巨大的冰风奇美拉进行战斗。这些动物有控制冰冻魔法的力量。如果你希望得到抵抗冰冷的能力，就把你从它们身上找到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。',12340),
(4805,1,1,'在冬泉谷，你会与巨大的冰蓟雪人战斗。他们的行动非常缓慢，但是厚厚的皮毛可以让他们获得超强的防御力。如果你希望拥有躲避攻击的能力，就把你从他们身上找到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。',12340),
(4806,1,1,'在冬泉谷，你已经跟那些霜槌部族的冰巨人战斗过了，他们拥有巨大的力量。如果你希望拥有霜槌的力量，就从他们身上收集魂精，把它们交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。',12340),
(4807,1,1,'在冬泉谷，你将与拥有强大的魔法天赋的生物进行搏斗，那些枭兽可以使用强大的魔法。如果你想要提高自己的智力，就把你从枭兽那里得到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。',12340),
(4808,1,0,'这里真冷！你有毯子吗？',12340),
(4809,6,6,'你拿到冰风奇美拉的角了吗，$N？',12340),
(4810,6,6,'$N！你找菲诺克谈过话了吗？我要的东西呢？',12340),
(4811,1,6,'关于那块红色水晶，你有什么要汇报的吗？它真的存在吗？',12340),
(4812,1,0,'这块水晶伫立在黑海岸繁茂的森林中，与周围的景色格格不入。你似乎听到有非常轻微的嗡嗡声从水晶里面传出来。',12340),
(4813,1,0,'',12340),
(4821,1,1,'我必须要对这枚神秘的卵有更多了解，天知道它会孵出什么东西来。',12340),
(4822,6,0,'我希望他们除了草莓冰淇淋之外还能做出更多口味的冰淇淋，但是还好我最喜欢的就是草莓口味！',12340),
(4841,1,25,'快一点，$N，我知道你还没有完成我交给你的任务。猎杀那些半人马，然后我就会给你一份奖励以表示感谢。',12340),
(4842,1,0,'泉水似乎有些古怪……我还不能确定这意味着什么……',12340),
(4861,1,0,'',12340),
(4862,6,6,'你是弄到蜘蛛卵了，还是仅仅跑来跟我打个招呼？',12340),
(4863,1,0,'',12340),
(4864,1,1,'啊……你有什么新消息么？',12340),
(4865,1,0,'你把自己的发现汇报给莫特加·火鬃了吗？你应该立即告诉他这个消息。',12340),
(4866,1,35,'<狼狈不堪的约翰使劲拧了拧你。>',12340),
(4867,1,0,'啊！你把我的魔精带来了吗？',12340),
(4881,1,0,'什么？他们想要杀死我！让他们来吧，我会让他们知道厉害的！',12340),
(4882,1,0,'你是要汇报另一项任务的进展吗？',12340),
(4883,6,6,'我能帮你什么忙吗，$N？',12340),
(4901,1,0,'',12340),
(4902,1,0,'你好！',12340),
(4903,66,66,'<督军高图斯向你敬礼。>',12340),
(4904,1,0,'萨利亚我好想你……',12340),
(4906,1,20,'请你快点去结束费伍德森林的生物所遭受的痛苦。',12340),
(4907,1,0,'',12340),
(4921,1,6,'你找到她的线索了吗？我胸中的疼痛告诉我，也许最糟糕的事情已经发生了，但我还心存一点点希望……',12340),
(4941,1,0,'你没看见我很忙吗？',12340),
(4961,1,1,'你必须杀死那个恶魔，将它永远地从宝珠中驱逐出去，$N。',12340),
(4962,6,6,'是的，$N？你选好了吗？地狱火还是恶魔犬？$B$B每个选择都是个人的，应当反映你的长处与短处。$C不补短板、转而进一步强化自身，并非罕见。有时压倒敌人，与成为更均衡的施法者一样是高明的战术。',12340),
(4963,6,6,'是的，$N？你选好了吗？地狱火还是恶魔犬？$B$B每个选择都是个人的，应当反映你的长处与短处。$C不补短板、转而进一步强化自身，并非罕见。有时压倒敌人，与成为更均衡的施法者一样是高明的战术。',12340),
(4964,1,0,'',12340),
(4965,1,0,'',12340),
(4966,1,0,'',12340),
(4967,1,0,'',12340),
(4968,1,0,'',12340),
(4969,1,0,'',12340),
(4970,1,1,'纪律和决心是你的目标。我会让你完成若干个简单的任务，每次你都必须尽全力。',12340),
(4971,1,1,'当时间的进程被打乱时，时光寄生虫就会出现。现在就是这种状况，这可真是件令人烦恼的事儿。$B$B除掉那些时光寄生虫将有助于我控制不断恶化的情况。如果你完成了任务，我应该可以很快感知到。',12340),
(4972,1,1,'我寻找的那些计时器都是简单的小装置，当瘟疫侵袭安多哈尔的时候，它们就停止走动了。$B$B时间永远不会停止，而你找到的怀表会自动调整回正确时间……就是说，只要这儿仍在混乱之中。',12340),
(4973,1,1,'安多哈尔的怀表，就像城镇大厅废墟上的大钟，所有的指针都停留在三点的位置。这便是瘟疫首次席卷城市时带来的效应，指针停止转动了。$B$B几乎所有人都为那天发生的事情惋惜不已，就如人类感知的那样，时间流形成了。青铜龙军团必须坚持守护时间线！',12340),
(4974,0,0,'<萨尔低吼着。>',12340),
(4975,1,0,'',12340),
(4976,6,6,'你搜寻塔贝萨和宝珠的事情有没有新的进展，$N？$B$B塔贝萨对魔法的力量可以说是应付自如。我相信如果你能找到她的话，她肯定会帮助你的。',12340),
(4981,1,0,'很高兴见到你！',12340),
(4982,6,6,'找到了吗？',12340),
(4983,5,5,'那个地精在哪儿？',12340),
(4984,1,0,'感染了瘟疫的狼必须被除掉，$N。他们所患的疾病无法治愈。我曾经尝试过……我一直在试图拯救他们，直到我自己也死于瘟疫。',12340),
(4985,1,0,'我听到你的脚步声了，$N。我的视力已经消退，但我仍然能感觉到周围的事物。你让那些受尽疾病折磨的灰熊安息了吗？',12340),
(4986,2,0,'我代表塞纳里奥议会欢迎你的到来，$c。你找我们有什么事吗？',12340),
(4987,2,0,'我代表塞纳里奥议会欢迎你的到来，$C。你找我们有什么事吗？',12340),
(5001,6,6,'运气如何？',12340),
(5002,1,0,'啊，$N。好久不见了。',12340),
(5021,1,0,'',12340),
(5022,2,0,'欢迎来到暴风城人口普查办公室，如果你需要我们城市居民的资讯，那么我可以帮助你。',12340),
(5023,6,0,'你到这里来是寻求幽暗城人口普查局的帮助，还是问我某个你认识的人是不是已经死了？每天都有无数人来问我这个问题……',12340),
(5041,6,6,'你找到我们的补给物资了吗？$N？我相信你很容易就把野猪人打败了。',12340),
(5042,0,0,'如果你想要得到阿迦玛甘的力量，就给我弄四块血岩裂片来，$r。$B$B如果你被赐予了这个祝福，你的敌人就会在你的力量面前退缩。<哼哼>$B$B钢鬃部落中最伟大的战士都拥有这种力量！',12340),
(5043,0,0,'据说我们部族里最强大的斥候有着无与伦比的准确度，而且任何盗贼<哼哼>在战争中都无法与他们的灵巧和迅捷媲美。$B$B给我弄四块血岩裂片来，我就会让你变得比任何野猪人都更加敏捷。',12340),
(5044,0,0,'野猪人部族的萨满与地卜师<哼>在战斗和仪式中召唤阿迦玛甘的力量，$r。$B$B如果你也希望在法术中得到阿迦玛甘祝福的额外力量，那就给我带四块血碎片来，裂牙会帮你。<哼>',12340),
(5045,0,0,'各种战士<哼哼>都需要强大的精神力量。当所有希望都不复存在时，只有它能驱使你去完成更伟大的事业。这对<哼哼>钢鬃野猪人来说并不是秘密。我们是一个有着共同信仰的部族——比起我们在战斗中所表现出的威力<哼哼>来说，我们更以能与阿迦玛甘保持精神联系为荣。$B$B给我弄四块血岩裂片来，我就会祝福你，让你在战斗中充满斗志。<哼哼>',12340),
(5046,0,0,'所有<哼哼>踏入战场的勇士都需要保护。他们的骨骼必须强壮，他们的皮肤必须坚韧。<哼哼>我的部族也知道这点，为了让我们与生俱来的鬃毛和皮肤有更好的防护效果，<哼哼>我们经常在上战场之前请求阿迦玛甘保护我们免受伤害。$B$B给我带来四块血石裂片，<哼哼>我就会赐给你同样的保护。',12340),
(5047,0,0,'什么事？',12340),
(5048,25,0,'我本想叫你离开我的草坪，但是如你所见的，我没有草坪。',12340),
(5049,18,0,'每次有人踩到蟑螂，我都会哭。请不要让我哭泣。',12340),
(5050,0,0,'约翰，亲爱的……是你吗？我突然觉得好冷……',12340),
(5051,0,0,'约翰，不要让那些食尸鬼抓到你……不要让这些食尸鬼抓到我……肮脏的食尸鬼……我们的幸运符会让我们安全的。',12340),
(5052,1,0,'我们的部族聚集在遍及贫瘠之地的荆棘旁，<猪哼声>因为那种地方是神圣的，但它们都不如剃刀沼泽那般神圣。阿迦玛甘的身体构成了剃刀沼泽的全部<猪哼声>，但高地是最关键的，因为那个入口是由他巨大的嘴形成的！<猪哼声>它会吞掉所有不忠于他的人，并把咀嚼后的尸体吐出来！<猪哼声>$B$B阿迦玛甘把肉体留下来保护我们，而且他还献出了他的灵魂，让我们来保护他。<猪哼声>',12340),
(5054,1,0,'动身吧，$c。去找出尤西乌斯。',12340),
(5055,1,25,'布鲁米兰在呼唤你，$N。',12340),
(5056,1,1,'希洛塔姆勇猛而无情，她会以热情和生命保卫她的同类。',12340),
(5057,1,0,'',12340),
(5058,1,0,'',12340),
(5059,0,0,'一个极其结实的柜子立在你面前，柜子的门被一个内建的锁牢牢地锁着。柜子的前面有深深的划痕与刻痕，看起来好像是在无数次想要解开其中秘密的粗暴失败尝试所导致的结果。$B$B如果你想要打开这个柜子，就得先找到钥匙。',12340),
(5060,0,0,'一个极其结实的柜子立在你面前，柜子的门被一个内建的锁牢牢地锁着。柜子的前面有深深的划痕与刻痕，看起来好像是在无数次想要解开其中秘密的粗暴失败尝试所导致的结果。$B$B如果你想要打开这个柜子，就得先找到钥匙。',12340),
(5061,1,0,'你回到达纳苏斯并不是没有预兆的，尽管在教你学习水中形态之前，我需要你在月光林地所学课程的证据。$B$B你得到海狮的坠饰了吗？',12340),
(5062,0,0,'那么说来玛加萨·图腾要对付了阿利卡拉……好吧，这真是个重大的消息。$B$B<玛加萨看了看四周。>$B$B阿利卡拉是一个危险的生物，它的诞生只是为了对那些犯了极度可恶罪行的人寻求报复。$B$B<玛加萨微笑着。>',12340),
(5063,6,6,'除非你收集到了我要的东西，否则你就是在浪费我的时间。',12340),
(5064,6,6,'你找到恐怖图腾族到底在做什么了吗？',12340),
(5065,6,6,'你拿到石板了吗？我怕那些石板上所刻的文字会揭示一个对我们世界造成巨大威胁的力量。',12340),
(5066,1,0,'',12340),
(5067,6,6,'除非你收集到了我要的东西，否则你就是在浪费我的时间。',12340),
(5068,6,6,'除非你收集到了我要的东西，否则你就是在浪费我的时间。',12340),
(5081,1,0,'情况如何？',12340),
(5082,1,0,'感谢你的帮助！',12340),
(5083,0,0,'那是什么东西？',12340),
(5084,1,0,NULL,12340),
(5085,5,0,'我希望你有些发现，$N。熊怪变得越来越咄咄逼人了！',12340),
(5086,0,0,'我想我们就快揭开谜底了，$N。',12340),
(5087,1,1,'让我们来看没有火酒的冬泉熊怪变成什么样子吧！',12340),
(5088,1,1,'你杀死邪恶的毒蛇阿利卡拉了吗，$N？',12340),
(5089,6,6,'你有什么要给我的吗，$N？',12340),
(5090,1,0,'',12340),
(5091,1,0,'',12340),
(5092,1,25,'我希望你做好最坏的打算，$N——要深入敌军腹地。我们要完成的可不是简单的任务。在我们集结军队与天灾军团决战之前，你将作为先遣部队的一员对他们发起攻击！你在悔恨岭的任务将是我们通往胜利之路的起点！',12340),
(5093,1,0,'',12340),
(5094,1,0,'',12340),
(5095,1,0,NULL,12340),
(5096,1,0,'对血色十字军薄弱的防线进行突袭，这为我们赢取了向安多哈尔进军的时间。我相信你是来此汇报胜利的消息的！$B$B一旦你成功地完成了任务，我们很快就要开战了。如果天灾军团和血色十字军识破我们的计谋，以我们的实力是不可能同时与这两方抗衡的。',12340),
(5097,1,1,'一旦那几座哨塔被做上了标记，它们就将成为我们在安多哈尔的首要攻击目标。我预计在攻占那些哨塔塔之后就要和安多哈尔城中的主力部队交锋了。那时，我们要进行一场痛快淋漓的战斗，一举夺取城市的控制权！$B$B我希望你凯旋而归，另外别忘了把信号火炬也带回来，我们可不能浪费资源。',12340),
(5098,1,0,'一旦那几座哨塔被做上了标记，它们就将成为我们在安多哈尔的首要攻击目标。我预计在攻占那些哨塔塔之后就要和安多哈尔城中的主力部队交锋了。那时，我们要进行一场痛快淋漓的战斗，一举夺取城市的控制权！$b$b我希望你凯旋而归，另外别忘了把信号火炬也带回来，我们可不能浪费资源。',12340),
(5102,1,6,'任务完成了吗？',12340),
(5103,1,0,'',12340),
(5121,1,0,'也许你可以在冬泉谷里找到更多的线索，$N。',12340),
(5122,1,0,'这个小教堂给了我抵抗内心中的腐化力量。如果离开这里，我就会变成一个死亡骑士。但是有一枚勋章，信仰勋章，它可以给予我离开这里所需的力量。$B$B$N，请帮我拿回这枚勋章。它被狂热的玛洛尔看守着，他是血色十字军的一员，居住在西斯坦索姆的血色十字军堡垒深处。',12340),
(5123,6,0,'嗯，这是什么，$N？',12340),
(5124,1,0,'时间就是金钱，$N和我都浪费不起。',12340),
(5125,1,0,'',12340),
(5126,1,0,NULL,12340),
(5127,1,0,'别让我等得不耐烦……',12340),
(5128,2,0,'翡翠议会对所有的种族都非常友善，$R。我能帮你什么忙吗？',12340),
(5141,1,0,'如果你决心成为龙鳞制皮师，那么我就收下你这个学生。把我要的东西交给我，我就可以开始向你传授技能了。',12340),
(5142,1,0,'',12340),
(5143,1,1,'在你期望学习如何利用大自然提供的材料制作皮甲之前，你必须对它有所贡献。让我看看你为大自然奉献了什么吧，它会回报你的。',12340),
(5144,1,0,'制造皮甲需要耐心和热情。一旦你投身元素制皮工作，就不能退出了。让我看看你是否能胜任这项工作，然后我们就可以开始了。',12340),
(5145,1,1,'如果你决心成为龙鳞制皮师，那么我就收下你这个学生。把我要的东西交给我，我就可以开始向你传授技能了。',12340),
(5146,1,1,'制造皮甲需要耐心和热情。一旦你投身元素制皮工作，就不能退出了。让我看看你是否能胜任这项工作，然后我们就可以开始了。',12340),
(5147,0,0,'你有什么关于阿纳克·恐怖图腾的消息吗？',12340),
(5148,1,0,'在你期望学习如何利用大自然提供的材料制作皮甲之前，你必须对它有所贡献。让我看看你为大自然奉献了什么吧，它会回报你的。',12340),
(5149,0,0,'你找到我的洋娃娃了吗？',12340),
(5150,0,0,'当你走向达丹加的时候，她目不转睛地看着你。她似乎在希望你拿给她什么东西……$B$B她也许是饿了！$B$B也许在环形山里长着一些可以喂给这头大型食草动物的花花草草。达丹加的个头不小，不管你准备给她喂什么，数量肯定少不了！',12340),
(5151,0,0,'你拿到我的超适应齿轮了吗？',12340),
(5152,1,0,'',12340),
(5153,6,0,'你来访的时间很有意思……你不是来自未来的吧？',12340),
(5154,6,6,'你找到书了吗，$N？',12340),
(5155,1,6,'你的战斗进行得怎么样了，$N？我知道把挥洒的鲜血作为荣誉的证明让有些人感到疑惑，但是你必须懂得这么做的原因:它可以让我的任务变得简单一些。另一方面，我们可以因此而互相尊重。$B$B我希望你能懂得这些。',12340),
(5156,1,1,'我希望你的搜索进行得很顺利，$N。我还没有准备启程去森林北部，但是我必须承认，穿越一片到处都是地狱火的区域让我感到有些害怕。那些生物没有思想，但仍然非常具有威胁性。',12340),
(5157,6,6,'一旦我们有了月亮井的水，就可以对其进行净化，然后用它来熄灭保护暗影堡的火盆。这样我就有充足的时间来侦测他们的老巢，并搞清楚是谁在领导着他们……$b$b我希望大地之母能与我们同在。',12340),
(5158,2,0,'我感觉你不是个找路去棘齿城的旅人。过来，在我们的帐篷里休息一下，当你准备好了就和我说说吧。',12340),
(5159,2,0,'啊，你回来了，$N。很好。你在贫瘠之地找到水之先知伊斯伦了吗？如果没有的话，那我们就得另想办法来达成目标了。',12340),
(5160,2,2,'见到你很高兴，$N。',12340),
(5161,1,0,'',12340),
(5162,1,0,'',12340),
(5163,5,5,'真想知道我的朋友会有什么反应！$B$B他们绝对会被吓一大跳的！',12340),
(5164,1,0,'你打开了书。',12340),
(5165,1,1,'如果我们想要发动一场大战的话，那些火盆就必须被熄灭。毫无准备地闯入暗影堡无异于找死。现在我们所面对的敌人甚至比一条龙还要危险——暗影议会犯下了无数滔天的罪行。如果我们要阻止他们的话，就必须快点行动了。',12340),
(5166,273,273,'你做出了明智的选择，$R。',12340),
(5167,1,1,'这样一件东西以前从未被铸造出来过！',12340),
(5168,0,0,'你找到那些圣物了吗，$N？',12340),
(5181,0,0,'你找到头颅和宝剑了吗，$N？',12340),
(5201,1,1,'熊怪们似乎患上了妄想症……',12340),
(5202,6,0,'我不禁开始怀疑我是否能逃离这只牢笼。$b$b他们迟早会把我献祭给他们所崇拜的恶魔。',12340),
(5203,1,0,'你看起来气喘吁吁的，$n。你还好吗？',12340),
(5204,1,0,'你检查了那具尸体，毫无疑问，这就是白银之手骑士团的特雷·莱弗治的遗体了。你想起了亚科纳琳，并想起了这位圣骑士的死对她所造成的打击。$B$B过了一会儿，你重新收回了思绪。你很清楚，在没有杀死折磨这个圣骑士的恶徒之前，你是无法把他的遗体带回杰希尔那里的。',12340),
(5206,6,6,'你拿到头骨了吗？克罗米说那些东西对她的法术至关重要，而那个法术会给我们带来拯救达隆郡的机会。',12340),
(5210,0,0,'你从西边来的？洛丹伦的其它人怎么样了？我知道安多哈尔已经陷落了，但是天灾军团到达美丽的提瑞斯法了吗？',12340),
(5211,1,5,'达隆郡的防卫者们在我的梦中向我哭喊，$N。你必须释放他们！',12340),
(5212,5,5,'有些人说我担心太多了，我对他们说，“是你们太掉以轻心了！”',12340),
(5213,5,5,'我们就快要揭开这种新的活性瘟疫的秘密了！',12340),
(5214,5,5,'我受不了了，$N！你必须帮帮我！我要死了！',12340),
(5215,1,0,NULL,12340),
(5216,0,0,'天灾之锅的控制面板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。',12340),
(5217,3,0,'欢迎回到相对来说还算安全的冰风营地，$N。你在天灾之锅那边有什么进展要汇报吗？',12340),
(5218,0,0,'天灾军团的天灾之锅就伫立在你面前，它将大量的毒素喷洒到空气中。在锅炉的巨大平台下，有一条细长的管道。$B$B你已经击败了护锅者并获得了这口锅的钥匙，可以随心所欲地向锅内添加适当的药剂来抵消瘟疫的效果了。',12340),
(5219,0,0,'天灾之锅的控制面板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。',12340),
(5220,1,0,'我们知道每一口天灾之锅都使用不同的药剂来产生毒素，同样，我们也知道我们必须针对各个天灾之锅中的毒素研制出相应的解药。你从达尔松之泪取得的样品是我们解决那里的天灾之锅的关键。',12340),
(5221,1,0,'天灾军团的天灾之锅就伫立在你面前，它将大量的毒素喷洒到空气中。在锅炉的巨大平台下，有一条细长的管道。$B$B你已经击败了护锅者并获得了这口锅的钥匙，可以随心所欲地向锅内添加适当的药剂来抵消瘟疫的效果了。',12340),
(5222,0,0,'天灾之锅的控制面板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。',12340),
(5223,1,0,'一旦我们成功地分析了从嚎哭鬼屋的天灾之锅里取得的样品，就可以再研制出一种能有效对抗天灾军团的药剂了！',12340),
(5224,0,0,'天灾军团的天灾之锅就伫立在你面前，它将大量的毒素喷洒到空气中。在锅炉的巨大平台下，有一条细长的管道。$B$B你已经击败了护锅者并获得了这口锅的钥匙，可以随心所欲地向锅内添加适当的药剂来抵消瘟疫的效果了。',12340),
(5225,0,0,'天灾之锅的控制面板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。',12340),
(5226,1,0,'盖罗恩农场的天灾之锅是我们在东部的最后一个目标。只要我们得到锅中的瘟疫样本，我们就可以通过这四口锅把我们的解药散播到空气中！即使有克尔苏加德的支持，天灾军团也很难兼顾四口天灾之锅。',12340),
(5227,1,0,'天灾军团的天灾之锅就伫立在你面前，它将大量的毒素喷洒到空气中。在锅炉的巨大平台下，有一条细长的管道。$B$B你已经击败了护锅者并获得了这口锅的钥匙，可以随心所欲地向锅内添加适当的药剂来抵消瘟疫的效果了。',12340),
(5228,1,0,'',12340),
(5229,1,0,'天灾之锅的控制面板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。',12340),
(5230,6,0,'欢迎回到相对来说还算安全的亡灵壁垒，$N。你在天灾之锅那边有什么进展要汇报吗？',12340),
(5231,1,0,'天灾之锅的控制面板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。',12340),
(5232,1,0,'我们知道每一口天灾之锅都使用不同的药剂来产生毒素，同样，我们也知道我们必须针对各个天灾之锅中的毒素研制出相应的解药。你从达尔松之泪取得的样品是我们解决那里的天灾之锅的关键。',12340),
(5233,1,0,'天灾之锅的控制面板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。',12340),
(5234,1,0,'只要我们成功的分析从嚎哭鬼屋的天灾之锅里取得的样品，就可以研制出另一种能够有效对抗瘟疫的解药了！',12340),
(5235,1,0,'天灾之锅的控制面板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。',12340),
(5236,1,0,'盖罗恩农场的天灾之锅是我们在西瘟疫之地的最后一个目标。只要我们得到锅中的瘟疫样本，我们就可以通过这四口锅把我们的解药散播到空气中！即使有克尔苏加德的支持，天灾军团也很难兼顾四口天灾之锅。',12340),
(5237,1,0,'',12340),
(5238,1,0,'',12340),
(5241,1,0,'',12340),
(5242,1,1,'如果没有了费尔丹，暗影议会就很有可能失去重心并开始内讧。他们会各怀鬼胎地相互争夺权力和财宝。那将是毁灭他们的绝佳时机。',12340),
(5243,1,1,'你要注意，并不是所有的补给木箱都在城市被毁灭后保存了下来。天灾军团不敢碰触圣水，但圣水并不能阻止害虫的侵袭。',12340),
(5244,1,0,'',12340),
(5245,0,0,'你为何而来？',12340),
(5246,0,0,'只有看过圣书，我才能知道是否可以帮助你……',12340),
(5247,0,0,'神器必须放在最值得信任的人手中。它不能再次被盗了……',12340),
(5248,1,0,'诅咒……永远……',12340),
(5249,1,0,'',12340),
(5250,1,0,'有事吗？',12340),
(5251,1,5,'记住，$N——我们需要宽容，但是我们也必须坚持自己的信仰！',12340),
(5252,6,0,'你离开已经很长时间了，$N。这段时间以来，你都遇见了些什么事情？',12340),
(5253,0,0,'怎么了，$R？',12340),
(5261,6,6,NULL,12340),
(5262,25,0,'你有什么要给我的吗，$N？',12340),
(5263,1,1,'男爵杀的人也许比你一生所看到的都要多。',12340),
(5264,1,0,'啊，伟大的英雄！',12340),
(5265,1,0,'箱子悄无声息地打开了。',12340),
(5281,1,0,'我可没料到会有人来找我。',12340),
(5282,1,0,'怜悯是我们与动物的区别所在，$N。记住这一点……',12340),
(5283,1,1,'啊，没什么比一双巧手更有价值的了，你只需看看护甲的线脚，就可以知道它是个什么级别的货色。',12340),
(5284,0,0,'<埃隆努斯正忙于将金币整理成堆。>',12340),
(5301,1,1,'我要用尽全力，把这块铁敲打得坚固无比。',12340),
(5302,4,4,'为部落的荣耀而努力吧！',12340),
(5305,5,5,'他的围裙！在哪儿？',12340),
(5306,5,5,'据说用沃许加斯的菊石打磨过的斧头可以保持锋利达千年之久！',12340),
(5307,6,6,'你忘记自己的任务了吗，$N？',12340),
(5321,0,0,'克罗尼亚来了没有？',12340),
(5341,25,25,'向我行礼鞠躬，你这低贱的$r。我是身出名门的贵族，而你只不过是个一文不值的农民。',12340),
(5342,0,0,'确保我得到这笔财产，你也不会吃亏的。',12340),
(5343,25,25,'在我面前低头，$R。毕竟我是贵族，而你是个身无分文的农民。',12340),
(5344,6,6,'你难道不想要报酬吗？',12340),
(5361,0,0,'你带来了什么消息，$C？啊——你是说我兄弟托送的消息？好吧，把报告给我吧！',12340),
(5381,0,0,'$n，你拿到恶魔之盒了吗？',12340),
(5382,1,5,'我们必须除掉这个屠夫！',12340),
(5384,1,1,'小心，基尔图诺斯是个经验丰富的战士。',12340),
(5385,6,0,'加德纳尔的情况怎么样了，$N？',12340),
(5386,1,1,'当我想到油炸的血肚鱼时，我的蹄子便开始发痒，口水都快流下来了……你搞到鱼了吗？',12340),
(5401,1,0,'',12340),
(5402,1,1,'爪牙的天灾石是天灾军团的身份象征，通常是由那些部署在瘟疫之地的、较为弱小的士兵所携带的。我所说的“较为弱小”是个相对的概念，无论天灾军团出现在哪里，他们都是一个不可轻视的威胁。$B$B如果你能拿来二十个这样的天灾石，银色黎明将会给你颁发一枚勇气徽记，以此表彰你在于天灾军团的战争中做出的贡献！',12340),
(5403,1,1,'侵略者的天灾石是天灾军团精英部队的象征，通常是由那些部署在瘟疫之地的主力部队中的士兵携带的。斩杀这样的敌人对你来说是一个挑战，但是你也会因此得到丰厚的奖赏。$B$B如果你能拿来十块这样的天灾石，银色黎明就将给你颁发一枚勇气徽记。',12340),
(5404,1,1,'堕落者的天灾石是天灾军团将领的标志。那些统御天灾军团的将领总是会随身携带一块这样的徽记。如果能杀掉如此强大可怕的敌人对银色黎明和我们的正义事业来说都是非常有利的！$B$B如果你能拿来一块这样的天灾石，我会代表银色黎明颁发一枚勇气徽记给你。不过你要小心，$N——你要面对的绝非一般的敌人。',12340),
(5405,1,0,'',12340),
(5406,1,1,'堕落者的天灾石是天灾军团将领的标志。那些统御天灾军团的将领总是会随身携带一块这样的徽记。如果能杀掉如此强大可怕的敌人对银色黎明和我们的正义事业来说都是非常有利的！$B$B如果你能拿来一块这样的天灾石，我会代表银色黎明颁发一枚勇气徽记给你。不过你要小心，$N——你要面对的绝非一般的敌人。',12340),
(5407,1,1,'侵略者的天灾石是天灾军团精英部队的象征，通常是由那些部署在瘟疫之地的主力部队中的士兵携带的。斩杀这样的敌人对你来说是一个挑战，但是你也会因此得到丰厚的奖赏。$B$B如果你能拿来十块这样的天灾石，银色黎明就将给你颁发一枚勇气徽记。',12340),
(5408,1,1,'爪牙的天灾石是天灾军团的身份象征，通常是由那些部署在瘟疫之地的、较为弱小的士兵所携带的。我所说的“较为弱小”是个相对的概念，无论天灾军团出现在哪里，他们都是一个不可轻视的威胁。$B$B如果你能拿来二十个这样的天灾石，银色黎明将会给你颁发一枚勇气徽记，以此表彰你在于天灾军团的战争中做出的贡献！',12340),
(5421,1,1,'谁能使我的生活更惬意些，我就报答谁……我喜欢尽可能地少做事，多睡觉！$B$B我在葬影村的码头放了许多捕贝装置，如果你愿意帮我收集贝壳，我也会给你一些好东西……明白我的意思了吗？你每交给我五块贝壳，我就送你一条血肚鱼。',12340),
(5441,5,1,'偷懒可不好……$b$b嗯？你手里拿的是我的木棒？你抓到偷懒睡觉的苦工没有？',12340),
(5461,0,0,'$N，巫妖生前的遗物是很难找到的。',12340),
(5462,274,0,'不要问你不需要答案的问题。',12340),
(5463,1,0,'米奈希尔的礼物周围的区域显得特别寒冷。',12340),
(5464,0,0,'<莱尼德战栗着。>',12340),
(5465,6,0,'你完成了我交给你的任务了吗？',12340),
(5466,1,1,'你肩负着为上万个永不安息的灵魂复仇的责任，$N。',12340),
(5481,0,0,'那个没用的憎恶在哪里？要是你还没拿到我要的东西，就赶快给我去找。',12340),
(5482,6,0,'嗯，你收集到我要的末日草了吗？',12340),
(5501,0,0,'你弄到科多兽骨吗？车队随时都会来的。我只需要十根科多兽骨就可以达到我事业的巅峰。事业的巅峰，你明白吗？！',12340),
(5502,1,0,'很高兴再见到你，$N。你有没有在儿童周中完成自己的义务？',12340),
(5503,1,0,'',12340),
(5504,1,0,'啊，高尚的$C！你带来我所要求的银色黎明勇气勋章了吗？只要你把它们交给我，我就可以向你提供各种各样的披肩了。',12340),
(5505,1,0,'好了，给你，$n——这就是骷髅钥匙。我很确定它能打开通灵学院的大门。不过只有一个办法能检验它，我说，你就别在我这浪费时间了。',12340),
(5507,1,0,'啊，高尚的$C！你带来我所要求的银色黎明勇气勋章了吗？只要你把它们交给我，我就可以向你提供各种各样的披肩了。',12340),
(5508,1,1,'堕落者的天灾石是天灾军团将领的标志。那些统御天灾军团的将领总是会随身携带一块这样的徽记。如果能杀掉如此强大可怕的敌人对银色黎明和我们的正义事业来说都是非常有利的！$B$B如果你能拿来一块这样的天灾石，我会代表银色黎明颁发一枚勇气徽记给你。不过你要小心，$N——你要面对的绝非一般的敌人。',12340),
(5509,1,1,'侵略者的天灾石是天灾军团精英部队的象征，通常是由那些部署在瘟疫之地的主力部队中的士兵携带的。斩杀这样的敌人对你来说是一个挑战，但是你也会因此得到丰厚的奖赏。$B$B如果你能拿来十块这样的天灾石，银色黎明就将给你颁发一枚勇气徽记。',12340),
(5510,1,1,'爪牙的天灾石是天灾军团的身份象征，通常是由那些部署在瘟疫之地的、较为弱小的士兵所携带的。我所说的“较为弱小”是个相对的概念，无论天灾军团出现在哪里，他们都是一个不可轻视的威胁。$B$B如果你能拿来二十个这样的天灾石，银色黎明将会给你颁发一枚勇气徽记，以此表彰你在于天灾军团的战争中做出的贡献！',12340),
(5511,1,0,'好了，给你，$n——这就是骷髅钥匙。我很确定它能打开通灵学院的大门。不过只有一个办法能检验它，我说，你就别在我这浪费时间了。',12340),
(5513,1,0,'啊，高尚的$C！你带来我所要求的银色黎明勇气勋章了吗？只要你把它们交给我，我就可以向你提供各种各样的披肩了。',12340),
(5514,1,0,'嗯，我知道你是谁，我也知道你来这里干什么。阿尔比顿在你来之前就跟我说过了。让我们长话短说吧，怎么样？$b$b我确实有可以用来制作骷髅钥匙的模具，但是它非常贵——15个金币，现货，不二价。我会把骸骨碎片放进模具里交给你，我也会教你如何铸造钥匙，即使你连一点锻造的相关知识都没有……这些都是免费的。$b$b谁说商人都是唯利是图的！',12340),
(5515,0,0,'<艾瓦若隐若现。>',12340),
(5517,1,0,'向你致敬，强大的$c！你有没有带来我要的银色黎明勇气勋章？当你把它们交给我之后，我就会把炫彩黎明披肩给你。',0),
(5518,1,0,'我制作巨魔装所需要的材料中，巨魔鞣酸也许是最难找到的——我想也许你可以在这里的楼上找到一些？不过很难说，因为我被拴在这里寸步难行……$B$B不管怎样，把我需要的东西给我拿来，我就会帮你制作一件巨魔装，然后你就可以用它来欺骗克罗卡斯，因为他会以为你是自己人。',12340),
(5519,1,0,'还要一件？好吧，看起来我一时半会也没法出去，那么你就像上次那样把材料给我拿来，我帮你把衣服做好。',12340),
(5521,1,0,'向你致敬，强大的$C！你有没有带来我要的银色黎明勇气勋章？当你把它们交给我之后，我就会把炫彩黎明披肩给你。',12340),
(5522,6,0,'你就是那个在黑石塔搞事的家伙，对吧？我要的东西你带来了吗？',12340),
(5524,1,0,'向你致敬，强大的$C！你有没有带来我要的银色黎明勇气勋章？当你把它们交给我之后，我就会把炫彩黎明披肩给你。',12340),
(5525,1,0,'我说的是戈多克镣铐钥匙——好吧，那些胖家伙是这么叫它的。任何巨魔都有可能拿着这把钥匙，不过我不清楚到底谁拿着它。没准那些卫兵是负责看管钥匙的……$B$B啊呀，我到底在想什么？你已经拿到钥匙了，对吧？',12340),
(5526,1,0,'拿到净化之匣后，我们不仅可以从世界上消除一股堕落的力量，而且可以谨慎理智地对其进行研究。也许我们可以找到与威胁艾泽拉斯的堕落力量抗衡的新方法。$b$b我知道米利会得到它的……',12340),
(5527,1,0,'净化之匣本身就是一件神器。最初制造出来的净化之匣数量不多，随着时间的推移，其数量越来越少。$B$B我承认，很早之前我就知道南风村中的那个净化之匣的存在了。老实说，随着希利苏斯不断出现新的混乱状况，我希望你能把这个秘密一直保持下去。过多地泄露这个秘密将会引起敌人更多的怀疑。$B$B啊，看来和平时期又要结束了，尤其是当埃德萨拉斯处于当前这种情况下的时候。',12340),
(5528,1,0,'',12340),
(5529,1,5,'到通灵学院去，$N。一定要在那些龙崽长大之前干掉它们！',12340),
(5531,3,0,'你好，$N！我听说你带来一些龙蛋？嗯，快让我看看！',12340),
(5533,1,0,'',12340),
(5534,1,0,'那么，$N，符石在哪里？你是个好的雇员，不是吗？你来这里是要帮我忙的吧？$b$b不要让我后悔付钱给你。什么？哦，我们之间没有达成任何协定？哦，太好了……那么你慢慢来吧——不过如果你浪费了很多时间的话，那是你的损失，不是我的。',12340),
(5535,1,6,'你搜寻精灵贵族之魂的工作进行得怎么样了，$c？$B$B有很多事情使得整个艾泽拉斯都遭受了巨大的痛苦，但是因为某些原因，这些游魂对所有人来说好像一场瘟疫。也许它们仍然还是渴望着获得魔法的力量——这种渴望最终会引来燃烧军团，我们知道这意味着什么。',12340),
(5536,1,1,'你和萨特的战斗进行得怎么样了，$c？$B$B他们是不是如你想象中的一般强大呢？或者更强？',12340),
(5537,1,1,'虽然这听起来很恶心，但是我们确实需要许多合适的骸骨碎片来制作钥匙的外层部分。你要知道，如果没有这些东西，那它也不叫骷髅钥匙了。',12340),
(5538,1,0,'嗯，我知道你是谁，我也知道你来这里干什么。阿尔比顿在你来之前就跟我说过了。让我们长话短说吧，怎么样？$B$B我确实有可以用来制作骷髅钥匙的模具，但是它非常贵——15个金币，现货，不二价。我会把骸骨碎片放进模具里交给你，我也会教你如何铸造钥匙，即使你连一点锻造的相关知识都没有……这些都是免费的。$B$B谁说商人都是唯利是图的！',0),
(5541,6,6,'我希望你不是来买弹药的，因为我已经没有库存了！',12340),
(5542,1,5,'别怜悯那些恶魔犬，$r。它们是可憎之物！',12340),
(5543,1,1,'别小看这些带翼的害虫，$r。瘟疫赋予了它们超自然的能力。',12340),
(5544,1,1,'你会慢慢习惯这个味道的，$r。',12340),
(5545,0,0,'期限马上就要到了，$C。请马上帮我收集一些木材。',12340),
(5561,0,0,'商队就要来了，我要的5头科多兽呢？',12340),
(5581,6,6,'你有没有放逐玛诺洛克集会所里的恶魔传送门？',12340),
(5582,1,0,'$N，你有什么东西要给我看的吗？',12340),
(5601,1,0,'',12340),
(5621,1,0,'我们的强化法术非常强大，德洛尔。它们能让同伴承受更多各类攻击的伤害，在本会倒下的情形中活下来。但这与我们治疗的能力相比不值一提。没有比牧师更伟大的治疗者——务必记住这点。单是你的力量就能轻易扭转战局。',12340),
(5622,1,0,'',12340),
(5623,1,0,'',12340),
(5624,1,1,'就如同你所了解的，在日前这种艰苦的时期中，我们的治疗法术对我们的生存是非常重要的——特别是对于那些使用武器和魔法对抗许多不同威胁的冒险者和英雄们。$B$B牢记这些技能的重要性。使用真言术：韧，你的战友就可以在战斗中活得更久，可以承受更多次的攻击，也能让你表现得很好。$B$B不要让任何人忽视你所掌控的魔法力量。',12340),
(5625,1,0,'你找到多尔夫了吗，$N？$B$B也许你已经知道了这些，但是，我们的治疗技能确实非常有用。我们不仅仅能治疗受伤的人，而且对于那些未来的英雄或者想要打向自己名字的人的生命也非常重要。使用真言术：韧，我们就可以让自己和伙伴们变得更加耐打，而我们的治疗法术能让他们活得更久，没有什么是我们不能克服的！',12340),
(5626,6,0,'',12340),
(5627,1,0,'',12340),
(5628,1,0,'',12340),
(5629,1,0,'',12340),
(5630,1,0,'',12340),
(5631,1,0,'',12340),
(5632,1,0,'',12340),
(5633,1,0,'',12340),
(5634,1,0,NULL,12340),
(5635,1,0,NULL,12340),
(5636,1,0,NULL,12340),
(5637,1,0,NULL,12340),
(5638,1,0,NULL,12340),
(5639,1,0,NULL,12340),
(5640,1,0,NULL,12340),
(5641,1,0,'',12340),
(5642,1,0,'',12340),
(5643,1,0,'',12340),
(5644,1,0,'',12340),
(5645,1,0,'',12340),
(5646,1,0,'',12340),
(5647,1,0,NULL,12340),
(5648,1,0,'许多人都知道治疗法术非常强大，但是他们并不知道它有多么强大。你可以拯救无数即将消逝的生命，让他们不致过早地在另一个世界见到他们的祖先。治疗法术与真言术：韧的结合是非常强大的，你要牢记这一点。无论是战士、法师，还是其它的职业，都会很需要你的这种能力。',12340),
(5649,1,0,'',12340),
(5650,1,0,'我们的力量让我们在许多场合都很理想，$N。但你会发现，无论如何，我们治愈伤痛、让同伴承受更多伤害的能力，始终是我们最受青睐的天赋。别因此放弃当$C的其他道路——你可以在许多方面发挥效用。不过……如果你真希望用魔法能量摧毁敌人，也许奥术更合你意。',12340),
(5651,1,0,'',12340),
(5652,1,0,'',12340),
(5654,1,0,'',12340),
(5655,1,0,'',12340),
(5656,1,0,'',12340),
(5657,1,0,'',12340),
(5658,1,0,NULL,12340),
(5659,1,0,NULL,12340),
(5660,1,0,NULL,12340),
(5661,1,0,NULL,12340),
(5662,1,0,NULL,12340),
(5663,1,0,NULL,12340),
(5672,1,0,'',12340),
(5673,1,0,'',12340),
(5674,1,0,'',12340),
(5675,1,0,'',12340),
(5676,1,0,'',12340),
(5677,1,0,'',12340),
(5678,1,0,NULL,12340),
(5679,1,0,'',12340),
(5680,1,0,'',12340),
(5713,1,0,'你在路上看到哨兵阿娜莎了吗？她正在执行重要的任务，不过直到现在她还没有回来。',12340),
(5721,1,0,'我想我听到了外面那些鬼魂的声音。他们在低声告诉我一些可怕的事情……',12340),
(5722,1,0,'尸体',12340),
(5723,1,6,'搜寻怒焰裂谷的工作进行得怎么样了？穴居人呢？$B$B我们绝不允许它们的威胁继续存在——这只会伤害到我们的兽人同胞。',12340),
(5724,6,6,'你找到什么东西了吗，$N？我想知道为什么她的族人要做出无谓的牺牲，任何有关的线索都会对我们很有帮助的。',12340),
(5725,1,0,'我还有好几百个任务要执行，$C。你取到书了吗？',12340),
(5726,6,6,'你拿到了徽章了吗，$N？$b$b它将是你渗透到火刃氏族中去的重要工具，我认为他们是部落的最大威胁，也是我们刚刚得到的和平的最大威胁。$b$b你会发现，当人类或是兽人受到贪欲和权力驱使时，他们会干出多么可怕的事情来。那些阴暗的勾当和隐藏的敌人终将露出真面目来。你将发现自己置身于一场你从未想象过的战争中。',12340),
(5727,1,6,'嗯，$c？他相信我们了没有？要不然就是事情比预计的更加糟糕？$b$b向尼尔鲁证明你的价值，这样我们就更容易进入暗影议会。我们可以利用他提供的大量情报找到真正的幕后主使。',12340),
(5728,1,0,'你找到他们了吗，$N？我是说灼刃氏族的领袖。$b$b我知道暗影议会想要从我手中夺走奥格瑞玛以及整个部落，但是我还不清楚他们能以多快的速度渗透到这座城市里来。这群叛徒拥有如此大的势力……我们可以全力以赴，奋勇杀敌，直至筋疲力尽，但是情况并不会好转多少。我必须让我的探子更活跃一些。',12340),
(5729,1,0,'',12340),
(5730,1,0,'',12340),
(5741,6,6,'你拿到圣光权杖了吗？',12340),
(5742,1,0,'朋友，请你坐下听听我的故事。',12340),
(5761,1,0,'你杀死那头野兽了吗？他一定是怒焰裂谷中那些灼刃氏族成员的首领。',12340),
(5762,6,0,'你的领子上是沙漠的尘土吗？$b$b嗯……如果我的鼻子没有毛病的话，那不是沙漠上的尘土，是沙漠盐！你去过闪光平原了，是不是？',12340),
(5763,6,0,'坐下，$C。不久之后，你就要重新杀入丛林之中了。',12340),
(5781,5,5,'他必须得到救赎。',12340),
(5801,6,0,'你铸造出骷髅钥匙的主体部分了吗？很抱歉你得自己掏钱来买这个模具，但是我们必须各尽所能地共同对抗天灾军团。一旦你把未完成的钥匙交给我，你就可以开始准备铸造钥匙所需的最后一件物品了。$b$b虽然这并不简单，但是你为了进攻安多哈尔所做的准备将会初见成效。你会看到的。',12340),
(5802,6,0,'你铸造出骷髅钥匙的主体部分了吗？很抱歉你得自己掏钱来买这个模具，但是我们必须各尽所能地共同对抗天灾军团。一旦你把未完成的钥匙交给我，你就可以开始准备铸造钥匙所需的最后一件物品了。$b$b虽然这并不简单，但是你为了进攻安多哈尔所做的准备将会初见成效。你会看到的。',12340),
(5803,1,1,'你必须明白，$N——只有摧毁“召唤者”阿拉基的肉身才能拿到完成钥匙所必需的材料。把阿拉基的圣甲虫交给我，我会将它制成钥匙的头部。',12340),
(5804,1,1,'你必须明白，$N——只有摧毁“召唤者”阿拉基的肉身才能拿到完成钥匙所必需的材料。把阿拉基的圣甲虫交给我，我会将它制成钥匙的头部。',12340),
(5805,1,0,'您好！很高兴见到您！$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品！',12340),
(5821,1,0,'为什么我要等那可恶的商队？$b$b<斯米德看起来若有所悟。>$b$b哦，对了，他们付钱。你看到他们了吗？',12340),
(5841,1,0,'您好！很高兴见到您！$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品！',12340),
(5842,1,0,'您好！很高兴见到您！$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品！',12340),
(5843,1,0,'您好！很高兴见到您！$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品！',12340),
(5844,1,0,'您好！很高兴见到您！$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品！',12340),
(5845,1,1,'我的信仰会指引你，$N。光明无界。',12340),
(5846,1,0,'',12340),
(5847,1,0,'您好！很高兴见到您！$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品！',12340),
(5848,6,6,'画，$N。你找到画了吗？',12340),
(5861,2,0,'我就知道会有这么一天的。',12340),
(5862,25,0,'你是从提尔之手来的援军吗？',12340),
(5863,1,1,'我很担心！请保重！',12340),
(5881,1,0,'你有来自马格兰的消息吗？',12340),
(5882,1,1,'只要你拿着塞纳里奥信标，你就能从那些堕落的野兽身上找到受污染的灵魂裂片，为了费伍德森林的未来，你一定要拿到那些裂片。我会对裂片进行研磨加工，将其制成塞纳里奥植物药膏。我们可以用这种药膏拯救那些奄奄一息的堕落植物。$b$b如果你能给我弄些裂片来，我就可以给你几份植物药膏。',12340),
(5883,1,0,'如果你随身带着塞纳里奥信标，那么你在采矿的时候就会看到那些污染了矿脉的硫酸盐。我可以对那些硫酸盐进行净化，然后把它们制成塞纳里奥植物药膏。你可以用这种药膏来拯救堕落的大自然。$b$b给我弄些受污染的硫酸盐来，我就可以给你几份药膏。',12340),
(5884,1,0,'训练有素的草药师可以用塞纳里奥信标探测到那些被污染的魔藤——这是费伍德森林被污染后所诞生的产物。我在这里进行了一些研究工作，现在我可以把魔藤转化为一种净化原料……然后就可以用它来制作我们所说的塞纳里奥植物药膏了。$b$b当你在费伍德森林里收集草药的时候，别忘了带着这个信标来寻找魔藤。给我弄些魔藤来，我就给你几份药膏作为交换。',12340),
(5885,1,0,'训练有素的剥皮匠可以用塞纳里奥信标从费伍德森林里的生物身上找到受污染的毛皮，我可以把这些皮制作成塞纳里奥植物药膏。$b$b当你在这里采集兽皮的时候，记得带上信标。给我弄些受污染的毛皮来，我就可以给你几份药膏。',12340),
(5886,1,0,'分解物品所得到的魔法精华中蕴藏着相当大的能量。我已经研究出一种方法，可以把炼金术所使用的原始精华材料转化为制作塞纳里奥植物药膏所需的材料。你不需要拿着塞纳里奥信标，只要是能够分解出次级虚空精华的物品都适用。$b$b我只需要一个次级虚空精华，作为交换，我可以给你一些塞纳里奥植物药膏。那些精华的能量很强大，所以即使很少的精华就能制作出不少的药膏了。',12340),
(5887,1,1,'只要你拿着塞纳里奥信标，你就能从那些堕落的野兽身上找到受污染的灵魂裂片，为了费伍德森林的未来，你一定要拿到那些裂片。我会对裂片进行研磨加工，将其制成塞纳里奥植物药膏。我们可以用这种药膏拯救那些奄奄一息的堕落植物。$b$b如果你能给我弄些裂片来，我就可以给你几份植物药膏。',12340),
(5888,1,0,'如果你随身带着塞纳里奥信标，那么你在采矿的时候就会看到那些污染了矿脉的硫酸盐。我可以对那些硫酸盐进行净化，然后把它们制成塞纳里奥植物药膏。你可以用这种药膏来拯救堕落的大自然。$B$B给我弄些受污染的硫酸盐来，我就可以给你几份药膏。',12340),
(5889,1,0,'训练有素的草药师可以用塞纳里奥信标探测到那些被污染的魔藤——这是费伍德森林被污染后所诞生的产物。我在这里进行了一些研究工作，现在我可以把魔藤转化为一种净化原料……然后就可以用它来制作我们所说的塞纳里奥植物药膏了。$b$b当你在费伍德森林里收集草药的时候，别忘了带着这个信标来寻找魔藤。给我弄些魔藤来，我就给你几份药膏作为交换。',12340),
(5890,1,0,'训练有素的剥皮匠可以用塞纳里奥信标从费伍德森林里的生物身上找到受污染的毛皮，我可以把这些皮制作成塞纳里奥植物药膏。$b$b当你在这里采集兽皮的时候，记得带上信标。给我弄些受污染的毛皮来，我就可以给你几份药膏。',12340),
(5891,1,0,'分解物品所得到的魔法精华中蕴藏着相当大的能量。我已经研究出一种方法，可以把炼金术所使用的原始精华材料转化为制作塞纳里奥植物药膏所需的材料。你不需要拿着塞纳里奥信标，只要是能够分解出次级虚空精华的物品都适用。$B$B我只需要一个次级虚空精华，作为交换，我可以给你一些塞纳里奥植物药膏。那些精华的能量很强大，所以即使很少的精华就能制作出不少的药膏了。',12340),
(5892,1,0,'你拿到补给品了吗，$N？我们的补给品一直都很缺乏！',12340),
(5893,1,0,'你去过冷齿矿洞了吗，$N？你拿到我要的补给品没有？',12340),
(5901,6,6,'你拿到白蚁了吗，$N？我确定像你这样聪明的$C肯定可以很轻松地完成这个任务。$B$B一旦你收集到了足够的白蚁，我们就能确保再也没有人可以使用那个伐木场了！',12340),
(5902,1,0,'你把木桶放在了木箱上，然后在旁边找了一根撬棍打开了它。',12340),
(5903,6,6,'你找到蚁丘了吗，$N？我听说病木林里到处都是这种巢穴。',12340),
(5904,1,0,'你把木桶放在了木箱上，然后在旁边找了一根撬棍打开了它。',12340),
