(5929,1,0,'只有当巨熊之灵让你回来的时候，你才可以回来。除非获得了它的祝福，否则你的训练是无法继续的。',12340),
(5930,1,0,'只有当巨熊之灵让你回来的时候，你才可以回来。除非获得了它的祝福，否则你的训练是无法继续的。',12340),
(5931,1,0,'',12340),
(5932,1,0,'',12340),
(5941,6,0,'我一直和你的朋友卡林保持联系。他对自己的村庄遭受的厄运感到极度痛苦，但是他对你评价很高并知道你可以把事情搞定。$B$B哦，但是好像我有点离题了……$N，你拿到我需要的圣物了吗？',12340),
(5942,0,0,'这只箱子非常破旧，表面满是污迹。',12340),
(5943,1,0,'你要知道，如果那个车队没有到达目的地的话，那我就完了！你不是带来厄运的使者，是不是？$b$b<斯米德擦了一下额头。>$b$b感谢贪婪女神！',12340),
(5944,1,0,'<提里奥恢复了镇静。>',12340),
(5961,1,0,'<纳萨诺斯咆哮着。>',12340),
(5981,1,1,'你必须持续的证明你的忠诚，$N。',12340),
(6001,1,0,'当你面对挑战的时候，你对身心之力的理解就会更加充分。在你领会那种力量的精髓之前，我无法帮你做什么。',12340),
(6002,1,0,'当你面对挑战的时候，你对身心之力的理解就会更加充分。在你领会那种力量的精髓之前，我无法帮你做什么。',52237),
(6004,1,6,'进展如何，$N？它们比你想象得更加强大吗？我希望不是。如果换成是我的话，还不知要费多大的劲呢。',12340),
(6021,5,0,'你找到他的藏身之处了吗，$N？你有没有干掉塞达尔？',12340),
(6022,6,6,'你在哭吗？如果这个任务对你来说太“艰难”了，我的“英雄”，那么我建议你回到黑暗女王那里，向她哭诉你在我这里遇到的遭遇。$b$b现在从我的视野中消失！',12340),
(6023,1,6,'你找到他们了吗，$N？如果你能干掉他们两个，我就可以进入壁炉谷好好侦察一番了。没有你的帮助，我是根本做不到这些的。请你一定要帮我找到莱德雷和杜尔根。',12340),
(6024,0,0,'这只箱子被牢牢地锁着。',12340),
(6025,1,1,'这是个危险的任务，$n。我羡慕你的勇气。',12340),
(6026,1,1,'相信老烟鬼吧，$r。报酬值得的。这些银色黎明的人在付钱上可不含糊。\n',12340),
(6027,1,1,'啊，$N！很高兴再见到你。你拿到上古之书了吗？',12340),
(6028,66,0,'你好，$N。我代表银色黎明，在你逗留寒风营地期间为你提供安全与庇护。我或许还有些活儿给你……',12340),
(6029,66,0,'你好，$C。以银色黎明的名义，我在亡灵壁垒这里保护你的安全。我还会为你提供一个机会，让你为了值得争取的东西而战斗！',12340),
(6030,2,0,'愿圣光照亮你前行的道路，$C。是什么在这黑暗而动荡的时代中将你带到这个希望之地来的？',12340),
(6031,0,0,'你有符文布吗？我们需要符文布来制作很多东西！',12340),
(6032,0,0,'你带来月布了吗，$N？',12340),
(6041,1,1,'我这里还库存了一些材料，可以制造更多含有特殊混合物的炸药。如果你需要的话，告诉烟鬼就行了。',12340),
(6042,1,1,'情况也许会更糟，我应该让你去收集蝙蝠粪便的。$B$B<纳萨诺斯注视着你。>$B$B嗯……嘿！等等，你要去哪儿？',12340),
(6061,1,1,'练习你的技能，$N。去驯服成年平原陆行鸟。',12340),
(6062,1,1,'祝你好运，年轻的$C。',12340),
(6063,1,0,'你会学有所成，$N，总有一天你会成为一位伟大的$C。',12340),
(6064,1,1,'别担心，姑娘！在最终选定之前，你可以先试几样。',12340),
