(6082,1,1,'你驯服蝎子了吗？',12340),
(6083,1,1,'你需要练习以掌握有效控制宠物的方法。你驯服海浪蟹了吗？',12340),
(6084,1,6,'你认为雪豹怎么样，$N？',12340),
(6085,1,6,'你驯服冰爪熊了吗？',12340),
(6086,1,0,'',12340),
(6087,6,6,'你找到草原捕食者了没有？',12340),
(6088,1,1,'你很快就会准备就绪，$N。',12340),
(6089,1,0,'',12340),
(6101,1,0,'理解自然与自我之间的平衡，是每个$R的生活方式。',12340),
(6102,1,0,'我为你的成功而自豪，$N。你完成我给你的任务了吗？',12340),
(6103,1,0,'',12340),
(6121,1,0,'',12340),
(6122,1,0,'你是月光林地的塞纳里奥议会派来的？太好了！那些中毒的鹿危在旦夕，我们很高兴能够获得你的帮助。$B$B你拿到德迪利特·星焰所说的水样了吗？他告诉过我说你会拿来一份水样，让我们一起找出应对的方法。',12340),
(6123,1,0,'你拿到我制作解药所需的材料了吗？鹿群无法自己恢复健康，所以我们一定要帮助它们！',12340),
(6124,1,0,'你完成了奥伯丁的奥兰达利亚·夜歌给你的任务了吗？不要倦怠！',12340),
(6125,1,0,'',12340),
(6126,1,0,'',12340),
(6127,1,0,'你是月光林地的塞纳里奥议会派来的？太好了！我们正在致力于救治那些中毒的蹬羚，很高兴能够获得你的帮助。$B$B你拿到德迪利特·星焰所说的水样了吗？他告诉过我说你会拿来一份水样，让我们一起找出应对的方法。',12340),
(6128,1,0,'你拿到我制作解药所需的材料了吗？瞪羚无法自己恢复健康，所以我们一定要帮助它们！',12340),
(6129,1,0,'你完成了十字路口的图加·符文图腾给你的任务了吗？不要倦怠！',12340),
(6130,1,0,'',12340),
(6131,1,0,'',12340),
(6132,1,0,'你有没有看到我妹妹梅丽萨？她总是到处乱跑，到处给我惹麻烦。',12340),
(6133,0,0,'不要让我空等，$C。',12340),
(6134,0,0,'我的幽灵电浆在哪里，$N？',12340),
(6135,1,1,'我不建议你独自迎接这次挑战，$c。',12340),
(6136,6,6,'最近我有没有告诉你，我恨你？',12340),
(6141,1,0,'',12340),
(6142,1,0,'我等不及要带些新鲜的软壳蚌肉去钓鱼了，你弄到我要的十块肉了吗？',12340),
(6143,1,0,'我还能听到我的手下在被纳迦屠杀时哭喊求救的声音。如果不是因为我的膝盖坏掉了，我肯定会跟你一起去，帮你杀死那些混蛋纳迦！$B$B你通常都可以在水下的珊瑚礁深处找到他们……潜伏着……策划着阴谋……',12340),
(6144,1,0,'你就是纳萨诺斯最能干的特工？',12340),
(6145,1,0,'如果你成功了，那你也许可以就此赢得我的尊敬，$C。',12340),
(6146,5,0,'这是不可接受的，士兵！',12340),
(6147,1,0,'什么？',12340),
(6148,1,0,'怎么样了，$N？',12340),
(6161,1,0,'这个箱子被牢牢地锁着。',12340),
(6162,6,6,'你拿到那野兽的爪子了吗，$N？它会为它的罪行付出代价的。我不管它是堕落了还是仅仅因为生活在这片阴暗的森林中而感到愤怒。任何熊怪都不能在对我的家庭犯下这种恶行之后逍遥法外！',12340),
(6163,1,1,'在希尔瓦娜斯让我获得自由之后的这几个月来，我一直都在这片废土上狩猎那个混蛋，它居然躲进了斯坦索姆……',12340),
(6164,0,0,'你找到我的收据册了吗？我还等着重新开业哪！',12340),
(6181,6,0,'你看起来是要急着赶路。嗯，你来对地方了！',12340),
(6182,1,0,'你是乌瑞恩派来的？',12340),
(6183,1,0,'',12340),
(6184,1,0,'',12340),
(6185,6,0,'你发现……发现什么了吗？',12340),
(6186,1,0,'',12340),
(6187,1,0,'<瓦里安·乌瑞恩国王陷入了沉思。>',12340),
(6221,1,0,'一旦你获得了木喉部族的信任，作为对你的忠诚的回报，也许我们可以帮你做点什么。',12340),
(6241,1,0,'',12340),
(6261,1,0,'你额头上是汗吗，小子？你跑得太多了。下次骑狮鹫吧！',12340),
(6281,6,0,'你是在到处旅行吗？有没有去过什么有趣的地方？',12340),
(6282,1,1,'不要对焦炭谷掉以轻心，许多邪恶的生物都盘踞在那里。保持斗志，$N，你将帮助我们消除这些威胁。现在出发去痛击敌人吧——让我们的后代永远都不知道这些邪恶曾经存在过。',12340),
(6283,1,1,'血怒撕裂者是个肮脏的生物！你可以在焦炭谷西部的山岭中找到她。$b$b只要干掉了她，血怒鹰身人就会乱作一团……然后我们就可以把它们完全消灭掉！',12340),
(6284,1,1,'贝瑟莱斯是个残忍的猎食者……我晚上都不敢独自在蛛网小径行走。每当那个时候，她和她的孩子们就会潜伏在黑暗中，准备猎捕无辜的旅人。我也曾经落入她的魔爪，幸运的是我活着逃了出来。我会为干掉这头怪兽而付出一切的。',12340),
(6285,6,0,'你从暴风城回来了？奥斯瑞克的护甲拿到了没有？',12340),
(6301,1,1,'战争带来的持续破坏，还有那些想要从木材贸易中牟利的商人都深深地刺痛了我。我们所能做的就是尽量治愈大自然，种植盖亚之种，用新生的森林来抚平大地的创伤。你弄到我要的盖亚之种了吗，$C？',12340),
(6321,6,0,'你似乎是有公务在身……',12340),
(6322,1,0,'如果你非得进行长途跋涉的话，最好选择乘坐蝙蝠的方式。',12340),
(6323,6,0,'我的武器保养得无懈可击。它们毫无瑕疵，随时都可使用。',12340),
(6324,6,0,'$N，你回来了。你从幽暗城带来我们所需的物资了吗？',12340),
(6341,1,0,'我能帮你什么忙吗？你是来搭乘角鹰兽的吗？',12340),
(6342,1,0,'你是从泰达希尔来的？告诉我，那里的渔业近况如何？',12340),
(6343,1,0,'$N，你从奥伯丁必来了？你和赖尔德谈过了吗？',12340),
(6344,1,0,'',12340),
(6361,1,0,'你是来租用双足飞龙的吗？你需要运送什么货物吗？',12340),
(6362,1,0,'你肩膀上有来自贫瘠之地的灰尘。你同我的朋友加翰见过面吗？',12340),
(6363,1,0,'你好，$C。我能为你做什么吗？',12340),
(6364,1,0,'$N，你是从雷霆崖回来的吗？你把皮革送到安哈努那里了吗？',12340),
(6365,6,0,'你需要快速赶到某个地方去？找我就对了！',12340),
(6381,1,1,'你所种下的种子将使得森林更加强大，使它可以抵御那些足够杀死所有新生命的堕落能量。它们将不断生长，防止死亡和破坏继续在这块土地上蔓延。$b$b你种下所有的盖亚之种了吗？',12340),
(6382,1,0,'',12340),
(6383,1,0,'',12340),
(6384,6,0,'这味儿真好闻！你身上带着新鲜的肉，对吗？',12340),
(6385,6,0,'你需要租用双足飞龙吗？',12340),
(6386,6,0,'你是从奥格瑞玛回来的吗？格雷什卡喜欢我送给她的肉吗？',12340),
(6387,0,0,'你这么快就办完了在塞尔萨玛的事儿吗？现在你是要转至其它座城市吗？',12340),
(6388,0,0,'似乎你是要外出旅行，需要乘坐狮鹫吗？',12340),
(6389,6,0,'你完成任务了吗，$N？你把白蚁放出来了吗？愿圣光保佑我们，将血色十字军逐出伐木场和壁炉谷，我们不能让他们控制任何一处地方。血色十字军只不过是利用上一次战争的牺牲者来达到自己疯狂的目标而已，因此你应该像杀死那些发疯的动物一样杀死他们！',12340),
(6390,6,6,'你完成任务了吗，$N？你把伐木场里的白蚁放出来了吗？我的系列成员失去了工作和生命，这糟糕透了，但是看着我儿时成长的地方被那些令人厌恶的所谓圣徒占据着……啊！',12340),
(6391,6,0,'我能为你做什么，先生？',12340),
(6392,6,0,'啊，$n。你已经从铁炉堡回来了吗？',12340),
(6393,1,0,'海潮议会开始变得有些不耐烦了。他们试图结束这场持续数年、波及各个位面的战争。我的同胞们迫切地希望听到战胜那些讨厌的火元素的消息。你拿到我要的东西了吗？',12340),
(6394,0,0,'你进入燃刃集会所了吗，$N？你找到我的镐了吗？',12340),
(6395,1,1,'我们尊重死者，$N。这是我们与天灾军团的不同之处……',12340),
(6401,1,0,'你把这个好消息告诉塔姆拉·荒原了吗？',12340),
(6402,1,0,'',12340),
(6403,1,0,'我……我……我没有力量了。',12340),
(6421,1,1,'你在滚岩峡谷有什么发现吗？我记得一些与共鸣水晶有关的传说……但是我没法亲自去那儿。或许当我知道洞穴底部都有些什么东西的时候就能洞察他们的意图了。',12340),
(6441,0,0,'我希望你能快点找到这些角，$N。我马上就要回棘齿城了！',12340),
(6442,0,0,'纳迦的数量正在激增，$n。请赶快完成我交给你的任务。',12340),
(6461,1,6,'嘿，你杀死那些浑身长毛、性格暴躁的畜生了吗？我在石爪山什么都不怕，但是晚上我可不敢在附近闲逛……你该明白我的意思吧！$b$b只有我确信自己不会成为它们的盘中餐，我才会感到安全。$b$b祝你好运，$c！',12340),
(6462,14,14,'你找到符咒了吗，$N？一想到那些神圣的符咒落在熊怪手中，我就气不打一处来！',12340),
(6481,1,1,'如果我们不能尽快解决威胁的话，也许我们会丧失整个石爪山地区。任何魔法都无法与土灵的力量抗衡。当高戈罗克清醒时，他的力量将因长期沉睡而减弱，你必须利用这个机会……去吧，$N！',12340),
(6482,1,6,'你看见我的兄弟卢尔了吗？他几天前进入了森林，一直都没有回来……',12340),
(6501,1,0,'我感到了你身上散发出的邪恶气息，$R。是什么让你被这种气息笼罩？',12340),
(6502,1,0,'时间的流动不会停止或滞后，$R。我的生命是永恒的，但是你的却不是。不要浪费时间了……',12340),
(6503,1,0,'我等待着你杀死先驱者的消息，$N。',12340),
(6504,0,0,'我希望你尽快把纸张找回来，$N！我必须马上回去工作！',12340),
(6521,1,0,'你找到大使了吗，$N？他死了吗？$B$B我们承受不起让天灾军团在卡利姆多建立据点的威胁。现在我们陷入了两面作战的境地，这足以说明他们已经对我们构成了足够的威胁。$B$B你告诉我的事情中唯一让我感到乐观的事情就是那个野猪人的首领看起来还未被腐蚀。她肯定知道天灾军团可能会带来巨大的力量，但如果她同意接受他们的条件，贫瘠之地并不会真正成为她的地盘。',12340),
(6522,1,0,'你有什么事，$N？如果你不断来烦我，那你一定是有什么你以为很重要的事情。',12340),
(6523,1,0,NULL,12340),
(6541,1,0,NULL,12340),
(6542,1,0,'又一个精神抖擞的新兵，不错！',12340),
(6543,0,0,'快点，$N。我们必须拿到他们的报告，事关紧急。',12340),
(6544,1,0,'托雷克被派去执行突袭银翼哨站的任务了，他取得胜利了吗？',12340),
(6545,0,0,'那么，你是来给我传达上面的命令的？看见你这样体格健壮、意志坚定的新兵，我总是会感到很高兴。$B$B要是你希望继续在这里待下去的话，最好尽快成长起来。纳迦的威胁正在日益增长，$N。自从我到这儿之后，就开始着手研究对策，并在这个前哨站里抵挡了他们的多次进攻。$B$B但是如果你也想要投入到对敌作战中，就去跟这里的其它人也谈谈吧。',12340),
(6546,0,0,'这条路上危机四伏，$N。你最好在整个旅途中都牢记这一点。联盟的威胁近在咫尺。$B$B我们已经陷入了四面受敌的困境，灰谷东部的萨特是一种可怕的生物，而纳迦也已经占据了艾萨拉的大片区域。$B$B我们的军队数量始终维持在较高的水准，这很好，随时准备应付我们的敌人吧，$N。',12340),
(6547,0,0,'保持警惕，$R。精灵总是潜伏在黑暗中……$B$B我们必须继续监视敌人。我们在努力地控制这片土地，而精灵也在寻找机会从我们手中夺走它。$B$B我想你是来传达卡德拉克下达给我的新命令的吧？',12340),
(6548,1,6,'你杀死他们了吗？',12340),
(6561,1,0,'愿大地之母与你同在，$N。$B$B世界和平是我们的目标。大地之母对整个世界有一个宏伟的计划，我们都在其中扮演了某种角色。',12340),
(6562,1,0,'',12340),
(6563,6,6,'搜寻水晶的工作进行得如何，$N？你有见到纳迦在采集它们吗？祖先保佑，希望我们能找到纳迦收集这些东西的原因。',12340),
(6564,6,0,'什么事，$N？你需要什么吗？对于纳迦正在收集的那些水晶，我还知之甚少。',12340),
(6565,1,5,'你找到他了没有，$N？我们必须阻止洛古斯！',12340),
(6566,1,0,'耐心点，$N。注意听！',12340),
(6567,1,0,'',12340),
(6568,1,0,'在洛丹伦这一带我可不常看到部落的人。你给米兰达带来了什么？',12340),
(6569,11,11,'那些眼睛是制作幻影所必需的重要材料，$N。$B$B<米兰达指了指一个标着“血色十字军”字样的满是眼球的袋子，哈哈大笑着。>',12340),
(6570,1,0,'你是来接受考验的吗？',12340),
(6571,1,1,'希望你能成功运送这批物资！如果我不快点运送这些货物我就会有大麻烦了！',12340),
(6581,1,0,'战歌锯刃！当然，我这儿就有。$B$B……但是你要如何回报我呢？要知道，你可不能白拿！我的时间可不能白费！$B$B我真正想要的是一把好枪，我要在旅途中随身携带它。女孩子要学会自我保护，你明白吗？我想，精通工程学的人可以毫不费力地制作出一把我喜欢的枪来。$B$B如果你能给我一把威力强大的火枪，我就给你这些锯刃。这笔交易如何？',12340),
(6582,0,0,'<艾博斯塔夫发出嘶嘶声。>',12340),
(6583,15,15,'在你浸浴敌人的鲜血前不要回来，让它们感受死亡和痛苦吧。',12340),
(6584,1,1,'小家伙，你必须知道，时间紧迫……',12340),
(6585,0,0,'改变……我感觉到了你的改变，小家伙。通过这个试炼，等着你的就是庆典了。',12340),
(6601,1,0,'别慌，$N！',12340),
(6602,1,1,'我想不用我告诉你，德拉基萨特可不是能轻视的。$B$B就让那数千条死在他手里的性命来说话吧。',12340),
(6603,1,0,'',12340),
(6604,1,0,'',12340),
(6605,1,0,'',12340),
(6606,1,0,'',12340),
(6607,6,6,'有东西上钩了吗？',12340),
(6608,1,0,'我不太常有访客……让我算算上次有人来找我是那一年的事情了……',12340),
(6609,1,0,'我猜你是老矮人的朋友，……是不是？',12340),
(6610,5,5,'我的瘾头会要了我的命！快点，$N——趁我还没动用自己的存货。',12340),
(6611,1,0,'<迪尔格正在尝试吃下一只皮鞋。>',12340),
(6612,1,0,'<迪尔格正在尝试吃下一只皮鞋。>',12340),
(6621,6,6,'你击败了穆戈特酋长了吗，$N？你拿回他的图腾了吗？',12340),
(6622,1,0,'干得太出色了，医生。实在是太出色了。',12340),
(6623,1,0,'你一定是新来的吧。很高兴你来到这里，医生。',12340),
(6624,1,0,'干得太出色了，医生。实在是太出色了。',12340),
(6625,1,0,'你一定是新来的吧。很高兴你来到这里，医生。',12340),
(6626,1,0,'狩猎行动进行得怎么样了，$N？看到这么一小批家伙，我就已经不再怀疑天灾军团是这个世界上最大的威胁了。',12340),
(6627,1,1,'生命中充满了疑问，$C。你永远无法全部回答它们，但是随着时间的流逝和学习的深入，也许你可以获得更多的知识。',12340),
(6628,1,1,'我觉得，如果你想要在这个世界上生存的话，就需要明白一个道理：你知道的越多，你能看到的就越多。$b$b如果你不断学习，不断观察，那么你就可以看到这个世界上的许多其它$r看不见的东西。',12340),
(6629,1,6,'你把格鲁迪格·暗云和他的手下都干掉了吗？',12340),
(6641,1,0,'',12340),
(6642,1,0,'黑铁矿蕴藏在黑石山脉的深处，对于兄弟会来说，它是很有价值的商品。拉格纳罗斯神圣的护甲和装备都需要黑铁。$B$B你每给我十块黑铁矿石，兄弟会对你的好感就会增加。',12340),
(6643,1,0,'在熔火之心中人人命运难测，死亡说到就到，惩罚来得毫不留情。$B$B兄弟会里面有很多人为了搜寻炽热之核而丧失生命。$B$B给我一个炽热之核，兄弟会对你的好感就会增加。',12340),
(6644,1,0,'你和瑟银兄弟会同心同德，$r。因此洛克索斯才会被授权与你进行交易。$B$B拿一块熔岩之核来，你就会得到兄弟会的好感。',12340),
(6645,1,0,'许多神圣的配方需要拉格纳罗斯心爱的宠物皮毛。$B$B拿二块来，将可以获得兄弟会对你的好感。从熔火之心的熔核犬身上割下的熔核犬皮。',12340),
(6646,1,0,'火焰之王的眼泪是一种非常稀有的珍宝。$B$B给我一个山脉之血，你就可以获得兄弟会的好感。',12340),
(6661,5,5,'呀啊……甲板仔，你怎么这么久？',12340),
(6662,0,0,'<尼普希把他的食指伸进纸箱的换气孔。>$b$b生气勃勃，活力十足……而且时间刚刚好！',12340),
(6681,1,0,'你遇到密尔顿了吗？$B$B<法拉德笑了起来。>',12340),
(6701,1,0,'我们与辛迪加交战数年，他们战斗技艺极差，却屡屡以数量取胜。单凭砍杀是不可能对他们的数量造成明显影响的！$B$B不过我们发现，要削减辛迪加的人数，最好的办法是窃取他们的纹章。谁丢失了纹章，他们的组织就会“处理”谁。$B$B去翻他们的口袋，把纹章交给我或是其它的守卫。$B$B你就从南边的敦霍尔德城堡开始吧。',12340),
(6721,1,0,'',12340),
(6722,1,0,'',12340),
(6741,1,0,'我需要更多护甲碎片，$N！你有吗？',12340),
(6761,1,0,NULL,12340),
(6762,1,0,NULL,12340),
(6781,1,0,'$N，我们需要更多护甲碎片来补给部队！',12340),
(6801,1,0,'我来自雷霆崖，$r。凯恩亲自安排我在这些艰难时刻协助霜狼氏族。$b$b但别再多浪费时间了。你必须击杀我们的敌人，把他们的血带给我。一旦聚集了足够的血，召唤仪式便可开始。$b$b当元素领主被释放到风暴之矛军中，胜利必将到来。',12340),
(6804,0,0,'你拿到那些护腕了吗？',12340),
(6805,1,0,'胆怯不是我们所尊崇的品德，$c。去希利苏斯证明自己的勇敢吧。',12340),
(6821,1,0,'你拿到眼珠了吗，$C？你有能力杀入黑石塔吗？',12340),
(6822,1,0,'胜利在熔火之心向你招手，$N。',12340),
(6823,1,0,'',12340),
(6824,1,0,'你打败鲁西弗隆和其它的家伙了吗，$N？你拿到他们的手了吗？',12340),
(6825,1,0,'我们必须准备好新的战骑队伍，$r！我的骑手们即将对中央战场发动突击；但首先，我得吊起他们的胃口——让他们为冲锋做好准备。$b$b我需要足够喂饱一支队伍的风暴之矛士兵血肉！几百磅！你肯定能办到，对吧？快去吧！',12340),
(6826,1,0,'你工作得很努力，$n，但是我们只是刚刚开始而已！$b$b我的驭风者部队要在吃饱之后才能对敌人发起突袭！$b$b我的部队在我们的空军中实力排名第二，它们将对敌人最强的部队发起进攻。因此它们也需要优质的食物，从雷矛士官那里抢夺他们随身携带的生肉吧。$b$b快点出发，勇士！',12340),
(6827,1,0,'我曾经被终日锁在一个矮小的洞穴里，我要报仇！$b$b我们必须仔细计划一下。$b$b首先，我的驭风者必须吃到最优质的食物，才能储备精力以待发起攻击。从雷矛指挥官那里抢一些生肉来喂养它们。不幸的是，那些可恶的家伙都躲在最后方！显然，你面临的是一个艰巨的任务。',12340),
(6844,1,0,'嘿，你好！嗯……$b$b老实对你说，朋友……你的体味有些夸张。也许有人说你浑身都散发着恶臭。我不会对你的种族进行抨击，我只是说说……下一次你离开战场的时候最好清洗一下，这会使你给其它人留下的第一印象大大改善！$b$b总之……我能为你做什么？',12340),
(6845,1,0,NULL,12340),
(6846,1,0,'我的军队已经整装待发，准备攻击。只要诺雷格·雷矛中尉一声令下，我们就会发起冲锋！',12340),
(6847,1,0,'全视之眼，你这个蠢货。你拿到全视之眼了吗？',12340),
(6848,1,0,'全视之眼，你这个蠢货。你拿到全视之眼了吗？',12340),
(6861,1,0,'“像山那么大的一堆”是个地精工程学的术语……',12340),
(6862,1,0,'“像山那么大的一堆”是个地精工程学的术语……',12340),
(6881,1,0,'霜狼氏族被一种堕落的元素能量保护着。如果我们不加以注意的话，他们的萨满必然会利用这种力量来毁掉我们。$b$b这种能量已经不是议会可以控制的了！我们必须找到伊弗斯，寻求他的帮助。$b$b霜狼氏族的战士身上带着一种名叫暴风水晶的符咒，我们可以用这些符咒来召唤伊弗斯。快去拿来那些水晶吧，$n！',12340),
(6901,1,0,'我的战士渴望战斗！我所需要的就是进攻命令……',12340),
(6921,6,6,'你找到深渊之核了吗？没有它的话，我们就无法得知暮光之锤究竟在那里做什么。',12340),
(6922,1,0,'啊，又见面了，$N。我正在像往常一样观察海洋的波涛。什么风把你吹到这里来了？',12340),
(6941,1,0,'你必须去对付守卫前线的部落精英士兵！我现在命令你去削弱那些绿皮蛮子的力量，把他们的中尉和军团士兵的勋章给我拿来。当我拿到足够的勋章时，我会命令开始对他们进行空中打击的。',12340),
(6942,1,0,'我的狮鹫应该在前线作战，但是在那里的敌人被削弱之前，它们是无法发动攻击的。$b$b部落的战士胸前挂着代表荣誉的勋章勇猛冲锋，而你要做的就是从他们腐烂的尸体上把勋章拿下来，并把它们交给我。$b$b只要敌人在前线的力量受到足够的打击，我就会发出命令进行空袭！我们将从空中给敌人造成致命的创伤！',12340),
(6943,1,0,'它们的士气很低，战士。自从我们上次对部落的空中打击失败之后，它们就拒绝再次飞行！你必须鼓舞它们的士气。$B$B回到战场并攻击部落的核心力量，杀死他们的指挥官和卫兵。尽可能带回更多的勋章！我向你保证，当我的狮鹫看到这些战利品并嗅到敌人的鲜血时，它们就会再次起飞！现在就出发吧！',12340),
(6961,1,0,'',12340),
(6962,1,0,'一天到晚给别人礼物让我自己也想要礼物了。嗯……我要姜饼和牛奶……',12340),
(6963,1,0,'',12340),
(6964,1,0,'',12340),
(6981,2,0,'你好啊，风尘仆仆的$R。我可以为你做些什么吗？',12340),
(6982,1,0,'你去过部落领地中的冷齿矿洞了吗，$N？你有没有抢到他们的补给品？',12340),
(6983,5,0,'$N——我们冬幕节的礼物如果没有那些货物的话就准备不好了！格拉库就没有机会和这些好孩子们一起分享他的美味肉派了……',12340),
(6984,1,0,'',12340),
(6985,1,0,'你去过深铁矿洞了吗，$N？你有没有拿到那里的补给品？',12340),
(7001,1,0,'没有你的帮助，霜狼氏族的狼骑兵就无法获得足够的坐骑来进行作战。你干得很好！',12340),
(7002,1,0,'在我们的一些战士帮助兽栏管理员捕捉巨狼的同时，其它人还需要去找一些将它们变成坐骑所必需的东西，比如缰绳和坐鞍。$B$B你必须去猎捕这个地区的山羊，也就是那些与雷矛骑兵的坐骑很相似的山羊！$B$B杀了它们，把它们的皮交给我。只要收集到足够多的羊皮，我们就可以开始为骑手们制作坐具了。霜狼氏族的狼骑兵很快就将再次驰骋在战场上！',0),
(7003,6,6,'微缩残渣，我可以确信地告诉你，它是工程学中非常重要的一种材料！好吧，它可以确保压缩器不会发生诸如爆炸之类的让人感到不爽的故障。$B$B哦，我说的当然不是给你的那一台。当然不是！',12340),
(7021,1,0,NULL,12340),
(7022,1,0,NULL,12340),
(7023,1,0,NULL,12340),
(7024,1,0,NULL,12340),
(7025,1,0,'所有这些关于礼物的谈话都让我十分向往。嗯~~~~~姜饼与牛奶……',12340),
(7026,1,0,'没有鞍具，雷矛卫队就无法重新投入到战斗中！我们必须为坐骑配上鞍具，这样我们才不会像野蛮人一样骑着一头光溜溜的山羊。$B$B我们可以简单地干掉基地周围的山羊来获得皮革，但是那样做是非常愚蠢的。因为我们还要把那些山羊驯化成坐骑哪！$B$B你必须去攻击敌人的基地，杀死他们的霜狼坐骑，然后拿回他们的皮。把它们的皮交给我，这样我就可以帮我们的骑兵制作鞍具了。出发吧！',0),
(7027,1,0,'没有你的帮助，雷矛卫队的山羊骑兵就无法获得足够的坐骑来进行作战。你干得很好！',12340),
(7028,25,25,'不要问问题！$B$B我给你的指示是非常明确的。',12340),
(7029,1,1,'如果你可以治疗那些植物，它们就可以再次生长了。我们必须尽力而为，$N……',12340),
(7041,1,1,'如果你可以治疗那些植物，它们就可以再次生长了。我们必须尽力而为，$N……',12340),
(7042,1,0,'',12340),
(7043,1,0,'$N——我们冬幕节的礼物如果没有那些货物的话就准备不好了！格拉库就没有机会和这些好孩子们一起分享他的美味肉派了……',12340),
(7044,1,0,'我从看似永无止境的梦魇中醒来……',12340),
(7045,1,0,'',12340),
(7046,1,0,'如果你希望重新启动仪式，请放弃我们的这一次尝试，然后再和我谈谈。',12340),
(7061,1,0,'我敢打赌莫高雷以及谦卑的雷霆崖都非常欢迎你，朋友。我对选择去关注王国，人民以及其传说的人一直都非常的感兴趣，这就是你站在我面前的原因吗？',12340),
(7062,1,0,'',12340),
(7063,1,0,'我敢打赌铁炉堡王国很欢迎你，朋友。我对选择去关注王国，人民与及其传说的人一直都非常的感兴趣，这是你站在我面前的原因吗？',12340),
(7064,1,0,'我原本想要自己去进行这场战斗，但是我们没有选择——我们需要更加强大的帮手，而艾泽拉斯的各个种族早已证明，只要他们团结起来就可以击败非常可怕的敌人。所以我寻求你的帮助。$B$B我希望这已经足够了。$B$B作为雷姆洛斯的兄弟，札尔塔给这个世界带来了无尽的痛苦，并最终导致了他自己的死亡。我只希望我们不会再造成更多的死亡。',12340),
(7065,1,0,'我原本想要自己去进行这场战斗，但是我们没有选择——我们需要更加强大的帮手，而艾泽拉斯的各个种族早已证明，只要他们团结起来就可以击败非常可怕的敌人。所以我寻求你的帮助。$B$B我希望这已经足够了。$B$B作为雷姆洛斯的兄弟，札尔塔给这个世界带来了无尽的痛苦，并最终导致了他自己的死亡。这对我们来说是很有报警意义的。',12340),
(7066,1,0,'你身上有堕落的气味，$N……最近一段时间到这里来的许多旅行者都是这样。但是你身上的有所不同。你来这里是有什么事情要告诉我的吗？你身上有一种让我感觉非常熟悉的气息，但是我不知道那是什么。$B$B请你告诉我，你为什么要来找我？',12340),
(7067,0,0,'你考虑得怎么样了，$N？你能帮助我吗？你愿意进入那块圣地并帮我重建一个伟大的半人马部族吗？',12340),
(7068,0,0,'你找到水晶了吗？强大的仪式，惊人的法术——那些裂影碎片可能对于各种魔法都有极大的帮助。',12340),
(7070,6,6,'你去过玛拉顿了吗？我知道那是很危险的，但是如果你成功了，那一切努力都是值得的。',12340),
(7081,1,5,'$N，你还没有占领一座墓地。当你完成任务之后再回到我这里来！',12340),
(7082,1,0,'为联盟占领一座墓地！',12340),
(7101,1,0,'你还没有攻陷任何一座哨塔，$N！你是不是在等着别人来夺取属于你的荣耀？',12340),
(7102,1,5,'你还没有攻陷任何一座哨塔，$N！你在等什么？',12340),
(7121,1,0,NULL,12340),
(7122,1,5,'你还没有占领一座矿洞，$N！$B$B只有控制了矿洞，我们才能方便地采集矿石和获取补给。',12340),
(7123,1,0,NULL,12340),
(7124,1,0,'你还没有占领一座矿洞，$N！找到一个还未被我们控制的矿洞，然后击败里面的首领！',12340),
(7141,1,6,'你拿到地图了吗，$N？那些地图上可能标明了更多神器的位置！',12340),
(7142,1,0,'',12340),
(7161,1,0,'醒醒！醒醒，$N！这不是做梦。你已经进入了战场中央！',12340),
(7162,5,5,'小心那个地区的鹰身人，$C。它们会毫不留情地割破你的喉咙！',12340),
(7163,1,0,'',12340),
(7164,1,0,'',12340),
(7165,1,0,'如此多的勇士献出了生命，鲜血染红了整个战场。然而，你活下来了……你还坚定地站在这里。你带领我们的部队取得了无数胜利，你做出了杰出的贡献，这为你赢得了更高的声望和军阶。$B$B这就是你的新徽记。',12340),
(7166,1,0,'在我的面前站着的是联盟所尊崇的英雄。$B$B<哈格丁中尉向你敬礼。>$B$B很少人能够在雷矛卫队赢得这样的称号。我看到敌人向你蜂拥而来，旋即全部倒下。$B$B你踏入战场，就成了我们部队的明灯！$B$B这是你的新徽记。',12340),
(7167,1,0,'',12340),
(7168,1,1,'许多人都没有活到摆脱平庸的那一天。你已经证明了自己是一个勇士的楷模，$c。现在是提升你的军阶的时候了。$B$B这是你的新徽记。',12340),
(7169,5,5,'整个基地中都在传颂你在征战平原上英勇杀敌的事迹！你对我们的敌人造成了沉重的打击，把他们杀得四散逃窜！为此，你在雷矛卫队中的军阶获得了提升。$B$B这就是你的新徽记。',12340),
(7170,6,6,'我必须知道，$n。当你直视敌人的眼睛时，你看到恐惧了吗？他们现在会在你面前畏缩吗？他们必须明白自己已被击败！$B$B你已赢得卫队的敬意。出示你的徽记！',12340),
(7171,66,66,'在我的面前站着的是联盟所尊崇的英雄。$B$B<哈格丁中尉向你敬礼。>$B$B很少人能够在雷矛卫队赢得这样的称号。我看到敌人向你蜂拥而来，旋即全部倒下。$B$B你踏入战场，就成了我们部队的明灯！$B$B这是你的新徽记。',12340),
(7172,5,5,'范达尔·雷矛赞美着你的伟业，东部王国到处都在传颂你的事迹。国王很高兴——你为我们联盟做出的贡献让他感到非常高兴。$B$B你将统御我们的部队。$B$B这就是你的新徽记，指挥官$n。$B$B<哈格丁中尉向你致敬。>',12340),
(7181,1,0,'小心一点，士兵。雷矛卫队也在猎捕科尔拉克。',12340),
(7201,5,5,'<搓揉着她的双手。>$B$B给我看看！',12340),
(7202,1,0,'小心一点，士兵。霜狼氏族也在猎捕科尔拉克。',12340),
(7223,1,0,'你带回护甲碎块了吗，$N？',12340),
(7224,1,0,'收集工作进行得怎么样，$N。你有没有可以给我的护甲碎块？',12340),
(7241,1,0,'嗯？又来一个新兵？',12340),
(7261,1,0,'<哈格丁中尉向你敬礼！>',12340),
(7281,1,0,'他一定非常痛苦，因为只有他独自活着，而他的兄弟已经升华到了一个完美的境界。',12340),
(7282,1,0,'我下达这个命令的时候心情非常沉重，士兵。',12340),
(7301,1,0,'有什么要让我知道的事情？',12340),
(7302,1,0,'任务进行得怎么样，士兵？',12340),
(7321,6,6,'幸运光环笼罩着你找到原因了吗？我告诉你，联盟狗在这一片真是太多了……在我看来，他们离得够近了。',12340),
(7341,6,0,'你好，$r。我是考拉克，来自雷霆崖的赏金猎人。我游历了整个世界，见识过很多奇异的事情。$B$B我穿越了整个南海，并偶然找到了这些奇妙的瑟银之箭。啊，我有无数的箭，但是我的子弹都用光了。呸，没有好的装备，一个牛头人怎么可能横行战场。这些箭现在毫无用处！$B$B我们来进行一个交易:你可以用瑟银弹来交换我的瑟银之箭。怎么样？',12340),
(7342,5,5,'你能相信吗？！刚从卡拉诺斯运来的这一批弹药都是劣等货！我们现在手里只有这些弓箭！我要用这500000支瑟银箭来做什么？$b$b我告诉你，孩子。如果你可以给我弄些瑟银弹壳，我就给你瑟银箭作为交换——成交吗？',12340),
(7361,1,0,'他们想要灭绝我们？他们自己才应该被灭绝。',12340),
(7362,1,0,'我可不管头发是什么地方来的，$R。',12340),
(7363,1,0,'对，事实确实如此。我的兄弟是人类。这让我感到惭愧……这是我几乎完美的纪录上的一个污点。',12340),
(7364,1,0,'我倒要看看没有蹄子的牛头人还能耍什么花样。该死的东西……',12340),
(7365,1,0,'这是一个众所周知的事实:所有巨魔都带着魔精。',12340),
(7366,1,0,'本尼迪塔斯！我无法从他的光辉中找到一丝瑕疵。赞美他！',12340),
(7367,1,0,NULL,12340),
(7368,1,0,'你没看见我正在尽力避免把自己炸上天么？你有什么事？',12340),
(7381,1,0,'他回来了吗？那个嗜血的野兽又复活了吗？',12340),
(7382,1,0,'他复活了吗？',12340),
(7383,1,1,'神谕之树、大德鲁伊和德鲁伊们一起密切关注着泰达希尔的成长。但是虽然我们有了一个新家，但我们还没有重新得到不朽的生命。',12340),
(7385,1,0,'你可以为我提供更多敌人的鲜血。我很乐意接受更多，$n。',0),
(7386,1,0,'你可以避开硝烟弥漫的战场。在激烈的战斗之外，你可以帮我收集霜狼氏族的风暴水晶。$B$B议会正在收集这样的水晶，$n。',0),
(7401,1,0,'我做的是批发式的反讽，士兵。',12340),
(7402,1,0,'放松一点，士兵。',12340),
(7421,1,0,'',12340),
(7422,1,0,'看来高等技工已经听说了我们参加奥特兰克山谷之战的事情。他已经下达了命令，要求其子民拿回牛头人的蹄子作为报复。这些地精比我想象得更难对付！我们必须进行更多的研究，我们需要更多地精的头发。',12340),
(7423,1,0,'',12340),
(7424,1,0,'',12340),
(7425,1,0,'除非所有巨魔都永远沉默……否则鹿盔是不会满意的。继续从他们病态的躯体上收集魔精油吧。',12340),
(7426,1,0,'',12340),
(7427,1,0,'只要我有了足够的脊骨，就可以将它们都装载在我们的投石车上，然后射向丹巴达尔。$B$B雷矛卫队将感受到分离和死亡的恐怖。我简直等不及了！$B$B我们还需要更多的脊骨。',12340),
(7428,1,0,'',12340),
(7429,1,0,'我说的是戈多克镣铐钥匙——好吧，那些胖家伙是这么叫它的。任何巨魔都有可能拿着这把钥匙，不过我不清楚到底谁拿着它。没准那些卫兵是负责看管钥匙的……$b$b啊呀，我到底在想什么？你已经拿到钥匙了，对吧？',12340),
(7441,1,0,'我毫不后悔，陌生人。女王早已逝去。申德拉拉尔的成果被托塞德林王子的疯狂所毁。我只求自由……逃离……',12340),
(7461,1,0,'你要小心，冒险者。王子非常善于……花言巧语。',12340),
(7462,1,0,'这是一只大箱子。',12340),
(7463,1,0,'什么？我认识你吗？',12340),
(7481,1,0,'我的同事，暗夜精灵的学者卢索恩·纹角正在找人帮助他来完成这项任务。',12340),
(7482,1,0,'我的同事，牛头人的先知科鲁拉克正在找人帮助他来完成这项任务。',12340),
(7483,1,0,'你有什么事？我还有很多事得做！',12340),
(7484,1,0,'你又来了？这一次你有什么事？',12340),
(7485,1,0,'我的耐心让你免受痛苦。',12340),
(7486,1,0,'',12340),
(7487,1,0,'现在跳入裂缝之中将会给你带来无穷的灾难……',12340),
(7488,6,6,'你拿到了网了没有，$N？我们必须驱散它所汇集的魔法能量！',12340),
(7489,6,0,'$N，你拿到莱瑟恩德里的网了吗？',12340),
(7490,1,0,'<萨尔看着奥妮克希亚那颗巨大的头颅，努力克制着自己的情绪，强大的末日之锤已经被他握在手中了。>',12340),
