(7521,1,0,'即使要毁灭整个世界都在所不惜！',12340),
(7541,1,0,'',12340),
(7562,1,0,'',12340),
(7563,6,6,'你找到那些疯狂的枭兽了吗，$N？那些生物拥有很强大的魔法能量，而它们那饱经折磨的躯体中流淌的血液就是这种能量的载体。',12340),
(7564,6,0,'你有东西要给我？难道是一只巨大而多汁的蜘蛛？或者是一只蟑螂？我希望它还是活的……我很喜欢嚼活蜘蛛或者蟑螂……',12340),
(7581,1,1,'只有荒野萨特之血才能满足要求。',12340),
(7582,1,1,'赫达琳恶魔绝对不会轻易放弃它们珍贵的宝石，$N。',12340),
(7583,6,6,'嗯？干得怎么样了？',12340),
(7601,1,0,'你的能力绝不比我的主人差。',12340),
(7602,1,0,'不要告诉别人，其实尼比是个傻瓜。',12340),
(7603,6,6,'你是不是迷路了？',12340),
(7604,1,0,'我们之间有商业往来吗？',12340),
(7621,1,0,'',12340),
(7622,1,0,'',12340),
(7623,1,0,'',12340),
(7624,15,15,'我仿佛已经可以尝到乌拉泰克心脏的味道了。叛徒的血肉真是美味……',12340),
(7625,6,6,'你去过加德纳尔了吗，$N？你有没有从贝恩霍勒领主那里弄到星尘？',12340),
(7626,6,6,'你拿到那些药剂了吗，$N？莫苏尔说你需要一只达斯莫拉之铃，我需要那些药剂才能制造充满暗影力量的东西！',12340),
(7627,6,6,'黑暗战车之轮并不容易制造，而且它也需要很多材料。你收集到了我所需的材料了吗？',12340),
(7628,6,6,'你把龙鳞带来了吗，$N？在你带来鳞片之前我不会开始制作蜡烛……否则整个营地都会被炸上天的！',12340),
(7629,6,6,'你去过通灵学院了没有，$N？小鬼有没有用星尘制作羊皮纸？',12340),
