(7635,1,0,'我确信找一头黑龙然后干掉它并没有什么难度，$N。不要浪费我的时间。',12340),
(7636,1,0,'不要被它们的伪装所迷惑！',12340),
(7637,1,0,'你好，高贵的$C！我已用最新鲜的香料备好我信赖的香炉，并为它祝福了三次，供你使用。你的捐助不仅会帮助我们在铁炉堡打造新的香炉，还会补充我们为贫民日渐枯竭的粮食储备。',12340),
(7638,1,0,'',12340),
(7639,2,0,'欢迎回来，$N。你得到驱魔香炉了吗？',12340),
(7640,6,6,'很高兴再次见到你，$N。你在恐惧谷的工作完成了？',12340),
(7641,1,0,'',12340),
(7642,6,6,'啊，$C。没有我提到的那些材料，我没法完成你的马铠。你都凑齐了吗？',12340),
(7643,1,0,'上古圣马之魂期盼地看着你，好像它希望从你这里得到什么。',12340),
(7644,6,6,'$N，你回来了！你有没有搞定梅丽德丝·卡尔森和特迪斯·扭木？老实说，我现在还不能确定哪一个威胁更大……',12340),
(7645,5,5,'怎么样，我证明你是错的了，是不是？我证明你们都错了！我一直以来都是正确的！',12340),
(7646,1,1,'你已经走到了这一步，$N。你为它所做的一切牺牲都将为你带来伟大的成就。我可以向你保证这一点。',12340),
(7647,1,0,'堕落的战骑之灵用悲哀的眼神凝视着你。它空洞的双眼中充满了绝望。',12340),
(7648,1,0,'你的任务进展得不错，$N。一旦你完成了马饰，就可以进入任务的下一步了。',12340),
(7649,1,0,'你找到了一本书！',12340),
(7650,1,0,'你找到了一本书！',12340),
(7651,1,0,'你找到了一本书！',12340),
(7652,1,0,'',12340),
(7653,1,1,'你想得到腰带的设计图，就给我拿10块瑟银锭来。',12340),
(7654,11,11,'你想得到靴子的设计图，就给我拿20块瑟银锭来。对，20块。你是不是要哭了？你要不要手帕？$B$B<德罗泰恩大笑着。>',12340),
(7655,0,0,'要做护腕图纸，我需要 10 块瑟银锭。$B$B你还好吗，孩子？你脸都红了。',12340),
(7656,1,1,'想得到胸甲的设计图，就给我拿30块瑟银锭来。$B$B哦，孩子，又是你。你是否要跑到你的神明那里哭诉，抱怨他们为什么要抛弃你？！？坚强点，孩子！没有人说过生活是公平的。',12340),
(7657,1,1,'只要给我25块瑟银锭，头盔的设计图就是你的了。',12340),
(7658,1,1,'只要给我30块瑟银锭，护腿的设计图就是你的了。$B$B我知道，我快要把你搞得破产了！但是你那些陈腔滥调的悲惨故事我早就听腻了，省省吧。',12340),
(7659,1,1,'你想得到护肩的设计图，就给我拿10块瑟银锭来。',12340),
(7660,1,0,'如果你把原本供你骑乘的高速座狼给我带来，我就可以让你从新的狼中选择一头。新的狼将和你原来的狼拥有同样的速度，但是其外观将会有所不同，看看周围的这些迅捷座狼就可以知道它们大概是什么样子了。',12340),
(7661,1,0,'如果你把原本供你骑乘的高速座狼给我带来，我就可以让你从新的狼中选择一头。新的狼将和你原来的狼拥有同样的速度，但是其外观将会有所不同，看看周围的这些迅捷座狼就可以知道它们大概是什么样子了。',12340),
(7662,1,0,'如果你把原本供你骑乘的高速科多兽给我带来，我就可以让你从新的科多兽中选择一头。新的科多兽将和你原来的科多兽拥有同样的速度，但是其外观将会有所不同，看看周围的这些科多兽就可以知道它们大概是什么样子了。',12340),
(7663,1,0,'如果你把原本供你骑乘的高速科多兽给我带来，我就可以让你从新的科多兽中选择一头。新的科多兽将和你原来的科多兽拥有同样的速度，但是其外观将会有所不同，看看周围的这些科多兽就可以知道它们大概是什么样子了。',12340),
(7664,1,0,'如果你把原本供你骑乘的高速迅猛龙给我带来，我就可以让你从新的迅猛龙中选择一头。新的迅猛龙将和你原来的迅猛龙拥有同样的速度，但是其外观将会有所不同，看看周围的这些迅猛龙就可以知道它们大概是什么样子了。',12340),
(7665,1,0,'如果你把原本供你骑乘的高速迅猛龙给我带来，我就可以让你从新的迅猛龙中选择一头。新的迅猛龙将和你原来的迅猛龙拥有同样的速度，但是其外观将会有所不同，看看周围的这些迅猛龙就可以知道它们大概是什么样子了。',12340),
(7666,1,0,'',12340),
(7667,1,0,'我知道开口要这些材料并不好，但是我的预言水晶球——就是我想要制作的装置——必须用到它们。如果你不能帮助我的话，我也可以理解。',12340),
(7671,1,0,'如果你将你忠诚的坐骑交给我的话，我就会给你一头新的迅捷猎豹坐骑。你的新猎豹坐骑将会和原来的坐骑拥有相同的速度，但是却有崭新的外观。你可以看看这里的迅捷猎豹来决定究竟要选哪一只。',12340),
(7672,1,0,'如果你将你忠诚的坐骑交给我的话，我就会给你一头新的迅捷猎豹坐骑。你的新猎豹坐骑将会和原来的坐骑拥有相同的速度，但是却有崭新的外观。你可以看看这里的迅捷猎豹来决定究竟要选哪一只。',12340),
(7673,1,0,'如果你把你的冰霜山羊带来交给我，那么我可以换给你一头新的山羊，它和你的冰霜山羊速度一样快，但是拥有不同的外观。你可以看看这里的迅捷山羊，然后再决定要选哪一头。',12340),
(7674,1,0,'如果你把你的黑山羊带来交给我，那么我可以换给你一头新的山羊，它和你的旧山羊速度一样快，但是拥有不同的外观。你可以看看这里的迅捷山羊，然后再决定要选哪一头。',12340),
(7675,1,0,'如果你还骑着旧的冰蓝色机械陆行鸟A型，那么你一定想要用它来换一台新型号的坐骑。你的新型机械陆行鸟的速度会和旧的型号一样，但是它拥有崭新的外表。你可以看看这里的迅捷机械陆行鸟，然后决定要选哪一个型号。',12340),
(7676,1,0,'如果你还骑着旧的白色机械陆行鸟A型，那么你一定想要用它来换一台新型号的坐骑。你的新型机械陆行鸟的速度会和旧的型号一样，但是它拥有崭新的外表。你可以看看这里的迅捷机械陆行鸟，然后决定要选哪一个型号。',12340),
(7677,1,0,'如果你把你的白马给我带来，那么我可以让你从新的马中选择一匹。它们和你原来的马拥有同样的速度，但是其外观将会有所不同。看看这里的马就知道它们大概是什么样子了。',12340),
(7678,1,0,'如果你把你的褐色马给我带来，那么我可以让你从新的马中选择一匹。它们和你原来的马拥有同样的速度，但是其外观将会有所不同。看看这里的马就知道它们大概是什么样子了。',12340),
(7701,34,34,'你没看见我正忙着吗？你*嗝*想要什么？*嗝*',12340),
(7702,0,0,'别被这古怪的护目镜迷惑了，$N。我是这儿最聪明的。',12340),
(7703,1,0,'哈哈，你还没有找到它，是不是，老大？也许那只是一个故事……很难相信那个可恶的精灵居然可以从我们戈多克的大王身边偷走东西！',12340),
(7704,0,0,'这真是个巨大的枕头！你从哪儿弄来的？',12340),
(7721,6,6,'也许你会对那些技术细节感到厌烦，但是我所准备付出的报酬一定会让你动心的。怎么样，你完成任务了没有？',12340),
(7722,6,6,'你找到那些设计图了吗？',12340),
(7723,1,6,'你杀死它们了吗？',12340),
(7724,1,6,'奥菲斯特说的是真的吗？那些蜘蛛真的是从屁股里吐丝的吗？',12340),
(7725,6,6,'啊，微缩残渣，甜蜜的结晶！好吧，老实说，我不会在进行研究的时候尝它的味道。$B$B基本不会……',12340),
(7726,6,6,'你有没有找到我要的水元素核心？',12340),
(7727,1,0,'<汉瑟尔正忙着揉搓他肿胀的指头。>$B$B别站在那儿，去抢一些油和一根丝瓜，用这些东西来消解我的疼痛。$B$B你没有丝瓜吗？嗯好！或许你该出去找些丝瓜了？$B$B嘿，你去哪儿？',12340),
(7728,1,1,'如果你是来领取奖励的，那么你必须把被盗的物品交给我。',12340),
(7729,1,1,'我们得比较你穿上衣服时和脱下衣服后的体重。',12340),
(7730,6,6,'你的狩猎进行得怎么样了，$N？你是不是要向我报告你成功的消息？',12340),
(7731,6,6,'你有没有把毒刺鞭笞者干掉？',12340),
(7732,0,0,'你好，朋友……看来你到这里来是有急事在身。我有什么可以帮你的？',12340),
(7733,5,5,'如果怒痕雪人的毛皮的品质可以和那些深痕谷中的雪人相媲美，那么它们一定像瑟银一样具有韧性！$B$B想象一下吧！',12340),
(7734,5,5,'如果怒痕雪人的毛皮的品质可以和那些深痕谷中的雪人相媲美，那么它们一定像瑟银一样具有韧性！$B$B想象一下吧！',12340),
(7735,6,0,'嗯……$N？你有什么特别的东西要给我吗？',12340),
(7736,1,1,'我没时间跟你扯东扯西的，$r。现在是补充我们日益减少的炽热助熔剂储备的时候了。$B$B我需要的物品有：$B$B*熏火龙的鳞片。$B$B*皇血草。$B$B*煤块。$B$B凡是你能给我的，我都要！$B$B如果你想要跟兄弟会搞好关系的话，就最好快点去找。',12340),
(7737,1,0,'你已经达到了可以和兄弟会进行合作的层次了，$r。我们开始对你另眼相看。干得很不错！$B$B如果你希望能赢得我们更多的尊敬，那就听好了。$B$B我们可以通过在炽热助熔剂中添加黑铁残油的方式来进一步提炼它，到黑石深渊去收集黑铁残油吧。$B$B把你找到的所有黑铁残油都交给我！',12340),
(7738,6,0,'嗯……$N？你有什么特别的东西要给我吗？',12340),
(7761,1,0,'<整个房间中充满了烧焦的尸体的味道。>',12340),
(7781,1,0,'难以置信！',12340),
(7782,1,0,'欢迎你，勇士。',12340),
(7783,1,0,' $N，真希望我能亲眼看到那头野兽被你杀掉之前那张痛苦的脸。',12340),
(7784,1,0,'你的成就让我感到备受鼓舞。',12340),
(7785,6,6,'你会帮助他从那永恒的牢狱中解脱出来吗？',12340),
(7786,5,5,'即使要毁灭整个世界都在所不惜！',12340),
(7787,1,0,'<德米提恩看到你的时候蜷缩成了一团。>',12340),
(7788,1,0,'银翼要塞那边有什么消息吗？你有没有击败战歌氏族的部队，拿到你的功勋奖章？',12340),
(7789,1,0,'敌人的鲜血就是我们的荣耀的象征，你做得很出色。',12340),
(7791,1,1,'我们现在接受毛料的捐赠。只要捐赠60块毛料，暴风城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。',12340),
(7792,1,1,'我们现在接受毛料的捐赠。只要捐赠60块毛料，埃索达就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。',12340),
(7793,1,1,'和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在我们中的地位无疑将大大提升！那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。',12340),
(7794,1,1,'我们的魔纹布储量很低，而你可以帮助我们补充库存！如果计算所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被暴风城的人们广为传颂，这一点我可以向你保证！$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。',12340),
(7795,1,1,'$n，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$b$b如果你愿意的话，请把你多余的符文布捐献给我。我们现在接受一次60块符文布捐赠。',12340),
(7796,1,1,'你什么时候准备好交那叠符文布，我就收下。',12340),
(7798,1,1,'和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在我们中的地位无疑将大大提升！那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。',12340),
(7799,1,1,'我们的魔纹布储量很低，而你可以帮助我们补充库存！如果计算所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被达纳苏斯的暗夜精灵广为传颂，这一点我可以向你保证！$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。',12340),
(7800,1,1,'$n，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$b$b如果你愿意的话，请把你多余的符文布捐献给我。我们现在接受一次60块符文布捐赠。',12340),
