(7811,1,1,'$n，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$b$b如果你愿意的话，请把你多余的符文布捐献给我。我们现在接受一次60块符文布捐赠。',12340),
(7812,1,1,'你什么时候准备好交那叠符文布，我就收下。',12340),
(7813,1,1,'我们现在接受毛料的捐赠。只要捐赠60块毛料，幽暗城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。',12340),
(7814,1,1,'和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在我们的地位无疑将大大提升！那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。',12340),
(7815,1,6,'狩猎进行得怎么样？',12340),
(7816,6,6,'你拿到它了吗？',12340),
(7817,1,1,'我们的魔纹布储量很低，而你可以帮助我们补充库存！如果计算你所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被幽暗城的被遗忘者们广为传颂，这一点我可以向你保证！$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。',12340),
(7818,1,1,'$n，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$b$b如果你愿意的话，请把你多余的符文布捐献给我。我们现在接受一次60块符文布捐赠。',12340),
(7819,1,1,'你好，$N！我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于幽暗城的贡献而被大家认同。$B$B随时欢迎你捐献符文布。',12340),
(7820,1,1,'我们现在接受毛料的捐赠。只要捐赠60块毛料，雷霆崖就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。',12340),
(7821,1,1,'和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在我们中的地位无疑将大大提升！那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。',12340),
(7822,1,1,'我们的魔纹布储量很低，而你可以帮助我们补充库存！如果计算所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被雷霆崖的牛头人广为传颂，这一点我可以向你保证！$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。',12340),
(7823,1,1,'$n，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$b$b如果你愿意的话，请把你多余的符文布捐献给我。我们现在接受一次60块符文布捐赠。',12340),
(7824,1,1,'$n，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$b$b如果你愿意的话，请把你多余的符文布捐献给我。我们现在接受一次60块符文布捐赠。',12340),
(7825,1,1,'你什么时候准备好交那叠符文布，我就收下。',12340),
(7826,1,1,'我们现在接受毛料的捐赠。只要捐赠60块毛料，暴风城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。',12340),
(7827,1,1,'和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在我们中的地位无疑将大大提升！那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。',12340),
(7828,1,5,'让它们尝尝恶齿巨魔的厉害！',12340),
(7829,1,0,'清除你心中的杂念，$r。成为大自然的一部分！',12340),
(7830,1,1,'翱翔的锋喙狮鹫是狮鹫中的稀有品种，它的职责是繁衍后代。',12340),
(7831,1,1,'我们的魔纹布储量很低，而你可以帮助我们补充库存！如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被铁炉堡的矮人广为传颂，这一点我可以向你保证！$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。',12340),
(7832,1,1,'你什么时候准备好交那叠符文布，我就收下。',12340),
(7833,1,1,'我们现在接受毛料的捐赠。只要捐赠60块毛料，部落就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。',12340),
(7834,1,1,'和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在部落中的地位无疑将大大提升！那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。',12340),
(7835,1,1,'我们的魔纹布储量很低，而你可以帮助我们补充库存！如果计算整个部落所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被部落的英雄广为传颂，这一点我可以向你保证！$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。',12340),
(7836,1,1,'$n，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$b$b如果你愿意的话，请把你多余的符文布捐献给我。我们现在接受一次60块符文布捐赠。',12340),
(7837,1,1,'你什么时候准备好交那叠符文布，我就收下。',12340),
(7838,1,0,'嘿，傻大个！给我12个竞技场大师饰物，你就可以成为古拉巴什竞技场的宗师！',12340),
(7839,1,1,'小心邪枝巨魔，$N。他们是一群无情冷血的渣滓。',12340),
(7840,0,0,'<拉尔德揉着他硕大的肚子。>$B$B拉尔德好饿。',12340),
(7841,1,0,'你看起来太干净了，伙计。你要努力啊——让敌人的鲜血沾满你的身体吧。',12340),
(7842,0,0,'最后一条警告一定会让他们胆战心惊，或者会让他们变得非常非常愤怒。',12340),
(7843,1,6,'进行得怎么样，伙计？',12340),
(7844,1,0,'邪枝割颅者和邪枝预卜者居住在辛特兰的东北部。',12340),
(7845,1,0,'你必须帮帮我……',12340),
(7846,1,0,'你必须马上行动！',12340),
(7847,1,0,'太好了！',12340),
(7848,1,0,'现在跳入裂缝之中将会给你带来无穷的灾难……',12340),
(7849,1,1,'当我看到他的尸体时，我会把它交给雅尔金，并进行一个火葬仪式。',12340),
(7850,1,1,'在和邪枝巨魔作战的时候要多加小心，$N。他们的理智已经丧失了——他们会奋战到底。',12340),
(7861,1,6,'你从辛萨罗那边带来什么消息了吗？',12340),
(7862,1,6,'你是来这里申请职位的吗？',12340),
(7863,1,0,NULL,12340),
(7864,1,0,NULL,12340),
(7865,1,0,NULL,12340),
(7866,1,0,NULL,12340),
(7867,1,0,NULL,12340),
(7868,1,0,NULL,12340),
(7871,1,0,'银翼要塞那边有什么消息吗？你有没有击败战歌氏族的部队，拿到你的功勋奖章？',12340),
(7872,1,0,'银翼要塞那边有什么消息吗？你有没有击败战歌氏族的部队，拿到你的功勋奖章？',12340),
(7873,1,0,'银翼要塞那边有什么消息吗？你有没有击败战歌氏族的部队，拿到你的功勋奖章？',12340),
(7874,1,0,'敌人的鲜血就是我们的荣耀的象征，你做得很出色。',12340),
(7875,1,0,'敌人的鲜血就是我们的荣耀的象征，你做得很出色。',12340),
(7876,1,0,'敌人的鲜血就是我们的荣耀的象征，你做得很出色。',12340),
(7877,1,0,'这是一只大箱子。',12340),
(7881,1,0,'我们暗月马戏团四海为家。我们从一个地方走到另外一个地方……事实上，你会发现我们永远停不下来！因此我们穿破了无数的鞋子也不足为奇！我们需要时髦而且耐穿的鞋子，而雕花皮甲长靴正好满足我们的需要。$B$B你！你是一个制皮匠，那么帮我制作雕花皮甲长靴吧，我会给你一张暗月马戏团奖券作为回报。',12340),
(7882,1,0,'我们的工作人员不仅仅是负责清扫垃圾的！他们还在大篷车在巡游的时候负责警戒，因此他们需要优质的护甲。$B$B如果你可以制作结实的皮甲，那我可以保证它一定会物尽所用。我会给你一些暗月马戏团奖券作为报酬。',12340),
(7883,1,0,'亚布·尼比盖尔正在找寻更多的天才来加入他的演出，他正在找世界上个头最大的地精。你知道有身材尺寸合适的地精吗？$B$B在我们找到那个地精之前，他希望可以把他的演出服装给准备好。我想野人背心就可以胜任，你可以制作一些背心吗？如果可以的话，我会给你一叠暗月马戏团奖券的……',12340),
(7884,1,0,'亚布正在为他的动物园增加新的观光景点，包括一间沼泽小屋，用来安顿一个被鳄鱼喂养长大的小男孩，或者也许是给一个鱼人住的。我们需要高档的防水护腿，避免在水底行动的时候弄得浑身湿透。我想我们需要龟壳护腿。$B$B$N，你可以制作这种护腿吗？如果可以的话，那么一大堆暗月马戏团奖券就是你的了……',12340),
(7885,1,0,'你可能不会相信，但是经营一个流动的嘉年华会是很花钱的！每样东西都耗损的那么快，我们还可以赚钱实在是个奇迹。$B$B为了节省开支，我们一直在寻找方法来尽可能便宜的维护我们的设备。举例来说，我们的帐棚常常会裂开，但是我发现皮制护甲片可以拿来做很好的修复。你可以帮我带一些护甲片来吗？这会让我们在买新帐篷的花费上节省许多！如果你可以做到的话，我有一大堆的暗月马戏团奖券可以给你……',12340),
(7886,1,0,'你已经证明了自己在战歌峡谷中的价值！继续帮助我们作战，并给我带来更多的功勋奖章。我们会因此而更加信任你。',12340),
(7887,1,0,'你已经证明了自己在战歌峡谷中的价值！继续帮助我们作战，并给我带来更多的功勋奖章。我们会因此而更加信任你。',12340),
(7888,1,0,'你已经证明了自己在战歌峡谷中的价值！继续帮助我们作战，并给我带来更多的功勋奖章。我们会因此而更加信任你。',12340),
(7889,1,0,'要当世界上最强壮的女人可不是一件容易的事情！我的体重已经开始变得太轻了，要维持适当的身材就需要增加更多体重！$B$B你认为你可以给我弄一些镇石来吗？如果可以的话，那么我会给你一张暗月马戏团奖券。',12340),
(7890,1,0,'如果你想要帮我健身的话，我需要一根两头穿着重砂轮的杖子，然后我把这根杖子举过头顶来锻炼。听起来并不简单，但是作为世界上最强的女人，我不能有丝毫的松懈！$B$B你能不能帮我？我需要更多的重砂轮——给我弄一些来，我可以用暗月马戏团奖券和你进行交易。',12340),
(7891,1,0,'我正在忙着制作一件新的戏服，当我有自己的展台来展示我是世界上最强的女人时，就可以穿着它上台了！现在我正在寻找合适的护腕。它们不能遮盖太多，否则大家就看不到我的肌肉了，另外我希望它能有些闪光，你明白了吗？$B$B你看绿铁护腕是不是适合我呢，$N？你可以帮我做一双绿铁护腕吗？如果可以的话，我有许多的暗月马戏团奖券可以送给你。',12340),
(7892,1,0,'作为世界上最强的女人，我计划从观众那里收集各种东西，然后用大锤把它们全都敲碎！$B$B你可以帮我制作一柄巨型黑锤吗，$N？',12340),
(7893,1,0,'$N，在我寻求成为世上最强的女人过程中，我曾周游世界，从各种高手那里和古书中学到了强化肌肉的秘密。我掌握着可以让你将弱者轻松击溃的锻炼方法！$B$B要进行这种训练的话，我需要很多砂轮。$N，你有砂轮吗？',12340),
(7894,1,0,'亚布正在为动物园研制一种新玩意儿，它能使人们沉浸在疯狂的愉悦中！但是这东西需要耗费大量精力和原料……$B$B其中包括铜质调节器。我们需要大量的铜质调节器作为机械部件，我会用暗月马戏团奖券来与你交换。',12340),
(7895,1,0,'我的崭新的售货亭将是一道风景线，没错！一道风景线，而且……只有少数的幸运儿才可以接近！$B$B当顾客走近我的售货亭时，那些高速青铜齿轮便会欢快地吟唱起来！$B$B啊……现在我需要一些高速青铜齿轮来实现这一梦想。$N，请给我弄点高速青铜齿轮来吧……我会用暗月马戏团奖券来和你交换的！',12340),
(7896,1,0,'当我的售货亭一切准备就绪，开始营业时，我会做一些广告！还有什么宣传方式比烟火更加有效呢？$B$B嗯，或许有人认为在沸腾的大熔炉中翻煮敌人的头颅更能吸引人群，但是……我们这里什么种族的成员都有。烟火一定能达到华丽的效果！$B$B给我绿色烟火，$N，我会用一叠暗月马戏团奖券来交换的。',12340),
(7897,1,0,'我的售货亭不能开张的最大原因是……所有的东西都坏啦！我需要机械修理包进行修理！$B$B你能给我机械修理包吗，$N？我会用暗月马戏团奖券来交换的，你觉得怎么样？',12340),
(7898,1,0,'亚布·尼比盖尔跟我一样，正在进行一项新发明。叶博说，这个这东西是那么的惊人华丽，足以把整个世界的人都吸引过来……这将会让我们每个人都变的非常非常的富有！$B$B他说他需要瑟银零件来进行这项工程，所以要我去收集给他。你觉得如何，$N？你想要用瑟银零件来交换暗月马戏团奖券吗？',12340),
(7899,1,0,'要吸引人潮的第一课就是:用小东西跟小玩意儿引诱他们！你可以帮我吗？$B$B我需要毛茸茸的小爪子做为奖品。你可以在贫瘠之地或是黑海岸的猫身上取得它们……$B$B帮我带一些爪子来，我可以用暗月马戏团奖券来交换它们。',12340),
(7900,1,0,'小孩子喜欢玩具！我发现所有的小孩都喜欢用破损的熊皮制成的绒毛玩具！$B$B你可以在灰谷或希尔斯布莱德的熊身上弄到熊皮。我会用暗月马戏团奖券来和你交换的！',12340),
(7901,1,0,'人们评断事物价值的方法实在很奇妙！就这么举例来说好了，一根绑上了一条柔软的狼尾的木棍。现在，你跟我可能都会觉得像这样的东西并不是那么的值钱……但是如果你替那个垃圾取个很棒的名字，像是“荒野绒毛小尾巴”，然后把它放到一个很漂亮的盒子里面，那人们就会觉得它价值不斐。垃圾立刻变黄金！$B$B帮我从凄凉之地跟荒芜之地带些柔软的狼尾回来，我就给你暗月马戏团奖券。',12340),
(7902,1,0,'人的想象力实在是很不可思议的东西。它能让小小的山丘变成巍峨的高峰，让平淡无奇的阴影变成恐怖的梦魇！$B$B在暗月马戏团，它可以让最无害的影子表现的像是个可怕的梦靥！$B$B我们暗月马戏团就是要让我们的参观者的想象力无尽扩展！但是要诱发他们的想象力……有时候我们必须耍点小手段。$B$B我其中一个吸引点需要用到鲜艳的羽毛。你可以从艾泽拉斯大陆上一些危险的地区中的鸟身上取得。把这些羽毛带来给我，你就可以得到很多的奖券！',12340),
(7903,1,0,'你有没有曾经在一个伸手不见五指的洞穴里游荡，追寻冒险跟刺激？你有？真的吗？很好，那你一定看过蝙蝠那令人毛骨悚然的眼睛从高高的地方凝视着你，等待着你放松戒备的时候好来吸你的血！$B$B很可怕的想法，你不觉得吗？当然！蝙蝠眼毫无疑问是很可怕的！$B$B你可以帮我拿些蝙蝠眼来吗，$N？我需要它们来……给我正在设计的某件东西。某件很可怕的东西。$B$B你可以从东瘟疫之地的蝙蝠身上找到它们。',12340),
(7905,1,0,'我的朋友，我能帮你什么忙吗？你有需要兑换的礼券吗？',12340),
(7907,1,0,'看来你集满一整套野兽套牌了！恭喜你！',12340),
(7921,1,0,'你已经证明了自己在战歌峡谷中的价值！继续帮助我们作战，并给我带来更多的功勋奖章。我们会因此而更加信任你。',12340),
(7922,1,0,'你已经证明了自己在战歌峡谷中的价值！继续攻打银翼要塞的哨兵部队，给我带来更多的功勋奖章！',12340),
(7923,1,0,'你已经证明了自己在战歌峡谷中的价值！继续攻打银翼要塞的哨兵部队，给我带来更多的功勋奖章！',12340),
(7924,1,0,'你已经证明了自己在战歌峡谷中的价值！继续攻打银翼要塞的哨兵部队，给我带来更多的功勋奖章！',12340),
(7925,1,0,'你已经证明了自己在战歌峡谷中的价值！继续攻打银翼要塞的哨兵部队，给我带来更多的功勋奖章！',12340),
(7926,1,0,'我的朋友，我能帮你什么忙吗？你有需要兑换的礼券吗？',12340),
(7927,1,0,'看来你集满一整套入门套牌了！恭喜你！',12340),
(7928,1,0,'看来你集满一整套督军套牌了！恭喜你！',12340),
(7929,1,0,'看来你集满一整套元素套牌了！恭喜你！',12340),
(7930,5,0,'靠过来，靠过来！如果你想要兑换暗月马戏团奖券，尽管开口吧！你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧！',12340),
(7931,1,0,'靠过来，靠过来！如果你想要兑换暗月马戏团奖券，尽管开口吧！你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧！',12340),
(7932,1,0,'靠过来，靠过来！如果你想要兑换暗月马戏团奖券，尽管开口吧！你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧！',12340),
(7933,1,0,'靠过来，靠过来！如果你想要兑换暗月马戏团奖券，尽管开口吧！你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧！',12340),
(7934,1,0,'靠过来，靠过来！如果你想要兑换暗月马戏团奖券，尽管开口吧！你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧！',12340),
(7935,5,0,'靠过来，靠过来！如果你想要兑换从暗月马戏团得到的奖券，尽管开口吧！你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧！',12340),
(7936,1,0,'靠过来，靠过来！如果你想要兑换暗月马戏团奖券，尽管开口吧！你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧！',12340),
(7937,1,0,'这堆干草看起来跟幻象中的很像……',12340),
(7938,1,0,'这箱子看起来跟幻象中的很像……',12340),
(7939,1,0,'$N，感谢你所给予我的一切帮助。我实在无法足够的表达我的谢意！$B$B虽然我没那么需要了……但是如果你带给我更多的致密砂轮，我可以给你更多暗月马戏团奖券。',12340),
(7940,1,0,'靠过来，靠过来！如果你想要兑换暗月马戏团奖券，尽管开口吧！你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧！',12340),
(7941,1,0,'$N，我必须要感谢你的帮助。我有很多的补给了，当然这里面你帮了很大的忙，如果你可以带更多的护甲片给我的话，我会很乐意用暗月马戏团奖券来交换它们。',12340),
(7942,1,0,'$N，你对我们真是太好了，一直不嫌疲倦的替我带来这些货物。我由衷地感谢你！$B$B虽然我们对于瑟银零件的需求已经不像之前那么大了，但是你仍然可以拿来给我，我还是会很乐意用它们来交换暗月马戏团奖券的。',12340),
(7943,1,0,'$N，我正在设计的东西将是继诺莫瑞根被入侵后最可怕的事件！这要大力的感谢你以及你带给我的小玩意儿。真是太太太感谢你了！$B$B虽然我已经不太需要了，但是……如果你可以从东瘟疫之地的蝙蝠身上取得更多的邪恶蝙蝠眼给我的话……我也许会给你更多暗月马戏团奖券。',12340),
(7944,1,0,'这箱子看起来跟幻象中的很像……',12340),
(7945,1,0,'这树桩看起来跟幻象中的很像……',12340),
(7946,1,0,'我真高兴加布加布终于回来了。她是那么喜欢黑铁啤酒，所以当我没有了以后，她就跑去找更多的酒了！$B$B现在加布加布回来了，我要所有我可以取得的啤酒！我不希望她再跑掉了！$B$B你有黑铁啤酒吗？如果你有的话，我愿意用一颗加布加布的蛋跟你换……',12340),
(7981,5,0,'靠过来，靠过来！如果你想要兑换暗月马戏团的奖券，尽管开口吧！你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧！',12340),
(8001,1,0,'你已经证明了自己在战歌峡谷中的价值！继续帮助我们作战，并给我带来更多的功勋奖章。我们会因此而更加信任你。',12340),
(8041,1,0,'',12340),
(8042,1,0,'见到你身体健康真好，$n。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$b$b把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧！',12340),
(8043,1,0,'$n大师，你回来了！莫尔索已把你的功绩报给了国王。你的名字甚至传到了南海。也许有一天你会成为传说中的$c——流芳百世的故事。$b$b把你的护符给我，我好再一次强化它的力量。',12340),
(8044,1,0,'拉斯塔哈向你致敬，$n。这样的荣誉对非赞达拉部族的成员来说还是头一次。$b$b<金罗克向你鞠躬。>$b$b把坠饰给我吧，我会再次强化它的力量。穆贾巴的怒火已经与你的灵魂连在了一起。',12340),
(8045,1,0,'',12340),
(8046,1,0,'我的判断看来有些草率，$c。似乎你对圣光的盲目信仰还有些用处。$b$b把烙印给我吧，我会强化它的力量。',12340),
(8047,1,0,'我的判断看来有些草率，$c。似乎你对圣光的盲目信仰还有些用处。$b$b把烙印给我吧，我会强化它的力量。',12340),
(8048,1,0,'你获得了国王的认可，$c。拉斯塔哈承认你是赞达拉真正的盟友，这在你的族人中还是头一次呢。$b$b你将收到丰厚的奖励。把烙印给我吧，我会最后一次强化它。',12340),
(8049,1,0,'牧师，你与古拉巴什一族作战的英勇事迹早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。',12340),
(8050,1,0,'牧师，你与古拉巴什一族作战的英勇事迹早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$b$b现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。',12340),
(8051,1,0,'欢迎，$c。祖尔达萨之眼涌动着能量。你已准备好迈出下一步。把护符交给我，我来进行灌注。',12340),
(8052,1,0,'$n，如果我们有上万名像你这样的人物，哈卡的军队将在瞬间灰飞烟灭。$b$b<阿塔比姆发出了一声叹息。>$b$b唉，祖达萨之眼就要发挥它所有的潜能了。把它给我。',12340),
(8053,1,0,'你回来了？你带回权力珍宝了吗？你在浪费我时间吗？$B$B我希望不是，异教徒。',12340),
(8054,1,0,'你获胜了？你取回权力珍宝了吗？你杀死敌人了吗？',12340),
(8055,1,0,'你拿到权力珍宝了吗？那里面有魔精，我们必须得到它。你必须帮助我们。',12340),
(8056,1,0,'你有没有从祖尔格拉布取回我需要的权力珍宝？这些护腕值得你为之付出努力！',12340),
(8057,1,0,'你有没有从祖尔格拉布找到权力珍宝？这些护腕价值不菲呢，$N。相信我！',12340),
(8058,1,0,'你取回权力珍宝了吗？你以赞达拉的名义复仇了吗？',12340),
(8059,1,0,'你有没有带回权力珍宝？如果你可以击败哈卡的恶魔仆从，那么你不仅向我们证明了自己的实力，而且还证明了你想要学习恶魔之道的意愿。',12340),
(8060,1,0,'$N——你已经回来啦？你带回我需要的权力珍宝了吗？',12340),
(8061,1,0,'你从祖尔格拉布回来了？你有没有成功地从哈卡的手下那里获得权力珍宝？',12340),
(8062,1,0,'去祖尔格拉布，打败那些拥有权力珍宝的家伙，$N。他们是你的猎物，他们拥有我们需要的东西。',12340),
(8063,1,0,'去祖尔格拉布寻找那些发狂的家伙，用你自己的力量征服他们，$N！丰厚的奖励在等待着你，不要让哈卡占了上风！',12340),
(8064,1,0,'从祖尔格拉布带回我需要的权力珍宝了吗？只要你带来那些东西占卜师腰带就是你的了。',12340),
(8065,1,0,'从祖尔格拉布带回我需要的权力珍宝了吗？占卜师外套绝对值得你付出那些努力。',12340),
(8066,1,0,'攻击祖尔格拉布那些愚蠢的哈卡爪牙——他们身上有权力珍宝，$N。宣告自己的胜利，向部族证明你的实力。',12340),
(8067,1,0,'你在祖尔格拉布取得胜利了吗，$N？你只有带回我需要的权力珍宝，证明你对部族的价值，才能赢得赞达拉捕猎者披肩。',12340),
(8068,1,0,'祖尔格拉布的情况如何？你利用幻术的力量打败敌人了吗？无论如何，他们都得死——从他们那儿取回的权力珍宝将会帮助我们打败哈卡。',12340),
(8069,1,0,'你带回了我们需要的能量典范吗？我知道这并不容易……但我早就预言会有一个外来者前来协助我们对抗哈卡。我说，就让你来吧！',12340),
(8070,1,0,'权力珍宝……你拿到它们了吗？只有当我们拥有了它们之后，才能使用那些储存在里面的强大能量。如果我们能对血神的仆从发起反攻，就再好不过了……',12340),
(8071,1,0,'你拿到祖尔格拉布的权力珍宝了吗？',12340),
(8072,1,0,'你回来了——你带来了我需要的权力珍宝了吗？$B$B卡瓦萨尔的传说告诉我们，无论敌人有多强大，他们都不是不可战胜的。混乱会使所有人屈服，这点是毫无疑问的……而混乱中那些最有序的因素也可能使所有人屈服。',12340),
(8073,1,0,'欢迎回到尤亚姆巴岛，$N……你成功地取回权力珍宝了吗？',12340),
(8074,1,0,'我需要的正是权力珍宝——在对祖尔格拉布的恶魔作战时，我们可以利用它的力量。你带来权力珍宝了吗？',12340),
(8075,1,0,'权力珍宝是魔法的关键来源——占兆师炼衫中也蕴藏了这样的魔法。把我需要的东西交给我，我就送你一件赞达拉占兆师梦寐以求的炼衫。',12340),
(8076,1,0,'你找到了祖尔格拉布中的权力珍宝？我们将从这些物品中抽取力量并为我们所用，如果你成功了，我们会给你应得的奖励……',12340),
(8077,1,0,'权力珍宝……你有没有找到它们？只有我们得到这些东西，你才能获得恶魔力量的终极象征，$N。',12340),
(8078,1,0,'你带回权力珍宝了吗？你打败部族的敌人了吗？必须让哈卡尝到辩护者的愤怒！',12340),
(8079,1,0,'你获胜了吗？你取回权力珍宝了吗？告诉我你的复仇经历！',12340),
(8080,6,6,'你拿到资源木箱了吗，$N？如果没有足够的资源，阿拉索联军的士兵可没有办法好好干一仗……',12340),
(8081,1,0,'$N，阿拉索联盟有项长期任务交给你：重返阿拉希盆地，夺取更多资源木箱并交给我。',12340),
(8101,1,0,'',12340),
(8102,1,0,'欢迎回来，$c。我能发现卡亚罗之石有了变化。很多敌人都栽在你那超凡的能力下了。他们罪有应得。是该让我提升石头的能力了。把它拿给我。',12340),
(8103,1,0,'哈卡里人畏惧你，$n。他们述说着只有他们那无面之神才做得出的恐怖。你已用卡哈罗的力量焚烧了他们。如今他们在两处都懂得了恐惧。$b$b是时候进一步强化这颗小石了。把护符交给我。',12340),
(8104,1,0,'把坠饰给我吧，$n。我要给你看点东西。',12340),
(8105,1,0,NULL,12340),
(8106,1,0,'',12340),
(8107,1,0,'荣誉在赞达拉巨魔中要靠争取，$n。荣誉带来奖赏——友谊、同盟……$b$b把护符交给我，好让我增强它的力量。',12340),
(8108,1,0,'我为你准备好了，$c。我会再次强化你的护符。我只要求你继续消灭哈卡和他的爪牙。$b$b把护符给我。',12340),
(8109,1,0,'召唤恶魔，$c。让它们汲取玷污科赞的黑暗能量。指挥它们大开杀戒！$b$b是的……是时候对科赞的玷污进行最后一次强化了。把它给我吧。',12340),
(8110,1,0,'',12340),
(8111,1,0,'嘿，兄弟！再次见到你真好。部族都在传你杀哈卡里人的事。莫尔索给我消息，要给你的护符再加更多魔力。把它给我，麦维基会把它弄更好。',12340),
(8112,1,0,'那护符怎样，兄弟？看起来是时候给它的叶片再加点法术和魔力了。它需要一点绽放。把它给我，麦维基会修得好好的。',12340),
(8113,1,0,'$n！好久不见。拉斯塔哈命令我为你的坠饰加入更多的魔精和魔法，这可是最后一次呢，你知道吗？真的！要不是亲眼所见，我怎么都无法相信呢。把坠饰放在这儿吧。',12340),
(8114,1,0,NULL,12340),
(8115,1,0,NULL,12340),
(8116,1,0,'',12340),
(8117,1,0,'啊哈！梅维基闹了一个笑话！$B$B<梅维基大笑了起来。>$B$B这么说，你一直利用灵魂和元素的力量对抗那些藏在祖尔格拉布的敌人，是吗？这值得奖励！$B$B梅维基会磨亮你的宝珠的。把宝珠放在这儿，$n。',12340),
(8118,1,0,'啊哈！梅维基闹了一个笑话！$b$b<梅维基大笑了起来。>$b$b这么说，你一直利用灵魂和元素的力量对抗那些藏在祖尔格拉布的敌人，是吗？这值得奖励！$b$b梅维基会磨亮你的宝珠的。把宝珠放在这儿，$n。',12340),
(8119,1,0,'<梅维基指着你的坠饰。>$b$b看看它，$n！看起来象真的一样。灵魂在围绕着宝珠跳舞。$b$b把它交给梅维基吧，她会进行最后一次调整的。',12340),
(8120,1,0,NULL,12340),
(8121,1,0,NULL,12340),
(8122,1,0,NULL,12340),
(8123,1,0,NULL,12340),
(8124,1,0,'$N，污染者有项长期任务交给你：重返阿拉希盆地，夺取更多资源木箱并交给我。',12340),
(8141,1,0,'',12340),
(8142,1,0,'令人印象深刻，$n。你有一种杀戮的天赋，我多年来未在他人身上感受到过。连莫尔索都知道你为赞达拉做的事。是时候进一步强化你的护符了。把它给我。',12340),
(8143,1,0,'我感觉到你给哈卡里人带来了无数死亡，$n。你身上带着他们魔力的臭味。$b$b我猜暗影护符在杀戮中帮了忙？把它给我，让我增强它的力量。',12340),
(8144,1,0,'$n，它渴望成长。坠饰已经吸取了祖尔格拉布上千具巨魔尸体的能量。把它给我吧，我会对它做最后一次强化。',12340),
(8145,1,0,'',12340),
(8146,1,0,'即使在这里，我也能听到你的齐射把敌人打得七零八落的声音。他们的惨叫回荡着痛苦。$b$b你已在赞达拉巨魔中闯出了名声，$n。我们感激你所做的一切。$b$b把你的护符交给我，好让我再加一层编织。',12340),
(8147,1,0,'啊，$n，能再次闻到你的味道真好。$b$b<法尔希尔咧嘴一笑。>$b$b请原谅我的幽默感，它有时确实很糟糕。$b$b我感觉到你给我们的敌人带来了巨大的痛苦。哈卡的爪牙在愤怒中呼喊你的名字。这真是太好了。$b$b你已为你的护符赢得又一次编织。把它交给我。',12340),
(8148,1,0,'莫托尔替拉斯塔哈传话给你，$n。皇室对你全力剿灭哈卡军队的行为倍加赞赏。我会在坠饰中编入最后一根漩涡之藤的。把它给我吧。',12340),
(8149,1,0,'你到达光明使者乌瑟尔的墓碑，放下他的祭品了吗？$b$b对经验并不丰富的冒险家来说，这是一次危险的旅程。沿着穿越希尔斯布莱德的河流向北进入瘟疫之地是一条相对安全的道路。河流从悔恨岭附近的湖泊发源，往西奔流进入群山，穿过寂静的坟墓……那儿到处都是天灾军团的爪牙。',12340),
(8150,1,0,'你造访了格罗姆·地狱咆哮的纪念碑，放下他的祭品了吗？$b$b纪念碑的所在地仍然受到燃烧军团的污染。当你接近纪念碑时，一定要多加小心，不要太过冒险了。',12340),
(8151,1,0,'很少人来看望老熊怪了。你也是来看我的吗？',12340),
(8153,1,0,'你找到鹿角了吗？',12340),
(8154,6,6,'你拿到资源木箱了吗，$N？如果没有足够的资源，阿拉索联军的士兵可没有办法好好打一仗……',12340),
(8155,6,6,'你拿到资源木箱了吗，$N？如果没有足够的资源，阿拉索联军的士兵可没有办法好好打一仗……',12340),
(8156,6,6,'你拿到资源木箱了吗，$N？如果没有足够的资源，阿拉索联军的士兵可没有办法好好打一仗……',12340),
(8157,1,0,'$N，阿拉索联盟有项长期任务交给你：重返阿拉希盆地，夺取更多资源木箱并交给我。',12340),
(8158,1,0,'$N，阿拉索联盟有项长期任务交给你：重返阿拉希盆地，夺取更多资源木箱并交给我。',12340),
