(8181,1,0,'',12340),
(8182,1,0,'',12340),
(8183,1,0,'$N，一种邪灵的臭味环绕着你。你是否已经被夺魂者诅咒了？',12340),
(8184,1,0,'只要有合适的材料，赞扎就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官：金度和血领主那里夺来1个原始哈卡莱雕像。$B$B接下来是打孔的巫毒人偶——你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔！',12340),
(8185,1,0,'只要有合适的材料，赞扎就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官：金度和血领主那里夺来1个原始哈卡莱雕像。$B$B接下来是打孔的巫毒人偶——你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔！',12340),
(8186,1,0,'只要有合适的材料，赞扎就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官：金度和血领主那里夺来1个原始哈卡莱雕像。$B$B接下来是打孔的巫毒人偶——你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔！',12340),
(8187,1,0,'只要有合适的材料，赞扎就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官：金度和血领主那里夺来1个原始哈卡莱雕像。$B$B接下来是打孔的巫毒人偶——你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔！',12340),
(8188,1,0,'只要有合适的材料，赞扎就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官：金度和血领主那里夺来1个原始哈卡莱雕像。$B$B接下来是打孔的巫毒人偶——你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔！',12340),
(8189,1,0,'只要有合适的材料，赞扎就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官：金度和血领主那里夺来1个原始哈卡莱雕像。$B$B接下来是打孔的巫毒人偶——你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔！',12340),
(8190,1,0,'只要有合适的材料，赞扎就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官：金度和血领主那里夺来1个原始哈卡莱雕像。$B$B接下来是打孔的巫毒人偶——你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔！',12340),
(8191,1,0,'只要有合适的材料，赞扎就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官：金度和血领主那里夺来1个原始哈卡莱雕像。$B$B接下来是打孔的巫毒人偶——你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔！',12340),
(8192,0,0,'只要有合适的材料，赞扎就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官：金度和血领主那里夺来1个原始哈卡莱雕像。$B$B接下来是打孔的巫毒人偶——你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔！',12340),
(8193,0,0,'今天下午2点到4点，我们会有一场比赛，看谁是最厉害的钓鱼达人！你只要能率先从荆棘谷海岸的特定水域中钓出40条可口鱼来，就能赢得钓鱼大师的称号！这些鱼群是很容易找到的，你只需留意水面的动静就可以啦！$b$b即使你不是第一个钓到40条鱼的参赛者，我的学徒也会按每5条一定价格的方式向你收购你钓到的鱼。$b$b啊呀，你还犹豫什么，可口鱼游得很快的！',12340),
(8194,1,0,'虽然比赛冠军已经出来了，但是我仍然会以合理的价格收购你钓到的鱼。怎么样？',12340),
(8195,1,0,'我在寻找被称为部族硬币的权力珍宝。在过去，祖尔格拉布的居民们将它们作为流通货币使用，每一枚硬币都浸入了微量而强效的魔精。$B$B这些硬币分为9种。如果你有多余的硬币，我可以按三枚硬币对应一枚荣誉勋章的价值跟你交换，然后你就可以用勋章跟林沃斯换取某些特殊的物品。',12340),
(8196,1,0,'南海的许多岛屿上都生长着拥有强效精华的芒果树。吃下芒果的人在身体上和精神上都会有焕然一新的感觉。如果你没有吃过，那真是太可惜了！$B$B这岛上有足够的芒果，你可以用赞达拉荣誉勋章来跟我们交换。如果你想知道如何获得勋章，就去跟温卡萨谈谈。如果你有勋章的话，我们就立即交易吧！',12340),
(8201,1,0,'你拿到那些头颅了吗，$N？我们必须在哈卡获得更多力量前阻止他！',12340),
(8221,0,0,'*吱吱**喀喀*$b$b我在帮钓鱼大师布鲁吉尔寻找世界上的各种稀有鱼类。如果你可以帮我找来一些基佛天使鱼，那么我就把这个很不错的奖励品送给你。$b$b*嘎嘎**吱吱*',12340),
(8222,1,0,'在我为马戏团工作的这段时间中，我学到了很多关于顾客的事情。以下是我的一些经验:顾客喜欢闪光的东西！不管它是什么东西——你甚至可以把一根椅脚拆掉然后使它发光，这样，每个孩子都会从很远的地方赶来要一根。$B$B因此，$N，我需要发光的蝎血。你可以在希利苏斯、燃烧平原或者诅咒之地找到它。',12340),
(8223,0,0,'发光的蝎血非常不错，$N！只需要一些闪烁的光芒就可以把一件原本一文不值的垃圾变成价格高昂的商品。所有人都喜欢这样的东西，你不这样认为吗……$B$B你帮我了大忙，$N，虽然不需要更多的发光的蝎血，但是如果你能继续提供给我的话，我将继续给你奖券。',12340),
(8224,0,0,'*吱吱**喀喀*$b$b我在帮钓鱼大师布鲁吉尔寻找世界上的各种稀有鱼类。如果你可以帮我找来一些迪森皇后鱼，那么我就把这个很不错的奖励品送给你。$b$b*嘎嘎**吱吱*',12340),
(8225,0,0,'*吱吱**喀喀*$b$b我在帮钓鱼大师布鲁吉尔寻找世界上的各种稀有鱼类。如果你可以帮我找来一些布隆奈尔蓝斑鱼，那么我就把这个很不错的奖励品送给你。$b$b*嘎嘎**吱吱*',12340),
(8227,1,0,'你好，$g小朋友:小姑娘。你是来钓鱼的吗？',12340),
(8228,1,0,'',12340),
(8229,1,0,'',12340),
(8231,1,0,'你成功了吗？',12340),
(8232,1,0,'在你双眼我看到了智慧，$N。你狩猎结束了吗？',12340),
(8233,1,0,'',12340),
(8234,6,6,'我认识你吗？',12340),
(8235,6,6,'你找到够多碎片让我继续我的工作了吗？',12340),
(8236,6,6,'我已经收到了大法师克希雷姆送来的包裹，你找到钥匙了吗？',12340),
(8238,1,0,'我在寻找被称为部族硬币的权力珍宝。在过去，祖尔格拉布的居民们将它们作为流通货币使用，每一枚硬币都浸入了微量而强效的魔精。$B$B这些硬币分为9种。如果你有多余的硬币，我可以按3枚硬币对应一枚荣誉勋章的价格跟你交换，然后你就可以用勋章去跟林沃斯换取某些特殊的物品了。',12340),
(8239,1,0,'我在寻找被称为部族硬币的权力珍宝。在过去，祖尔格拉布的居民们将它们作为流通货币使用，每一枚硬币都浸入了微量而强效的魔精。$B$B这些硬币分为9种。如果你有多余的硬币，我可以按3枚硬币对应一枚荣誉勋章的价格跟你交换，然后你就可以用勋章去跟林沃斯换取某些特殊的物品了。',12340),
(8240,1,0,'你在赞扎祭坛摧毁宝石了吗？要是你成功的话，你会收到赞扎的双倍祝福！',12340),
(8241,1,1,'我没时间跟你扯东扯西的，$r。现在是补充我们日益减少的炽热助熔剂储备的时候了。$B$B我需要的物品有：$B$B*熏火龙的鳞片。$B$B*铁锭。$B$B*煤块。$B$B凡是你能给我的，我都要！$B$B如果你想要跟兄弟会搞好关系的话，就最好快点去找。',12340),
(8242,1,1,'我没时间跟你扯东扯西的，$r。现在是补充我们日益减少的炽热助熔剂储备的时候了。$B$B我需要的物品有：$B$B*熏火龙的鳞片。$B$B*重皮。$B$B*煤块。$B$B凡是你能给我的，我都要！$B$B如果你想要跟兄弟会搞好关系的话，就最好快点去找。',12340),
(8243,1,0,'随着你在部族中的声望不断提高，你可以购买到更多的强效饮料。你要知道……这些饮料含有很强的魔精——并且被赞达拉部族所钟爱，它特别适合那些到处冒险的旅行者！$B$B我可以让你从这三件中选择一个不过作为交换，我需要赞达拉荣誉勋章。你要知道，同一时间内，你身上只可以有一种精神效果。$B$B当你准备好进行交换的时候，就来找我吧！',12340),
(8246,1,0,'$N，当你在赞达拉部族中的声望达到了崇拜之后，我有一些特别的东西要给你。这来自于我们在南海的家园……赞达拉的徽记！这些徽记可以用于加强你所拥有的任何护肩。如果你在寻求力量，魔精或者平静……那么我有你所需要的一切！$B$B我需要十五块赞达拉荣誉勋章才会给你一枚徽记。如果你拥有了足够的勋章，那么就来找我吧！',12340),
(8249,1,0,'我们的盗贼需要练习开锁技能，因此我需要有足够挑战性的上锁的箱子——不过我们手头上的箱子难度太低，只适合那些初学者们练手。$b$b如果你能给我5个重垃圾箱，我就送你一把品质极佳的飞刀。$b$b你可以打开箱子，取出里面的东西，但是至少你得留下一点硬币……即使对训练中的盗贼来说，他们也需要动力的。',12340),
(8250,1,0,'你是？',12340),
(8251,1,0,'你找到粉尘了吗？',12340),
(8252,1,0,'恶鞭海妖是非常强大的法师。我想，他们不及你强大吧？',12340),
(8253,1,0,'你杀死了我的敌人吗？',12340),
(8254,1,0,'',12340),
(8255,0,0,'你回来了。你成功了没？',12340),
(8256,0,0,'我们必须迅速获得腐液。你找到它了吗？',12340),
(8257,6,6,'你把摩弗拉斯的血液带来了吗？',12340),
(8258,1,0,'时间非常紧迫，$N——你有没有成功解除死亡骑士达克雷尔的威胁？',12340),
(8260,1,0,NULL,12340),
(8261,1,0,NULL,12340),
(8262,1,0,NULL,12340),
(8263,1,0,NULL,12340),
(8264,1,0,NULL,12340),
(8265,1,0,NULL,12340),
(8266,1,0,'我知道在战歌峡谷获得胜利并不是容易的事情。但是，你为我们所做出的贡献——即使你还没有获得胜利——对我们来说也很重要。$B$B如果你完成一次战歌峡谷中的试炼但是没有获得胜利的话，你还是可以获得一根奉献绶带。把它带给我，银翼哨兵会因你所做出的贡献而奖励你……即使你未能获得这次战役的胜利。',12340),
(8267,1,0,'我知道在战歌峡谷获得胜利并不是容易的事情。但是，你为我们所做出的贡献——即使你还没有获得胜利——对我们来说也很重要。$B$B如果你完成一次战歌峡谷中的试炼但是没有获得胜利的话，你还是可以获得一根奉献绶带。把它带给我，银翼哨兵会因你所做出的贡献而奖励你……即使你未能获得这次战役的胜利。',12340),
(8268,1,0,'我知道在战歌峡谷获得胜利并不是容易的事情。但是，你为我们所做出的贡献——即使你还没有获得胜利——对我们来说也很重要。$B$B如果你完成一次战歌峡谷中的试炼但是没有获得胜利的话，你还是可以获得一根奉献绶带。把它带给我，银翼哨兵会因你所做出的贡献而奖励你……即使你未能获得这次战役的胜利。',12340),
(8269,1,0,'我知道在战歌峡谷获得胜利并不是容易的事情。但是，你为我们所做出的贡献——即使你还没有获得胜利——对我们来说也很重要。$B$B如果你完成一次战歌峡谷中的试炼但是没有获得胜利的话，你还是可以获得一根奉献绶带。把它带给我，银翼哨兵会因你所做出的贡献而奖励你……即使你未能获得这次战役的胜利。',12340),
(8275,1,0,'我们正忙于准备进攻对付异种蝎，我希望你能前来协助我们。',12340),
(8276,1,0,'我们正忙于准备进攻对付异种蝎，我希望你能前来协助我们。',12340),
(8277,0,0,'你完成了样本收集工作吗？拯救诺格刻不容缓！',12340),
(8278,0,0,'这是我们最后一次救诺格的机会！快！',12340),
(8279,0,0,'是谁啊？喔，是你！你找到暮光词典了吗？',12340),
(8280,1,5,'掘泥打击者是一个很严重的威胁，必须马上解决他们！',12340),
(8281,1,5,'掘泥打击者是一个很严重的威胁，必须立即将他们解决！',12340),
(8282,0,0,'还没找到我的包包吗？不过我已经很幸运了，至少毒药已经被净化过。',12340),
(8283,25,25,'我需要那个生物的蝎钳做为证据。没有蝎钳，没有奖励。',12340),
(8284,0,0,'那个荒芜的营地就在这里的西北方。拿到所有的碎片后再回来。',12340),
(8285,0,0,'你！你怎么找到我的？你是谁？没人跟着你来吧，有吗？说话！',12340),
(8286,1,6,'阿纳克洛斯回来了吗？',12340),
(8287,0,0,'你带给我的是什么，$N？',12340),
(8288,1,1,'你必须赢得诺兹多姆的子嗣的好感。',12340),
(8291,1,0,'银翼要塞那边有什么消息吗？你有没有击败战歌氏族的部队，拿到你的功勋奖章？',12340),
(8292,1,0,'你已经证明了自己在战歌峡谷中的价值！继续帮助我们作战，并给我带来更多的功勋奖章。我们会因此而更加信任你。',12340),
(8293,1,0,'你已经证明了自己在战歌峡谷中的价值！继续攻打银翼要塞的哨兵部队，给我带来更多的功勋奖章！',12340),
(8294,1,0,'敌人的鲜血就是我们的荣耀，你干得很出色。',12340),
(8297,6,6,'你拿到资源木箱了吗，$N？如果没有足够的资源，阿拉索联军的士兵可没有办法好好干一仗……',12340),
(8298,1,0,'$N，阿拉索联盟有项长期任务交给你：重返阿拉希盆地，夺取更多资源木箱并交给我。',12340),
(8299,1,0,NULL,12340),
(8300,1,0,'$N，污染者有项长期任务交给你：重返阿拉希盆地，夺取更多资源木箱并交给我。',12340),
(8301,1,1,'它们之所以不信任人类种族是有深厚的历史因素的。不过，唉，这种故事还是留给他的子嗣在对的时机来讲吧。',12340),
(8302,1,1,'说不定有一天整个塞纳里奥要塞都会在你的控制之下。',12340),
(8303,1,0,'<阿纳克洛斯点点头。>',12340),
(8304,1,5,'别浪费时间了，$N！',12340),
(8305,1,0,'',12340),
(8306,1,0,'纳塔莉亚？',12340),
(8307,1,0,'',12340),
(8308,0,0,'喔，亲爱的。',12340),
(8309,1,1,'如果你在其中一个虫巢里发现一些疯狂的暗夜精灵小姑娘，别忘了替我们给她点颜色瞧瞧。',12340),
(8310,25,25,'去和猴子玩吧，小鬼。我现在没空。',12340),
(8311,1,0,'你完成“不给糖就捣蛋”了吗？我很遗憾我生病了不能去，不过你的帮忙让我感觉好多了……',12340),
(8312,1,0,'你完成“不给糖就捣蛋”了吗？我很遗憾我生病了不能去，不过你的帮忙让我感觉好多了……',12340),
(8313,6,6,'你学得食谱了吗？你不会想占为己有吧，我希望！',12340),
(8314,6,6,'天啊！你手上的是什么东西，$N？',12340),
(8315,25,25,'你一定要在机会出现时奋力一击！',12340),
(8317,6,6,'丸子做的怎么样了？',12340),
(8318,6,6,'你找到那些密信了吗？',12340),
(8319,1,1,'继续带密信给我。我们很快就能逼暮光之锤回到他们爬出来的巢穴了。',12340),
(8320,1,0,'进入沙漠寻找暮光地领主，$N。杀了他们之后回来找我。',12340),
(8321,6,6,'$N，你打败卑鄙的维拉尔了吗？有没有拿到他的玺戒呢？',12340),
(8322,1,0,'桶子里装满了麦芽酒。',12340),
(8323,0,0,'你有找到一些暮光密文信吗？我对阅读这个月的《真正的信徒》感到非常好奇！',12340),
(8324,0,0,'有找到更多的暮光密文信吗？给我带更多的暮光密文信，虽然解码的工作会花上一些时间……',12340),
(8325,1,0,'我们重新建设的工程就在这里展开，$N。当我们夺回我们的家园就能扬眉吐气了。',12340),
(8326,1,0,'要你杀死这些野兽对我来说也不是件快乐的事。过去我们也与这些生物和平共处，现在情况已大不相同了。对所有的辛多雷而言，最重要的一个任务就是生存，记住这一点。',12340),
(8327,1,0,NULL,12340),
(8328,1,0,NULL,12340),
(8330,1,1,'你找到了我的东西吗？如果我们想要重拾逐日岛的统治权，玩嘛就会需要这些东西。至于现在，我必须继续看守着太阳之井……',12340),
(8331,1,0,NULL,12340),
(8332,6,6,'你拿到碎片和徽记了吗，恶魔猎犬？我需要它们来制作暮光教徒的身份勋章。',12340),
(8333,1,1,'如果你还需要另一个暮光信徒身份勋章，我很乐意效劳。不过，我还需要另一块艳丽的裂片和一些深渊纹章。',12340),
(8334,1,25,'你最好多了解一点生存的意义——还有生存的代价——早点知道比较好。身为一个血精灵，作困难的决定是你即将习惯的事。$B$B当天灾军团将我们的家园一分为二的时候没有人伸出援手。是我们，我们自己重新振作，东山再起。',12340),
(8335,1,0,'记住这个警告……',12340),
(8336,1,0,'岛上许多生物都因为我们的魔法忽然变的无侵略性又温驯。在天灾军团摧毁太阳之井后，我们对这些生物的控制就被粉碎了。奥术薄片是我们曾掌握控制的一点余烬，或许能从中想出一个新对策，让我们重拾对这些生物的控制权。$B$B更顺利的话，或许薄片还能让我们知道这座岛到底是为何而抑郁。',12340),
(8338,1,0,'从你的举止看来，好像有什么急事。有什么特别的事我可以帮你吗？',12340),
(8341,6,6,'你拿到裂片和羽饰了吗，$N？我需要它们才能制作一个贵族之戒。',12340),
(8342,0,0,'$N，如果你打算再次联系深渊高等议会，那么你需要另一枚暮光徽记之戒。带更多的裂片和羽饰给我，我就能为你制作一枚戒指。',12340),
(8343,1,0,NULL,12340),
(8344,1,0,'怨灵的精华会成为我很好的实验材料。就像你作为$c的一生，从世间所遇之物中学到东西很重要……然后把它们扭曲为我们的意志。恶魔是最丰富的力量之源，若这岛上真有这种污秽，那将是大有裨益。$B$B嗯……对我们术士而言是大有裨益。',12340),
(8345,1,0,'你已经读过神龛中的铭文了吗，$c？',12340),
(8346,1,25,'啊，$N。你的任务完成了吗？',12340),
(8347,1,0,NULL,12340),
(8348,6,6,'你跟深渊公爵进行得如何？它打人很痛吗？',12340),
(8349,1,0,NULL,12340),
(8350,2,0,'欢迎来到我的旅店，$C。你有什么东西要给我吗？',20886),
(8351,1,0,NULL,12340),
(8352,6,6,'嗯，事情进行得如何？我会不计代价让自己离开这个地点并与它们搏斗的。',12340),
(8355,0,0,'嗯，开始吧……',12340),
(8356,0,0,'你不展示肌肉是不会有糖果的，$N……',12340),
(8357,0,0,'你会跳舞吧？先伸你的右脚……再缩你的右脚……伸你的右脚……扭扭身子……',12340),
(8358,0,0,'嗯，开始吧……',12340),
(8359,0,0,'你不展示肌肉是不会有糖果的，$N……',12340),
(8360,0,0,'你会跳舞吧？先伸你的右脚……再缩你的右脚……伸你的右脚……扭扭身子……',12340),
(8361,6,6,'你完成工作了吗？',12340),
(8362,1,1,'你已经证明了自己，$N。让我们继续给暮光之锤施压吧。我需要你去击杀更多的深渊圣殿骑士！我会奖励你一些我和胡姆在战斗中找到的东西。',12340),
(8363,1,1,'你证明自己可以应付深渊公爵，$N。我总是鼓励好的习惯。因此记得给我带来更多的徽记，我会给你相应的奖励。',12340),
(8364,1,1,'你已经完全超越了我的期望，$N。你干掉了我和霍姆一直以来都不敢面对的敌人。$B$B现在我能做的就是继续奖励你对抗暮光之锤的行为。$B$B带给我更多的深渊权杖，然后我将尽力给你最好的奖励。',12340),
(8365,6,6,'你收集到20顶帽子了吗？我不相信——除非你让我看看那些帽子，而且它们最好保存完好！',12340),
(8366,1,0,'那么快就回来了？我希望你好好教训了那帮无赖，让他们一辈子都无法忘记。',12340),
(8367,0,0,'阿拉希到处流淌着战士的鲜血，奥特兰克的金属碰撞声不绝于耳。除非你从前线带回了消息，否则不要浪费我的时间！',12340),
(8368,1,0,'在战歌峡谷与银翼哨兵的战斗至关重要。联盟打着保护一片并不属于他们的森林的幌子，企图夺走部落最大的木材来源之一。$B$B别让这事得逞，$N！带着为部落效力的可堪一提的证明回来见我！',12340),
(8369,1,0,'你从霜狼的地盘上带来了什么消息？现在奥特兰克山谷的战事进行得怎样了？',12340),
(8370,1,0,NULL,12340),
(8371,1,0,'你的旅程如何，小子？',12340),
(8372,1,0,NULL,12340),
(8374,1,0,'告诉我，前线那边有什么消息吗？',12340),
(8375,1,0,'你从风暴之矛的土地带来了什么消息？奥特兰克山谷的战事如何？',12340),
(8381,1,0,NULL,12340),
(8383,1,0,NULL,12340),
(8384,1,0,NULL,12340),
(8385,1,0,'啊，$N。我希望你在各个战场的前线传授你的经验。许多刚刚来到战场上的小伙子和小姑娘都非常尊敬你这样的老兵。',12340),
(8386,1,0,'不要忘记，在战歌峡谷中进行战斗不止是为了保护森林，更重要的是我们在保护灰谷和贫瘠之地之间的自然屏障。你有没有从战场带回什么消息，$N？',12340),
(8387,1,0,'你从霜狼的土地带来了什么消息？奥特兰克山谷的战事如何？',12340),
(8388,1,0,'阿拉希依然被伟大战士的鲜血浸染，钢铁的交击声仍在奥特兰克回荡。除非你带来前线的消息，否则别浪费我的时间！',12340),
(8389,1,0,'在战歌峡谷与银翼哨兵的战斗至关重要。联盟打着保护一片并不属于他们的森林的幌子，企图夺走部落最大的木材来源之一。$B$B别让这事得逞，$N！带着为部落效力的可堪一提的证明回来见我！',12340),
