(8409,1,0,NULL,12340),
(8410,0,0,'你为我带来了什么东西，$C？',12340),
(8411,1,0,'元素在那？',12340),
(8412,1,0,'灵魂们很清楚我们在干嘛，他们想要杀了我！我希望你能取得材料。',12340),
(8413,1,0,'羽毛在那？',12340),
(8414,6,0,'你带给我什么邪恶的东西？',12340),
(8415,1,0,'只有圣骑士能承担我给予的任务。你就是我要找的人吗？',12340),
(8416,6,0,'赛尔丹尼斯净化了天灾石吗？',12340),
(8417,1,0,'斯托利把我的酒吐出来了吗？',12340),
(8418,6,0,'你把那些邪恶的巨魔杀死了吗？',12340),
(8419,1,0,'你带来恶魔布了吗？',12340),
(8420,1,0,'你带恶魔布来了吗？',12340),
(8421,1,0,'我要的东西你带来了吗？',12340),
(8422,1,0,'你把羽毛带来了吗？这个玩偶需要填充物！',12340),
(8423,1,1,'地狱野猪燃烧的棘刺会留下可怕的疤痕。别怕痛苦与伤残，战士，比起我受困的牢笼，那都不算什么。',12340),
(8424,1,1,'要打败影誓者并不容易，是吗？但是你是个战士，要嘛获胜，要嘛死去。',12340),
(8425,1,1,'你这么快就回来了？时间对我的意义不太一样，或许对你而言，这是一次相当长的旅途……',12340),
(8426,1,0,'在战歌峡谷与银翼哨兵的战斗至关重要。联盟打着保护一片并不属于他们的森林的幌子，企图夺走部落最大的木材来源之一。$B$B别让这事得逞，$N！带着为部落效力的可堪一提的证明回来见我！',12340),
