(8433,1,0,'在战歌峡谷与银翼哨兵的战斗至关重要。联盟打着保护一片并不属于他们的森林的幌子，企图夺走部落最大的木材来源之一。$B$B别让这事得逞，$N！带着为部落效力的可堪一提的证明回来见我！',12340),
(8434,1,0,'在战歌峡谷与银翼哨兵的战斗至关重要。联盟打着保护一片并不属于他们的森林的幌子，企图夺走部落最大的木材来源之一。$B$B别让这事得逞，$N！带着为部落效力的可堪一提的证明回来见我！',12340),
