(8446,1,0,'怎么了，$R？',12340),
(8447,1,0,'你已经看到你必须看到的事情了。',12340),
(8460,1,0,'加油，$N。如果你想赢得我们的信任，你就需要向我们证明你的能力。',12340),
(8461,1,0,'一旦你获得了木喉部族的信任，作为对你的忠诚的回报，也许我们可以帮你做点什么。',12340),
(8462,1,0,NULL,12340),
(8463,1,0,'你拿回被劫走的物品了没？',12340),
(8464,1,0,'我们很感激你为木喉部族所做的一切，$N。',12340),
(8465,1,0,NULL,12340),
(8466,0,1,'虽然你已向我证明自己的来意，你还需要继续努力向我部族怀疑的兄弟们证明你自己。只有这样我才能继续帮助你。$B$B有些死木熊怪戴着特殊的头饰，可以作为削减他们势力的证据。带给我你从任何头饰上取得的羽毛；你每给我一套5个，就会赢得木喉的信赖。',12340),
(8467,0,1,'虽然你已向我证明自己的来意，你还需要继续努力向我部族怀疑的兄弟们证明你自己。只有这样我才能继续帮助你。$B$B有些死木熊怪戴着特殊的头饰，可以作为削减他们势力的证据。带给我你从任何头饰上取得的羽毛；你每给我一套5个，就会赢得木喉的信赖。',12340),
(8468,1,0,'你有东西要给我瞧瞧吗？',12340),
(8469,1,0,'你无疑地得到了我的信任，$N，但你仍要努力得到我整个部族的信任。拜托……让我继续帮助你。$B$B冬泉谷的人都会配戴灵魂珠子来避开邪恶的灵魂。但这些珠子显然失去了它们的意义，因为冬泉谷的人就是腐败的媒介。帮我从冬泉谷熊怪那里带来这些灵魂珠子；你每给我一套5个，就会赢得木喉的信赖。',12340),
(8470,0,0,'$C，我可以帮你什么忙吗？你平静地走在我们之中，虽然一定有什么事情出错了。我感觉到什么东西……麻烦的东西……',12340),
(8471,0,0,'$C——你以平静的姿态向我们走来，但我可以感觉你是为了沉重、严肃的事而来……因为熊怪和$r是相似的。你有什么事要告诉我们？',12340),
(8472,1,0,'你有顺利收集完奥术核心吗，$N？',12340),
(8473,1,0,'我不太敢问，$N……任务完成了吗？',12340),
(8474,1,0,'你有东西要给我瞧瞧吗？',12340),
(8475,1,0,'你回来了，$N。你击退了死亡之痕的不死族吗？',12340),
(8476,1,0,'你在东南方可以找到拉伯瓦萨，杀掉巨魔再回来。',12340),
(8477,1,0,'你给我带来了奥特姆贝的锤子？ ',12340),
(8479,1,0,'你带回祖玛罗什头颅了没？',12340),
(8480,1,0,'你收集好丢失的武器了吗？',12340),
(8481,1,1,'你回到我们这里了，$N……这代表恶魔已经被杀死了吗？',12340),
(8482,1,0,'你有带东西给我吗？让我瞧瞧。',12340),
(8483,1,0,'你有处理好间谍吗？',12340),
(8484,2,0,'$C，我的领地欢迎你。铁炉堡永远是像你这样的英雄的家。现在，你找我有什么事吗？',12340),
(8485,2,0,'大酋长向你问好，$C。在这混乱时代，你的功绩让部落日益壮大。现在，有什么事要与我讨论吗？',12340),
(8486,1,0,'你杀死那些法力怨灵了吗？',12340),
(8487,1,0,'你收集好我要求的样品了吗，$N？',12340),
(8488,1,0,'结束了吗？他们都走光了吗？',12340),
(8490,1,0,'你成功的增强符文石了吗，$N？',12340),
(8491,1,0,'你回来了，你有带那些毛皮吗？',12340),
(8492,1,0,'你收集好那20个铜锭了吗？',12340),
(8493,1,0,'又回来了$C？太好了！我们还需要大量的铜锭，为了准备安其拉之战，请尽你所能地帮我收集铜锭，这些铜锭是要用来建造蒸汽坦克跟旋翼机，$B$B我们为了安其拉战役，真的还需要更多铜锭，你愿意帮帮我们吗？',12340),
(8494,1,0,'如果你收集到那20个铁锭，我可不想发现你把它们都藏起来了！',12340),
(8495,1,0,'这么快就回来了？不要让我再重新评估对你不好的看法$C，你让我觉得很感伤。那么，你知道我们仍然没有足够的铁锭供应武器、护甲、蒸汽坦克和搜寻故障所有需要的东西。你觉得你可以在去祖尔格拉布的路上，或是你们这些孩子现在鬼混的地方带回另一批20个铁锭吗？',12340),
(8496,0,0,'你有东西要给我吗，$n？',12340),
(8497,0,0,'你有东西给我吗，$n？',12340),
(8498,0,0,'你带了什么东西要给我吗？',12340),
(8499,1,0,'我希望你已经成功收集好我们之前讲的瑟银锭了。',12340),
(8500,0,0,'能再见到你真好，$N。希望你一切都好。我们现在还需要瑟银锭。如果你有的话请分给我，我正在为安其拉之战收集。',12340),
(8501,0,0,'你有什么事要跟我说吗，$N？',12340),
(8502,0,0,'你有事要告诉我，$C。',12340),
(8503,1,0,'这不是真的！我从来没有将这些堆积物上面的荆棘藻去除过。有人可能会认为它几乎就是经济利义下有效的万灵丹。*咳咳*你不会正好有我们先前谈的荆棘藻吧？',12340),
(8504,1,0,'又见面了……有什么事？啊，对了，$N！来看看我是否需要更多的荆棘藻吗？嗯，今天真是你的幸运日，因为这个重要问题的答案是肯定的“是”！你可以再收集20个来吗？',12340),
(8505,1,0,'你有我要的紫莲花草药了吗？',12340),
(8506,1,0,'欢迎回来，年轻的$c。我们的收集仍在成长，但即使现在我们仍需要更多的紫莲花。如果你还能收集更多草药，我恳求你继续做并将它们带来给我。',12340),
(8507,0,0,'你可以在佐拉虫巢外找到布莱卡维尔上尉的军队。和他的中尉，珍妮拉·顽锤谈谈，如果你能找到他的话。',12340),
(8508,6,6,'我会拿到那些你想要的已签字文件，$G小伙子:小姑娘？',12340),
(8509,1,0,'那是什么？大声的说出来，$C！你拿到我要的阿尔萨斯之泪吗？',12340),
(8510,1,0,'嗯，看来我仍需要更多的阿尔萨斯之泪。我想你应该可以再到上次收集它们的地方帮我找到更多吧。我们越快弄到这些东西，就能越快开始防守安其拉的军队。$B$B你会再次帮助我们吗$c？',12340),
(8511,1,0,'$C，我希望你带来了你所允诺的轻皮。',12340),
(8512,1,0,'很高兴再见到你，$N。显然我们需要更多轻皮来制作各种战争要用的东西。如果你能再帮我带来10张轻皮就太完美了。',12340),
(8513,1,0,'是的，先生，我记得你。你身上带的就是中皮吗？',12340),
(8514,1,0,'是的，先生，看来我们已经收集了不少中皮，但还需要更多。我向你保证全都会派上用场，一块都不会浪费。我知道这要求很多，但如果你还愿意，我需要你的帮助来削减剩下的配额。',12340),
(8515,1,0,'你包包里的东西是重皮吗，$C？是吗？我等不及你把它们交给我了！大家都会很满意我们的，你说是吗？',12340),
(8516,1,0,'没错，存货仍然不够。$N，我们仍未达到理想的目标。想想我们能用重皮做的所有东西！各种护甲和武器。蒸汽坦克的零件和步枪瞄准器！工程学护目镜，而且如果到最后我们还有剩下，可以把它们交给部落的齐柏林飞艇！$B$B你会为我带更多的重皮回来吗？',12340),
(8517,1,0,'你有我要的20个亚麻布绷带了吗，$C？',12340),
(8518,1,0,'我对于你在私下还有如此无私的行为感到很惊讶。$C，在我的任务完成之前我仍需要一些亚麻布绷带。你能再次帮我收集那些绷带吗？',12340),
(8519,1,0,'<阿纳克洛斯点点头。>',12340),
(8520,1,0,'我需要那些外衣和头带做好，还需要那株野藤，然后我才会把野皮头盔的知识教给你。$B$B头饰在冒险者中极受追捧，无论是朴素得令人意外的头带，还是全罩式头盔。打造珍贵头饰的基本要领始终不变，无论外观如何。',12340),
(8521,1,0,'你能再次提供我协助真是太好了，$c。看来我们已经收集了一堆丝质绷带，不过我们还需要更多。$N，你可以再想办法弄另一捆绷带拿来给我吗？联盟和我都会非常感激的。',12340),
(8522,1,0,'日子一天天过去，我们也继续向前走。$C，你有那些符文布绷带了吗？',12340),
(8523,1,0,'又是讨论紧急事件的时候了，$C。我再次感谢你之前所作的努力不是每个人都能如此无私奉献。但是我们仍然很多事要完成。$B$B$N，你可以再去收集符文布绷带并拿回来这里给我吗？',12340),
(8524,1,0,'我敢打赌你已经把我们之前说的那些彩虹鳍长鳍金枪鱼都带回来了，对吧，$C？',12340),
(8525,1,0,'什么！又是你？那我就成猴子的叔叔了……只不过我是个$R。准确说，我是滑溜的美食家！所以你又回来帮忙了，是吧？嗯，我不能说你错。你难道不喜欢那些食物的香味吗？<流口水>$B$B别再闲逛了！出去再给我带些彩虹鳍长鳍金枪鱼回来！',12340),
(8526,1,0,'你拿到所有的烤迅猛龙肉了吗？',12340),
(8527,1,0,'又见面了，$c。我看的出来你对一切感到相当兴奋。所以我想你应该可以再另外帮我带20份烤迅猛龙肉来。很好。你会帮忙吧。回头见罗。',12340),
(8528,1,0,'我有信心你很快就会带着我们讨论的斑点黄尾鱼回来。',12340),
(8529,1,0,'如果你愿意我想派你再去捕一批斑点黄尾鱼，$N。我想你有了第一次的经验，这次捕鱼一定会更快更容易。你愿意吗？',12340),
(8532,1,0,'我希望你带来的是20个铜锭，$C。',12340),
(8533,1,0,'这么快就回来了？你很快就会成为一个真正的矿工了$C。那么，你已经知道怎么钻孔了，我需要你出去帮我挖掘一堆铜矿，熔解它们做成铜锭再带回来给我。我知道你能办到，问题是，你愿意吗？',12340),
(8534,0,0,'你会在佐拉虫巢里找到塞纳里奥斥候艾泽奈尔。快，$N！时间就是金钱。',12340),
(8535,0,0,'你的任务完成了吗，$N？',12340),
(8536,0,0,'你的任务完成了吗，$N？',12340),
(8537,0,0,'你的任务完成了吗，$N？',12340),
(8538,0,0,'你的任务完成了吗，$N？',12340),
(8539,0,0,'你有事要告诉我吗，$C？',12340),
(8540,0,0,'你有东西给我吗，$n？',12340),
(8541,0,0,'你有东西给我吗，$n？',12340),
(8542,1,0,'淤泥打击者是严重威胁，必须迅速处理！',12340),
(8543,1,0,'很好，我看的出你对这场战争很用心。我有点期盼战争可以赶快开始，我想你应该也是一样，$C。当战争开始时一定会是很光荣的。部落这在希利苏斯沙漠的尘土上奔驰着，手上拿着武器，冲锋陷阵在无数的虫群之中。总有一天将会取得极大的荣耀！$B$B哈！但是首先我们需要锡锭。真有趣，这样的小东西却可以带来巨大的不同，你说不是吗？',12340),
(8544,1,0,'你收集好我要的材料了吗？',12340),
(8545,1,0,'如果能拥有所有安其拉之战需要的秘银锭就好了。这就是你回来的原因吗？你把我的秘银锭带来了？',12340),
(8546,1,0,'太好了，很高兴你出现在这。你之前帮过我，现在我再次需要你的帮忙。我们仍然需要更多的秘银锭需要制作很多护甲和武器还有其它东西来歼灭那些安其拉的虫子。$B$B所以如果你是个真正的朋友，你就会为我带回来更多的秘银锭。我会一直收下你的秘银锭直到达到我们的配额。你现在就可以给我一些吗？',0),
(8547,1,0,'您好！很高兴见到您！$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品！',12340),
(8548,0,0,'你完成必要的任务了吗，$N？',12340),
(8549,1,0,'去吧，$C。去找$N。',12340),
(8550,1,0,'又见面了，$N。我很高兴你又回来关心我们从未停止需要的宁神花。战事不停，我们就不断需要制作药水和药剂。$B$B你会再次协助我们吗，$C？我需要和以前相同数量的宁神花，所以如果你可以收集到再拿来这里给我，我会很感激。当然，如果你现在就有的话，我会非常乐意收下它们。',12340),
(8551,0,0,'你好啊，$N！你找到高拉什了吗？那箱子是我最喜欢的，里面有个小夹层，我最值钱的宝贝都藏在里面！',12340),
(8552,6,6,'你好。你有什么事吗？',12340),
(8553,1,0,NULL,12340),
(8554,6,6,'把我的弯剑抢回来没有，$N？',12340),
(8555,1,0,NULL,12340),
(8556,6,6,'你帮我把戒指和材料带来了吗，$N？',12340),
(8557,6,6,'你帮我带来了披风的材料吗，$N？',12340),
(8558,6,6,'你把我要的材料带来了吗，$N？',12340),
(8559,1,0,'你把我要的东西都带来了吗，$N？',12340),
(8560,1,0,'你把我要的材料带来了吗，$N？',12340),
(8561,1,0,'你有带我要的材料吗，$N？',12340),
(8562,1,0,'在安其拉的住所里，可怕的克苏恩在睡眠中等待着。',12340),
(8563,1,0,NULL,12340),
(8564,1,0,NULL,12340),
(8565,1,0,NULL,12340),
(8566,1,0,NULL,12340),
(8567,1,0,NULL,12340),
(8568,1,0,NULL,12340),
(8569,1,0,'当然胜利不是唯一重要的事情，英雄的努力是一切的精神所在！',12340),
(8570,1,0,'当然胜利不是唯一重要的事情，英雄的努力是一切的精神所在！',12340),
(8572,0,0,'你完成必要的任务了吗，$N？',12340),
(8573,0,0,'你完成必要的任务了吗，$N？',12340),
(8574,0,0,'你完成必要的任务了吗，$N？',12340),
(8575,1,0,'喔！魔法跳动的东西！是给我的吗？',12340),
(8576,1,0,NULL,12340),
(8577,1,0,'<箱子里一个高声调的声音回应了你的呼唤>$B$B是谁啊？打扫房间的吗？',12340),
(8578,1,0,'熔火之心啊？我希望我的护目镜还完好如初！',12340),
(8579,1,0,'',12340),
(8580,1,0,'你不想让比雷凯基生气吧。要让比雷凯基高兴，你就得快速地带给他很多的火焰花。',12340),
(8581,1,0,'比雷凯基知道你来帮忙。带很多火焰花来让他高兴。比雷凯基可能会用火焰花制作大炸弹。战争来临时把它们丢到安其拉的昆虫身上。但是比雷凯基需要更多火焰花，$C！$B$B你要帮比雷凯基带火焰花来，动作要快。至少要带和上次一样多的火焰花来他才会开心。',12340),
(8582,1,0,'你找到大使了吗，$N？他死了吗？$B$B我们不能让天灾在卡利姆多站稳脚跟。它们对我方边境的威胁已足够让我们两面受敌。$B$B从你讲述的事情中唯一乐观的迹象是，那个老妇似乎未被腐化。她内心深处一定明白，天灾或许能带来强大力量，但她若答应他们的交易，贫瘠之地也并非真正属于她。',12340),
(8583,1,0,'事实上我们需要更多的紫莲花，$c。虽然我自己的研究尚未找出草药的新配方，但仍有已被试验和需要的试剂要使用。$B$B我需要你再去帮我收集至少20朵紫莲花样本。把它们交给我。',0),
(8584,1,0,'一只什么？',12340),
(8585,1,0,'嗯……奇美洛克……',12340),
(8586,1,0,'快一点，孩子。我们不想让肉坏掉。',12340),
(8587,1,0,'是什么味道这么香？',12340),
(8588,1,0,'如果你只是要来这里碎碎念的话我可没有时间，$C。有太多堆重皮需要保存。等你至少有10张后再回来找我。',12340),
(8589,1,0,'没错，$c，我还需要更多重皮。将军和军需官的需求似乎永无止尽。而这些跟飞艇管理员所要求的数量比起来更加微不足道！$B$B我需要收集双倍的配额量。$n，帮我带更多重皮来，越快越好！',0),
(8590,1,0,'$C，你这么快就带着我们说的10张厚皮回来了吗？',12340),
(8591,1,0,'$c，你可以看见我仍需要收集更多厚皮。我再次要求你协助这个任务，并且保证，如果你完成任务我们会肯定你的努力。$B$B时间就是金钱！带着厚皮回来找我，我们就能完成准备去打仗！',0),
(8592,1,0,'你带回我要求的材料了吗，$N？',12340),
(8593,1,0,'你把我需要的材料带来了吗，$N？',12340),
(8594,1,0,'你收集好我要的材料了吗？',12340),
(8595,1,0,'杀死其拉主使者对人类而言是个显着的成就，$n。无论如何，他们拥有强大的能量与数量。继续对抗他们以证明自己成为我们勇士的价值。',12340),
(8596,1,0,'你把我要的东西都带来了吗，$N？',12340),
(8597,1,0,'那个地方有一个X标记……',12340),
(8598,1,0,'嘿，有什么事吗？',12340),
(8599,1,0,'你身上都是鱼腥味！',12340),
(8600,1,0,'帮我切割10张硬甲皮不需要这么久的时间吧！你是不是应该磨锐你的剥皮小刀了呢？',12340),
(8601,1,0,'为安其拉即将到来的战争所做的准备正在进行，$C。不过，为确保我们不落后，或者至少不让我成为拖后腿的那个，我要你再带回一叠粗皮。你对这事的及时关注会大受感激，$N。',12340),
(8602,1,0,'你收集好我要的材料了吗？',12340),
(8603,1,0,'在安其拉的住所里，可怕的克苏恩在睡眠中等待着。',12340),
(8604,1,0,'淤泥打击者是严重威胁，必须迅速处理！',12340),
(8605,1,0,'能再见到你真好，$C。我们仍在为战事做准备，所以我仍然需要你协助我收集绒线绷带。我们非常感谢你能提供的任何协助。',12340),
(8606,1,0,'',12340),
(8607,1,0,'不许失败让我颜面扫地，$C！尽快带着我们讨论的魔纹布绷带回到这里。',12340),
(8608,1,0,'你回来了？真有趣。你看我还在收集安其拉战役要用的东西。这表示我需要你再次为我收集一堆魔纹布绷带。如果你能再做一次会相当令人惊讶的$C。',12340),
(8609,1,0,'你拿到毒液了吗？',12340),
(8610,1,0,'我们全力投入安其拉战火的日子越来越近了，牧师。但首先我们必须积蓄力量、做好准备，才能在虫群及其主人的猛攻中存活。$B$B如果你又来了，那一定是想再为战争捐献一批符文布绷带？请尽快办妥，然后再次回到我这里。',12340),
(8611,1,0,'小精龙被激怒时会是很危险的生物。对付它们时要小心，$C。对附近任何暗夜精灵也要更加小心。那些烦人的家伙往往也躲在森林里。$B$B等你收集到足够多的翅膀，就来告诉我，我一定重重赏你！',12340),
(8612,1,0,'如你所见，$C，我们仍需要打包更多的食物给士兵。我不知道你打过仗没有，但是一旦你经过战场上第一个杀戮，你就会变的很饥饿。你上次做的很好，所以我希望这次也可以，如果不是有点赶，请为我带回另一批瘦狼排。',12340),
(8613,1,0,'小精龙被激怒时会是很危险的生物。对付它们时要小心，$C。对附近任何暗夜精灵也要更加小心。那些烦人的家伙往往也躲在森林里。$B$B等你收集到足够多的翅膀，就来告诉我，我一定重重赏你！',12340),
(8614,1,0,'如你所见，我们仍然需要很多的鱼。安其拉的战士们需要很多食物，所以我要尽所能的弄到所有斑点黄尾鱼。你抓到、煮好它们并带来给我，我会表达我的谢意，还有部落的谢意。',12340),
(8615,1,0,'小精龙被激怒时会是很危险的生物。对付它们时要小心，$C。对附近任何暗夜精灵也要更加小心。那些烦人的家伙往往也躲在森林里。$B$B等你收集到足够多的翅膀，就来告诉我，我一定重重赏你！',12340),
(8616,1,0,'你捐赠的最后一批烤鲑鱼看起来非常好吃，$C。我承认我真的很想偷留几条。你也看到了，我们尚未达到需要的配额。我希望你快点回来，因为你还要收集另一批烤鲑鱼。',12340),
(8619,1,0,NULL,12340),
(8620,1,0,'我和你一样把裤子穿上——一次穿一条腿进去。只不过等你穿好了，我已经在制作奥金浮标了。奥金浮标啊，宝贝！',12340),
