(8694,6,6,'你帮我带来了披风的材料吗，$N？',12340),
(8695,6,6,'你帮我带来了斗蓬的材料吗，$N？',12340),
(8696,6,6,'你帮我带来了披风的材料吗，$N？',12340),
(8697,6,6,'你帮我把戒指和材料带来了吗，$N？',12340),
