(8707,6,6,'你带了我要的材料来吗，$N？',12340),
(8708,6,6,'布埃诺，你给我带来我需要的材料了吗？',12340),
(8709,6,6,'你带了我要的材料来吗，$N？',12340),
(8710,6,6,'你带了我要的材料来吗，$N？',12340),
