(8723,1,0,NULL,12340),
(8724,1,0,NULL,12340),
(8725,1,0,NULL,12340),
(8726,1,0,NULL,12340),
(8727,1,0,NULL,12340),
(8728,1,0,'奥金浮标不会自己制造，$N。还有，你不要指望可以在我这里赊账。',12340),
(8729,1,0,'时间在不断流逝，勇士。',12340),
(8730,1,0,'又有一位英雄因为挑战死亡之翼的子嗣而阵亡了。我们将因这样的损失而被永远诅咒……',12340),
(8731,0,0,'你已完成你的战地任务了吗，$N？你可以在雷戈虫巢外面找到劈颅队长。',12340),
(8732,6,6,'我会拿到那些你想要的已签字文件，$G小伙子:小姑娘？',12340),
(8733,1,0,'<幽光哼了一声。>',12340),
(8734,1,0,'<雷姆洛斯冷冷地看着你。>$B$B我们所做的可能会毁了我们。',12340),
(8735,1,0,'<雷姆洛斯陷入沉思。>',12340),
(8736,1,0,'',12340),
(8737,0,0,'你的任务完成了吗，$N？',12340),
(8738,0,0,'到雷戈虫巢去找斥候兰迪奥，快一点，$N！时间紧迫！',12340),
(8739,0,0,'到亚什虫巢去找到斥候佳莉亚，快一点，$N！时间紧迫！',12340),
(8740,0,0,'你的任务完成了吗，$N？',12340),
(8741,1,0,'<阿纳克洛斯点点头。>',12340),
(8742,0,0,'一千年过去了，正如预言所说，有人站在了我面前。此人将引领其族人走向新时代。$B$B上古之神在颤抖，$N。哦是的，它畏惧你的信念。粉碎克苏恩的预言吧。$B$B它知道你来了，勇士——而与你同来的，是卡利姆多的力量。你只需告诉我你何时准备好，我便赐予你流沙权杖。',12340),
(8743,1,0,'甲虫之锣嗡嗡作响，给你一种不安的感觉。坚强起来，$N。一旦甲虫之锣被敲响，安其拉的大门就将被打开。$B$B从这扇大门之后涌出来的将会是混乱和毁灭。保护你的人民！',12340),
(8744,1,0,NULL,12340),
(8745,1,0,NULL,12340),
(8746,20,20,'$N！你找到它了吗？我给你的背袋中的纸条，有给你足够的讯息来确定梅特森的位置吗？我简直不敢去想那些恶棍会对梅特森做些什么……但我们绝对不会对这样的绑架勒索行为妥协！',12340),
(8747,1,0,'相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献已被记录下来。$b$b防卫者的徽记之戒将会在你对抗邪恶力量时提供更多的保护。$b$b提高警觉，一旦你选择了你的道路，就无法回头了。',12340),
(8748,1,0,'你一直保护卡利姆多生灵的行为已经被我们认可。把徽记之戒拿来，让我增强它的能量。',12340),
(8749,1,0,'向你致敬，$N。粉碎卡利姆多的敌人！告诉他们污染这片不灭星光照耀下的大陆要付出什么代价！$b$b你又赢得了一个强效施法。请把徽记之戒给我，我来灌注能量。',12340),
(8750,1,0,'如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$b$b请将你的徽记之戒交给我，这样我才能强化它的能量。',12340),
(8751,1,0,'我从没看过这样不屈不挠的凡人！青铜龙军团将给你最后的附魔强化。这是永恒之王本人的希望！$B$B请将你的徽记之戒交给我，这样我才能开始施法。',12340),
(8752,1,0,'相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$b$b征服者徽记之戒将会大大提升你的力量和速度。$b$b提高警觉，一旦你选择了你的道路，就无法回头了。',12340),
(8753,1,0,'你一直保护卡利姆多生灵的行为已经被我们认可。把徽记之戒拿来，让我增强它的能量。',12340),
(8754,1,0,'向你致敬，$N。粉碎卡利姆多的敌人！告诉他们污染这片不灭星光照耀下的大陆要付出什么代价！$b$b你又赢得了一个强效附魔。请把徽记之戒给我，我来灌注能量。',12340),
(8755,1,0,'如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$b$b将你的徽记之戒交给我，这样我才能强化它的附魔。',12340),
(8756,1,0,'我从没看过这样不屈不挠的凡人！青铜龙军团将给你最后的附魔强化。这是永恒之王本人的希望！$B$B请将你的徽记之戒交给我，这样我才能开始施法。',12340),
(8757,1,0,'相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$b$b塑能师的徽记之戒将会大大提升你的魔法和自然能力。$b$b提高警觉，一旦你选择了你的道路，就无法回头了。',12340),
(8758,1,0,'你一直保护卡利姆多生灵的行为已经被我们认可。把徽记之戒拿来，让我增强它的能量。',12340),
(8759,1,0,'向你致敬，$N。粉碎卡利姆多的敌人！告诉他们污染这片不灭星光照耀下的大陆要付出什么代价！$b$b你又赢得了一个强效施法。请把徽记之戒给我，我来灌注能量。',12340),
(8760,1,0,'如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$b$b请将你的徽记之戒交给我，这样我才能强化它的能量。',12340),
(8761,1,0,'我从没看过这样不屈不挠的凡人！青铜龙军团将给你最后的附魔强化。这是永恒之王本人的希望！$B$B请将你的徽记之戒交给我，这样我才能开始施法。',12340),
(8762,1,0,'$N！我给你的背袋里面的信息有没有包含什么有用的线索？我简直不敢去想那些恶棍会对梅特森做些什么……但我们绝对不可能付得出这么过份的赎金！',12340),
(8763,1,0,'这台“冬青保存机”第一眼看起来还满坚固的，但是经过仔细的检查之后，你发现它上面有些地精式的改造。不过，你的烹饪技能使得你可以理解它这台机器是如何运作的。$B$B机器里面已经有了新鲜的冬青了－－你只需要提供一些石中盐跟5个金币就可以让这台机器运作起来。',12340),
(8764,1,0,'勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。',12340),
