(8858,0,0,'嗯……',12340),
(8859,0,0,'朋友，你穿那双靴子看起来有些笨拙。',12340),
(8860,0,0,'你好啊！你是来参加新年庆典的吗？',12340),
(8861,0,0,'你好啊，$C！你是来雷霆崖参加新年庆典的吗？',12340),
(8862,1,0,'艾露恩的蜡烛对新年信徒而言是个带有极大尊敬的工艺品。蜡烛内有着真正的月光，等待被释放！$b$b这个光束对大部分的生物都是无害的，但是你会发现年兽和他的爪牙会感到眩目并被它灼伤。',12340),
(8864,1,0,'你可能会对我出售的洋装感兴趣。这样的洋装适合在新年穿着，而且我今天带来的款式都是最好的一批。每件洋装都是用最精细柔软的材料手工缝制。$B$B拿一些先祖硬币来交换，我就会让你从这三种款式中挑选一件。这样你可以接受吗？',12340),
(8865,1,0,'很高兴告诉你，我有一系列的节庆长裤套装供你选择……只是要用先祖硬币来交换。如果时髦对你而言很重要的话，这些就是你要找的东西！我跟你保证，你不可能在别的地方买到这样的长裤套装。$B$B拿一点先祖硬币来交换，我就会让你从这三种样式中挑选一件。这样你可以接受吗？',12340),
(8866,1,0,NULL,12340),
(8867,0,0,'你找到那些发射器了吗，$N？',12340),
(8874,1,0,NULL,12340),
(8876,1,0,'我知道制作新年烟花的秘诀，而且我很乐意将我的知识分享给有荣誉感的人。$B$B拿一点先祖硬币来交换，我就会给你制作小型烟花的设计图……',12340),
(8877,1,0,'烟花是节庆不可或缺的好东西，但是要看到这样美丽绚烂的花朵在空中绽放……你就得使用烟火发射器。$B$B给我先祖硬币，我就教你学会制作月光林地里随处可见的那种烟火发射器。',12340),
(8878,1,0,NULL,12340),
(8879,1,0,'大型的烟花可以把夜空照耀得有如白昼一般，只有集束的烟花可以与它们的华丽媲美！$B$B给我一些先祖硬币，我就教你制作大型烟花的办法。',12340),
(8880,1,0,'把一束烟花聚集在一起，它们就会绽放令人赞叹的美丽烟火！给我一些先祖硬币，我就告诉你如何制作烟花束……',12340),
(8881,1,0,'必须有许多材料和精湛的技艺才能制作大型烟花束，但效果绝对惊人且值回票价！给我一些先祖硬币，我就把大型烟花束的制作工艺传授给你。',12340),
(8882,1,0,'最灿烂的烟火秀一定要发射烟花束，而且那些烟花束绝对要用烟花束发射器发射！那么要你学会制作烟花束发射器的秘诀不是很有道理吗？拿点先祖硬币来给我，我就会传授你这个知识。',12340),
(8884,1,0,'我们远行者居所的骑兵巡逻队奉命导正我们这块美好土地上遭到的破坏。为达此目的我们会无所不用其极。$B$B我相信你已带着我要你去收集的鱼人头颅回来？',12340),
(8885,1,0,'你是我成功与复仇的工具！$B$B你拿到戒指了吗？ ',12340),
(8886,1,0,'我对像你这样的人来帮忙感到十分感激，$N。你的帮助几乎让我可以绽放笑容。但后来我就知道这些怪物对我的船做了还有奎尔萨拉斯发生了什么事。$B$B你有货物的消息了吗？',12340),
(8887,1,0,'嗨，$C，见到你真高兴。我知道，我出现在这里是很疯狂的事，泊地都被失心者给占据了。微兰德丝和他的游侠发誓要保护我直到我取回我的货物。$B$B你手里拿得是什么……看起来有那么点眼熟？',12340),
(8888,1,0,'',12340),
