(9138,1,0,'有你的协助我们一定可以遏制天灾军团，$c。达克汗会被制服的！$B$B你有处理过日冠村蛛魔蛛怪的问题吗？',12340),
(9139,1,0,'我在这里已经经历过很多对抗天灾军团的事了。他们会被击退的，但是一定要一小步一小步慢慢地来。他们有一种卑鄙的手段，就是将你们死去的人抢走，加入他们自己的力量成为新的势力，因此你们一路上千万不能有一点疏失。$B$B那么，金雾村的战绩如何？',12340),
(9140,1,0,'$C，风行者村被释放了吗？那些可恶的太阳圣所博学者严厉地要我把那些我要你去收集的天灾遗物交到他们手中。$B$B不过别担心。你慢慢来把工作做好。让我来烦恼那些博学者的事。',12340),
