(9259,1,0,'里维加兹那个肮脏的家伙已经饶恕了所有愿意改过自新的血帆！那船底的人渣要我去杀了其它的人并把他们的面罩带回来做为证据。$b$b我不想这么做，所以也不会叫你去做。帮我带来一些丝绸和红色染料，我就能制作合适的复制品。我会跟男爵说你变节了，但是请小心……血帆不会喜欢这个主意的！',12340),
