(9265,1,0,'你调查过入侵行动了吗？没有时间可以浪费了！',12340),
(9266,1,1,'你一定是对我们或我们的朋友做了什么可怕的事，$n。无论如何，我是来提供你一个方法赢回我们的好感。$b$b你知道，冬泉谷还满冷的。我们有这么多的地精从别的城市过来，需要一些帮忙来保持温暖。帮我带一些符文布和煤炭来我就会帮你说点好话。不过要小心，我们的敌人不会对你的帮忙产生好感的。',12340),
(9267,1,0,'你在到达棘齿城之前要考虑清楚，$n！到处都传言着你的肮脏行为。$b$b不过你运气不错，刚好有一艘和血帆海盗交战过、载满伤者的船只抵达。这是你证明自己不是彻底的坏蛋的机会。帮我们把制作绷带的亚麻布和装药水的空瓶子拿来。',12340),
