(10075,0,0,'这地方就是德莱尼研究纳鲁水晶的主要研究场所。$B$B我们发现了一个名副其实的金矿——基于关于沃舒古的“钻石”山的研究笔记。似乎这儿的一切都带着一种水晶尘。如果你在这区域探险时发现了这些水晶尘，请将它们带给我，我将给予你以回报——你可以用他们来在军需官那儿买些东西。',12340),
(10076,1,0,'从山上来的结晶粉末充满着这个区域的地心。',12340),
(10077,1,0,'这地方就是德莱尼研究纳鲁水晶的主要研究场所。$B$B我们发现了一个名副其实的金矿——基于关于沃舒古的“钻石”山的研究笔记。似乎这儿的一切都带着一种水晶尘。如果你在这区域探险时发现了这些水晶尘，请将它们带给我，我将给予你以回报——你可以用他们来在军需官那儿买些东西。',12340),
(10078,1,0,'你看起来精神很好。烧了部落攻城器械让你回复了活力吗？',12340),
(10079,1,0,'告诉我震摇已经结束了而我的人能够回去工作了……拜托？',12340),
(10081,1,0,'所以你就是那个灵魂们提到的人吗？',12340),
(10082,1,0,'你不需要药剂就可以看到灵魂了，$N。',12340),
(10085,1,0,'像风一样快速的动身吧，$N。',12340),
(10086,0,0,'回收物资的工作进行的如何呢？你有找到可以利用的东西吗？',12340),
(10087,0,0,'我一直在找火炮被烧毁的明显迹象——燃烧的烟云或者着火的邪兽人的哀号声……$B$B你的任务成功了吗？',12340),
(10088,1,0,'那么，你在矿洞中有任何进展吗？',12340),
(10091,0,0,'嗯恩？我能为你做什么呢，$C？',12340),
(10093,1,0,'欢迎来到塔哈玛特神庙，旅人。',12340),
(10095,0,0,'$N，你从暗影迷宫带回了什么消息阿？',12340),
(10096,1,6,'什么？这么快就回来了？变怎样了？',12340),
(10097,0,0,'你有找到她吗，$N？她还被扣留在大厅里吗？',12340),
(10098,1,1,'泰罗克的遗物已经从斯克提斯离开太久了。你能把他们从塞泰克带回来吗？',12340),
(10099,1,0,'我几乎不敢问。看到你安好的从矿洞里走出来代表着有两种可能:要不就是你杀了那怪物，要不就是你失去了你的胆量。那么，是哪一个呢？',12340),
(10100,1,0,'你有办法从这所有线索中找到这个罪人吗？',12340),
(10101,1,0,'<库尔的手脚随着身体的光源振动同时的移动起伏。>',12340),
(10102,1,0,'<阿达尔的身体旋转和律动如同舒服的声音充满你的心里。>$B$B我们没有办法去解决玛格汉的困境。',12340),
(10103,1,0,'你是从猎鹰岗哨来的援军吗？',12340),
(10104,1,0,NULL,12340),
(10105,1,0,'你从祖莱那带来了什么消息吗？',12340),
(10106,0,0,'$N，等你协助占领每一个堡垒的占领行动后回来找我！',12340),
(10108,1,0,'说吧。',12340),
(10109,6,0,'拿到气体了吗？',12340),
(10110,0,0,'在你协助占领完每一个堡垒后回来找我吧！',12340),
(10111,1,0,'我有跟你说我对蛋的爱恋程度吗？',12340),
(10112,1,0,'嗯，我好像想起来了点什么了。',12340),
(10113,1,0,'我就知道他是最没用的那一个。',12340),
(10114,1,0,'你找到我兄弟吗？真棒的消息啊！',12340),
(10115,1,1,'你有看到这些匕潭失落者做了什么吗？现在你了解为什么我们必须将他们与其它破碎者隔离了吧。',12340),
(10116,1,1,'你得到穆玛基酋长的图腾了吗？',12340),
(10117,1,0,'你得到穆玛基酋长的图腾了吗？',12340),
(10118,1,1,'匕潭失落者唯一了解的事就是快速又残暴的攻击。他们应该知道我们不会让他们任意妄为。',12340),
(10119,1,0,'',12340),
(10120,0,0,'我看到你在跟沃雷恩谈话——一定是很重要的事吧……',12340),
(10122,1,0,'伏倒，你要在被抓到前快去检查这些计划。',12340),
(10123,0,0,'只要奥术师和他的血法师们坚持在前线，萨尔玛就安全了。',12340),
(10128,1,0,'感谢圣光你找到我了！',12340),
(10129,0,0,'假如你在第一次操作的时候失败了，这里是第二个炸弹……',12340),
(10130,1,0,'你看起来很不安。有什么发现吗？',12340),
(10132,1,0,'你已经消灭了这个巨大的威胁了吗？',12340),
(10134,1,0,'你手中的水晶还真大。那是你到坠星山那边杀死巨人时得到的吗？$B$B让我看看。',12340),
(10136,1,0,'命运来的时候谁都挡不住，$N。残忍的阿拉修斯已经苟活得够久了。把他的死讯告诉那些胆敢反抗部落之人。这也是你存在的意义。',12340),
(10138,1,0,NULL,12340),
(10139,1,0,NULL,12340),
(10140,5,0,'感谢圣光你安全的将它送达这里。荣耀堡需要集合所有经验丰富的战士。',12340),
(10141,1,0,'<阿图玛斯中士没有注意到你。她看起来有点疲惫。>',12340),
(10142,1,0,'只要弓箭手看守着我们的领空，荣耀堡就会很安全。',12340),
(10143,1,0,'所以你就是清除苦痛之路的那个人，是吗？',12340),
(10144,1,0,'真希望我能到那里观赏烟火展示。那些爆裂物的威力强大！',12340),
(10146,0,0,'这是个非常重要的任务，$N。是个我不会轻易相信随便任何人的任务。',12340),
(10150,1,0,'俯倒，在你还没被抓到前快去检查这些计划书。',12340),
(10152,1,0,'你看起来很不安。你发现了什么吗？',12340),
(10156,1,0,NULL,12340),
(10157,1,0,'斥候玛克哈在从葛卡兹哨站回来时带回了有关你的发现的消息。你在这对抗邪兽人的事迹不会被忽略的。',12340),
(10159,1,0,'你清理棘牙陵的进展得如何？',12340),
(10160,1,0,'很开心可以在这看到新面孔。你是军队指挥者派来的吗？',12340),
(10161,1,0,'你找到足够的零件了吗？如果没有，我可能得使用那个雷加希一直在附近挥舞的平底锅。下面我将飞艇重新命名为“飞行平底锅”。',12340),
(10162,0,0,'让他们知道领空权是我们的！',12340),
(10163,5,0,'让他们知道领空权是我们的！',12340),
(10164,1,0,'拯救那些灵魂，$N。',12340),
(10165,1,0,'我不喜欢“分享”。',12340),
(10166,1,0,'你回来了，你做的还不够多吗？',12340),
(10167,1,0,'<迪欧瑞的鬼魂哼了几下。>$B$B你好啊，$N。',12340),
(10168,1,0,'<卡舒尔宗母看起来很生气。>$B$B这些纳鲁远比世界上所有形态的生命还要聪明。',12340),
(10169,0,0,'这些药草跟香料的香味充满着锅炉周围的空气中。',12340),
(10170,1,0,NULL,12340),
(10171,1,0,'话语……无意义的话语……',12340),
(10172,1,0,'<盖亚安祖母躺了下来。>',12340),
(10173,0,0,'大法师瓦格斯之杖归还，我才会休息。你可以从恶魔的手中将它抢回来吗？',12340),
(10175,1,0,NULL,12340),
(10176,0,0,'终于，我们见面了。',12340),
(10180,1,0,'你怎么会知道在这里可以找到我？',12340),
(10182,0,0,'你找到什么了，$N？',12340),
(10183,1,0,'忙阿忙阿。没有时间可以浪费了！有一艘火箭船等着施工呢！$B$B你要干嘛？',12340),
(10184,0,0,'它让我痛到了解能为我们的同胞做的太少了。',12340),
(10185,1,0,'你有设法解决一些村庄废墟里的法力生物吗？',12340),
(10186,1,0,'X-52虚空火箭看起来像是准备好可以发射了吗？我是为了我驾驶座的舒适而漫行虚空的吗？开发陌生的新世界？寻找新科技及商机？勇敢的去那些没有地精去过的地方？$B$B不是的！$B$B因此，我希望你能有我给你之后的那些水晶。',12340),
(10188,0,0,'如果我要解开这座塔的诅咒，我就必须有那个魔符。',12340),
(10189,1,0,'你拿到我要你去拿的东西了吗，$N？',12340),
(10190,0,0,'你已经将电池充满电了吗？',12340),
(10191,1,0,'这么快就回来了？$B$B麦克斯米林V型还好吗？！',12340),
(10192,0,0,'你把书带来了吗？',12340),
(10193,1,0,'进行的怎样，$N？有任何消息吗？你最近为我做了什么？',12340),
(10194,1,0,NULL,12340),
(10195,1,0,'自从你带了第一批羽毛让我完成波尔泰姆的帽子，其它所有的佣兵吵着他们也要，包括萨德尔。我告诉他们我已经在进行了，但我需要替这个计划找到一个提供鸦人羽毛的稳定货源。$B$B我会很乐意接受你在森林探险中收集的任何鸦人羽毛。',12340),
(10196,1,0,'我很成功的引来了鸦人的灵魂到我身边，但他们仍然很害羞。也许如果我改变我的打扮，他们会更愿意在催眠状态下接近我。$B$B虽然，为了这样，我需要更多像你带来给我的这种羽毛。如果你有更多这种羽毛的话，我会很乐意从你手中接过来的。',12340),
(10197,1,0,'你有拿到我要的那些东西吗？',12340),
(10198,1,0,'窃听的如何阿，$N？你最好快一点。我已经开始坐立不安了。',12340),
(10199,0,0,'如果我能从这些虚空鳐的钉刺萃取出足够的毒液，我想我们会拥有有史以来最具爆炸性的燃料！',12340),
(10200,1,0,NULL,12340),
(10201,1,0,'那么，你有测试的结果了吗？',12340),
(10202,1,0,NULL,12340),
(10203,0,0,'这地方是不是很棒啊？而且每天都生产出崭新且奇特的东西！$B$B真是幸运，我们差点在探钻下来时毁了这座城镇。',12340),
(10204,1,0,'你调查过日怒博学者使用的那些血宝石了吗，$N？',12340),
(10205,0,0,'结束了吗？星界强盗奈萨德死了？',12340),
(10206,1,0,'这么快就带着他们的技术回来咯？你最好不要只是在这扯我的后腿，$C。$B$B这里的X-52计划成功与否，就全靠你赶快将那些东西带来给我们了！',12340),
(10208,0,0,'军团会对你带给他们的惊喜措手不及，对吧，$N？',12340),
(10209,0,0,'你有安全的取拿到格拉修斯之石吗？',12340),
(10210,1,0,NULL,12340),
(10211,1,0,'人类的故事是短暂的，$N。而城市的故事才能长远流传。',12340),
(10212,1,0,'他来了吗？',12340),
(10213,1,0,'祝你在搜寻幸存者时拥有好运气。我怀疑是不是有人在这场空难中存活下来。',12340),
(10214,1,0,'唔，你在矿洞那里有任何进展吗？',12340),
(10216,0,0,'这个装备有上百个按钮，没有一个你能看得懂的。',12340),
(10218,0,0,'嗨，小噬尸兽。',12340),
(10220,0,0,'你让那些不屈的灵魂见识到反抗被遗忘者的下场了吗？',12340),
(10221,1,0,'你将我们从砰砰博士的蹂躏中解救出来了吗？我发誓现在将不会有任何爆炸性的武器了，虽然那非常的有趣！$B$B我们真的应该要常常那样做。',12340),
(10222,1,0,'完成了吗，$N！你已经为了肯瑞瓦村庄的沦陷复仇了吗？',12340),
(10223,1,0,'你完成任务了吗，$N？',12340),
(10224,0,0,'你拿到所有精华了吗？',12340),
(10225,0,0,'嗯，嗨。我现在有点忙。你有什么东西要给我吗？',12340),
(10226,0,0,'你从那些元素生物身上得到力量了没？喔，我不是想催你或什么的。只不过我的生活及工作都靠你了。',12340),
(10227,1,0,'<拉姆杜尔惊讶的看着你。>$B$B嗯嗯，有事吗？',12340),
(10228,1,0,'圣光与你同在，我的朋友。',12340),
(10229,0,0,'这是什么？一本传达不屈者意念的书？真是奇怪。我研究看看。也许我有办法知道不屈者的历史。',12340),
(10230,0,0,'我们得尽快帮助不屈者。要是我们能够说服他们加入我们，部落将获得一个有利的盟友。',12340),
(10231,1,0,'你要啥？',12340),
(10232,0,0,'我当然希望你忙着与燃烧军团战斗。$B$B没有什么是比背信更让我厌恶的，还有咳咳地精，而恶魔必定就是这两种其中一种！',12340),
(10233,0,0,'烟从日怒要塞的堡垒中升起。那是你的杰作吗？',12340),
(10234,0,0,'你取得那些零件了吗？随着燃烧军团每次一个一个进驻我们在这里的领地，我们所剩的时间不多了。',12340),
(10235,0,0,'解决厄运之爪了没？',12340),
(10236,1,0,'你帮我的伐木机找到修理的零件了吗？我希望赶快修好他我才能继续去矿洞工作。不论如何我都必须要赚钱过日子，只有这样我才能赚足够的钱买一张回去藏宝海湾的单程票。',12340),
(10238,1,0,'你救回我的苦工了没？拜托快一点，我怕他们很快就会被吃掉而且他们应该不好吃。假如邪兽人吃了倒胃口的话他们可是会迁怒到我呢。',12340),
(10239,0,0,'你有办法取得他们的能源隔离器吗？',12340),
(10240,0,0,'你启动了所有的符文了吗？我很急切的想知道是否我们无法改善这里的血精灵秩序。任何凯尔萨斯的手下可以做到的事，真正的肯瑞托可以做的更好。',12340),
(10241,0,0,'你完成任务了吗，$N？',12340),
(10242,1,0,'欢迎来到断背岗哨。我能帮你什么忙吗？',12340),
(10243,0,0,'这个在你面前出现的符号看起来怪异且难懂。',12340),
(10245,0,0,'让我们看看你带了什么要给我们，$N。',12340),
(10246,0,0,'完成你的任务了吗，$N？',12340),
(10248,1,0,'你觉得如何？是否需要大翻修呢？',12340),
(10250,0,0,'你在攻塔时吹了这个号角了吗？我们必须快点进行这件事。谁知道萨尔玛何时会需要不屈者。',12340),
(10251,1,0,'你……你在找亡者之书吗？它不见了。我弄丢了……',12340),
(10252,1,0,'利维休斯的军队每分每秒都在壮大。你一定要加紧脚步。',12340),
(10253,1,0,'你是谁，你想要干嘛？喔……是你喔。',12340),
(10254,1,0,'',12340),
(10255,0,0,'你知道实验的结果了吗？',12340),
(10257,0,0,'你拿到钥石了吗？',12340),
(10258,1,0,'你是谁还有你想要从这个被诅咒的地方得到什么？这里不欢迎活人。',12340),
(10259,1,0,'再次进入裂缝里吧，我的朋友！',12340),
(10261,0,0,'我希望你是来关照我张贴的悬赏布告的！',12340),
(10262,0,0,'完成了吗？你有除去外域的萨克希斯渣滓，并将他们的徽记带来给我了吗？',12340),
(10265,0,0,'我有印象王子正在寻找一颗特别的水晶，但是我不确定它是什么。$B$B你已经从恐惧领主那拿到一个了吗？',12340),
(10267,0,0,'你拿到那些血精灵拖欠的测量装置了吗？',12340),
(10268,0,0,'靠近一点。',12340),
(10269,0,0,'你好啊，旅人。你到哈斯辛这来是想要买我的商品吗？',12340),
(10270,0,0,'你准备好现在谈生意了吗，$N？',12340),
(10271,1,0,'我相信你会有很多问题，所有的问题都会在适当的时间得到回答。',12340),
(10272,1,0,'你可以去收集蛋吗？',12340),
(10273,1,0,'这个玛利德是个笨蛋，或者我该说，曾经是个笨蛋。',12340),
(10274,1,0,'你去挑战并且打败维拉库了吗？',12340),
(10275,0,0,'你要买还是要卖？',12340),
(10276,0,0,'又见面啦，我的朋友。水晶找的如何阿？',12340),
(10277,1,1,'直到你至少初步了解到发生的事情前都不要回来。',12340),
(10278,0,0,'你有试着使用我的实验设备吗？我认为我的不稳定的迁跃裂隙生成器会在如此接近坑道的深处的地方发生作用。',12340),
(10279,1,0,'你好……',12340),
(10280,1,0,'<纳鲁说话的美妙口音充满了你的内心。>$B$B我感觉到你带着某种拥有巨大力量的东西，$R。你带给我的是什么呢？',12340),
(10281,1,0,'我很开心你决定接受我的邀请。',12340),
(10282,1,0,'不用紧张，凡人。你的外表已经被改变了，因此你不会干扰到时间线。',12340),
(10283,1,0,'你是谁？',12340),
(10284,0,0,'<伊洛森点了点头。>',12340),
(10285,1,0,'这么快就回来啦？',12340),
(10286,1,0,NULL,12340),
(10287,1,0,NULL,12340),
(10288,5,0,'我看过你在那跟杜隆交谈。你一定是在进行一项重要的任务吧！',12340),
(10289,0,0,'来自沃雷恩的报告吗？快一点拿过来！$B$B<克拉库克克将军皱着眉头迅速地审视了潦草的文件。>$B$B可恶，这是我们所担心的。沃雷恩和他的战士们随时可能被包围！',12340),
(10290,0,0,'我了解收集天然法兰石的风险，但是做生意也是如此。不愿意冒险的商人最好关门大吉，为自己减少麻烦。',12340),
(10292,1,0,'你有拿到那些我需要的火炮吗？',12340),
