(10324,1,1,'这些雄鹿的皮革是坚固而表面布满粗线条的图案，他们的肉非常的坚韧——虽然不能吃但是我们有其它的用途。',12340),
(10325,1,0,'你手上有任何我们敌人的徽记吗，$N？',12340),
(10326,1,0,'你带回了更多敌人的印记了吗，$C？燃烧军团仍是一个威胁，不论天涯海角我们都将继续对抗他们。',12340),
(10327,0,0,'我将拿走你剩下的所有印记。别担心你的行为将被正式的表扬。',12340),
