(10346,1,0,'在这个地狱岩床上仍然有许多的目标，$N。当你准备好进行下一回合时找只狮鹫吧。',12340),
(10347,5,5,'军团一定会认为他们哪怕是岩床上也不安全了。我们一定要不断的攻击他们！',12340),
(10348,0,0,'你设法去采取这些铃笼草了吗？',12340),
(10349,6,0,'那就是来自坠星山上水晶裂片的一部分吗？',12340),
(10350,1,0,NULL,12340),
(10351,6,6,'有用吗？你看到了什么？你找出是谁或者什么东西在背后主导发生在坠星山的事件吗？',12340),
(10352,1,1,'我们现在接受毛料的捐赠。只要捐赠60块毛料，达纳苏斯就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。',12340),
(10353,1,0,'报出名来，凡人？报上你的名来？',12340),
(10354,1,1,'和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在我们中的地位无疑将大大提升！那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。',12340),
(10355,1,1,'你能够去收集这些样本吗？',12340),
(10356,1,1,'我们的魔纹布储量很低，而你可以帮助我们补充库存！如果计算所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被埃索达的德莱尼人广为传颂，这一点我可以向你保证！$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。',12340),
(10357,1,1,'$n，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$b$b如果你愿意的话，请把你多余的符文布捐献给我。我们现在接受一次60块符文布捐赠。',12340),
(10358,1,0,'你什么时候准备好交那叠符文布，我就收下。',12340),
(10359,1,1,'我们现在接受毛料的捐赠。只要捐赠60块毛料，银月城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。',12340),
(10360,1,1,'和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在我们中的地位无疑将大大提升！那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。',12340),
(10361,1,1,'我们的魔纹布储量很低，而你可以帮助我们补充库存！如果计算所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被银月城的血精灵们广为传颂，这一点我可以向你保证！$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。',12340),
(10362,1,0,'$n，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$b$b如果你愿意的话，请把你多余的符文布捐献给我。我们现在接受一次60块符文布捐赠。',12340),
