(10450,0,0,'你挑战了噬骨氏族吗，$N？我希望他们的鲜血洒满大地！',12340),
(10451,1,0,'你找到威尔达姐妹了吗？',12340),
(10455,1,0,'我不是说过吗？林间潜伏猞猁不仅危害途经此地的人，也威胁到希尔瓦纳尔本身。$B$B它们的死固然可惜，但我们创造生命林地的全部意义，正是让希尔瓦纳尔被一片天然的、宁静美丽的防御地带环绕。',12340),
(10456,1,0,'我无法充分的强调杀掉那些雷神恶狼的必要性。他们的存在危及到活木林的稳定以及我们在这的工作。',12340),
(10457,1,0,'活木林的防御加固进展如何？$B$B纱幕莱什那边鸦人的意图不明，而部落就在峡谷对面，我怕若我们不迅速行动，保护新家园和林中工作的处境就会很糟。',12340),
