(10502,1,0,'我们的斥候回报这些刀塔食人魔已经在更接近山路的地方创建了一个营地，就是从他们的堡垒到我们这里的那条路。$B$B不过我们不甘心就这样屈服于这些食人魔垃圾之下，但如果他们想要开战，他们会发现部落不只适应力好而已。',12340),
(10503,1,0,'我们的斥候回报这些刀塔食人魔已经在更接近山路的地方创建了一个营地，就是从他们的堡垒到我们这里的那条路。$B$B不过我们不甘心就这样屈服于这些食人魔垃圾之下，但如果他们想要开战，他们会发现部落不只适应力好而已。',12340),
(10504,1,0,'血槌氏族或刀塔氏族都不重要。所有的食人魔氏族互相征战，争取拥有屠龙者格鲁尔支持的统治权。$B$B每一个都是我们的敌人，不管最后花落谁家。',12340),
(10505,1,0,'血槌氏族或刀塔氏族都不重要。所有的食人魔氏族互相征战，争取拥有屠龙者格鲁尔支持的统治权。$B$B每一个都是我们的敌人，不管最后花落谁家。',12340),
(10506,1,0,'有任何收获吗？我知道混在血槌食人魔中进行这项工作很危险，不过要是我们能够避免再杀害任何动物，我会觉得比较开心。',12340),
