(10692,0,0,'你已经完成我要求的工作了吗，$N？',12340),
(10693,1,0,'如果如果你有荣誉徽章，我可以用它来帮助你提高在暴风城的知名度。$B$B请注意，你最好一次交给我十枚荣誉徽章，这样你的知名度会获得更大的提高。我们提供针对一枚荣誉徽章的交换服务是为了方便那些没有足够荣誉徽章的冒险者。$B$B总之，如果你想要用荣誉徽章来换取声望的话，我随时在这里等着你。',12340),
(10694,1,0,'完成了自己的任务并得到荣誉徽章的冒险者可以把他们的徽章交给我，你每次把10枚徽章交给我，我都可以用它们来显着提升你在暴风城的声望。当然，我也接受单枚徽章的交换申请，但是这对于声望的提升效果就会逊色许多。虽然我们不会忘记每一位冒险者的努力，但是贡献越大，回报就越大。$B$B如果你有足够的荣誉徽章要给我的话，随时来找我。',12340),
