(10965,1,0,'快点，$r。如果这些怪物从墓穴中脱逃，将不只是克林塔尔·梦行者会有危险而已。',12340),
(10966,1,1,'很高兴又见到你了，$C。我相信你和年轻的朵娜一起共渡了一段美好的时光吧？',12340),
