(10971,1,1,'你找到标识牌了吗？',12340),
(10972,1,1,'我需要更多的标识牌，$N。当前为止我发现这些标签不只是拿来辨识囚犯的身份而已，它同时也记载着位置！$B$B一旦我破解上面的编码，就可以明确的知道所有盟友被囚禁的位置，并且以最小的冲突救出他们。',27980),
(10973,1,1,'我知道你付出了很多，但是想想这样你可以拯救多少人啊！',12340),
(10974,1,1,'你办到了！有什么发现吗？',12340),
(10975,0,0,'我们当前陷入了僵局，$n。你收集到的资料已经给我们足够的资讯以救出我们被关在虚空风暴小监狱里头的盟友们，但是我们必须一股作气的把复仇军对巴什伊尔平台造成的威胁连根拔起。$b$b加入与复仇军的战斗吧！把复仇军监狱钥匙交给我，而我将帮你打造复仇军监狱钥匙，使你得以开启巴什伊尔平台静止密室。',12340),
(10976,1,1,'这将会是你最不愿面对的任务，$N。',12340),
(10977,1,1,'假如你选择不再进行下去，我能谅解的，$N。',27980),
