(10979,1,0,'你帮莫希斯带消息来吗？他终于派人来找我了吗？',12340),
(10980,1,0,'<阿尔索恩充满希望的看着你。>$B$B你找到任何关于乌鸦之书的讯息吗？',12340),
(10981,0,0,'只有意志最坚定以及最勇猛善战的冒险者才会向我提出这项要求，$n。假如你想要面对法力陵墓第二间密室里头的惊恐魔物，我可以帮你制作通往那里的钥匙。给我一个节点之王印记，我就可以达成你的愿望。',12340),
