(11023,1,1,'轰炸任务进行的如何呢？',12340),
(11024,0,0,'解释一下！为什么你身上有着斯克提斯的味道！',12340),
(11025,1,0,'当你了解那些碎片和水晶的本质与用途，你就能对底下的巨魔同胞们提供更大的帮助。$B$B那些碎片的名字来自于曾经居住在山顶的一个已经灭亡的古鸦人文明。$B$B你把那些碎片带来了吗？',12340),
