(11027,1,1,'那个营地的恶魔时常修理他们的传送门。贾克说$n这一次给那些恶魔好看！$b$b但是，贾克要另一个暗色符文来制作晶铸暗色符文给你。$b$b假如小$r没有暗色符文，你就去跟克朗克说话。他试着每天做一个暗色符文！也许你可以去他的袋子里拿一个？！',12340),
(11029,1,1,'那本书，$N。你弄到它了吗？',12340),
(11030,1,1,'你弄到那个魔法药水了吗？那对托尔库斯而言可是全世界。',12340),
