(11032,1,0,'你决定违背先前的选择？我想我可以帮你改变它。最终达拉然在意你的忠诚比你选择如何表现它来的多。$b$b这花费可不低。当然我需要你把旧的戒指交回来。',12340),
(11033,1,0,'你决定违背先前的选择？我想我可以帮你改变它。最终达拉然在意你的忠诚比你选择如何表现它来的多。$b$b这花费可不低。当然我需要你把旧的戒指交回来。',12340),
(11034,1,0,'你决定违背先前的选择？我想我可以帮你改变它。最终达拉然在意你的忠诚比你选择如何表现它来的多。$b$b这花费可不低。当然我需要你把旧的戒指交回来。',12340),
