(11057,1,1,NULL,12340),
(11058,1,0,'你学会如何使用圣物了吗？我们和北边的沙塔尔天空卫队都对你所学到的东西很有兴趣。',12340),
(11059,1,1,'我们厌恶暴力，但至少我们派你去对抗的结构不是一个活的生命。$B$B说到这，你弄到那个头颅了吗？',12340),
(11060,1,1,'那些恶魔正在把怒气营地扩建得更大。很快他们就会太强大，把我们碾碎。你要先碾碎他们！$b$b沙图尔的传送器是关键，但它被魔法护盾和一种叫堕落者的恶魔保护着。我们强大的$c，制作特殊的黑暗符文，让你能控制那名堕落者。$r把黑暗符文交给加克，我们再把晶铸黑暗符文还给$r。$b$b夺取堕落者的控制权，尽可能附身那些穿过传送门的恶魔，阻止他们！',12340),
(11061,1,1,'巫术合剂绝对会让我的儿子们变的更聪明，那对他们到了沙塔尔天空卫队之后要做的事会有很大的帮助。',12340),
(11062,1,1,NULL,12340),
