(11066,1,1,'你对我们贡献良多，$N。我要你知道我们真的很感谢你所做的一切，让我们有足够存量的最新坐骑！',12340),
(11067,1,1,'川普击败了我一些最厉害的骑手。别让他的污秽骗了你。',12340),
